/// Validated, content-private proof of one completed Cordis Session turn.
///
/// Callers cannot construct this value directly. The constructor replays the
/// complete typed Session log and derives the draft only from the final model
/// message in the exact turn containing the deterministic Mission input.
#[derive(Clone)]
pub struct CordisMissionDraft {
    session_id: String,
    turn: u64,
    provider: String,
    model: String,
    system_prompt_digest: String,
    body: String,
    body_digest: String,
    user_message_id: String,
}

impl fmt::Debug for CordisMissionDraft {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("CordisMissionDraft")
            .field("session_id", &self.session_id)
            .field("turn", &self.turn)
            .field("provider", &self.provider)
            .field("model", &self.model)
            .field("system_prompt_digest", &self.system_prompt_digest)
            .field("body_digest", &self.body_digest)
            .field("user_message_id", &self.user_message_id)
            .field("body", &"[REDACTED]")
            .finish()
    }
}

#[must_use]
pub fn cordis_mission_user_message_id(mission_id: &MissionId, generation: u64) -> String {
    format!(
        "mission:{}:generation:{generation}:user",
        mission_id.as_str()
    )
}

#[derive(Clone, Debug)]
pub enum CordisMissionTurnPlan {
    Adopt(CordisMissionDraft),
    Dispatch {
        user_message_id: String,
        attempt: u64,
    },
}

impl CordisMissionTurnPlan {
    /// Selects the only safe next action for one Mission generation.
    ///
    /// A completed attempt always wins and is adopted without provider replay.
    /// Closed non-completed attempts advance to a fresh deterministic identity;
    /// open, duplicate, gapped, or malformed attempt histories fail closed.
    pub fn from_session(
        checkpoint: Option<&SessionCheckpoint>,
        mission_id: &MissionId,
        generation: u64,
    ) -> Result<Self, ApplicationError> {
        if generation == 0 {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        }
        let Some(checkpoint) = checkpoint else {
            return Ok(Self::Dispatch {
                user_message_id: cordis_mission_user_message_id(mission_id, generation),
                attempt: 1,
            });
        };
        SessionLog::restore(checkpoint.header.clone(), checkpoint.events.clone())
            .map_err(|_| ApplicationError::CordisDraftSessionInvalid)?;
        if checkpoint.header.id.as_str() != mission_id.as_str() {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        }

        let mut open_turn = None;
        let mut open_attempt = None;
        let mut attempts = BTreeMap::<u64, (String, Option<TurnEndReason>)>::new();
        for event in &checkpoint.events {
            match &event.kind {
                SessionEventKind::TurnStart { turn } => {
                    open_turn = Some(*turn);
                    open_attempt = None;
                }
                SessionEventKind::UserMessage { message, .. } => {
                    let Some(attempt) =
                        cordis_mission_user_message_attempt(&message.id, mission_id, generation)?
                    else {
                        continue;
                    };
                    let expected_attempt = u64::try_from(attempts.len())
                        .ok()
                        .and_then(|attempt| attempt.checked_add(1))
                        .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
                    if message.role != SessionMessageRole::User
                        || message.source != SessionMessageSource::User
                        || open_turn.is_none()
                        || open_attempt.is_some()
                        || attempt != expected_attempt
                    {
                        return Err(ApplicationError::CordisDraftScopeMismatch);
                    }
                    open_attempt = Some(attempt);
                    attempts.insert(attempt, (message.id.clone(), None));
                }
                SessionEventKind::TurnEnd { turn, reason } if open_turn == Some(*turn) => {
                    if let Some(attempt) = open_attempt.take() {
                        attempts
                            .get_mut(&attempt)
                            .ok_or(ApplicationError::CordisDraftScopeMismatch)?
                            .1 = Some(*reason);
                    }
                    open_turn = None;
                }
                _ => {}
            }
        }
        if open_turn.is_some() || open_attempt.is_some() {
            return Err(ApplicationError::CordisDraftTurnNotCompleted);
        }
        let completed = attempts
            .iter()
            .filter_map(|(attempt, (_, reason))| {
                (reason.as_ref() == Some(&TurnEndReason::Completed)).then_some(*attempt)
            })
            .collect::<Vec<_>>();
        if completed.len() > 1 {
            return Err(ApplicationError::CordisDraftReplayMismatch);
        }
        if let Some(completed_attempt) = completed.first().copied() {
            if Some(completed_attempt) != attempts.keys().next_back().copied() {
                return Err(ApplicationError::CordisDraftReplayMismatch);
            }
            let message_id = &attempts
                .get(&completed_attempt)
                .ok_or(ApplicationError::CordisDraftReplayMismatch)?
                .0;
            let draft = CordisMissionDraft::from_completed_session(checkpoint, message_id)?
                .ok_or(ApplicationError::CordisDraftReplayMismatch)?;
            return Ok(Self::Adopt(draft));
        }
        if attempts.values().any(|(_, reason)| reason.is_none()) {
            return Err(ApplicationError::CordisDraftTurnNotCompleted);
        }
        let next_attempt = attempts
            .keys()
            .next_back()
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
        Ok(Self::Dispatch {
            user_message_id: cordis_mission_user_message_id_for_attempt(
                mission_id,
                generation,
                next_attempt,
            ),
            attempt: next_attempt,
        })
    }
}

fn cordis_mission_user_message_id_for_attempt(
    mission_id: &MissionId,
    generation: u64,
    attempt: u64,
) -> String {
    if attempt == 1 {
        cordis_mission_user_message_id(mission_id, generation)
    } else {
        format!(
            "mission:{}:generation:{generation}:attempt:{attempt}:user",
            mission_id.as_str()
        )
    }
}

fn cordis_mission_user_message_attempt(
    message_id: &str,
    mission_id: &MissionId,
    generation: u64,
) -> Result<Option<u64>, ApplicationError> {
    let scope = format!("mission:{}:generation:{generation}:", mission_id.as_str());
    let Some(suffix) = message_id.strip_prefix(&scope) else {
        return Ok(None);
    };
    if suffix == "user" {
        return Ok(Some(1));
    }
    let attempt = suffix
        .strip_prefix("attempt:")
        .and_then(|suffix| suffix.strip_suffix(":user"))
        .and_then(|attempt| attempt.parse::<u64>().ok())
        .filter(|attempt| *attempt >= 2)
        .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
    if suffix != format!("attempt:{attempt}:user") {
        return Err(ApplicationError::CordisDraftScopeMismatch);
    }
    Ok(Some(attempt))
}

impl CordisMissionDraft {
    /// Return `None` when this Session has never consumed the requested input.
    /// Once that identity is present, every mismatch fails closed.
    pub fn from_completed_session(
        checkpoint: &SessionCheckpoint,
        expected_user_message_id: &str,
    ) -> Result<Option<Self>, ApplicationError> {
        SessionLog::restore(checkpoint.header.clone(), checkpoint.events.clone())
            .map_err(|_| ApplicationError::CordisDraftSessionInvalid)?;

        let mut open_turn = None;
        let mut matching_turn = None;
        let mut request_header = None;
        let mut assistant_messages = Vec::new();
        for event in &checkpoint.events {
            match &event.kind {
                SessionEventKind::TurnStart { turn } => {
                    open_turn = Some(*turn);
                    request_header = None;
                    assistant_messages.clear();
                }
                SessionEventKind::UserMessage { message, .. }
                    if message.id == expected_user_message_id =>
                {
                    if message.role != SessionMessageRole::User
                        || message.source != SessionMessageSource::User
                        || open_turn.is_none()
                        || matching_turn.is_some()
                    {
                        return Err(ApplicationError::CordisDraftScopeMismatch);
                    }
                    matching_turn = open_turn;
                }
                SessionEventKind::RequestHeader { request } if open_turn == matching_turn => {
                    request_header = Some(request.clone());
                }
                SessionEventKind::AssistantMessage {
                    turn,
                    step,
                    message,
                    ..
                } if Some(*turn) == matching_turn => {
                    assistant_messages.push((*step, message.clone()));
                }
                SessionEventKind::TurnEnd { turn, reason } if Some(*turn) == matching_turn => {
                    if *reason != TurnEndReason::Completed {
                        return Err(ApplicationError::CordisDraftTurnNotCompleted);
                    }
                    let header = request_header
                        .as_ref()
                        .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
                    return Self::from_closed_turn(
                        checkpoint.header.id.as_str(),
                        *turn,
                        expected_user_message_id,
                        header,
                        &assistant_messages,
                    )
                    .map(Some);
                }
                SessionEventKind::TurnEnd { turn, .. } if open_turn == Some(*turn) => {
                    open_turn = None;
                }
                _ => {}
            }
        }
        if matching_turn.is_some() {
            Err(ApplicationError::CordisDraftTurnNotCompleted)
        } else {
            Ok(None)
        }
    }

    fn from_closed_turn(
        session_id: &str,
        turn: u64,
        user_message_id: &str,
        request: &SessionRequestHeader,
        messages: &[(u64, hartevo_cordis::SessionMessage)],
    ) -> Result<Self, ApplicationError> {
        let (step, message) = messages
            .iter()
            .max_by_key(|(step, _)| *step)
            .ok_or(ApplicationError::CordisDraftMessageMissing)?;
        if messages
            .iter()
            .filter(|(candidate, _)| candidate == step)
            .count()
            != 1
            || message.role != SessionMessageRole::Assistant
        {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        }
        let SessionMessageSource::Model { provider, model } = &message.source else {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        };
        if request.header.config.provider != *provider || request.header.config.model != *model {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        }
        let system_prompt = request
            .header
            .system
            .as_deref()
            .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
        let mut body = String::new();
        for block in &message.content {
            match block {
                SessionContentBlock::Text { text } => body.push_str(text),
                SessionContentBlock::Reasoning { .. } => {}
                SessionContentBlock::ToolCall { .. } | SessionContentBlock::ToolResult { .. } => {
                    return Err(ApplicationError::CordisDraftScopeMismatch);
                }
            }
        }
        if body.trim().is_empty() {
            return Err(ApplicationError::CordisDraftMessageMissing);
        }
        Ok(Self {
            session_id: session_id.to_owned(),
            turn,
            provider: provider.clone(),
            model: model.clone(),
            system_prompt_digest: sha256(system_prompt.as_bytes()),
            body_digest: sha256(body.as_bytes()),
            body,
            user_message_id: user_message_id.to_owned(),
        })
    }
}

