#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum MissionCheckpointDispatchState {
    Ready,
    Blocked,
    WaitingUser,
    WaitingApproval,
    Verifying,
}

impl TryFrom<MissionCheckpointStatus> for MissionCheckpointDispatchState {
    type Error = ApplicationError;

    fn try_from(status: MissionCheckpointStatus) -> Result<Self, Self::Error> {
        match status {
            MissionCheckpointStatus::Running => Ok(Self::Ready),
            MissionCheckpointStatus::Blocked => Ok(Self::Blocked),
            MissionCheckpointStatus::WaitingUser => Ok(Self::WaitingUser),
            MissionCheckpointStatus::WaitingApproval => Ok(Self::WaitingApproval),
            MissionCheckpointStatus::Verifying => Ok(Self::Verifying),
            MissionCheckpointStatus::Pending
            | MissionCheckpointStatus::Ready
            | MissionCheckpointStatus::Completed
            | MissionCheckpointStatus::Skipped => {
                Err(ApplicationError::MissionCheckpointDispatchUnavailable)
            }
        }
    }
}

/// Content-free proof of the exact current Catalog Checkpoint route. A
/// `Ready` Checkpoint is first started with its route-bound Task in the same
/// durable boundary used by `begin_mission_checkpoint`; callers may then
/// select only the returned executor. This proof does not claim that an
/// Application, Effect Broker, Runtime, or Human handler completed any work.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MissionCheckpointDispatch {
    pub project_id: ProjectId,
    pub mission_id: MissionId,
    pub mission_revision: u64,
    pub cycle: u64,
    pub checkpoint_id: String,
    pub checkpoint_revision: u64,
    pub capability_id: String,
    pub executor: MissionCheckpointExecutor,
    pub oracle_ids: BTreeSet<String>,
    pub completion_policy: MissionCheckpointCompletionPolicy,
    /// Present only for an Application route. `Implemented` means the exact
    /// versioned handler is present in both the machine registry and this
    /// binary; absence from the allow-list is explicitly `NotImplemented`.
    #[serde(default)]
    pub application_handler_status: Option<ApplicationCheckpointHandlerStatus>,
    #[serde(default)]
    pub application_handler_id: Option<String>,
    pub state: MissionCheckpointDispatchState,
}

