#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CompiledApplicationCheckpointHandler {
    LocalProjectIdentity,
    LocalProjectInventory,
    LocalEncryptionWorkspaceReady,
    EventIngest,
    NormalizeDedupeOrder,
    IdentityChain,
    MissionSpecificKpi,
    AttributionAndUnattributed,
    RefundCommissionPayoutRecalc,
    OutcomeReview,
    NextContractOrValidTerminal,
}

impl CompiledApplicationCheckpointHandler {
    fn handler_id(self) -> &'static str {
        match self {
            Self::LocalProjectIdentity => VM00_LOCAL_PROJECT_IDENTITY_HANDLER_ID,
            Self::LocalProjectInventory => VM00_LOCAL_PROJECT_INVENTORY_HANDLER_ID,
            Self::LocalEncryptionWorkspaceReady => VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID,
            Self::EventIngest => VM11_EVENT_INGEST_HANDLER_ID,
            Self::NormalizeDedupeOrder => VM11_NORMALIZE_DEDUPE_ORDER_HANDLER_ID,
            Self::IdentityChain => VM11_IDENTITY_CHAIN_HANDLER_ID,
            Self::MissionSpecificKpi => VM11_MISSION_SPECIFIC_KPI_HANDLER_ID,
            Self::AttributionAndUnattributed => VM11_ATTRIBUTION_AND_UNATTRIBUTED_HANDLER_ID,
            Self::RefundCommissionPayoutRecalc => VM11_REFUND_COMMISSION_PAYOUT_RECALC_HANDLER_ID,
            Self::OutcomeReview => VM11_OUTCOME_REVIEW_HANDLER_ID,
            Self::NextContractOrValidTerminal => VM11_NEXT_CONTRACT_OR_VALID_TERMINAL_HANDLER_ID,
        }
    }

    fn primary_source_kind(self) -> &'static str {
        match self {
            Self::LocalProjectIdentity => "project_scope",
            Self::LocalProjectInventory => "project_inventory",
            Self::LocalEncryptionWorkspaceReady => "project_keyring",
            Self::EventIngest => "outcome_ledger",
            Self::NormalizeDedupeOrder => "outcome_normalization",
            Self::IdentityChain => "outcome_identity_chain",
            Self::MissionSpecificKpi => "outcome_mission_kpi",
            Self::AttributionAndUnattributed => "outcome_attribution",
            Self::RefundCommissionPayoutRecalc => "outcome_settlement",
            Self::OutcomeReview => "outcome_review",
            Self::NextContractOrValidTerminal => "outcome_review_decision",
        }
    }
}

#[derive(Clone, Debug)]
struct OutcomeIdentityChainSupport {
    connections: Vec<ConnectionSnapshot>,
    identity_links: Vec<IdentityLink>,
    people: Vec<Person>,
    companies: Vec<Company>,
    partners: Vec<Partner>,
    opportunities: Vec<Opportunity>,
}

impl OutcomeIdentityChainSupport {
    fn revision_fences(&self) -> Vec<ApplicationSourceRevisionFence> {
        self.connections
            .iter()
            .map(|item| {
                ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Connection,
                    item.id.to_string(),
                    item.revision,
                )
            })
            .chain(self.identity_links.iter().map(|item| {
                ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::IdentityLink,
                    item.id.to_string(),
                    item.revision,
                )
            }))
            .chain(self.people.iter().map(|item| {
                ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Person,
                    item.id.to_string(),
                    item.revision,
                )
            }))
            .chain(self.companies.iter().map(|item| {
                ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Company,
                    item.id.to_string(),
                    item.revision,
                )
            }))
            .chain(self.partners.iter().map(|item| {
                ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Partner,
                    item.id.to_string(),
                    item.revision,
                )
            }))
            .chain(self.opportunities.iter().map(|item| {
                ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Opportunity,
                    item.id.to_string(),
                    item.revision,
                )
            }))
            .collect()
    }
}

#[derive(Debug)]
enum OutcomeIdentityChainSupportLoadError {
    Missing {
        kind: ApplicationSourceKind,
        id: String,
    },
    Storage(StorageError),
}

fn required_identity_support_record<T>(
    result: Result<T, StorageError>,
    kind: ApplicationSourceKind,
    id: &str,
) -> Result<T, OutcomeIdentityChainSupportLoadError> {
    match result {
        Ok(value) => Ok(value),
        Err(StorageError::ScopedRecordNotFound { .. }) => {
            Err(OutcomeIdentityChainSupportLoadError::Missing {
                kind,
                id: id.into(),
            })
        }
        Err(error) => Err(OutcomeIdentityChainSupportLoadError::Storage(error)),
    }
}

#[allow(
    clippy::too_many_lines,
    reason = "the loader follows the complete transitive identity closure and performs no project-wide convenience reads"
)]
fn load_outcome_identity_chain_support(
    store: &ProjectStore,
    ledger: &OutcomeLedger,
) -> Result<OutcomeIdentityChainSupport, OutcomeIdentityChainSupportLoadError> {
    let connection_ids = ledger
        .events
        .iter()
        .filter_map(|event| event.connection_id.clone())
        .collect::<BTreeSet<_>>();
    let identity_link_ids = ledger
        .events
        .iter()
        .filter_map(|event| event.identity_link_id.clone())
        .collect::<BTreeSet<_>>();
    let opportunity_ids = ledger
        .events
        .iter()
        .filter_map(|event| event.opportunity_id.clone())
        .collect::<BTreeSet<_>>();
    let mut partner_ids = ledger
        .events
        .iter()
        .filter_map(|event| event.partner_id.clone())
        .chain(
            ledger
                .commissions
                .iter()
                .map(|commission| commission.partner_id.clone()),
        )
        .collect::<BTreeSet<_>>();

    let mut connections = Vec::with_capacity(connection_ids.len());
    for id in connection_ids {
        let connection = required_identity_support_record(
            store.load_connection(&ledger.project_id, &id),
            ApplicationSourceKind::Connection,
            id.as_str(),
        )?;
        connections.push(connection.snapshot());
    }
    let mut identity_links = Vec::with_capacity(identity_link_ids.len());
    let mut person_ids = BTreeSet::<PersonId>::new();
    let mut company_ids = BTreeSet::<CompanyId>::new();
    for id in identity_link_ids {
        let link = required_identity_support_record(
            store.load_identity_link(&ledger.project_id, &id),
            ApplicationSourceKind::IdentityLink,
            id.as_str(),
        )?;
        match &link.subject {
            IdentitySubject::Person(id) => {
                person_ids.insert(id.clone());
            }
            IdentitySubject::Company(id) => {
                company_ids.insert(id.clone());
            }
            IdentitySubject::Partner(id) => {
                partner_ids.insert(id.clone());
            }
        }
        identity_links.push(link);
    }

    let mut opportunities = Vec::with_capacity(opportunity_ids.len());
    for id in opportunity_ids {
        let opportunity = required_identity_support_record(
            store.load_opportunity(&ledger.project_id, &id),
            ApplicationSourceKind::Opportunity,
            id.as_str(),
        )?;
        company_ids.insert(opportunity.company_id.clone());
        person_ids.extend(
            opportunity
                .buying_committee
                .iter()
                .map(|member| member.person_id.clone()),
        );
        opportunities.push(opportunity);
    }

    let mut partners = Vec::with_capacity(partner_ids.len());
    for id in partner_ids {
        let partner = required_identity_support_record(
            store.load_partner(&ledger.project_id, &id),
            ApplicationSourceKind::Partner,
            id.as_str(),
        )?;
        if let Some(person_id) = &partner.person_id {
            person_ids.insert(person_id.clone());
        }
        if let Some(company_id) = &partner.company_id {
            company_ids.insert(company_id.clone());
        }
        partners.push(partner);
    }

    let mut people = Vec::with_capacity(person_ids.len());
    for id in person_ids {
        let person = required_identity_support_record(
            store.load_person(&ledger.project_id, &id),
            ApplicationSourceKind::Person,
            id.as_str(),
        )?;
        if let Some(company_id) = &person.company_id {
            company_ids.insert(company_id.clone());
        }
        people.push(person);
    }

    let mut companies = Vec::with_capacity(company_ids.len());
    for id in company_ids {
        companies.push(required_identity_support_record(
            store.load_company(&ledger.project_id, &id),
            ApplicationSourceKind::Company,
            id.as_str(),
        )?);
    }

    Ok(OutcomeIdentityChainSupport {
        connections,
        identity_links,
        people,
        companies,
        partners,
        opportunities,
    })
}

fn vm11_inherits_exact_parent_contract(mission: &Mission, parent: &Mission) -> bool {
    let Some(mission_definition) = mission.definition.as_ref() else {
        return false;
    };
    mission.tenant_id == parent.tenant_id
        && mission.project_id == parent.project_id
        && mission.id != parent.id
        && mission.contract.parent_mission_id.as_ref() == Some(&parent.id)
        && parent.definition.as_ref().is_some_and(|definition| {
            definition.manifest_id != "VM-11"
                && definition.catalog_digest == mission_definition.catalog_digest
        })
        && parent.contract.parent_mission_id.is_none()
        && !parent.contract.kpis.is_empty()
        && mission.contract.mode == parent.contract.mode
        && mission.contract.market == parent.contract.market
        && mission.contract.language == parent.contract.language
        && mission.contract.audience == parent.contract.audience
        && mission.contract.timezone == parent.contract.timezone
        && mission.contract.budget == parent.contract.budget
        && mission.contract.kpis == parent.contract.kpis
}

fn compiled_application_checkpoint_handler(
    handler_id: &str,
) -> Option<CompiledApplicationCheckpointHandler> {
    match handler_id {
        VM00_LOCAL_PROJECT_IDENTITY_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::LocalProjectIdentity)
        }
        VM00_LOCAL_PROJECT_INVENTORY_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::LocalProjectInventory)
        }
        VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::LocalEncryptionWorkspaceReady)
        }
        VM11_EVENT_INGEST_HANDLER_ID => Some(CompiledApplicationCheckpointHandler::EventIngest),
        VM11_NORMALIZE_DEDUPE_ORDER_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::NormalizeDedupeOrder)
        }
        VM11_IDENTITY_CHAIN_HANDLER_ID => Some(CompiledApplicationCheckpointHandler::IdentityChain),
        VM11_MISSION_SPECIFIC_KPI_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::MissionSpecificKpi)
        }
        VM11_ATTRIBUTION_AND_UNATTRIBUTED_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::AttributionAndUnattributed)
        }
        VM11_REFUND_COMMISSION_PAYOUT_RECALC_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc)
        }
        VM11_OUTCOME_REVIEW_HANDLER_ID => Some(CompiledApplicationCheckpointHandler::OutcomeReview),
        VM11_NEXT_CONTRACT_OR_VALID_TERMINAL_HANDLER_ID => {
            Some(CompiledApplicationCheckpointHandler::NextContractOrValidTerminal)
        }
        _ => None,
    }
}

fn vm11_next_contract_authorization_code(
    intent: OutcomeReviewNextContractIntent,
) -> Option<&'static str> {
    match intent {
        OutcomeReviewNextContractIntent::ScaleWithRevisedContract => {
            Some("revised_contract_authorization_required")
        }
        OutcomeReviewNextContractIntent::TestWithNewExperiment => {
            Some("experiment_contract_authorization_required")
        }
        OutcomeReviewNextContractIntent::ValidTerminal
        | OutcomeReviewNextContractIntent::ContinueCurrentContract => None,
    }
}

fn next_contract_intent_name(intent: OutcomeReviewNextContractIntent) -> &'static str {
    match intent {
        OutcomeReviewNextContractIntent::ValidTerminal => "valid_terminal",
        OutcomeReviewNextContractIntent::ContinueCurrentContract => "continue_current_contract",
        OutcomeReviewNextContractIntent::ScaleWithRevisedContract => "scale_with_revised_contract",
        OutcomeReviewNextContractIntent::TestWithNewExperiment => "test_with_new_experiment",
    }
}

fn application_checkpoint_handler_projection(
    definition: &MissionDefinition,
    checkpoint_id: &str,
    route: &MissionCheckpointRoute,
) -> Result<(Option<ApplicationCheckpointHandlerStatus>, Option<String>), ApplicationError> {
    if route.executor != MissionCheckpointExecutor::Application {
        return Ok((None, None));
    }
    let catalog = Catalog::load()?;
    let catalog_digest = catalog.snapshot()?.digest;
    if definition.catalog_digest != catalog_digest {
        return Ok((
            Some(ApplicationCheckpointHandlerStatus::CatalogRevisionMismatch),
            None,
        ));
    }
    let Some(handler) = catalog.application_handler(
        &definition.manifest_id,
        definition.manifest_version,
        checkpoint_id,
    ) else {
        return Ok((
            Some(ApplicationCheckpointHandlerStatus::NotImplemented),
            None,
        ));
    };
    if compiled_application_checkpoint_handler(&handler.handler_id).is_none() {
        return Err(
            ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                handler_id: handler.handler_id.clone(),
            },
        );
    }
    Ok((
        Some(ApplicationCheckpointHandlerStatus::Implemented),
        Some(handler.handler_id.clone()),
    ))
}

fn compiled_handler_for_checkpoint(
    mission: &Mission,
    checkpoint_id: &str,
) -> Result<Option<CompiledApplicationCheckpointHandler>, ApplicationError> {
    let definition = mission
        .definition
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let checkpoint = definition
        .checkpoints
        .iter()
        .find(|checkpoint| checkpoint.id == checkpoint_id)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let route = checkpoint
        .route
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    if route.executor != MissionCheckpointExecutor::Application {
        return Err(ApplicationError::ApplicationCheckpointExecutorMismatch {
            executor: route.executor,
        });
    }
    let (status, handler_id) =
        application_checkpoint_handler_projection(definition, checkpoint_id, route)?;
    match (status, handler_id) {
        (Some(ApplicationCheckpointHandlerStatus::Implemented), Some(handler_id)) => {
            compiled_application_checkpoint_handler(&handler_id)
                .map(Some)
                .ok_or(
                    ApplicationError::ApplicationCheckpointHandlerRegistryMismatch { handler_id },
                )
        }
        (Some(ApplicationCheckpointHandlerStatus::NotImplemented), None) => Ok(None),
        (Some(ApplicationCheckpointHandlerStatus::CatalogRevisionMismatch), None) => {
            Err(ApplicationError::ApplicationCheckpointCatalogRevisionMismatch)
        }
        (_, handler_id) => Err(
            ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                handler_id: handler_id.unwrap_or_else(|| "missing-registered-handler-id".into()),
            },
        ),
    }
}

fn current_checkpoint_dispatch_projection(
    mission: &Mission,
) -> Result<Option<MissionCheckpointDispatch>, ApplicationError> {
    if mission.stage.is_terminal() {
        return Ok(None);
    }
    let Some(definition) = mission.definition.as_ref() else {
        return Err(ApplicationError::MissionCheckpointDispatchUnavailable);
    };
    let Some(checkpoint) = definition.current_checkpoint() else {
        return Ok(None);
    };
    let route = checkpoint
        .route
        .as_ref()
        .filter(|route| route.is_contracted())
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let completion_policy = route
        .completion_policy
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let state = MissionCheckpointDispatchState::try_from(checkpoint.status)?;
    let (application_handler_status, application_handler_id) =
        application_checkpoint_handler_projection(definition, &checkpoint.id, route)?;
    if state == MissionCheckpointDispatchState::Ready
        && !mission.tasks.iter().any(|task| {
            task.status == TaskStatus::Running && task.capability == route.capability_id
        })
    {
        return Err(ApplicationError::MissionCheckpointDispatchUnavailable);
    }
    Ok(Some(MissionCheckpointDispatch {
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        mission_revision: mission.revision,
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        oracle_ids: route.oracle_ids.clone(),
        completion_policy,
        application_handler_status,
        application_handler_id,
        state,
    }))
}

type StartedCatalogCheckpoint = (String, u64, String, MissionCheckpointExecutor, TaskId, u64);

fn start_ready_catalog_checkpoint_in_memory(
    mission: &mut Mission,
    now: DateTime<Utc>,
) -> Result<Option<StartedCatalogCheckpoint>, ApplicationError> {
    let next = mission.definition.as_ref().and_then(|definition| {
        definition
            .current_checkpoint()
            .filter(|checkpoint| checkpoint.status == MissionCheckpointStatus::Ready)
            .and_then(|checkpoint| {
                checkpoint.route.as_ref().map(|route| {
                    (
                        definition.cycle,
                        checkpoint.id.clone(),
                        route.capability_id.clone(),
                        route.executor,
                    )
                })
            })
    });
    let Some((cycle, checkpoint_id, capability_id, executor)) = next else {
        return Ok(None);
    };
    let task_id = TaskId::from_stable(format!(
        "mission-checkpoint-task:{}:{checkpoint_id}:cycle:{cycle}",
        mission.id
    ));
    mission.begin_checkpoint_with_task(
        &checkpoint_id,
        Task {
            id: task_id.clone(),
            title: format!("Checkpoint: {checkpoint_id}"),
            status: TaskStatus::Running,
            capability: capability_id.clone(),
        },
        now,
    )?;
    let checkpoint_revision = mission
        .definition
        .as_ref()
        .and_then(MissionDefinition::current_checkpoint)
        .filter(|checkpoint| checkpoint.id == checkpoint_id)
        .map(|checkpoint| checkpoint.revision)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    Ok(Some((
        checkpoint_id,
        checkpoint_revision,
        capability_id,
        executor,
        task_id,
        cycle,
    )))
}

fn completed_application_checkpoint_replay(
    mission: &Mission,
    command: &ExecuteApplicationMissionCheckpoint,
    handler_id: &str,
    outcome_source_kind: &str,
) -> Result<Option<ApplicationMissionCheckpointExecution>, ApplicationError> {
    let Some(completion) = mission
        .definition
        .as_ref()
        .and_then(|definition| {
            definition.checkpoints.iter().find(|checkpoint| {
                checkpoint.id == command.checkpoint_id
                    && checkpoint.status == MissionCheckpointStatus::Completed
            })
        })
        .and_then(|checkpoint| checkpoint.completion.as_ref())
    else {
        return Ok(None);
    };
    let Some(evidence) = completion.application_evidence.as_ref() else {
        return Err(ApplicationError::ApplicationCheckpointReplayMismatch);
    };
    if evidence.handler_id != handler_id
        || evidence.dispatch_mission_revision != command.expected_mission_revision
        || evidence.dispatch_checkpoint_revision != command.expected_checkpoint_revision
        || evidence.checkpoint_id != command.checkpoint_id
    {
        return Err(ApplicationError::ApplicationCheckpointReplayMismatch);
    }
    let outcome_ledger_revision = evidence
        .sources
        .iter()
        .find(|source| source.source_kind == outcome_source_kind)
        .map(|source| source.source_revision)
        .ok_or(ApplicationError::ApplicationCheckpointReplayMismatch)?;
    Ok(Some(ApplicationMissionCheckpointExecution::Completed {
        completed_checkpoint_id: command.checkpoint_id.clone(),
        completion_evidence_digest: completion.evidence_digest.clone(),
        outcome_ledger_revision,
        replayed: true,
        next_dispatch: current_checkpoint_dispatch_projection(mission)?,
    }))
}

fn blocked_application_checkpoint_replay(
    store: &ProjectStore,
    mission: &Mission,
    command: &ExecuteApplicationMissionCheckpoint,
    handler_id: &str,
) -> Result<Option<ApplicationMissionCheckpointExecution>, ApplicationError> {
    if mission.stage != MissionStage::Blocked {
        return Ok(None);
    }
    let Some(event) = store
        .events_for_mission(&command.project_id, &command.mission_id)?
        .into_iter()
        .rev()
        .find(|event| {
            event.event_type == "mission.application_checkpoint_blocked"
                && event
                    .payload
                    .get("handlerId")
                    .and_then(serde_json::Value::as_str)
                    == Some(handler_id)
                && event
                    .payload
                    .get("checkpointId")
                    .and_then(serde_json::Value::as_str)
                    == Some(command.checkpoint_id.as_str())
                && event
                    .payload
                    .get("dispatchMissionRevision")
                    .and_then(serde_json::Value::as_u64)
                    == Some(command.expected_mission_revision)
                && event
                    .payload
                    .get("dispatchCheckpointRevision")
                    .and_then(serde_json::Value::as_u64)
                    == Some(command.expected_checkpoint_revision)
        })
    else {
        return Ok(None);
    };
    let code = event
        .payload
        .get("code")
        .and_then(serde_json::Value::as_str)
        .filter(|code| {
            mission
                .block
                .as_ref()
                .is_some_and(|block| block.code == *code)
        })
        .ok_or(ApplicationError::ApplicationCheckpointReplayMismatch)?;
    let outcome_ledger_revision = event
        .payload
        .get("outcomeLedgerRevision")
        .and_then(serde_json::Value::as_u64)
        .ok_or(ApplicationError::ApplicationCheckpointReplayMismatch)?;
    Ok(Some(ApplicationMissionCheckpointExecution::Blocked {
        checkpoint_id: command.checkpoint_id.clone(),
        code: code.into(),
        outcome_ledger_revision,
        replayed: true,
    }))
}

fn vm00_local_project_identity_application_evidence(
    mission: &Mission,
    project: &Project,
    route: &MissionCheckpointRoute,
    command: &ExecuteApplicationMissionCheckpoint,
    now: DateTime<Utc>,
) -> Result<MissionCheckpointApplicationEvidence, ApplicationError> {
    let definition = mission
        .definition
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let checkpoint = definition
        .checkpoints
        .iter()
        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    if project.tenant_id != mission.tenant_id || project.id != mission.project_id {
        return Err(StorageError::TenantScopeMismatch.into());
    }
    if definition.manifest_id != "VM-00"
        || definition.manifest_version != 3
        || checkpoint.id != "identity.resolve"
        || project.revision == 0
        || matches!(&project.storage_mode, StorageMode::Cloud)
    {
        return Err(ApplicationError::ApplicationCheckpointCommandMismatch);
    }
    let contract_digest = canonical_sha256(&serde_json::to_value(&mission.contract)?)?;
    let operating_state_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-application-checkpoint-state/v1",
        "tenantId": mission.tenant_id,
        "projectId": mission.project_id,
        "missionId": mission.id,
        "manifestId": definition.manifest_id,
        "manifestVersion": definition.manifest_version,
        "catalogDigest": definition.catalog_digest,
        "cycle": definition.cycle,
        "checkpointId": checkpoint.id,
        "dispatchMissionRevision": command.expected_mission_revision,
        "dispatchCheckpointRevision": command.expected_checkpoint_revision,
        "verificationMissionRevision": mission.revision,
        "verificationCheckpointRevision": checkpoint.revision,
        "capabilityId": route.capability_id,
        "executor": route.executor,
        "completionPolicy": route.completion_policy,
    }))?;
    // Bind only non-content project scope. Names, descriptions and workspace
    // paths stay in the encrypted Project aggregate and never enter evidence.
    let project_scope_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-vm00-local-project-scope/v1",
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "revision": project.revision,
        "storageMode": project.storage_mode,
        "dataCell": project.data_cell,
    }))?;
    Ok(MissionCheckpointApplicationEvidence {
        schema_version: MissionCheckpointApplicationEvidence::SCHEMA_VERSION,
        handler_id: VM00_LOCAL_PROJECT_IDENTITY_HANDLER_ID.into(),
        tenant_id: mission.tenant_id.clone(),
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        manifest_id: definition.manifest_id.clone(),
        manifest_version: definition.manifest_version,
        catalog_digest: definition.catalog_digest.clone(),
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        dispatch_mission_revision: command.expected_mission_revision,
        dispatch_checkpoint_revision: command.expected_checkpoint_revision,
        verification_mission_revision: mission.revision,
        verification_checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        completion_policy: route
            .completion_policy
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?,
        sources: BTreeSet::from([
            MissionCheckpointOracleSource {
                source_kind: "mission_contract".into(),
                source_id: mission.id.to_string(),
                source_revision: command.expected_mission_revision,
                projection_digest: contract_digest,
                oracle_ids: BTreeSet::from(["goal".into()]),
            },
            MissionCheckpointOracleSource {
                source_kind: "mission_checkpoint".into(),
                source_id: format!("{}:{}", mission.id, checkpoint.id),
                source_revision: command.expected_checkpoint_revision,
                projection_digest: operating_state_digest,
                oracle_ids: BTreeSet::from(["operating_state".into()]),
            },
            MissionCheckpointOracleSource {
                source_kind: "project_scope".into(),
                source_id: project.id.to_string(),
                source_revision: project.revision,
                projection_digest: project_scope_digest,
                oracle_ids: BTreeSet::from(["truth".into()]),
            },
        ]),
        observed_at: now,
    })
}

fn vm00_local_project_inventory_application_evidence(
    mission: &Mission,
    project: &Project,
    route: &MissionCheckpointRoute,
    command: &ExecuteApplicationMissionCheckpoint,
    now: DateTime<Utc>,
) -> Result<MissionCheckpointApplicationEvidence, ApplicationError> {
    let definition = mission
        .definition
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let checkpoint = definition
        .checkpoints
        .iter()
        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    if project.tenant_id != mission.tenant_id || project.id != mission.project_id {
        return Err(StorageError::TenantScopeMismatch.into());
    }
    if definition.manifest_id != "VM-00"
        || definition.manifest_version != 3
        || checkpoint.id != "project_inventory"
        || project.revision == 0
        || matches!(&project.storage_mode, StorageMode::Cloud)
        || project.workspace_roots.is_empty()
        || project
            .workspace_roots
            .iter()
            .any(|root| !root.is_absolute())
    {
        return Err(ApplicationError::ApplicationCheckpointCommandMismatch);
    }
    let mut workspace_roots = project.workspace_roots.iter().collect::<Vec<_>>();
    workspace_roots.sort();
    if workspace_roots.windows(2).any(|roots| roots[0] == roots[1]) {
        return Err(ApplicationError::ApplicationCheckpointCommandMismatch);
    }
    let operating_state_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-application-checkpoint-state/v1",
        "tenantId": mission.tenant_id,
        "projectId": mission.project_id,
        "missionId": mission.id,
        "manifestId": definition.manifest_id,
        "manifestVersion": definition.manifest_version,
        "catalogDigest": definition.catalog_digest,
        "cycle": definition.cycle,
        "checkpointId": checkpoint.id,
        "dispatchMissionRevision": command.expected_mission_revision,
        "dispatchCheckpointRevision": command.expected_checkpoint_revision,
        "verificationMissionRevision": mission.revision,
        "verificationCheckpointRevision": checkpoint.revision,
        "capabilityId": route.capability_id,
        "executor": route.executor,
        "completionPolicy": route.completion_policy,
    }))?;
    // Hash the exact persisted root set in deterministic order. Raw paths,
    // Project metadata, and Mission content never enter evidence or events.
    let project_inventory_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-vm00-local-project-inventory/v1",
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "revision": project.revision,
        "storageMode": project.storage_mode,
        "dataCell": project.data_cell,
        "workspaceRoots": workspace_roots,
    }))?;
    Ok(MissionCheckpointApplicationEvidence {
        schema_version: MissionCheckpointApplicationEvidence::SCHEMA_VERSION,
        handler_id: VM00_LOCAL_PROJECT_INVENTORY_HANDLER_ID.into(),
        tenant_id: mission.tenant_id.clone(),
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        manifest_id: definition.manifest_id.clone(),
        manifest_version: definition.manifest_version,
        catalog_digest: definition.catalog_digest.clone(),
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        dispatch_mission_revision: command.expected_mission_revision,
        dispatch_checkpoint_revision: command.expected_checkpoint_revision,
        verification_mission_revision: mission.revision,
        verification_checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        completion_policy: route
            .completion_policy
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?,
        sources: BTreeSet::from([
            MissionCheckpointOracleSource {
                source_kind: "mission_checkpoint".into(),
                source_id: format!("{}:{}", mission.id, checkpoint.id),
                source_revision: command.expected_checkpoint_revision,
                projection_digest: operating_state_digest,
                oracle_ids: BTreeSet::from(["operating_state".into()]),
            },
            MissionCheckpointOracleSource {
                source_kind: "project_inventory".into(),
                source_id: project.id.to_string(),
                source_revision: project.revision,
                projection_digest: project_inventory_digest,
                oracle_ids: BTreeSet::from(["truth".into()]),
            },
        ]),
        observed_at: now,
    })
}

fn vm00_local_encryption_workspace_ready_application_evidence(
    mission: &Mission,
    keyring: &ProjectKeyring,
    route: &MissionCheckpointRoute,
    command: &ExecuteApplicationMissionCheckpoint,
    now: DateTime<Utc>,
) -> Result<MissionCheckpointApplicationEvidence, ApplicationError> {
    let definition = mission
        .definition
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let checkpoint = definition
        .checkpoints
        .iter()
        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    if keyring.tenant_id != mission.tenant_id || keyring.project_id != mission.project_id {
        return Err(StorageError::TenantScopeMismatch.into());
    }
    if definition.manifest_id != "VM-00"
        || definition.manifest_version != 3
        || checkpoint.id != "encryption_workspace_ready"
        || keyring.revision == 0
        || keyring.active_key_version == 0
        || !keyring.is_workspace_ready_at(now)?
    {
        return Err(ApplicationError::ApplicationCheckpointCommandMismatch);
    }
    let operating_state_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-application-checkpoint-state/v1",
        "tenantId": mission.tenant_id,
        "projectId": mission.project_id,
        "missionId": mission.id,
        "manifestId": definition.manifest_id,
        "manifestVersion": definition.manifest_version,
        "catalogDigest": definition.catalog_digest,
        "cycle": definition.cycle,
        "checkpointId": checkpoint.id,
        "dispatchMissionRevision": command.expected_mission_revision,
        "dispatchCheckpointRevision": command.expected_checkpoint_revision,
        "verificationMissionRevision": mission.revision,
        "verificationCheckpointRevision": checkpoint.revision,
        "capabilityId": route.capability_id,
        "executor": route.executor,
        "completionPolicy": route.completion_policy,
    }))?;
    // Consume the exact keyring transiently but persist only its canonical
    // digest and public readiness coordinates. Envelope ciphertext, recipient
    // identifiers and wrapping-key references never enter Mission evidence.
    let project_keyring_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-vm00-project-keyring-readiness/v1",
        "tenantId": keyring.tenant_id,
        "projectId": keyring.project_id,
        "mode": keyring.mode,
        "activeKeyVersion": keyring.active_key_version,
        "remoteExecutionOptIn": keyring.remote_execution_opt_in,
        "rotationRequired": keyring.rotation_required,
        "keyringRevision": keyring.revision,
        "keyringDigest": keyring.canonical_digest()?,
        "observedAt": now,
    }))?;
    Ok(MissionCheckpointApplicationEvidence {
        schema_version: MissionCheckpointApplicationEvidence::SCHEMA_VERSION,
        handler_id: VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID.into(),
        tenant_id: mission.tenant_id.clone(),
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        manifest_id: definition.manifest_id.clone(),
        manifest_version: definition.manifest_version,
        catalog_digest: definition.catalog_digest.clone(),
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        dispatch_mission_revision: command.expected_mission_revision,
        dispatch_checkpoint_revision: command.expected_checkpoint_revision,
        verification_mission_revision: mission.revision,
        verification_checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        completion_policy: route
            .completion_policy
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?,
        sources: BTreeSet::from([
            MissionCheckpointOracleSource {
                source_kind: "mission_checkpoint".into(),
                source_id: format!("{}:{}", mission.id, checkpoint.id),
                source_revision: command.expected_checkpoint_revision,
                projection_digest: operating_state_digest,
                oracle_ids: BTreeSet::from(["operating_state".into()]),
            },
            MissionCheckpointOracleSource {
                source_kind: "project_keyring".into(),
                source_id: keyring.project_id.to_string(),
                source_revision: keyring.revision,
                projection_digest: project_keyring_digest,
                oracle_ids: BTreeSet::from(["truth".into()]),
            },
        ]),
        observed_at: now,
    })
}

#[allow(clippy::too_many_arguments)]
fn persist_vm00_project_keyring_block(
    store: &mut ProjectStore,
    mission: &mut Mission,
    expected_mission_revision: u64,
    command: &ExecuteApplicationMissionCheckpoint,
    dispatch: &MissionCheckpointDispatch,
    code: &str,
    detail: &str,
    source_revision: u64,
    source_fence: ApplicationSourceRevisionFence,
    now: DateTime<Utc>,
) -> Result<ApplicationMissionCheckpointExecution, ApplicationError> {
    if mission.stage == MissionStage::Blocked {
        mission.resume(now)?;
    }
    let block = hartevo_domain_kernel::MissionBlock {
        code: code.into(),
        detail: detail.into(),
        recoverable: true,
        observed_at: now,
    };
    mission.block_checkpoint(&command.checkpoint_id, &block, MissionStage::Blocked)?;
    store.update_mission_atomic_with_application_source_fences_only(
        mission,
        expected_mission_revision,
        &[source_fence],
        &[PendingEvent::new(
            "mission.application_checkpoint_blocked",
            serde_json::json!({
                "missionId": mission.id,
                "checkpointId": command.checkpoint_id,
                "capabilityId": dispatch.capability_id,
                "handlerId": VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID,
                "dispatchMissionRevision": command.expected_mission_revision,
                "dispatchCheckpointRevision": command.expected_checkpoint_revision,
                "code": code,
                "recoverable": true,
                "outcomeLedgerRevision": source_revision,
                "sourceKind": "project_keyring",
                "sourceRevision": source_revision,
                "sourceFenceCount": 1,
            }),
            now,
        )],
    )?;
    Ok(ApplicationMissionCheckpointExecution::Blocked {
        checkpoint_id: command.checkpoint_id.clone(),
        code: code.into(),
        outcome_ledger_revision: source_revision,
        replayed: false,
    })
}

#[allow(
    clippy::too_many_lines,
    reason = "the shared VM-00 Project transaction keeps evidence, completion, next-route start, source fence, and events in one atomic boundary"
)]
fn execute_vm00_local_project_checkpoint(
    store: &mut ProjectStore,
    mut mission: Mission,
    command: ExecuteApplicationMissionCheckpoint,
    dispatch: &MissionCheckpointDispatch,
    handler: CompiledApplicationCheckpointHandler,
    now: DateTime<Utc>,
) -> Result<ApplicationMissionCheckpointExecution, ApplicationError> {
    let expected_mission_revision = mission.revision;
    if mission.stage == MissionStage::Blocked {
        mission.resume(now)?;
    }
    mission.begin_checkpoint_verification(&command.checkpoint_id, now)?;
    let route = mission
        .definition
        .as_ref()
        .and_then(|definition| {
            definition
                .checkpoints
                .iter()
                .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        })
        .and_then(|checkpoint| checkpoint.route.clone())
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let (application_evidence, source_revision, source_fences) = match handler {
        CompiledApplicationCheckpointHandler::LocalProjectIdentity => {
            let project = store.load_project(&command.project_id)?;
            let evidence = vm00_local_project_identity_application_evidence(
                &mission, &project, &route, &command, now,
            )?;
            let revision = project.revision;
            (
                evidence,
                revision,
                vec![ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Project,
                    project.id.to_string(),
                    revision,
                )],
            )
        }
        CompiledApplicationCheckpointHandler::LocalProjectInventory => {
            let project = store.load_project(&command.project_id)?;
            let evidence = vm00_local_project_inventory_application_evidence(
                &mission, &project, &route, &command, now,
            )?;
            let revision = project.revision;
            (
                evidence,
                revision,
                vec![ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::Project,
                    project.id.to_string(),
                    revision,
                )],
            )
        }
        CompiledApplicationCheckpointHandler::LocalEncryptionWorkspaceReady => {
            let keyring = match store.load_project_keyring(&command.project_id) {
                Ok(keyring) => keyring,
                Err(StorageError::ScopedRecordNotFound {
                    kind: "project keyring",
                    ..
                }) => {
                    return persist_vm00_project_keyring_block(
                        store,
                        &mut mission,
                        expected_mission_revision,
                        &command,
                        dispatch,
                        "project_encryption_not_provisioned",
                        "Project encryption must be explicitly provisioned before this Mission can continue.",
                        0,
                        ApplicationSourceRevisionFence::absent(
                            ApplicationSourceKind::ProjectKeyring,
                            command.project_id.to_string(),
                        ),
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            };
            if keyring.tenant_id != mission.tenant_id || keyring.project_id != mission.project_id {
                return Err(StorageError::TenantScopeMismatch.into());
            }
            if !keyring.is_workspace_ready_at(now)? {
                let (code, detail) = if keyring.rotation_required {
                    (
                        "project_encryption_rotation_required",
                        "Project encryption requires an explicit key rotation before this Mission can continue.",
                    )
                } else {
                    (
                        "project_encryption_recipient_unavailable",
                        "Project encryption has no currently available mode-required recipient set.",
                    )
                };
                return persist_vm00_project_keyring_block(
                    store,
                    &mut mission,
                    expected_mission_revision,
                    &command,
                    dispatch,
                    code,
                    detail,
                    keyring.revision,
                    ApplicationSourceRevisionFence::present(
                        ApplicationSourceKind::ProjectKeyring,
                        keyring.project_id.to_string(),
                        keyring.revision,
                    ),
                    now,
                );
            }
            let evidence = vm00_local_encryption_workspace_ready_application_evidence(
                &mission, &keyring, &route, &command, now,
            )?;
            let revision = keyring.revision;
            (
                evidence,
                revision,
                vec![ApplicationSourceRevisionFence::present(
                    ApplicationSourceKind::ProjectKeyring,
                    keyring.project_id.to_string(),
                    revision,
                )],
            )
        }
        _ => return Err(ApplicationError::ApplicationCheckpointCommandMismatch),
    };
    validate_application_evidence_against_registry(&application_evidence)?;
    let evidence_digest = application_evidence.digest();
    mission.complete_checkpoint(
        &command.checkpoint_id,
        MissionCheckpointCompletion {
            oracle_ids: route.oracle_ids.clone(),
            work_product_ids: BTreeSet::new(),
            effect_ids: BTreeSet::new(),
            application_evidence: Some(application_evidence),
            evidence_digest: evidence_digest.clone(),
            verified_at: now,
        },
    )?;
    let completed_checkpoint_revision = mission
        .definition
        .as_ref()
        .and_then(|definition| {
            definition
                .checkpoints
                .iter()
                .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        })
        .map(|checkpoint| checkpoint.revision)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let next_started = start_ready_catalog_checkpoint_in_memory(&mut mission, now)?;
    let next_dispatch = current_checkpoint_dispatch_projection(&mission)?;
    let mut events = vec![PendingEvent::new(
        "mission.application_checkpoint_completed",
        serde_json::json!({
            "missionId": mission.id,
            "checkpointId": command.checkpoint_id,
            "checkpointRevision": completed_checkpoint_revision,
            "capabilityId": dispatch.capability_id,
            "handlerId": handler.handler_id(),
            "oracleIds": dispatch.oracle_ids,
            "sourceKind": handler.primary_source_kind(),
            "sourceRevision": source_revision,
            "sourceFenceCount": source_fences.len(),
            "evidenceDigest": evidence_digest,
        }),
        now,
    )];
    if let Some((checkpoint_id, checkpoint_revision, capability_id, executor, task_id, cycle)) =
        next_started
    {
        events.push(PendingEvent::new(
            "mission.checkpoint_started",
            serde_json::json!({
                "missionId": mission.id,
                "checkpointId": checkpoint_id,
                "checkpointRevision": checkpoint_revision,
                "capabilityId": capability_id,
                "executor": executor,
                "cycle": cycle,
                "taskId": task_id,
            }),
            now,
        ));
    }
    store.update_mission_atomic_with_application_source_fences_only(
        &mission,
        expected_mission_revision,
        &source_fences,
        &events,
    )?;
    Ok(ApplicationMissionCheckpointExecution::Completed {
        completed_checkpoint_id: command.checkpoint_id,
        completion_evidence_digest: evidence_digest,
        outcome_ledger_revision: source_revision,
        replayed: false,
        next_dispatch,
    })
}

fn vm11_event_ingest_application_evidence(
    mission: &Mission,
    route: &MissionCheckpointRoute,
    command: &ExecuteApplicationMissionCheckpoint,
    ledger: &OutcomeLedger,
    now: DateTime<Utc>,
) -> Result<MissionCheckpointApplicationEvidence, ApplicationError> {
    let definition = mission
        .definition
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let checkpoint = definition
        .checkpoints
        .iter()
        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let contract_digest = canonical_sha256(&serde_json::to_value(&mission.contract)?)?;
    // The canonical value is transient and only its digest is persisted. Bind
    // every structured identity, amount, relationship and source-verification
    // field instead of assuming the provider payload digest covers a parsed
    // projection supplied by a different boundary.
    let outcome_projection_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-vm11-event-ingest-source/v2",
        "ledger": ledger,
    }))?;
    let operating_state_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-application-checkpoint-state/v1",
        "tenantId": mission.tenant_id,
        "projectId": mission.project_id,
        "missionId": mission.id,
        "manifestId": definition.manifest_id,
        "manifestVersion": definition.manifest_version,
        "catalogDigest": definition.catalog_digest,
        "cycle": definition.cycle,
        "checkpointId": checkpoint.id,
        "dispatchMissionRevision": command.expected_mission_revision,
        "dispatchCheckpointRevision": command.expected_checkpoint_revision,
        "verificationMissionRevision": mission.revision,
        "verificationCheckpointRevision": checkpoint.revision,
        "capabilityId": route.capability_id,
        "executor": route.executor,
        "completionPolicy": route.completion_policy,
    }))?;
    let sources = BTreeSet::from([
        MissionCheckpointOracleSource {
            source_kind: "mission_contract".into(),
            source_id: mission.id.to_string(),
            source_revision: command.expected_mission_revision,
            projection_digest: contract_digest,
            oracle_ids: BTreeSet::from(["goal".into()]),
        },
        MissionCheckpointOracleSource {
            source_kind: "mission_checkpoint".into(),
            source_id: format!("{}:{}", mission.id, checkpoint.id),
            source_revision: command.expected_checkpoint_revision,
            projection_digest: operating_state_digest,
            oracle_ids: BTreeSet::from(["operating_state".into()]),
        },
        MissionCheckpointOracleSource {
            source_kind: "outcome_ledger".into(),
            source_id: ledger.project_id.to_string(),
            source_revision: ledger.revision,
            projection_digest: outcome_projection_digest,
            oracle_ids: BTreeSet::from(["outcome".into(), "truth".into()]),
        },
    ]);
    Ok(MissionCheckpointApplicationEvidence {
        schema_version: MissionCheckpointApplicationEvidence::SCHEMA_VERSION,
        handler_id: VM11_EVENT_INGEST_HANDLER_ID.into(),
        tenant_id: mission.tenant_id.clone(),
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        manifest_id: definition.manifest_id.clone(),
        manifest_version: definition.manifest_version,
        catalog_digest: definition.catalog_digest.clone(),
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        dispatch_mission_revision: command.expected_mission_revision,
        dispatch_checkpoint_revision: command.expected_checkpoint_revision,
        verification_mission_revision: mission.revision,
        verification_checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        completion_policy: route
            .completion_policy
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?,
        sources,
        observed_at: now,
    })
}

