    pub fn prepare_active_browser_recipe(
        &self,
        command: PrepareActiveBrowserRecipe,
        now: DateTime<Utc>,
    ) -> Result<PreparedDurableBrowserRecipe, ApplicationError> {
        let profile = self
            .store
            .load_browser_profile(&command.project_id, &command.profile_id)?;
        let workspace = self
            .store
            .load_browser_workspace(&command.project_id, &command.workspace_id)?;
        let mission = self
            .store
            .load_mission(&command.project_id, &workspace.mission_id)?;
        let runtime_state = self
            .store
            .load_browser_recipe_runtime_state(&command.project_id)?;
        let capability = &runtime_state
            .registry
            .active_release(&command.recipe_id)?
            .candidate
            .manifest
            .capability;
        if !mission.contract.enabled_capabilities.contains(capability)
            || mission.contract.forbidden_capabilities.contains(capability)
        {
            return Err(ApplicationError::Browser(BrowserError::RecipeScopeMismatch));
        }
        let resolved_actions = command
            .resolved_actions
            .iter()
            .map(|resolved| BrowserRecipeResolvedAction {
                action: &resolved.action,
                resolution: &resolved.resolution,
            })
            .collect::<Vec<_>>();
        let plan = runtime_state.registry.prepare_active_plan(
            &command.recipe_id,
            &runtime_state.trust,
            &profile,
            &workspace,
            command.policy_digest,
            &resolved_actions,
            now,
            command.expires_at,
        )?;
        Ok(PreparedDurableBrowserRecipe {
            runtime_state,
            plan,
        })
    }

