    pub fn record_connection_probe(
        &mut self,
        project_id: &ProjectId,
        connection_id: &ConnectionId,
        probe: ConnectionProbe,
        now: DateTime<Utc>,
    ) -> Result<Connection, ApplicationError> {
        let mut connection = self.store.load_connection(project_id, connection_id)?;
        let expected_revision = connection.revision();
        connection.begin_probe(now)?;
        let probing_revision = connection.revision();
        self.store.update_connection(
            &connection,
            expected_revision,
            "connection.probe_started",
            &serde_json::json!({"connectionId": connection_id}),
            now,
        )?;
        let status = connection.apply_probe(probe, now)?;
        self.store.update_connection(
            &connection,
            probing_revision,
            "connection.probed",
            &serde_json::json!({
                "connectionId": connection_id,
                "status": status,
                "probeEvidenceDigest": connection
                    .last_probe()
                    .map(|probe| &probe.evidence_digest),
            }),
            now,
        )?;
        Ok(connection)
    }

