    /// Content-free CRM Conversation facts for one Mission. Open Conversation
    /// uses only the live Person/Connection/gateway identity; Desktop never
    /// invents a Conversation or treats open as Effect or Verification.
    pub fn list_relationship_conversations_for_mission(
        &self,
        project_id: &ProjectId,
        mission_id: &MissionId,
    ) -> Result<Vec<RelationshipConversationProjection>, ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        if mission.project_id != *project_id {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        relationship_conversations_for_mission(&self.store, &mission)
    }

    pub fn open_conversation(
        &mut self,
        conversation: Conversation,
        now: DateTime<Utc>,
    ) -> Result<Conversation, ApplicationError> {
        conversation.validate().map_err(ApplicationError::from)?;
        if conversation.revision != 1
            || conversation.state != hartevo_domain_kernel::ConversationState::Open
            || !conversation.messages.is_empty()
            || conversation.mission_id.is_none()
        {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        let Some(mission_id) = conversation.mission_id.as_ref() else {
            return Err(ApplicationError::ConversationMissionRequired);
        };
        let mission = self
            .store
            .load_mission(&conversation.project_id, mission_id)?;
        if mission.tenant_id != conversation.tenant_id
            || mission.project_id != conversation.project_id
        {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        let person = self
            .store
            .load_person(&conversation.project_id, &conversation.person_id)?;
        if person.tenant_id != conversation.tenant_id
            || person.project_id != conversation.project_id
        {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        if conversation.company_id.as_ref() != person.company_id.as_ref() {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        if let Some(company_id) = conversation.company_id.as_ref() {
            let company = self
                .store
                .load_company(&conversation.project_id, company_id)?;
            if company.tenant_id != conversation.tenant_id
                || company.project_id != conversation.project_id
                || company.market != conversation.market
            {
                return Err(ApplicationError::ConversationOpenCommandMismatch);
            }
        }
        let connection = self
            .store
            .load_connection(&conversation.project_id, &conversation.connection_id)?;
        if connection.tenant_id() != &conversation.tenant_id
            || connection.project_id() != &conversation.project_id
            || connection.provider() != conversation.provider
            || connection.account_id() != &conversation.account_id
            || !connection.is_connected(now)
        {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        if !conversation
            .gateway
            .supports_provider(connection.provider())
        {
            return Err(ApplicationError::ConversationOpenCommandMismatch);
        }
        self.store.create_conversation(
            &conversation,
            "conversation.opened",
            &serde_json::json!({
                "conversationId": conversation.id,
                "missionId": conversation.mission_id,
                "personId": conversation.person_id,
                "gateway": conversation.gateway,
                "controlGeneration": conversation.control.generation(),
                "externalEffectExecuted": false,
                "verificationMinted": false,
            }),
            now,
        )?;
        Ok(conversation)
    }

    pub fn ingest_conversation_inbound(
        &mut self,
        project_id: &ProjectId,
        conversation_id: &ConversationId,
        input: InboundMessageInput,
        attestation: &WebhookAttestation,
    ) -> Result<(Conversation, InboundIngest), ApplicationError> {
        let mut conversation = self.store.load_conversation(project_id, conversation_id)?;
        let expected_revision = conversation.revision;
        let message_id = input.id.clone();
        let provider_event_digest = input.provider_event_digest.clone();
        let ingest = conversation.ingest_inbound(input, attestation)?;
        if ingest == InboundIngest::Inserted {
            let conversation_event = PendingEvent::new(
                "conversation.inbound_ingested",
                serde_json::json!({
                    "conversationId": conversation.id,
                    "messageId": &message_id,
                    "providerEventDigest": &provider_event_digest,
                    "state": conversation.state,
                }),
                attestation.received_at,
            );
            if let Some(mission_id) = conversation.mission_id.as_ref()
                && let Some(mut schedule) =
                    self.store.latest_mission_schedule(project_id, mission_id)?
                && schedule.status == MissionScheduleStatus::Pending
                && schedule.signal.is_none()
                && schedule.event_topics.contains("conversation.inbound")
            {
                let expected_schedule_revision = schedule.revision;
                let event_id_digest = sha256(message_id.as_str().as_bytes());
                schedule.signal_event(
                    "conversation.inbound",
                    event_id_digest.clone(),
                    provider_event_digest.clone(),
                    attestation.received_at,
                )?;
                self.store.update_conversation_and_signal_schedule_atomic(
                    &conversation,
                    expected_revision,
                    &schedule,
                    expected_schedule_revision,
                    &[conversation_event],
                    &[PendingEvent::new(
                        "mission.schedule_signalled",
                        serde_json::json!({
                            "scheduleId": schedule.id,
                            "missionId": schedule.mission_id,
                            "cycle": schedule.cycle,
                            "topic": "conversation.inbound",
                            "eventIdDigest": event_id_digest,
                            "payloadDigest": provider_event_digest,
                        }),
                        attestation.received_at,
                    )],
                )?;
                return Ok((conversation, ingest));
            }
            self.store.update_conversation(
                &conversation,
                expected_revision,
                &conversation_event.event_type,
                &conversation_event.payload,
                conversation_event.recorded_at,
            )?;
        }
        Ok((conversation, ingest))
    }

    pub fn prepare_conversation_reply_effect(
        &mut self,
        command: &PrepareConversationReplyEffect,
        now: DateTime<Utc>,
    ) -> Result<PreparedConversationReplyEffect, ApplicationError> {
        let mut conversation = self
            .store
            .load_conversation(&command.project_id, &command.conversation_id)?;
        let expected_conversation_revision = conversation.revision;
        if command.provider != conversation.provider
            || command.connection_id.as_ref() != Some(&conversation.connection_id)
            || command.account_id.as_ref() != Some(&conversation.account_id)
        {
            return Err(ApplicationError::InvalidConversationReplyEffect);
        }
        let mission_id = conversation
            .mission_id
            .clone()
            .ok_or(ApplicationError::ConversationMissionRequired)?;
        let mut mission = self.store.load_mission(&command.project_id, &mission_id)?;
        let expected_mission_revision = mission.revision;
        let generation = conversation.control.generation();
        let (prepared_reply, consent, consent_record_id, consent_requirement) =
            self.prepare_reply_with_authorization(&mut conversation, command, generation, now)?;
        let expires_at = now
            .checked_add_signed(command.expires_in)
            .ok_or(ApplicationError::InvalidConversationReplyEffect)?;
        let effect_id = mission.propose_effect(
            conversation_reply_effect_spec(
                &conversation,
                command,
                &prepared_reply,
                consent,
                consent_record_id,
                consent_requirement,
                expires_at,
            ),
            now,
        )?;
        let approval_digest = mission.effect(&effect_id)?.approval_digest();
        self.store.update_conversation_and_mission_atomic(
            &conversation,
            expected_conversation_revision,
            &mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "conversation.reply_prepared",
                serde_json::json!({
                    "conversationId": conversation.id,
                    "messageId": prepared_reply.message_id,
                    "effectId": prepared_reply.effect_id,
                    "controlGeneration": prepared_reply.control_generation,
                    "scopeDigest": prepared_reply.scope_digest,
                }),
                now,
            )],
            &[PendingEvent::new(
                "approval.requested",
                serde_json::json!({
                    "effectId": effect_id,
                    "scopeDigest": approval_digest,
                    "conversationId": conversation.id,
                    "conversationScopeDigest": prepared_reply.scope_digest,
                }),
                now,
            )],
        )?;
        Ok(PreparedConversationReplyEffect {
            conversation,
            mission,
            prepared_reply,
        })
    }

    fn prepare_reply_with_authorization(
        &self,
        conversation: &mut Conversation,
        command: &PrepareConversationReplyEffect,
        generation: u64,
        now: DateTime<Utc>,
    ) -> Result<
        (
            PreparedAutomaticReply,
            ConsentState,
            Option<ConsentRecordId>,
            Option<ConsentRequirement>,
        ),
        ApplicationError,
    > {
        match &command.authorization {
            ReplyAuthorization::Consent(record_id) => {
                let record = self
                    .store
                    .load_consent_record(&command.project_id, record_id)?;
                let prepared = conversation.prepare_automatic_reply(
                    command.message_id.clone(),
                    command.content_digest.clone(),
                    command.effect_id.clone(),
                    generation,
                    AutomatedReplyAuthorization::Consent(&record),
                    now,
                )?;
                Ok((
                    prepared,
                    ConsentState::Confirmed,
                    Some(record.id),
                    Some(ConsentRequirement {
                        person_id: conversation.person_id.clone(),
                        purpose: ConsentPurpose::AutomatedReply,
                        channel: conversation.contact_channel.clone(),
                        market: conversation.market.clone(),
                    }),
                ))
            }
            ReplyAuthorization::NotRequired { evidence_digest } => {
                let prepared = conversation.prepare_automatic_reply(
                    command.message_id.clone(),
                    command.content_digest.clone(),
                    command.effect_id.clone(),
                    generation,
                    AutomatedReplyAuthorization::NotRequired { evidence_digest },
                    now,
                )?;
                Ok((prepared, ConsentState::NotRequired, None, None))
            }
        }
    }

    pub fn take_human_conversation_control(
        &mut self,
        project_id: &ProjectId,
        conversation_id: &ConversationId,
        expected_generation: u64,
        actor_id: ActorId,
        now: DateTime<Utc>,
    ) -> Result<Conversation, ApplicationError> {
        let mut conversation = self.store.load_conversation(project_id, conversation_id)?;
        let expected_revision = conversation.revision;
        let pending_effect_ids = conversation
            .messages
            .iter()
            .filter_map(|message| match &message.delivery {
                MessageDelivery::EffectPrepared { effect_id } => Some(effect_id.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let generation = conversation.take_human_control(expected_generation, actor_id, now)?;
        if pending_effect_ids.is_empty() {
            self.store.update_conversation(
                &conversation,
                expected_revision,
                "conversation.human_control_acquired",
                &serde_json::json!({
                    "conversationId": conversation.id,
                    "controlGeneration": generation,
                }),
                now,
            )?;
        } else {
            let mission_id = conversation
                .mission_id
                .clone()
                .ok_or(ApplicationError::ConversationMissionRequired)?;
            let mut mission = self.store.load_mission(project_id, &mission_id)?;
            let expected_mission_revision = mission.revision;
            for effect_id in &pending_effect_ids {
                mission.cancel_effect(effect_id, now)?;
            }
            self.store.update_conversation_and_mission_atomic(
                &conversation,
                expected_revision,
                &mission,
                expected_mission_revision,
                &[PendingEvent::new(
                    "conversation.human_control_acquired",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "controlGeneration": generation,
                        "cancelledEffectIds": pending_effect_ids,
                    }),
                    now,
                )],
                &[PendingEvent::new(
                    "effect.cancelled_by_handoff",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "effectIds": pending_effect_ids,
                        "controlGeneration": generation,
                    }),
                    now,
                )],
            )?;
        }
        Ok(conversation)
    }

    pub fn pause_conversation_agent(
        &mut self,
        project_id: &ProjectId,
        conversation_id: &ConversationId,
        expected_generation: u64,
        reason_digest: &str,
        now: DateTime<Utc>,
    ) -> Result<Conversation, ApplicationError> {
        let mut conversation = self.store.load_conversation(project_id, conversation_id)?;
        let expected_revision = conversation.revision;
        let pending_effect_ids = conversation
            .messages
            .iter()
            .filter_map(|message| match &message.delivery {
                MessageDelivery::EffectPrepared { effect_id } => Some(effect_id.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let generation =
            conversation.pause_agent(expected_generation, reason_digest.to_owned(), now)?;
        if pending_effect_ids.is_empty() {
            self.store.update_conversation(
                &conversation,
                expected_revision,
                "conversation.agent_paused",
                &serde_json::json!({
                    "conversationId": conversation.id,
                    "controlGeneration": generation,
                    "reasonDigest": reason_digest,
                }),
                now,
            )?;
        } else {
            let mission_id = conversation
                .mission_id
                .clone()
                .ok_or(ApplicationError::ConversationMissionRequired)?;
            let mut mission = self.store.load_mission(project_id, &mission_id)?;
            let expected_mission_revision = mission.revision;
            for effect_id in &pending_effect_ids {
                mission.cancel_effect(effect_id, now)?;
            }
            self.store.update_conversation_and_mission_atomic(
                &conversation,
                expected_revision,
                &mission,
                expected_mission_revision,
                &[PendingEvent::new(
                    "conversation.agent_paused",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "controlGeneration": generation,
                        "reasonDigest": reason_digest,
                        "cancelledEffectIds": pending_effect_ids,
                    }),
                    now,
                )],
                &[PendingEvent::new(
                    "effect.cancelled_by_pause",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "effectIds": pending_effect_ids,
                        "controlGeneration": generation,
                    }),
                    now,
                )],
            )?;
        }
        Ok(conversation)
    }

