    pub fn start_mission(
        &mut self,
        command: StartMission,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let contract = compile_contract(&command.prompt, now);
        let title = command
            .title
            .unwrap_or_else(|| concise_title(&command.prompt));
        let mut mission = Mission::compile(
            project.tenant_id,
            command.id,
            command.project_id,
            title,
            contract,
            now,
        )?;
        mission.start_research(
            [Task {
                id: command.research_task_id,
                title: "核对市场证据并形成工作产物".into(),
                status: TaskStatus::Running,
                capability: "research.discover".into(),
            }],
            now,
        )?;
        self.store.create_mission_atomic(
            &mission,
            &[
                PendingEvent::new(
                    "mission.started",
                    serde_json::json!({"stage": mission.stage}),
                    now,
                ),
                PendingEvent::new(
                    "goal.confirmed",
                    serde_json::json!({
                        "goal": mission.contract.goal,
                        "constraints": mission.contract.constraints
                    }),
                    now,
                ),
            ],
        )?;
        Ok(mission)
    }

    #[allow(
        clippy::too_many_lines,
        reason = "Catalog dispatch compiles and persists the exact Mission definition, first checkpoint, contract, Conversation, and content-free evidence boundary"
    )]
    pub fn start_catalog_mission(
        &mut self,
        command: StartCatalogMission,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let catalog = Catalog::load()?;
        let snapshot = catalog.snapshot()?;
        let manifest = catalog
            .mission(command.manifest_id.trim())
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let parent_mission = command
            .parent_mission_id
            .as_ref()
            .map(|parent_id| self.store.load_mission(&command.project_id, parent_id))
            .transpose()?;
        let contract = compile_catalog_contract(
            &catalog,
            &snapshot.digest,
            manifest,
            &command,
            parent_mission.as_ref(),
            now,
        )?;
        let checkpoint_routes = manifest
            .checkpoint_routes
            .iter()
            .map(|route| {
                Ok((
                    route.checkpoint_id.clone(),
                    MissionCheckpointRoute::contracted(
                        route.capability_id.clone(),
                        MissionCheckpointExecutor::try_from(route.executor.as_str())?,
                        route.oracle_ids.iter().cloned(),
                        MissionCheckpointCompletionPolicy::try_from(
                            route.completion_policy.as_str(),
                        )?,
                    )?,
                ))
            })
            .collect::<Result<Vec<_>, MissionError>>()?;
        let definition = MissionDefinition::from_routed_linear_manifest(
            manifest.id.clone(),
            manifest.version,
            snapshot.digest.clone(),
            command.mode.clone(),
            manifest.capability_ids.iter().cloned(),
            manifest.required_artifacts.iter().cloned(),
            manifest.oracle_ids.iter().cloned(),
            checkpoint_routes,
        )?;
        let title = command
            .title
            .unwrap_or_else(|| format!("{} · {}", manifest.id, concise_title(command.goal.trim())));
        let first_checkpoint_id = manifest
            .checkpoint_ids
            .first()
            .cloned()
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let (first_capability, first_executor) = definition
            .checkpoints
            .first()
            .and_then(|checkpoint| checkpoint.route.as_ref())
            .map(|route| (route.capability_id.clone(), route.executor))
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let mut mission = Mission::compile_catalog(
            project.tenant_id,
            command.id,
            command.project_id,
            title,
            contract,
            definition,
            now,
        )?;
        mission.start_research(
            [Task {
                id: command.first_task_id,
                title: format!("Checkpoint: {first_checkpoint_id}"),
                status: TaskStatus::Running,
                capability: first_capability.clone(),
            }],
            now,
        )?;
        let conversation = MissionConversation::start(
            MissionConversationId::from_stable(format!(
                "mission-conversation:{}",
                mission.id.as_str()
            )),
            MissionConversationMessageId::from_stable(format!(
                "mission-message:goal:{}",
                mission.id.as_str()
            )),
            &mission,
            mission.contract.goal.clone(),
            format!("mission-start:{}", mission.id.as_str()),
            now,
        )?;
        let initial_message = conversation
            .messages
            .first()
            .expect("validated Mission Conversation has an initial message");
        let contract_digest = canonical_sha256(&serde_json::to_value(&mission.contract)?)?;
        self.store.create_catalog_mission_with_conversation_atomic(
            &mission,
            &conversation,
            &[
                PendingEvent::new(
                    "mission.catalog_bound",
                    serde_json::json!({
                        "manifestId": manifest.id,
                        "manifestVersion": manifest.version,
                        "catalogDigest": snapshot.digest,
                        "contractDigest": contract_digest,
                        "mode": mission.contract.mode,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "mission.checkpoint_started",
                    serde_json::json!({
                        "checkpointId": first_checkpoint_id,
                        "cycle": 1,
                        "checkpointRevision": 2,
                        "capabilityId": first_capability,
                        "executor": first_executor,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "mission.conversation_started",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "messageId": initial_message.id,
                        "sequence": initial_message.sequence,
                        "contentDigest": initial_message.content_digest,
                        "missionRevision": initial_message.mission_revision,
                        "checkpointId": initial_message.checkpoint_id,
                    }),
                    now,
                ),
            ],
        )?;
        Ok(mission)
    }

    /// Resolves the exact current Catalog Checkpoint and, when the DAG exposes
    /// a `Ready` node, starts that node with its route-bound Task before
    /// returning a revision-fenced dispatch proof. No executor is invoked by
    /// this method and no non-Runtime route may be inferred as Runtime work.
    pub fn dispatch_current_mission_checkpoint(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        now: DateTime<Utc>,
    ) -> Result<MissionCheckpointDispatch, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        let current_status = mission
            .definition
            .as_ref()
            .and_then(MissionDefinition::current_checkpoint)
            .map(|checkpoint| checkpoint.status)
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        if current_status == MissionCheckpointStatus::Ready {
            let checkpoint_id = mission
                .definition
                .as_ref()
                .and_then(MissionDefinition::current_checkpoint)
                .map(|checkpoint| checkpoint.id.clone())
                .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
            mission = self.begin_mission_checkpoint(project_id, mission_id, &checkpoint_id, now)?;
        }

        current_checkpoint_dispatch_projection(&mission)?
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)
    }

    /// Executes one exact Application-routed Checkpoint. Unsupported routes
    /// return `NotImplemented` without mutating the Mission; they are never
    /// completed by a caller-supplied digest. The first VM-11 handlers require
    /// current source verification and are fenced to the immutable Outcome
    /// Ledger revision inspected by their deterministic projections.
    #[allow(
        clippy::too_many_lines,
        reason = "the VM-11 Application handlers keep replay, source quarantine, source-fenced Oracle materialization, completion, and next-route handoff in one auditable boundary"
    )]
    pub fn execute_application_mission_checkpoint(
        &mut self,
        command: ExecuteApplicationMissionCheckpoint,
        now: DateTime<Utc>,
    ) -> Result<ApplicationMissionCheckpointExecution, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if let Some(replay_handler) =
            compiled_handler_for_checkpoint(&mission, &command.checkpoint_id)?
        {
            if replay_handler == CompiledApplicationCheckpointHandler::NextContractOrValidTerminal {
                return Err(ApplicationError::Vm11NextContractRouteSpecificCommandRequired);
            }
            if let Some(replay) = completed_application_checkpoint_replay(
                &mission,
                &command,
                replay_handler.handler_id(),
                replay_handler.primary_source_kind(),
            )? {
                return Ok(replay);
            }
            if let Some(replay) = blocked_application_checkpoint_replay(
                &self.store,
                &mission,
                &command,
                replay_handler.handler_id(),
            )? {
                return Ok(replay);
            }
        }

        let dispatch = current_checkpoint_dispatch_projection(&mission)?
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        if dispatch.executor != MissionCheckpointExecutor::Application {
            return Err(ApplicationError::ApplicationCheckpointExecutorMismatch {
                executor: dispatch.executor,
            });
        }
        if dispatch.checkpoint_id != command.checkpoint_id
            || dispatch.mission_revision != command.expected_mission_revision
            || dispatch.checkpoint_revision != command.expected_checkpoint_revision
        {
            return Err(ApplicationError::ApplicationCheckpointCommandMismatch);
        }
        let Some(handler_id) = dispatch.application_handler_id.as_deref() else {
            if dispatch.application_handler_status
                == Some(ApplicationCheckpointHandlerStatus::NotImplemented)
            {
                return Ok(ApplicationMissionCheckpointExecution::NotImplemented { dispatch });
            }
            if dispatch.application_handler_status
                == Some(ApplicationCheckpointHandlerStatus::CatalogRevisionMismatch)
            {
                return Err(ApplicationError::ApplicationCheckpointCatalogRevisionMismatch);
            }
            return Err(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: "missing-registered-handler-id".into(),
                },
            );
        };
        let Some(compiled_handler) = compiled_application_checkpoint_handler(handler_id) else {
            return Err(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            );
        };
        let handler_id = compiled_handler.handler_id();

        if matches!(
            compiled_handler,
            CompiledApplicationCheckpointHandler::LocalProjectIdentity
                | CompiledApplicationCheckpointHandler::LocalProjectInventory
                | CompiledApplicationCheckpointHandler::LocalEncryptionWorkspaceReady
        ) {
            return execute_vm00_local_project_checkpoint(
                &mut self.store,
                mission,
                command,
                &dispatch,
                compiled_handler,
                now,
            );
        }

        let outcome_ledger = match self.store.load_outcome_ledger(&command.project_id) {
            Ok(ledger) => Some(ledger),
            Err(StorageError::ScopedRecordNotFound {
                kind: "outcome ledger",
                ..
            }) => None,
            Err(error) => return Err(error.into()),
        };
        let outcome_ledger_revision = outcome_ledger.as_ref().map_or(0, |ledger| ledger.revision);
        if outcome_ledger
            .as_ref()
            .is_none_or(|ledger| ledger.events.is_empty())
        {
            let code = if outcome_ledger.is_some() {
                "outcome_events_unavailable"
            } else {
                "outcome_ledger_unavailable"
            };
            if mission.stage == MissionStage::Blocked
                && mission
                    .block
                    .as_ref()
                    .is_some_and(|block| block.code == code)
            {
                return Ok(ApplicationMissionCheckpointExecution::Blocked {
                    checkpoint_id: command.checkpoint_id,
                    code: code.into(),
                    outcome_ledger_revision,
                    replayed: true,
                });
            }
            let expected_mission_revision = mission.revision;
            let block = hartevo_domain_kernel::MissionBlock {
                code: code.into(),
                detail: if outcome_ledger.is_some() {
                    format!(
                        "No verified OutcomeEvent is available; {} remains blocked without inventing an outcome.",
                        command.checkpoint_id
                    )
                } else {
                    format!(
                        "The project OutcomeLedger has not been initialized; {} remains blocked without a substitute snapshot.",
                        command.checkpoint_id
                    )
                },
                recoverable: true,
                observed_at: now,
            };
            mission.block_checkpoint(&command.checkpoint_id, &block, MissionStage::Blocked)?;
            let events = [PendingEvent::new(
                "mission.application_checkpoint_blocked",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": command.checkpoint_id,
                    "capabilityId": dispatch.capability_id,
                    "handlerId": handler_id,
                    "dispatchMissionRevision": command.expected_mission_revision,
                    "dispatchCheckpointRevision": command.expected_checkpoint_revision,
                    "code": code,
                    "recoverable": true,
                    "outcomeLedgerRevision": outcome_ledger_revision,
                }),
                now,
            )];
            self.store.update_mission_atomic_with_outcome_ledger_fence(
                &mission,
                expected_mission_revision,
                outcome_ledger.as_ref().map(|ledger| ledger.revision),
                &events,
            )?;
            return Ok(ApplicationMissionCheckpointExecution::Blocked {
                checkpoint_id: command.checkpoint_id,
                code: code.into(),
                outcome_ledger_revision,
                replayed: false,
            });
        }

        let outcome_ledger = outcome_ledger.expect("non-empty ledger checked");
        let normalization = match outcome_ledger.verified_normalization_projection() {
            Ok(projection) => projection,
            Err(OutcomeLedgerError::UnverifiedOutcomeSource) => {
                let code = "outcome_source_unverified";
                let expected_mission_revision = mission.revision;
                if mission.stage == MissionStage::Blocked {
                    mission.resume(now)?;
                }
                let block = hartevo_domain_kernel::MissionBlock {
                    code: code.into(),
                    detail: format!(
                        "{} requires every OutcomeEvent to carry current source verification; migration-readable legacy evidence cannot complete this Checkpoint.",
                        command.checkpoint_id
                    ),
                    recoverable: true,
                    observed_at: now,
                };
                mission.block_checkpoint(&command.checkpoint_id, &block, MissionStage::Blocked)?;
                self.store.update_mission_atomic_with_outcome_ledger_fence(
                    &mission,
                    expected_mission_revision,
                    Some(outcome_ledger.revision),
                    &[PendingEvent::new(
                        "mission.application_checkpoint_blocked",
                        serde_json::json!({
                            "missionId": mission.id,
                            "checkpointId": command.checkpoint_id,
                            "capabilityId": dispatch.capability_id,
                            "handlerId": handler_id,
                            "dispatchMissionRevision": command.expected_mission_revision,
                            "dispatchCheckpointRevision": command.expected_checkpoint_revision,
                            "code": code,
                            "recoverable": true,
                            "outcomeLedgerRevision": outcome_ledger.revision,
                        }),
                        now,
                    )],
                )?;
                return Ok(ApplicationMissionCheckpointExecution::Blocked {
                    checkpoint_id: command.checkpoint_id,
                    code: code.into(),
                    outcome_ledger_revision: outcome_ledger.revision,
                    replayed: false,
                });
            }
            Err(error) => return Err(error.into()),
        };
        let mut application_source_fences = Vec::new();
        let (identity_chain, identity_support) = if matches!(
            compiled_handler,
            CompiledApplicationCheckpointHandler::IdentityChain
                | CompiledApplicationCheckpointHandler::MissionSpecificKpi
                | CompiledApplicationCheckpointHandler::AttributionAndUnattributed
                | CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc
                | CompiledApplicationCheckpointHandler::OutcomeReview
        ) {
            let support = match load_outcome_identity_chain_support(&self.store, &outcome_ledger) {
                Ok(support) => support,
                Err(OutcomeIdentityChainSupportLoadError::Missing { kind, id }) => {
                    let missing_fence = ApplicationSourceRevisionFence::absent(kind, id);
                    let code = match compiled_handler {
                        CompiledApplicationCheckpointHandler::MissionSpecificKpi => {
                            "mission_kpi_identity_support_missing"
                        }
                        CompiledApplicationCheckpointHandler::AttributionAndUnattributed => {
                            "attribution_identity_support_missing"
                        }
                        CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => {
                            "settlement_identity_support_missing"
                        }
                        CompiledApplicationCheckpointHandler::OutcomeReview => {
                            "outcome_review_identity_support_missing"
                        }
                        _ => "identity_chain_support_missing",
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        format!(
                            "{} cannot resolve the complete project-scoped identity support closure; no substitute identity was inferred.",
                            command.checkpoint_id
                        ),
                        true,
                        outcome_ledger.revision,
                        std::slice::from_ref(&missing_fence),
                        now,
                    );
                }
                Err(OutcomeIdentityChainSupportLoadError::Storage(error)) => {
                    return Err(error.into());
                }
            };
            application_source_fences = support.revision_fences();
            match outcome_ledger.verified_identity_chain_projection(
                &support.connections,
                &support.identity_links,
                &support.people,
                &support.companies,
                &support.partners,
                &support.opportunities,
            ) {
                Ok(projection) => (Some(projection), Some(support)),
                Err(
                    error @ (OutcomeLedgerError::IdentityLinkUnconfirmed
                    | OutcomeLedgerError::IdentityProviderAccountMismatch
                    | OutcomeLedgerError::IdentityRelationshipMismatch
                    | OutcomeLedgerError::IdentityChainSupportClosureMismatch
                    | OutcomeLedgerError::IdentityChainCoverageMismatch),
                ) => {
                    let (base_code, recoverable) = match error {
                        OutcomeLedgerError::IdentityLinkUnconfirmed => {
                            ("identity_link_unconfirmed", true)
                        }
                        OutcomeLedgerError::IdentityProviderAccountMismatch => {
                            ("identity_provider_account_mismatch", false)
                        }
                        OutcomeLedgerError::IdentityRelationshipMismatch => {
                            ("identity_relationship_inconsistent", true)
                        }
                        OutcomeLedgerError::IdentityChainSupportClosureMismatch
                        | OutcomeLedgerError::IdentityChainCoverageMismatch => {
                            ("identity_chain_broken", true)
                        }
                        _ => unreachable!("identity-chain error alternatives are exhaustive"),
                    };
                    let code = match compiled_handler {
                        CompiledApplicationCheckpointHandler::MissionSpecificKpi => {
                            "mission_kpi_identity_chain_changed"
                        }
                        CompiledApplicationCheckpointHandler::AttributionAndUnattributed => {
                            "attribution_identity_chain_changed"
                        }
                        CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => {
                            "settlement_identity_chain_changed"
                        }
                        CompiledApplicationCheckpointHandler::OutcomeReview => {
                            "outcome_review_identity_chain_changed"
                        }
                        _ => base_code,
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        format!(
                            "{} failed its deterministic identity-chain Oracle; Outcome identities remain unresolved and no attribution decision was fabricated.",
                            command.checkpoint_id
                        ),
                        recoverable,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            }
        } else {
            (None, None)
        };
        let parent_mission = if matches!(
            compiled_handler,
            CompiledApplicationCheckpointHandler::MissionSpecificKpi
                | CompiledApplicationCheckpointHandler::AttributionAndUnattributed
                | CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc
                | CompiledApplicationCheckpointHandler::OutcomeReview
        ) {
            let Some(parent_mission_id) = mission.contract.parent_mission_id.clone() else {
                let (code, detail) = match compiled_handler {
                    CompiledApplicationCheckpointHandler::MissionSpecificKpi => (
                        "mission_kpi_parent_missing",
                        "mission_specific_kpi requires an immutable parent Mission reference; no current Mission or project aggregate was substituted.",
                    ),
                    CompiledApplicationCheckpointHandler::AttributionAndUnattributed => (
                        "attribution_parent_missing",
                        "attribution_and_unattributed requires an immutable parent Mission reference; no current Mission or project aggregate was substituted.",
                    ),
                    CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => (
                        "settlement_parent_missing",
                        "refund_commission_payout_recalc requires an immutable parent Mission reference; no current Mission or project aggregate was substituted.",
                    ),
                    CompiledApplicationCheckpointHandler::OutcomeReview => (
                        "outcome_review_parent_missing",
                        "outcome_review requires an immutable parent Mission reference; no current Mission, stale summary, or project aggregate was substituted.",
                    ),
                    _ => unreachable!("parent-bound handler alternatives are exhaustive"),
                };
                return persist_application_checkpoint_block(
                    &mut self.store,
                    &mut mission,
                    &command,
                    &dispatch,
                    handler_id,
                    code,
                    detail.into(),
                    false,
                    outcome_ledger.revision,
                    &application_source_fences,
                    now,
                );
            };
            let parent_mission = match self
                .store
                .load_mission(&command.project_id, &parent_mission_id)
            {
                Ok(parent) => parent,
                Err(StorageError::MissionNotFound { .. }) => {
                    let missing_parent_fence = ApplicationSourceRevisionFence::absent(
                        ApplicationSourceKind::Mission,
                        parent_mission_id.to_string(),
                    );
                    application_source_fences.push(missing_parent_fence);
                    let (code, detail) = match compiled_handler {
                        CompiledApplicationCheckpointHandler::MissionSpecificKpi => (
                            "mission_kpi_parent_unavailable",
                            "The exact parent Mission is unavailable; no sibling Mission contract was inferred.",
                        ),
                        CompiledApplicationCheckpointHandler::AttributionAndUnattributed => (
                            "attribution_parent_unavailable",
                            "The exact attribution parent Mission is unavailable; no sibling Mission contract or project aggregate was inferred.",
                        ),
                        CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => (
                            "settlement_parent_unavailable",
                            "The exact settlement parent Mission is unavailable; no sibling Mission contract or project aggregate was inferred.",
                        ),
                        CompiledApplicationCheckpointHandler::OutcomeReview => (
                            "outcome_review_parent_unavailable",
                            "The exact review parent Mission is unavailable; no sibling Mission contract, cached narrative, or project aggregate was inferred.",
                        ),
                        _ => unreachable!("parent-bound handler alternatives are exhaustive"),
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        detail.into(),
                        true,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            };
            application_source_fences.push(ApplicationSourceRevisionFence::present(
                ApplicationSourceKind::Mission,
                parent_mission.id.to_string(),
                parent_mission.revision,
            ));
            if !vm11_inherits_exact_parent_contract(&mission, &parent_mission) {
                let code = match compiled_handler {
                    CompiledApplicationCheckpointHandler::MissionSpecificKpi => {
                        "mission_kpi_parent_contract_mismatch"
                    }
                    CompiledApplicationCheckpointHandler::AttributionAndUnattributed => {
                        "attribution_parent_contract_mismatch"
                    }
                    CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => {
                        "settlement_parent_contract_mismatch"
                    }
                    CompiledApplicationCheckpointHandler::OutcomeReview => {
                        "outcome_review_parent_contract_mismatch"
                    }
                    _ => unreachable!("parent-bound handler alternatives are exhaustive"),
                };
                return persist_application_checkpoint_block(
                    &mut self.store,
                    &mut mission,
                    &command,
                    &dispatch,
                    handler_id,
                    code,
                    "The VM-11 contract no longer exactly inherits its parent Mission mode, market, locale, audience, timezone, budget and KPI set."
                        .into(),
                    false,
                    outcome_ledger.revision,
                    &application_source_fences,
                    now,
                );
            }
            Some(parent_mission)
        } else {
            None
        };
        let mission_kpi = if matches!(
            compiled_handler,
            CompiledApplicationCheckpointHandler::MissionSpecificKpi
                | CompiledApplicationCheckpointHandler::OutcomeReview
        ) {
            let current_identity_chain = identity_chain.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let parent_mission = parent_mission.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            match outcome_ledger.verified_mission_kpi_projection(
                parent_mission,
                current_identity_chain,
                now,
            ) {
                Ok(projection) => Some(projection),
                Err(
                    error @ (OutcomeLedgerError::KpiSourceEventsUnavailable
                    | OutcomeLedgerError::UnsupportedKpiMetric
                    | OutcomeLedgerError::KpiCurrencyMismatch
                    | OutcomeLedgerError::InvalidKpiContract
                    | OutcomeLedgerError::KpiMissionScopeMismatch
                    | OutcomeLedgerError::KpiIdentityChainMismatch
                    | OutcomeLedgerError::KpiArithmetic),
                ) => {
                    let (code, recoverable) = match error {
                        OutcomeLedgerError::KpiSourceEventsUnavailable => {
                            ("mission_kpi_outcomes_unavailable", true)
                        }
                        OutcomeLedgerError::UnsupportedKpiMetric => {
                            ("mission_kpi_metric_unsupported", false)
                        }
                        OutcomeLedgerError::KpiCurrencyMismatch => {
                            ("mission_kpi_currency_conflict", false)
                        }
                        OutcomeLedgerError::InvalidKpiContract => {
                            ("mission_kpi_contract_invalid", false)
                        }
                        OutcomeLedgerError::KpiMissionScopeMismatch
                        | OutcomeLedgerError::KpiIdentityChainMismatch => {
                            ("mission_kpi_source_inconsistent", false)
                        }
                        OutcomeLedgerError::KpiArithmetic => {
                            ("mission_kpi_arithmetic_overflow", false)
                        }
                        _ => unreachable!("KPI error alternatives are exhaustive"),
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        format!(
                            "{} failed its deterministic parent-Mission KPI Oracle; no zero value, cross-currency sum, CRM-stage revenue, or unsupported metric was fabricated.",
                            command.checkpoint_id
                        ),
                        recoverable,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            }
        } else {
            None
        };
        let outcome_attribution = if matches!(
            compiled_handler,
            CompiledApplicationCheckpointHandler::AttributionAndUnattributed
                | CompiledApplicationCheckpointHandler::OutcomeReview
        ) {
            let parent_mission = parent_mission.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let current_identity_chain = identity_chain.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let support_mission_ids = match outcome_ledger
                .attribution_support_mission_ids(parent_mission, now)
            {
                Ok(ids) => ids,
                Err(OutcomeLedgerError::InvalidAttribution) => {
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        "attribution_record_invalid",
                        "An attribution record does not have a legal model/touchpoint shape; the handler did not infer a replacement source."
                            .into(),
                        false,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(OutcomeLedgerError::AttributionSourceOrdersUnavailable) => {
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        "attribution_source_orders_unavailable",
                        "The current attribution contract addresses verified orders; an empty order projection cannot complete a lead-, meeting-, or stage-only parent Mission."
                            .into(),
                        true,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(
                    error @ (OutcomeLedgerError::AttributionMissionScopeMismatch
                    | OutcomeLedgerError::AttributionWindowMismatch),
                ) => {
                    let code = if error == OutcomeLedgerError::AttributionWindowMismatch {
                        "attribution_window_inconsistent"
                    } else {
                        "attribution_parent_scope_inconsistent"
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        "The attribution source Mission or frozen observation window is inconsistent; no out-of-window touchpoint was selected."
                            .into(),
                        false,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            };
            let mut supporting_missions = Vec::with_capacity(support_mission_ids.len());
            for support_mission_id in support_mission_ids {
                let support_mission = if support_mission_id == parent_mission.id {
                    parent_mission.clone()
                } else if support_mission_id == mission.id {
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        "attribution_self_reference",
                        "The VM-11 review Mission cannot act as its own attribution touchpoint source; a prior source Mission is required."
                            .into(),
                        false,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                } else {
                    match self
                        .store
                        .load_mission(&command.project_id, &support_mission_id)
                    {
                        Ok(support) => support,
                        Err(StorageError::MissionNotFound { .. }) => {
                            application_source_fences.push(ApplicationSourceRevisionFence::absent(
                                ApplicationSourceKind::Mission,
                                support_mission_id.to_string(),
                            ));
                            return persist_application_checkpoint_block(
                                &mut self.store,
                                &mut mission,
                                &command,
                                &dispatch,
                                handler_id,
                                "attribution_support_unavailable",
                                "A touchpoint's exact source Mission is unavailable; no similarly named Mission or provider response was substituted."
                                    .into(),
                                true,
                                outcome_ledger.revision,
                                &application_source_fences,
                                now,
                            );
                        }
                        Err(error) => return Err(error.into()),
                    }
                };
                if support_mission.id != parent_mission.id {
                    application_source_fences.push(ApplicationSourceRevisionFence::present(
                        ApplicationSourceKind::Mission,
                        support_mission.id.to_string(),
                        support_mission.revision,
                    ));
                }
                supporting_missions.push(support_mission);
            }
            match outcome_ledger.verified_attribution_projection(
                parent_mission,
                current_identity_chain,
                &supporting_missions,
                now,
            ) {
                Ok(projection) => Some(projection),
                Err(
                    error @ (OutcomeLedgerError::UnverifiedAttributionSource
                    | OutcomeLedgerError::AttributionSupportClosureMismatch
                    | OutcomeLedgerError::AttributionWindowMismatch
                    | OutcomeLedgerError::AttributionEffectSupportInvalid
                    | OutcomeLedgerError::DuplicateAttributionTouchpoint
                    | OutcomeLedgerError::DisputedAttribution
                    | OutcomeLedgerError::AttributionMissionScopeMismatch
                    | OutcomeLedgerError::AttributionIdentityChainMismatch
                    | OutcomeLedgerError::InvalidAttribution),
                ) => {
                    let (code, recoverable) = match error {
                        OutcomeLedgerError::UnverifiedAttributionSource => {
                            ("attribution_source_unverified", true)
                        }
                        OutcomeLedgerError::AttributionSupportClosureMismatch => {
                            ("attribution_support_unavailable", true)
                        }
                        OutcomeLedgerError::AttributionWindowMismatch => {
                            ("attribution_window_inconsistent", false)
                        }
                        OutcomeLedgerError::AttributionEffectSupportInvalid => {
                            ("attribution_effect_unverified", true)
                        }
                        OutcomeLedgerError::DuplicateAttributionTouchpoint => {
                            ("attribution_touchpoint_duplicate", false)
                        }
                        OutcomeLedgerError::DisputedAttribution => ("attribution_disputed", true),
                        OutcomeLedgerError::AttributionMissionScopeMismatch
                        | OutcomeLedgerError::AttributionIdentityChainMismatch => {
                            ("attribution_source_inconsistent", false)
                        }
                        OutcomeLedgerError::InvalidAttribution => {
                            ("attribution_record_invalid", false)
                        }
                        _ => unreachable!("attribution error alternatives are exhaustive"),
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        format!(
                            "{} failed its deterministic attribution Oracle; verified identity, last-non-direct, first-touch and Unattributed remain distinct, and no correlation was promoted to causality.",
                            command.checkpoint_id
                        ),
                        recoverable,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            }
        } else {
            None
        };
        let outcome_settlement = if matches!(
            compiled_handler,
            CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc
                | CompiledApplicationCheckpointHandler::OutcomeReview
        ) {
            let parent_mission = parent_mission.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let current_identity_chain = identity_chain.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let current_identity_support = identity_support.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            match outcome_ledger.verified_settlement_projection(
                parent_mission,
                current_identity_chain,
                &current_identity_support.partners,
                now,
            ) {
                Ok(projection) => Some(projection),
                Err(
                    error @ (OutcomeLedgerError::SettlementMissionScopeMismatch
                    | OutcomeLedgerError::SettlementSourceOrdersUnavailable
                    | OutcomeLedgerError::SettlementIdentityChainMismatch
                    | OutcomeLedgerError::SettlementWindowMismatch
                    | OutcomeLedgerError::SettlementPartnerSupportClosureMismatch
                    | OutcomeLedgerError::SettlementPartnerPolicyMismatch
                    | OutcomeLedgerError::SettlementCommissionAuthorityMismatch
                    | OutcomeLedgerError::SettlementCommissionRecalculationRequired
                    | OutcomeLedgerError::SettlementPayoutMismatch
                    | OutcomeLedgerError::SettlementDuplicatePayout
                    | OutcomeLedgerError::SettlementMoneyMismatch),
                ) => {
                    let (code, recoverable) = match error {
                        OutcomeLedgerError::SettlementSourceOrdersUnavailable => {
                            ("settlement_source_orders_unavailable", true)
                        }
                        OutcomeLedgerError::SettlementCommissionRecalculationRequired => {
                            ("settlement_commission_recalculation_required", true)
                        }
                        OutcomeLedgerError::SettlementPartnerSupportClosureMismatch => {
                            ("settlement_partner_support_changed", true)
                        }
                        OutcomeLedgerError::SettlementIdentityChainMismatch => {
                            ("settlement_identity_chain_changed", true)
                        }
                        OutcomeLedgerError::SettlementPartnerPolicyMismatch => {
                            ("settlement_partner_policy_invalid", false)
                        }
                        OutcomeLedgerError::SettlementCommissionAuthorityMismatch => {
                            ("settlement_commission_authority_mismatch", false)
                        }
                        OutcomeLedgerError::SettlementPayoutMismatch => {
                            ("settlement_payout_mismatch", false)
                        }
                        OutcomeLedgerError::SettlementDuplicatePayout => {
                            ("settlement_duplicate_payout", false)
                        }
                        OutcomeLedgerError::SettlementMoneyMismatch => {
                            ("settlement_money_mismatch", false)
                        }
                        OutcomeLedgerError::SettlementMissionScopeMismatch
                        | OutcomeLedgerError::SettlementWindowMismatch => {
                            ("settlement_source_inconsistent", false)
                        }
                        _ => unreachable!("settlement error alternatives are exhaustive"),
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        format!(
                            "{} failed its deterministic settlement Oracle; immutable orders, separate refunds, current commission revisions, supply-class authority, minor-unit currency, and independently verified payout facts were not weakened or fabricated.",
                            command.checkpoint_id
                        ),
                        recoverable,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            }
        } else {
            None
        };
        let outcome_review = if compiled_handler
            == CompiledApplicationCheckpointHandler::OutcomeReview
        {
            let parent_mission = parent_mission.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let kpi = mission_kpi.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let attribution = outcome_attribution.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            let settlement = outcome_settlement.as_ref().ok_or(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            )?;
            match outcome_ledger.verified_outcome_review_projection(
                parent_mission,
                kpi,
                attribution,
                settlement,
                now,
            ) {
                Ok(projection) => Some(projection),
                Err(
                    error @ (OutcomeLedgerError::OutcomeReviewScopeMismatch
                    | OutcomeLedgerError::OutcomeReviewProjectionMismatch
                    | OutcomeLedgerError::OutcomeReviewEffectStateMismatch
                    | OutcomeLedgerError::OutcomeReviewMoneyMismatch),
                ) => {
                    let code = match error {
                        OutcomeLedgerError::OutcomeReviewScopeMismatch => {
                            "outcome_review_source_inconsistent"
                        }
                        OutcomeLedgerError::OutcomeReviewProjectionMismatch => {
                            "outcome_review_projection_inconsistent"
                        }
                        OutcomeLedgerError::OutcomeReviewEffectStateMismatch => {
                            "outcome_review_effect_state_inconsistent"
                        }
                        OutcomeLedgerError::OutcomeReviewMoneyMismatch => {
                            "outcome_review_money_inconsistent"
                        }
                        _ => unreachable!("outcome review error alternatives are exhaustive"),
                    };
                    return persist_application_checkpoint_block(
                        &mut self.store,
                        &mut mission,
                        &command,
                        &dispatch,
                        handler_id,
                        code,
                        format!(
                            "{} could not freeze one exact KPI, attribution, settlement and verified-cost review; no action, FX conversion, causal ROI, or replacement summary was fabricated.",
                            command.checkpoint_id
                        ),
                        false,
                        outcome_ledger.revision,
                        &application_source_fences,
                        now,
                    );
                }
                Err(error) => return Err(error.into()),
            }
        } else {
            None
        };
        let expected_mission_revision = mission.revision;
        if mission.stage == MissionStage::Blocked {
            mission.resume(now)?;
        }
        mission.begin_checkpoint_verification(&command.checkpoint_id, now)?;
        let definition = mission
            .definition
            .as_ref()
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let checkpoint = definition
            .checkpoints
            .iter()
            .find(|checkpoint| checkpoint.id == command.checkpoint_id)
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let route = checkpoint
            .route
            .as_ref()
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let application_evidence = match compiled_handler {
            CompiledApplicationCheckpointHandler::LocalProjectIdentity
            | CompiledApplicationCheckpointHandler::LocalProjectInventory
            | CompiledApplicationCheckpointHandler::LocalEncryptionWorkspaceReady => {
                unreachable!("VM-00 route returned before the generic VM-11 pipeline")
            }
            CompiledApplicationCheckpointHandler::EventIngest => {
                vm11_event_ingest_application_evidence(
                    &mission,
                    route,
                    &command,
                    &outcome_ledger,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::NormalizeDedupeOrder => {
                vm11_normalize_dedupe_order_application_evidence(
                    &mission,
                    route,
                    &command,
                    &normalization,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::IdentityChain => {
                vm11_identity_chain_application_evidence(
                    &mission,
                    route,
                    &command,
                    &normalization,
                    identity_chain.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::MissionSpecificKpi => {
                vm11_mission_specific_kpi_application_evidence(
                    &mission,
                    route,
                    &command,
                    mission_kpi.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::AttributionAndUnattributed => {
                vm11_attribution_and_unattributed_application_evidence(
                    &mission,
                    route,
                    &command,
                    outcome_attribution.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => {
                vm11_refund_commission_payout_recalc_application_evidence(
                    &mission,
                    parent_mission.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    route,
                    &command,
                    outcome_settlement.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::OutcomeReview => {
                vm11_outcome_review_application_evidence(
                    &mission,
                    parent_mission.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    route,
                    &command,
                    outcome_review.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    now,
                )?
            }
            CompiledApplicationCheckpointHandler::NextContractOrValidTerminal => {
                unreachable!("route-specific handler returned before the generic VM-11 pipeline")
            }
        };
        validate_application_evidence_against_registry(&application_evidence)?;
        let evidence_digest = application_evidence.digest();
        mission.complete_checkpoint(
            &command.checkpoint_id,
            MissionCheckpointCompletion {
                oracle_ids: route.oracle_ids.clone(),
                work_product_ids: BTreeSet::new(),
                effect_ids: BTreeSet::new(),
                application_evidence: Some(application_evidence),
                evidence_digest: evidence_digest.clone(),
                verified_at: now,
            },
        )?;
        let completed_checkpoint_revision = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == command.checkpoint_id)
            })
            .map(|checkpoint| checkpoint.revision)
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let next_started = start_ready_catalog_checkpoint_in_memory(&mut mission, now)?;
        let next_dispatch = current_checkpoint_dispatch_projection(&mission)?;
        let source_metrics = match compiled_handler {
            CompiledApplicationCheckpointHandler::LocalProjectIdentity
            | CompiledApplicationCheckpointHandler::LocalProjectInventory
            | CompiledApplicationCheckpointHandler::LocalEncryptionWorkspaceReady => {
                unreachable!("VM-00 route returned before the generic VM-11 pipeline")
            }
            CompiledApplicationCheckpointHandler::EventIngest
            | CompiledApplicationCheckpointHandler::NormalizeDedupeOrder => {
                serde_json::json!({
                    "eventCount": normalization.event_count,
                    "orderCount": normalization.order_count,
                    "refundCount": normalization.refund_count,
                    "observedReorderCount": normalization.observed_reorder_count,
                })
            }
            CompiledApplicationCheckpointHandler::IdentityChain => {
                let projection = identity_chain.as_ref().ok_or(
                    ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                        handler_id: handler_id.into(),
                    },
                )?;
                serde_json::json!({
                    "eventCount": projection.event_count,
                    "identityCoveredEventCount": projection.identity_covered_event_count,
                    "directIdentityEventCount": projection.direct_identity_event_count,
                    "inheritedOrderIdentityEventCount": projection.inherited_order_identity_event_count,
                    "externalAccountMatchCount": projection.external_account_match_count,
                    "connectionCount": projection.connection_count,
                    "identityLinkCount": projection.identity_link_count,
                    "personCount": projection.person_count,
                    "companyCount": projection.company_count,
                    "partnerCount": projection.partner_count,
                    "opportunityCount": projection.opportunity_count,
                })
            }
            CompiledApplicationCheckpointHandler::MissionSpecificKpi => {
                let projection = mission_kpi.as_ref().ok_or(
                    ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                        handler_id: handler_id.into(),
                    },
                )?;
                serde_json::json!({
                    "sourceEventCount": projection.source_event_count,
                    "measurementCount": projection.measurement_count,
                    "targetMetCount": projection.target_met_count,
                    "windowStartedAt": projection.window_started_at,
                    "windowEndedAt": projection.window_ended_at,
                    "parentMissionRevision": projection.source_mission_revision,
                })
            }
            CompiledApplicationCheckpointHandler::AttributionAndUnattributed => {
                let projection = outcome_attribution.as_ref().ok_or(
                    ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                        handler_id: handler_id.into(),
                    },
                )?;
                serde_json::json!({
                    "orderCount": projection.order_count,
                    "sourceRecordCount": projection.source_record_count,
                    "eligibleTouchpointCount": projection.eligible_touchpoint_count,
                    "verifiedIdentityOrderCount": projection.verified_identity_order_count,
                    "lastNonDirectOrderCount": projection.last_non_direct_order_count,
                    "unattributedOrderCount": projection.unattributed_order_count,
                    "firstTouchOrderCount": projection.first_touch_order_count,
                    "explicitUnattributedRecordCount": projection.explicit_unattributed_record_count,
                    "supportingMissionCount": projection.supporting_mission_count,
                    "verifiedEffectCount": projection.verified_effect_count,
                    "causalClaim": projection.causal_claim,
                    "windowStartedAt": projection.window_started_at,
                    "windowEndedAt": projection.window_ended_at,
                    "parentMissionRevision": projection.source_mission_revision,
                })
            }
            CompiledApplicationCheckpointHandler::RefundCommissionPayoutRecalc => {
                let projection = outcome_settlement.as_ref().ok_or(
                    ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                        handler_id: handler_id.into(),
                    },
                )?;
                serde_json::json!({
                    "orderCount": projection.order_count,
                    "refundedOrderCount": projection.refunded_order_count,
                    "refundCount": projection.refund_count,
                    "calculatedCommissionCount": projection.calculated_commission_count,
                    "networkCommissionEventCount": projection.network_commission_event_count,
                    "payoutCount": projection.payout_count,
                    "settlementGroupCount": projection.settlement_group_count,
                    "paidGroupCount": projection.paid_group_count,
                    "outstandingGroupCount": projection.outstanding_group_count,
                    "noPaymentDueGroupCount": projection.no_payment_due_group_count,
                    "officialNetworkGroupCount": projection.official_network_group_count,
                    "hartevoManagedGroupCount": projection.hartevo_managed_group_count,
                    "tenantPrivateGroupCount": projection.tenant_private_group_count,
                    "windowStartedAt": projection.window_started_at,
                    "windowEndedAt": projection.window_ended_at,
                    "parentMissionRevision": projection.source_mission_revision,
                })
            }
            CompiledApplicationCheckpointHandler::OutcomeReview => {
                let projection = outcome_review.as_ref().ok_or(
                    ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                        handler_id: handler_id.into(),
                    },
                )?;
                serde_json::json!({
                    "measurementCount": projection.measurement_count,
                    "targetMetCount": projection.target_met_count,
                    "targetGapCount": projection.target_gap_count,
                    "orderCount": projection.order_count,
                    "attributedOrderCount": projection.attributed_order_count,
                    "unattributedOrderCount": projection.unattributed_order_count,
                    "settlementGroupCount": projection.settlement_group_count,
                    "outstandingSettlementGroupCount": projection.outstanding_settlement_group_count,
                    "verifiedEffectCount": projection.verified_effect_count,
                    "pendingEffectCount": projection.pending_effect_count,
                    "unresolvedCostEffectCount": projection.unresolved_cost_effect_count,
                    "crossCurrencyCostEffectCount": projection.cross_currency_cost_effect_count,
                    "budgetCurrency": projection.budget.currency,
                    "budgetMinor": projection.budget.amount_minor,
                    "verifiedCostMinor": projection.budget_currency_verified_cost.amount_minor,
                    "budgetRemainingMinor": projection.budget_remaining.amount_minor,
                    "budgetOverrunMinor": projection.budget_overrun.amount_minor,
                    "kpiStatus": projection.kpi_status,
                    "attributionStatus": projection.attribution_status,
                    "settlementStatus": projection.settlement_status,
                    "costStatus": projection.cost_status,
                    "budgetStatus": projection.budget_status,
                    "scaleEvidenceStatus": projection.scale_evidence_status,
                    "loopPolicy": projection.loop_policy,
                    "causalStatus": projection.causal_status,
                    "roiStatus": projection.roi_status,
                    "caveats": projection.caveats,
                    "currencyBucketCount": projection.economics.len(),
                    "windowStartedAt": projection.window_started_at,
                    "outcomeWindowEndedAt": projection.outcome_window_ended_at,
                    "observedAt": projection.observed_at,
                    "parentMissionRevision": projection.source_mission_revision,
                })
            }
            CompiledApplicationCheckpointHandler::NextContractOrValidTerminal => {
                unreachable!("route-specific handler returned before the generic VM-11 pipeline")
            }
        };
        let mut events = vec![PendingEvent::new(
            "mission.application_checkpoint_completed",
            serde_json::json!({
                "missionId": mission.id,
                "checkpointId": command.checkpoint_id,
                "checkpointRevision": completed_checkpoint_revision,
                "capabilityId": dispatch.capability_id,
                "handlerId": handler_id,
                "oracleIds": dispatch.oracle_ids,
                "sourceKind": compiled_handler.primary_source_kind(),
                "sourceRevision": outcome_ledger.revision,
                "sourceMetrics": source_metrics,
                "sourceFenceCount": application_source_fences.len(),
                "evidenceDigest": evidence_digest,
            }),
            now,
        )];
        if let Some((checkpoint_id, checkpoint_revision, capability_id, executor, task_id, cycle)) =
            next_started
        {
            events.push(PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint_id,
                    "checkpointRevision": checkpoint_revision,
                    "capabilityId": capability_id,
                    "executor": executor,
                    "cycle": cycle,
                    "taskId": task_id,
                }),
                now,
            ));
        }
        if compiled_handler == CompiledApplicationCheckpointHandler::OutcomeReview {
            self.store
                .complete_vm11_outcome_review_application_checkpoint_atomic(
                    &mission,
                    expected_mission_revision,
                    outcome_ledger.revision,
                    &application_source_fences,
                    outcome_review.as_ref().ok_or(
                        ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                            handler_id: handler_id.into(),
                        },
                    )?,
                    &events,
                )?;
        } else {
            self.store
                .update_mission_atomic_with_application_source_fences(
                    &mission,
                    expected_mission_revision,
                    Some(outcome_ledger.revision),
                    &application_source_fences,
                    &events,
                )?;
        }
        Ok(ApplicationMissionCheckpointExecution::Completed {
            completed_checkpoint_id: command.checkpoint_id,
            completion_evidence_digest: evidence_digest,
            outcome_ledger_revision: outcome_ledger.revision,
            replayed: false,
            next_dispatch,
        })
    }

    pub fn begin_mission_checkpoint(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        let expected_revision = mission.revision;
        let (cycle, capability) = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == checkpoint_id)
                    .and_then(|checkpoint| {
                        checkpoint
                            .route
                            .as_ref()
                            .map(|route| (definition.cycle, route.capability_id.clone()))
                    })
            })
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let task = Task {
            id: TaskId::from_stable(format!(
                "mission-checkpoint-task:{}:{checkpoint_id}:cycle:{cycle}",
                mission.id
            )),
            title: format!("Checkpoint: {checkpoint_id}"),
            status: TaskStatus::Running,
            capability,
        };
        let task_id = task.id.clone();
        mission.begin_checkpoint_with_task(checkpoint_id, task, now)?;
        let checkpoint = mission
            .definition
            .as_ref()
            .and_then(|definition| definition.current_checkpoint())
            .filter(|checkpoint| checkpoint.id == checkpoint_id)
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint.id,
                    "checkpointRevision": checkpoint.revision,
                    "capabilityId": checkpoint.route.as_ref().map(|route| &route.capability_id),
                    "executor": checkpoint.route.as_ref().map(|route| route.executor),
                    "cycle": mission.definition.as_ref().map(|definition| definition.cycle),
                    "taskId": task_id,
                }),
                now,
            )],
        )?;
        Ok(mission)
    }

    pub fn begin_mission_checkpoint_verification(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        if mission.definition.as_ref().is_some_and(|definition| {
            definition.current_checkpoint().is_some_and(|checkpoint| {
                checkpoint.id == checkpoint_id
                    && checkpoint.route.as_ref().is_some_and(|route| {
                        route.completion_policy
                            == Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
                    })
            })
        }) {
            return Err(ApplicationError::HumanCheckpointConfirmationRequired);
        }
        let expected_revision = mission.revision;
        mission.begin_checkpoint_verification(checkpoint_id, now)?;
        let checkpoint = mission
            .definition
            .as_ref()
            .and_then(|definition| definition.active_checkpoint())
            .filter(|checkpoint| checkpoint.id == checkpoint_id)
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "mission.checkpoint_verification_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint.id,
                    "checkpointRevision": checkpoint.revision,
                    "capabilityId": checkpoint.route.as_ref().map(|route| &route.capability_id),
                    "executor": checkpoint.route.as_ref().map(|route| route.executor),
                    "cycle": mission.definition.as_ref().map(|definition| definition.cycle),
                }),
                now,
            )],
        )?;
        Ok(mission)
    }

    pub fn complete_mission_checkpoint(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        completion: MissionCheckpointCompletion,
    ) -> Result<Mission, ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        if let Some(route) = mission.definition.as_ref().and_then(|definition| {
            definition
                .current_checkpoint()
                .filter(|checkpoint| checkpoint.id == checkpoint_id)
                .and_then(|checkpoint| checkpoint.route.as_ref())
        }) {
            if route.completion_policy == Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
            {
                return Err(ApplicationError::HumanCheckpointConfirmationRequired);
            }
            if route.executor == MissionCheckpointExecutor::Application {
                return Err(ApplicationError::ApplicationCheckpointExecutionRequired);
            }
        }
        self.complete_mission_checkpoint_trusted(mission, checkpoint_id, completion)
    }

    fn complete_mission_checkpoint_trusted(
        &mut self,
        mut mission: Mission,
        checkpoint_id: &str,
        completion: MissionCheckpointCompletion,
    ) -> Result<Mission, ApplicationError> {
        let expected_revision = mission.revision;
        let completed_at = completion.verified_at;
        let evidence_digest = completion.evidence_digest.clone();
        let oracle_ids = completion.oracle_ids.clone();
        let work_product_count = completion.work_product_ids.len();
        let effect_count = completion.effect_ids.len();
        mission.complete_checkpoint(checkpoint_id, completion)?;
        let completed_checkpoint = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == checkpoint_id)
            })
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "mission.checkpoint_completed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": completed_checkpoint.id,
                    "checkpointRevision": completed_checkpoint.revision,
                    "capabilityId": completed_checkpoint.route.as_ref().map(|route| &route.capability_id),
                    "executor": completed_checkpoint.route.as_ref().map(|route| route.executor),
                    "cycle": mission.definition.as_ref().map(|definition| definition.cycle),
                    "oracleIds": oracle_ids,
                    "evidenceDigest": evidence_digest,
                    "workProductCount": work_product_count,
                    "effectCount": effect_count,
                    "nextCheckpointId": mission.definition.as_ref().and_then(|definition| definition.current_checkpoint().map(|checkpoint| &checkpoint.id)),
                }),
                completed_at,
            )],
        )?;
        Ok(mission)
    }

    /// Completes only VM-11's structured `continue_stop_scale_test` route.
    /// Generic free-text Human confirmation is explicitly rejected for this
    /// Checkpoint so the following Application handler can consume one typed,
    /// source-fenced action instead of parsing prose or trusting UI state.
    #[allow(
        clippy::too_many_lines,
        reason = "the structured decision boundary keeps replay, exact review projection, parent/source CAS, private rationale, typed action gates, completion, and next-route handoff visible together"
    )]
    pub fn decide_vm11_outcome_review(
        &mut self,
        command: DecideVm11OutcomeReview,
        now: DateTime<Utc>,
    ) -> Result<Vm11OutcomeReviewDecisionResult, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let mut conversation = self
            .store
            .load_mission_conversation(&command.project_id, &command.mission_id)?;
        let normalized_rationale = command.rationale.trim();
        let normalized_idempotency_key = command.idempotency_key.trim();
        let rationale_digest = sha256(normalized_rationale.as_bytes());
        let idempotency_key_digest = sha256(normalized_idempotency_key.as_bytes());
        if normalized_rationale.is_empty()
            || normalized_idempotency_key.is_empty()
            || command.decided_by.as_str().trim().is_empty()
            || !is_sha256_text(&command.expected_review_projection_digest)
            || !is_sha256_text(&command.expected_review_completion_digest)
        {
            return Err(ApplicationError::StructuredOutcomeDecisionCommandMismatch);
        }

        match self
            .store
            .load_vm11_outcome_review_decision(&command.project_id, &command.mission_id)
        {
            Ok(decision) => {
                let message = conversation
                    .messages
                    .iter()
                    .find(|message| message.id == decision.message_id)
                    .cloned()
                    .ok_or(ApplicationError::StructuredOutcomeDecisionReplayMismatch)?;
                if decision.action != command.action
                    || decision.decided_by != command.decided_by
                    || decision.message_id != command.message_id
                    || decision.rationale_digest != rationale_digest
                    || decision.idempotency_key_digest != idempotency_key_digest
                    || decision.source_review_projection_digest
                        != command.expected_review_projection_digest
                    || decision.source_review_completion_digest
                        != command.expected_review_completion_digest
                    || decision.dispatch_mission_revision != command.expected_mission_revision
                    || decision.dispatch_checkpoint_revision != command.expected_checkpoint_revision
                    || decision.conversation_revision.checked_sub(1)
                        != Some(command.expected_conversation_revision)
                    || message.body != normalized_rationale
                    || message.idempotency_key != normalized_idempotency_key
                {
                    return Err(ApplicationError::StructuredOutcomeDecisionReplayMismatch);
                }
                return Ok(Vm11OutcomeReviewDecisionResult {
                    next_dispatch: current_checkpoint_dispatch_projection(&mission)?,
                    mission,
                    conversation,
                    message,
                    decision,
                    replayed: true,
                });
            }
            Err(StorageError::ScopedRecordNotFound {
                kind: "VM-11 outcome review decision",
                ..
            }) => {}
            Err(error) => return Err(error.into()),
        }

        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        if conversation.revision != command.expected_conversation_revision {
            return Err(ApplicationError::MissionConversationRevisionMismatch {
                expected: command.expected_conversation_revision,
                actual: conversation.revision,
            });
        }
        let (cycle, checkpoint_revision, route) = mission
            .definition
            .as_ref()
            .filter(|definition| definition.manifest_id == "VM-11")
            .and_then(|definition| {
                definition.current_checkpoint().and_then(|checkpoint| {
                    checkpoint.route.as_ref().map(|route| {
                        (
                            definition.cycle,
                            checkpoint.id.clone(),
                            checkpoint.status,
                            checkpoint.revision,
                            route.clone(),
                        )
                    })
                })
            })
            .and_then(|(cycle, id, status, revision, route)| {
                (id == "continue_stop_scale_test" && status == MissionCheckpointStatus::Running)
                    .then_some((cycle, revision, route))
            })
            .ok_or(ApplicationError::StructuredOutcomeDecisionUnavailable)?;
        if checkpoint_revision != command.expected_checkpoint_revision {
            return Err(ApplicationError::MissionCheckpointRevisionMismatch {
                checkpoint_id: "continue_stop_scale_test".into(),
                expected: command.expected_checkpoint_revision,
                actual: checkpoint_revision,
            });
        }
        if !route.is_contracted()
            || route.executor != MissionCheckpointExecutor::Human
            || route.completion_policy != Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
            || route.capability_id != "decision.evaluate"
            || route.oracle_ids
                != BTreeSet::from([
                    "goal".into(),
                    "decision".into(),
                    "operating_state".into(),
                    "outcome".into(),
                ])
        {
            return Err(ApplicationError::StructuredOutcomeDecisionUnavailable);
        }
        let review = self
            .store
            .load_vm11_outcome_review(&command.project_id, &command.mission_id)?;
        let review_projection_digest = review.digest()?;
        let (source_review_checkpoint_revision, source_review_completion_digest) = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == "outcome_review")
            })
            .and_then(|checkpoint| {
                checkpoint
                    .completion
                    .as_ref()
                    .map(|completion| (checkpoint.revision, completion.evidence_digest.clone()))
            })
            .ok_or(ApplicationError::StructuredOutcomeDecisionUnavailable)?;
        if review_projection_digest != command.expected_review_projection_digest
            || source_review_completion_digest != command.expected_review_completion_digest
        {
            return Err(ApplicationError::StructuredOutcomeDecisionReviewMismatch);
        }

        let expected_mission_revision = mission.revision;
        let expected_conversation_revision = conversation.revision;
        let (message, appended) = conversation.append_user_message(
            command.message_id,
            MissionConversationMessageKind::CheckpointConfirmation,
            command.rationale,
            command.idempotency_key,
            &mission,
            now,
        )?;
        if !appended {
            return Err(ApplicationError::StructuredOutcomeDecisionReplayMismatch);
        }
        let decision = OutcomeReviewDecision::decide(
            &mission,
            &review,
            source_review_checkpoint_revision,
            source_review_completion_digest,
            command.action,
            command.decided_by,
            conversation.id.clone(),
            conversation.revision,
            message.id.clone(),
            message.sequence,
            message.content_digest.clone(),
            idempotency_key_digest,
            now,
        )?;
        let decision_digest = decision.digest()?;
        mission.begin_checkpoint_verification("continue_stop_scale_test", now)?;
        mission.complete_checkpoint(
            "continue_stop_scale_test",
            MissionCheckpointCompletion {
                oracle_ids: route.oracle_ids.clone(),
                work_product_ids: BTreeSet::new(),
                effect_ids: BTreeSet::new(),
                application_evidence: None,
                evidence_digest: decision_digest.clone(),
                verified_at: now,
            },
        )?;
        let completed_checkpoint_revision = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == "continue_stop_scale_test")
            })
            .map(|checkpoint| checkpoint.revision)
            .ok_or(ApplicationError::StructuredOutcomeDecisionUnavailable)?;
        let next_started = start_ready_catalog_checkpoint_in_memory(&mut mission, now)?;
        decision.validate_persisted(&mission, &review)?;
        let next_dispatch = current_checkpoint_dispatch_projection(&mission)?;
        let mut events = vec![
            PendingEvent::new(
                "mission.outcome_review_decided",
                serde_json::json!({
                    "missionId": mission.id,
                    "cycle": cycle,
                    "checkpointId": "continue_stop_scale_test",
                    "checkpointRevision": completed_checkpoint_revision,
                    "action": decision.action,
                    "nextContractIntent": decision.next_contract_intent,
                    "decidedByDigest": sha256(decision.decided_by.as_str().as_bytes()),
                    "conversationId": decision.conversation_id,
                    "conversationRevision": decision.conversation_revision,
                    "messageId": decision.message_id,
                    "messageSequence": decision.message_sequence,
                    "rationaleDigest": decision.rationale_digest,
                    "sourceReviewProjectionDigest": decision.source_review_projection_digest,
                    "sourceReviewCompletionDigest": decision.source_review_completion_digest,
                    "decisionDigest": decision_digest,
                    "externalEffectExecuted": false,
                }),
                now,
            ),
            PendingEvent::new(
                "mission.checkpoint_completed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": "continue_stop_scale_test",
                    "checkpointRevision": completed_checkpoint_revision,
                    "capabilityId": route.capability_id,
                    "executor": route.executor,
                    "cycle": cycle,
                    "oracleIds": route.oracle_ids,
                    "evidenceDigest": decision_digest,
                    "workProductCount": 0,
                    "effectCount": 0,
                    "nextCheckpointId": next_dispatch.as_ref().map(|dispatch| &dispatch.checkpoint_id),
                }),
                now,
            ),
        ];
        if let Some((checkpoint_id, revision, capability_id, executor, task_id, next_cycle)) =
            next_started
        {
            events.push(PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint_id,
                    "checkpointRevision": revision,
                    "capabilityId": capability_id,
                    "executor": executor,
                    "cycle": next_cycle,
                    "taskId": task_id,
                }),
                now,
            ));
        }
        self.store.complete_vm11_outcome_review_decision_atomic(
            &mission,
            expected_mission_revision,
            &conversation,
            expected_conversation_revision,
            &review,
            &decision,
            &events,
        )?;
        Ok(Vm11OutcomeReviewDecisionResult {
            mission,
            conversation,
            message,
            decision,
            next_dispatch,
            replayed: false,
        })
    }

    /// Resolves VM-11's exact post-review route without allowing a generic
    /// Application completion or a caller-supplied replacement contract.
    /// Stop produces the typed terminal; Continue reuses only the still-current
    /// frozen parent contract. Scale/Test wait for a separate Human approval
    /// that binds the complete revised contract digest.
    pub fn resolve_vm11_next_contract_or_valid_terminal(
        &mut self,
        command: ResolveVm11NextContractOrValidTerminal,
        now: DateTime<Utc>,
    ) -> Result<Vm11NextContractOrValidTerminalResult, ApplicationError> {
        let validated_command = ValidatedVm11NextContractCommand::new(command)?;
        let command = validated_command.command();
        let context = self.load_vm11_next_contract_resolution_context(command)?;
        if let Some(replayed) = self.replay_vm11_completed_resolution(&context, command)? {
            return Ok(replayed);
        }
        if let Some(replayed) = self.replay_vm11_waiting_resolution(&context, command)? {
            return Ok(replayed);
        }
        validate_vm11_next_contract_dispatch(&context.mission, command)?;

        match OutcomeReviewNextContractResolution::resolve(
            &context.mission,
            &context.parent_mission,
            &context.review,
            &context.decision,
            now,
        ) {
            Ok(resolution) => {
                self.persist_vm11_next_contract_resolution(context, command, resolution, now)
            }
            Err(
                error @ (OutcomeLedgerError::OutcomeReviewRevisedContractAuthorizationRequired
                | OutcomeLedgerError::OutcomeReviewExperimentContractAuthorizationRequired),
            ) => self.wait_vm11_next_contract_authorization(context, command, &error, now),
            Err(error) => Err(error.into()),
        }
    }

    fn load_vm11_next_contract_resolution_context(
        &self,
        command: &ResolveVm11NextContractOrValidTerminal,
    ) -> Result<Vm11NextContractResolutionContext, ApplicationError> {
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let review = self
            .store
            .load_vm11_outcome_review(&command.project_id, &command.mission_id)?;
        let decision = self
            .store
            .load_vm11_outcome_review_decision(&command.project_id, &command.mission_id)?;
        let parent_mission = self
            .store
            .load_mission(&command.project_id, &decision.source_mission_id)?;
        let source_contract_digest = OutcomeReviewNextContractResolution::validate_frozen_sources(
            &mission,
            &parent_mission,
            &review,
            &decision,
        )?;
        let decision_digest = decision.digest()?;
        if command.expected_decision_digest != decision_digest
            || command.expected_parent_mission_revision != parent_mission.revision
            || command.expected_parent_contract_digest != source_contract_digest
        {
            return Err(ApplicationError::Vm11NextContractCommandMismatch);
        }

        Ok(Vm11NextContractResolutionContext {
            mission,
            review,
            decision,
            parent_mission,
            source_contract_digest,
            decision_digest,
        })
    }

    fn replay_vm11_completed_resolution(
        &self,
        context: &Vm11NextContractResolutionContext,
        command: &ResolveVm11NextContractOrValidTerminal,
    ) -> Result<Option<Vm11NextContractOrValidTerminalResult>, ApplicationError> {
        let mission = &context.mission;
        let persisted_completion = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == "next_contract_or_valid_terminal")
            })
            .and_then(|checkpoint| checkpoint.completion.as_ref());
        let Some(completion) = persisted_completion else {
            return Ok(None);
        };
        let evidence = completion
            .application_evidence
            .as_ref()
            .ok_or(ApplicationError::Vm11NextContractReplayMismatch)?;
        if evidence.handler_id != VM11_NEXT_CONTRACT_OR_VALID_TERMINAL_HANDLER_ID
            || evidence.dispatch_mission_revision != command.expected_mission_revision
            || evidence.dispatch_checkpoint_revision != command.expected_checkpoint_revision
        {
            return Err(ApplicationError::Vm11NextContractReplayMismatch);
        }
        let resolution = OutcomeReviewNextContractResolution::reconstruct_persisted(
            mission,
            &context.parent_mission,
            &context.review,
            &context.decision,
            completion.verified_at,
        )?;
        let expected_resolution_event = vm11_next_contract_resolution_event_payload(
            mission,
            &resolution,
            &completion.evidence_digest,
        )?;
        if !self
            .store
            .events_for_mission(&command.project_id, &command.mission_id)?
            .into_iter()
            .any(|event| {
                event.event_type == "mission.next_contract_or_valid_terminal_resolved"
                    && event.payload == expected_resolution_event
            })
        {
            return Err(ApplicationError::Vm11NextContractReplayMismatch);
        }
        Ok(Some(Vm11NextContractOrValidTerminalResult::Resolved {
            next_dispatch: current_checkpoint_dispatch_projection(mission)?,
            mission: Box::new(mission.clone()),
            resolution: Box::new(resolution),
            replayed: true,
        }))
    }

    fn replay_vm11_waiting_resolution(
        &self,
        context: &Vm11NextContractResolutionContext,
        command: &ResolveVm11NextContractOrValidTerminal,
    ) -> Result<Option<Vm11NextContractOrValidTerminalResult>, ApplicationError> {
        if context.mission.stage != MissionStage::WaitingUser {
            return Ok(None);
        }
        let expected_code =
            vm11_next_contract_authorization_code(context.decision.next_contract_intent)
                .ok_or(ApplicationError::Vm11NextContractReplayMismatch)?;
        let expected_wait_event =
            vm11_next_contract_authorization_event_payload(context, command, expected_code);
        self.store
            .events_for_mission(&command.project_id, &command.mission_id)?
            .into_iter()
            .rev()
            .find(|event| {
                event.event_type == "mission.next_contract_authorization_required"
                    && event.payload == expected_wait_event
            })
            .ok_or(ApplicationError::Vm11NextContractReplayMismatch)?;
        if context
            .mission
            .block
            .as_ref()
            .is_none_or(|block| block.code != expected_code)
        {
            return Err(ApplicationError::Vm11NextContractReplayMismatch);
        }
        Ok(Some(Vm11NextContractOrValidTerminalResult::WaitingUser {
            mission: Box::new(context.mission.clone()),
            intent: context.decision.next_contract_intent,
            code: expected_code.into(),
            replayed: true,
        }))
    }

    fn persist_vm11_next_contract_resolution(
        &mut self,
        mut context: Vm11NextContractResolutionContext,
        command: &ResolveVm11NextContractOrValidTerminal,
        resolution: OutcomeReviewNextContractResolution,
        now: DateTime<Utc>,
    ) -> Result<Vm11NextContractOrValidTerminalResult, ApplicationError> {
        let expected_mission_revision = context.mission.revision;
        let (completion_evidence_digest, next_started) =
            complete_vm11_next_contract_resolution_in_memory(
                &mut context,
                command,
                &resolution,
                now,
            )?;
        resolution.validate_persisted(
            &context.mission,
            &context.parent_mission,
            &context.review,
            &context.decision,
        )?;
        let events = vm11_next_contract_resolution_events(
            &context.mission,
            &resolution,
            &completion_evidence_digest,
            next_started,
            now,
        )?;
        self.store
            .complete_vm11_next_contract_or_valid_terminal_atomic(
                &context.mission,
                expected_mission_revision,
                &context.parent_mission,
                command.expected_parent_mission_revision,
                &context.review,
                &context.decision,
                &resolution,
                &events,
            )?;
        Ok(Vm11NextContractOrValidTerminalResult::Resolved {
            next_dispatch: current_checkpoint_dispatch_projection(&context.mission)?,
            mission: Box::new(context.mission),
            resolution: Box::new(resolution),
            replayed: false,
        })
    }

    fn wait_vm11_next_contract_authorization(
        &mut self,
        mut context: Vm11NextContractResolutionContext,
        command: &ResolveVm11NextContractOrValidTerminal,
        error: &OutcomeLedgerError,
        now: DateTime<Utc>,
    ) -> Result<Vm11NextContractOrValidTerminalResult, ApplicationError> {
        validate_vm11_next_contract_resolution_time(&context, now)?;
        let code = vm11_next_contract_authorization_error_code(error);
        let expected_mission_revision = context.mission.revision;
        context.mission.block_checkpoint(
            "next_contract_or_valid_terminal",
            &hartevo_domain_kernel::MissionBlock {
                code: code.into(),
                detail: "The Human outcome action did not approve an exact replacement Operating Contract digest; budget, KPI, validity, experiment scope, and capabilities remain unchanged until a separate approval is recorded."
                    .into(),
                recoverable: true,
                observed_at: now,
            },
            MissionStage::WaitingUser,
        )?;
        let event = PendingEvent::new(
            "mission.next_contract_authorization_required",
            vm11_next_contract_authorization_event_payload(&context, command, code),
            now,
        );
        self.store.wait_vm11_next_contract_authorization_atomic(
            &context.mission,
            expected_mission_revision,
            &context.parent_mission,
            command.expected_parent_mission_revision,
            &context.review,
            &context.decision,
            code,
            &[event],
        )?;
        Ok(Vm11NextContractOrValidTerminalResult::WaitingUser {
            mission: Box::new(context.mission),
            intent: context.decision.next_contract_intent,
            code: code.into(),
            replayed: false,
        })
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the Human Checkpoint boundary binds replay, dual revisions, exact WorkProducts, confirmation evidence, completion, and next-route handoff in one transaction"
    )]
    pub fn confirm_human_mission_checkpoint(
        &mut self,
        command: ConfirmHumanMissionCheckpoint,
        now: DateTime<Utc>,
    ) -> Result<HumanMissionCheckpointConfirmation, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let mut conversation = self
            .store
            .load_mission_conversation(&command.project_id, &command.mission_id)?;
        if is_vm11_structured_outcome_decision_checkpoint(&mission, &command.checkpoint_id) {
            return Err(ApplicationError::StructuredOutcomeDecisionRequired);
        }
        let normalized_body = command.body.trim();

        if let Some(existing) = conversation
            .messages
            .iter()
            .find(|message| message.idempotency_key == command.idempotency_key.trim())
            .cloned()
        {
            let checkpoint = mission
                .definition
                .as_ref()
                .and_then(|definition| {
                    definition
                        .checkpoints
                        .iter()
                        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
                })
                .ok_or(ApplicationError::HumanCheckpointConfirmationReplayMismatch)?;
            let completion = checkpoint
                .completion
                .as_ref()
                .ok_or(ApplicationError::HumanCheckpointConfirmationReplayMismatch)?;
            if existing.id != command.message_id
                || existing.role != MissionConversationRole::User
                || existing.kind != MissionConversationMessageKind::CheckpointConfirmation
                || existing.body != normalized_body
                || existing.mission_revision != command.expected_mission_revision
                || existing.checkpoint_id.as_deref() != Some(command.checkpoint_id.as_str())
                || checkpoint.status != MissionCheckpointStatus::Completed
                || checkpoint.revision <= command.expected_checkpoint_revision
                || checkpoint.route.as_ref().is_none_or(|route| {
                    route.executor != MissionCheckpointExecutor::Human
                        || route.completion_policy
                            != Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
                        || completion.oracle_ids != route.oracle_ids
                })
                || completion.work_product_ids != command.work_product_ids
            {
                return Err(ApplicationError::HumanCheckpointConfirmationReplayMismatch);
            }
            return Ok(HumanMissionCheckpointConfirmation {
                mission: mission.clone(),
                conversation,
                message: existing,
                completed_checkpoint_id: command.checkpoint_id,
                completion_evidence_digest: completion.evidence_digest.clone(),
                next_dispatch: current_checkpoint_dispatch_projection(&mission)?,
            });
        }

        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        if conversation.revision != command.expected_conversation_revision {
            return Err(ApplicationError::MissionConversationRevisionMismatch {
                expected: command.expected_conversation_revision,
                actual: conversation.revision,
            });
        }
        let (cycle, checkpoint_revision, route) = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition.current_checkpoint().and_then(|checkpoint| {
                    checkpoint.route.clone().map(|route| {
                        (
                            definition.cycle,
                            checkpoint.revision,
                            (checkpoint.id.clone(), checkpoint.status, route),
                        )
                    })
                })
            })
            .map(|(cycle, revision, (checkpoint_id, status, route))| {
                (cycle, revision, checkpoint_id, status, route)
            })
            .and_then(|(cycle, revision, checkpoint_id, status, route)| {
                (checkpoint_id == command.checkpoint_id
                    && status == MissionCheckpointStatus::Running)
                    .then_some((cycle, revision, route))
            })
            .ok_or(ApplicationError::HumanCheckpointConfirmationUnavailable)?;
        if checkpoint_revision != command.expected_checkpoint_revision {
            return Err(ApplicationError::MissionCheckpointRevisionMismatch {
                checkpoint_id: command.checkpoint_id,
                expected: command.expected_checkpoint_revision,
                actual: checkpoint_revision,
            });
        }
        if !route.is_contracted()
            || route.executor != MissionCheckpointExecutor::Human
            || route.completion_policy != Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
        {
            return Err(ApplicationError::HumanCheckpointConfirmationUnavailable);
        }
        let requires_work_product = route.oracle_ids.contains("work_product");
        if requires_work_product == command.work_product_ids.is_empty() {
            return Err(ApplicationError::HumanCheckpointWorkProductMismatch);
        }
        let work_product_proofs = command
            .work_product_ids
            .iter()
            .map(|work_product_id| {
                mission
                    .work_products
                    .iter()
                    .find(|work_product| {
                        &work_product.id == work_product_id
                            && matches!(
                                work_product.status,
                                WorkProductStatus::ReadyForReview | WorkProductStatus::Accepted
                            )
                    })
                    .map(|work_product| {
                        serde_json::json!({
                            "id": work_product.id,
                            "revision": work_product.revision,
                            "status": work_product.status,
                            "contentDigest": work_product.content_digest,
                        })
                    })
                    .ok_or(ApplicationError::HumanCheckpointWorkProductMismatch)
            })
            .collect::<Result<Vec<_>, _>>()?;

        let expected_mission_revision = mission.revision;
        let expected_conversation_revision = conversation.revision;
        let (message, appended) = conversation.append_user_message(
            command.message_id,
            MissionConversationMessageKind::CheckpointConfirmation,
            command.body,
            command.idempotency_key,
            &mission,
            now,
        )?;
        if !appended {
            return Err(ApplicationError::HumanCheckpointConfirmationReplayMismatch);
        }
        let evidence_digest = canonical_sha256(&serde_json::json!({
            "schemaVersion": "hartevo-human-checkpoint-confirmation/v1",
            "tenantId": mission.tenant_id,
            "projectId": mission.project_id,
            "missionId": mission.id,
            "missionRevision": expected_mission_revision,
            "catalogDigest": mission.definition.as_ref().map(|definition| &definition.catalog_digest),
            "manifestVersion": mission.definition.as_ref().map(|definition| definition.manifest_version),
            "cycle": cycle,
            "checkpointId": command.checkpoint_id,
            "checkpointRevision": checkpoint_revision,
            "capabilityId": route.capability_id,
            "executor": route.executor,
            "completionPolicy": route.completion_policy,
            "oracleIds": route.oracle_ids,
            "conversationId": conversation.id,
            "conversationRevision": conversation.revision,
            "messageId": message.id,
            "messageSequence": message.sequence,
            "messageContentDigest": message.content_digest,
            "idempotencyKey": message.idempotency_key,
            "workProducts": work_product_proofs,
        }))?;

        mission.begin_checkpoint_verification(&command.checkpoint_id, now)?;
        mission.complete_checkpoint(
            &command.checkpoint_id,
            MissionCheckpointCompletion {
                oracle_ids: route.oracle_ids.clone(),
                work_product_ids: command.work_product_ids,
                effect_ids: BTreeSet::new(),
                application_evidence: None,
                evidence_digest: evidence_digest.clone(),
                verified_at: now,
            },
        )?;
        let completed_checkpoint_revision = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == command.checkpoint_id)
            })
            .map(|checkpoint| checkpoint.revision)
            .ok_or(ApplicationError::HumanCheckpointConfirmationUnavailable)?;

        let next_checkpoint_to_start = mission.definition.as_ref().and_then(|definition| {
            definition
                .current_checkpoint()
                .filter(|checkpoint| checkpoint.status == MissionCheckpointStatus::Ready)
                .and_then(|checkpoint| {
                    checkpoint.route.as_ref().map(|next_route| {
                        (
                            definition.cycle,
                            checkpoint.id.clone(),
                            next_route.capability_id.clone(),
                            next_route.executor,
                        )
                    })
                })
        });
        let next_started = if let Some((next_cycle, checkpoint_id, capability_id, executor)) =
            next_checkpoint_to_start
        {
            let task_id = TaskId::from_stable(format!(
                "mission-checkpoint-task:{}:{checkpoint_id}:cycle:{next_cycle}",
                mission.id
            ));
            mission.begin_checkpoint_with_task(
                &checkpoint_id,
                Task {
                    id: task_id.clone(),
                    title: format!("Checkpoint: {checkpoint_id}"),
                    status: TaskStatus::Running,
                    capability: capability_id.clone(),
                },
                now,
            )?;
            let revision = mission
                .definition
                .as_ref()
                .and_then(MissionDefinition::current_checkpoint)
                .filter(|checkpoint| checkpoint.id == checkpoint_id)
                .map(|checkpoint| checkpoint.revision)
                .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
            Some((
                checkpoint_id,
                revision,
                capability_id,
                executor,
                task_id,
                next_cycle,
            ))
        } else {
            None
        };
        let next_dispatch = current_checkpoint_dispatch_projection(&mission)?;

        let mut events = vec![
            PendingEvent::new(
                "mission.human_checkpoint_confirmed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": command.checkpoint_id,
                    "checkpointRevision": completed_checkpoint_revision,
                    "conversationId": conversation.id,
                    "conversationRevision": conversation.revision,
                    "messageId": message.id,
                    "messageSequence": message.sequence,
                    "messageContentDigest": message.content_digest,
                    "oracleIds": route.oracle_ids,
                    "workProductCount": work_product_proofs.len(),
                    "evidenceDigest": evidence_digest,
                }),
                now,
            ),
            PendingEvent::new(
                "mission.checkpoint_completed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": command.checkpoint_id,
                    "checkpointRevision": completed_checkpoint_revision,
                    "capabilityId": route.capability_id,
                    "executor": route.executor,
                    "cycle": cycle,
                    "oracleIds": route.oracle_ids,
                    "evidenceDigest": evidence_digest,
                    "workProductCount": work_product_proofs.len(),
                    "effectCount": 0,
                    "nextCheckpointId": next_dispatch.as_ref().map(|dispatch| &dispatch.checkpoint_id),
                }),
                now,
            ),
        ];
        if let Some((checkpoint_id, revision, capability_id, executor, task_id, next_cycle)) =
            &next_started
        {
            events.push(PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint_id,
                    "checkpointRevision": revision,
                    "capabilityId": capability_id,
                    "executor": executor,
                    "cycle": next_cycle,
                    "taskId": task_id,
                }),
                now,
            ));
        }
        self.store
            .complete_human_checkpoint_with_conversation_atomic(
                &mission,
                expected_mission_revision,
                &conversation,
                expected_conversation_revision,
                &events,
            )?;
        Ok(HumanMissionCheckpointConfirmation {
            mission,
            conversation,
            message,
            completed_checkpoint_id: command.checkpoint_id,
            completion_evidence_digest: evidence_digest,
            next_dispatch,
        })
    }

    pub fn append_mission_conversation_message(
        &mut self,
        command: AppendMissionConversationMessage,
        now: DateTime<Utc>,
    ) -> Result<MissionConversation, ApplicationError> {
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let mut conversation = self
            .store
            .load_mission_conversation(&command.project_id, &command.mission_id)?;
        let stored_revision = conversation.revision;
        let (message, appended) = conversation.append_user_message(
            command.message_id,
            command.kind,
            command.body,
            command.idempotency_key,
            &mission,
            now,
        )?;
        if !appended {
            return Ok(conversation);
        }
        if stored_revision != command.expected_conversation_revision {
            return Err(ApplicationError::MissionConversationRevisionMismatch {
                expected: command.expected_conversation_revision,
                actual: stored_revision,
            });
        }
        if let Some(previous_user_generation) = conversation
            .messages
            .iter()
            .rev()
            .skip(1)
            .find(|message| message.role == MissionConversationRole::User)
            .map(|message| message.sequence)
        {
            self.retire_previous_local_runtime_authority(
                &mission,
                previous_user_generation,
                message.sequence,
                now,
            )?;
        }
        self.store.append_mission_conversation_atomic(
            &conversation,
            command.expected_conversation_revision,
            &[PendingEvent::new(
                "mission.conversation_message_recorded",
                serde_json::json!({
                    "conversationId": conversation.id,
                    "messageId": message.id,
                    "sequence": message.sequence,
                    "role": message.role,
                    "kind": message.kind,
                    "contentDigest": message.content_digest,
                    "missionRevision": message.mission_revision,
                    "checkpointId": message.checkpoint_id,
                    "authorityChanged": false,
                }),
                now,
            )],
        )?;
        Ok(conversation)
    }

    #[allow(
        clippy::too_many_lines,
        reason = "generation retirement validates and revokes the complete branch, lease, capsule, handle, mailbox, and turn authority closure"
    )]
    fn retire_previous_local_runtime_authority(
        &mut self,
        mission: &Mission,
        previous_user_generation: u64,
        next_conversation_sequence: u64,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let turn = self
            .latest_runtime_turn_for_mission(&mission.project_id, &mission.id)?
            .filter(|turn| turn.scope.worker_generation == previous_user_generation);
        let Some(turn) = turn else {
            return self.retire_local_runtime_authority_without_turn(
                mission,
                previous_user_generation,
                next_conversation_sequence,
                now,
            );
        };
        if turn.status.is_active() && turn.status != RuntimeTurnStatus::Uncertain {
            return Err(ApplicationError::RuntimeGenerationHasActiveTurn);
        }
        let mut handle = self.store.load_worker_handle(
            &turn.scope.project_id,
            &turn.scope.workspace_id,
            &turn.scope.worker_id,
        )?;
        let mut branch = self
            .store
            .load_context_branch(&turn.scope.project_id, &turn.scope.branch_id)?;
        let mut lease = self
            .store
            .load_worker_lease(&turn.scope.project_id, &turn.scope.worker_lease_id)?;
        let mut capsule = self
            .store
            .load_context_capsule(&turn.scope.project_id, &turn.scope.capsule_id)?;
        let already_terminal = matches!(
            (branch.status, lease.status, capsule.status, handle.status),
            (
                ContextBranchStatus::Completed | ContextBranchStatus::Merged,
                WorkerLeaseStatus::Released,
                ContextCapsuleStatus::Accepted,
                WorkerHandleStatus::Completed
            ) | (
                ContextBranchStatus::Abandoned,
                WorkerLeaseStatus::Revoked | WorkerLeaseStatus::Expired,
                ContextCapsuleStatus::Cancelled | ContextCapsuleStatus::Expired,
                WorkerHandleStatus::Cancelled | WorkerHandleStatus::Failed
            )
        );
        if already_terminal {
            return Ok(());
        }
        if !matches!(
            turn.status,
            RuntimeTurnStatus::Completed
                | RuntimeTurnStatus::Interrupted
                | RuntimeTurnStatus::Failed
                | RuntimeTurnStatus::Uncertain
        ) || !matches!(
            handle.status,
            WorkerHandleStatus::Attached | WorkerHandleStatus::Detached
        ) || branch.status != ContextBranchStatus::Active
            || lease.status != WorkerLeaseStatus::Active
            || !matches!(
                capsule.status,
                ContextCapsuleStatus::Issued | ContextCapsuleStatus::Claimed
            )
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let expected_branch_revision = branch.revision;
        let expected_lease_revision = lease.revision;
        let expected_capsule_revision = capsule.revision;
        let expected_handle_revision = handle.revision;
        let conflict_digest = sha256(
            format!(
                "conversation-generation-superseded:{}:{}:{}",
                turn.id, previous_user_generation, next_conversation_sequence
            )
            .as_bytes(),
        );
        branch.abandon(&conflict_digest, now)?;
        if now >= lease.expires_at {
            lease.expire(now)?;
        } else {
            let lease_token_digest = lease.lease_token_digest.clone();
            lease.revoke(lease.generation, &lease_token_digest, now)?;
        }
        if now > capsule.expires_at {
            capsule.expire(now)?;
            handle.fail(&capsule, now)?;
        } else {
            capsule.cancel(now)?;
            handle.cancel(&capsule, now)?;
        }
        self.store.retire_runtime_turn_authority(
            &turn,
            &branch,
            expected_branch_revision,
            &lease,
            expected_lease_revision,
            &capsule,
            expected_capsule_revision,
            &handle,
            expected_handle_revision,
            &[PendingEvent::new(
                "context.runtime_turn_authority_retired",
                serde_json::json!({
                    "runtimeTurnAttemptId": turn.id,
                    "missionId": mission.id,
                    "workspaceId": turn.scope.workspace_id,
                    "workerId": turn.scope.worker_id,
                    "retiredGeneration": previous_user_generation,
                    "nextConversationSequence": next_conversation_sequence,
                    "turnStatus": turn.status,
                    "branchStatus": branch.status,
                    "leaseStatus": lease.status,
                    "capsuleStatus": capsule.status,
                    "handleStatus": handle.status,
                    "externalEffectReplayed": false,
                }),
                now,
            )],
            now,
        )?;
        Ok(())
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the pre-turn crash fence resolves and revokes every deterministic local Runtime authority aggregate"
    )]
    fn retire_local_runtime_authority_without_turn(
        &mut self,
        mission: &Mission,
        previous_user_generation: u64,
        next_conversation_sequence: u64,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let ids = LocalMissionRuntimeIds::for_mission(&mission.id, previous_user_generation);
        let workspace = match self
            .store
            .load_context_workspace(&mission.project_id, &ids.workspace_id)
        {
            Ok(workspace) => workspace,
            Err(StorageError::ScopedRecordNotFound { .. }) => return Ok(()),
            Err(error) => return Err(error.into()),
        };
        if workspace.project_id != mission.project_id
            || workspace.mission_id != mission.id
            || workspace.generation != previous_user_generation
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let recovery =
            self.latest_agent_runtime_recovery_for_mission(&mission.project_id, &mission.id)?;
        if recovery
            .as_ref()
            .is_some_and(|recovery| recovery.worker_generation > previous_user_generation)
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let recovery =
            recovery.filter(|recovery| recovery.worker_generation == previous_user_generation);
        let mut branch = self
            .store
            .load_context_branch(&mission.project_id, &ids.branch_id)?;
        let mut lease = self
            .store
            .load_worker_lease(&mission.project_id, &ids.worker_lease_id)?;
        let mut capsule = self
            .store
            .load_context_capsule(&mission.project_id, &ids.capsule_id)?;
        let mut handle = self.store.load_worker_handle(
            &mission.project_id,
            &ids.workspace_id,
            &ids.worker_id,
        )?;
        if handle.branch_id != ids.branch_id
            || handle.lease_id != ids.worker_lease_id
            || handle.capsule_id != ids.capsule_id
            || handle.mission_id != mission.id
            || handle.generation != previous_user_generation
            || branch.workspace_id != ids.workspace_id
            || branch.generation != previous_user_generation
            || lease.workspace_id != ids.workspace_id
            || lease.worker_id != ids.worker_id
            || lease.generation != previous_user_generation
            || capsule.workspace_id != ids.workspace_id
            || capsule.worker_id != ids.worker_id
            || capsule.worker_generation != previous_user_generation
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let already_terminal = matches!(
            (branch.status, lease.status, capsule.status, handle.status),
            (
                ContextBranchStatus::Completed | ContextBranchStatus::Merged,
                WorkerLeaseStatus::Released,
                ContextCapsuleStatus::Accepted,
                WorkerHandleStatus::Completed
            ) | (
                ContextBranchStatus::Abandoned,
                WorkerLeaseStatus::Revoked | WorkerLeaseStatus::Expired,
                ContextCapsuleStatus::Cancelled | ContextCapsuleStatus::Expired,
                WorkerHandleStatus::Cancelled | WorkerHandleStatus::Failed
            )
        );
        if let Some(recovery) = &recovery {
            if recovery.project_id != mission.project_id
                || recovery.mission_id != mission.id
                || recovery.workspace_id != ids.workspace_id
                || recovery.worker_id != ids.worker_id
                || recovery.worker_generation != previous_user_generation
            {
                return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
            }
            let checkpoint = self
                .store
                .load_context_checkpoint(&mission.project_id, &recovery.checkpoint_id)?;
            recovery.validate_for(&handle, &checkpoint, now)?;
        } else if handle.status != WorkerHandleStatus::Attached && !already_terminal {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        if already_terminal {
            return Ok(());
        }
        if !matches!(
            handle.status,
            WorkerHandleStatus::Attached | WorkerHandleStatus::Detached
        ) || branch.status != ContextBranchStatus::Active
            || lease.status != WorkerLeaseStatus::Active
            || !matches!(
                capsule.status,
                ContextCapsuleStatus::Issued | ContextCapsuleStatus::Claimed
            )
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let expected_branch_revision = branch.revision;
        let expected_lease_revision = lease.revision;
        let expected_capsule_revision = capsule.revision;
        let expected_handle_revision = handle.revision;
        let source_digest = recovery.as_ref().map_or_else(
            || sha256(ids.workspace_id.as_str().as_bytes()),
            |recovery| sha256(recovery.id.as_str().as_bytes()),
        );
        let conflict_digest = sha256(
            format!(
                "conversation-generation-superseded:no-turn:{source_digest}:{previous_user_generation}:{next_conversation_sequence}"
            )
            .as_bytes(),
        );
        branch.abandon(&conflict_digest, now)?;
        if now >= lease.expires_at {
            lease.expire(now)?;
        } else {
            let lease_token_digest = lease.lease_token_digest.clone();
            lease.revoke(lease.generation, &lease_token_digest, now)?;
        }
        if now > capsule.expires_at {
            capsule.expire(now)?;
            handle.fail(&capsule, now)?;
        } else {
            capsule.cancel(now)?;
            handle.cancel(&capsule, now)?;
        }
        let authority_source = if recovery.is_some() {
            "runtime_recovery_without_turn"
        } else {
            "prepared_context_without_recovery"
        };
        let runtime_process_may_require_cleanup = recovery.as_ref().is_some_and(|recovery| {
            matches!(
                recovery.status,
                RuntimeRecoveryStatus::Spawned
                    | RuntimeRecoveryStatus::Healthy
                    | RuntimeRecoveryStatus::ThreadBound
                    | RuntimeRecoveryStatus::Attached
            )
        });
        self.store.retire_context_generation_authority(
            &mission.id,
            previous_user_generation,
            &branch,
            expected_branch_revision,
            &lease,
            expected_lease_revision,
            &capsule,
            expected_capsule_revision,
            &handle,
            expected_handle_revision,
            &[PendingEvent::new(
                "context.runtime_generation_authority_retired",
                serde_json::json!({
                    "missionId": mission.id,
                    "workspaceId": ids.workspace_id,
                    "workerId": ids.worker_id,
                    "runtimeRecoveryId": recovery.as_ref().map(|recovery| &recovery.id),
                    "recoveryStatus": recovery.as_ref().map(|recovery| recovery.status),
                    "runtimeTurnAttemptId": null,
                    "retiredGeneration": previous_user_generation,
                    "nextConversationSequence": next_conversation_sequence,
                    "authoritySource": authority_source,
                    "runtimeProcessMayRequireCleanup": runtime_process_may_require_cleanup,
                    "branchStatus": branch.status,
                    "leaseStatus": lease.status,
                    "capsuleStatus": capsule.status,
                    "handleStatus": handle.status,
                    "externalEffectReplayed": false,
                }),
                now,
            )],
            now,
        )?;
        Ok(())
    }

