    pub fn prepare_creator_listing_effect(
        &mut self,
        command: &PrepareCreatorListingEffect,
        now: DateTime<Utc>,
    ) -> Result<EffectId, ApplicationError> {
        let hiring = self
            .store
            .load_creator_hiring(&command.project_id, &command.hiring_id)?;
        let mut mission = self
            .store
            .load_mission(&command.project_id, &hiring.mission_id)?;
        let expected_mission_revision = mission.revision;
        let scope_digest = hiring.listing_scope_digest();
        let effect_id = mission.propose_effect(
            creator_recruitment_effect_spec(
                &hiring,
                None,
                command.effect_id.clone(),
                command.actor_id.clone(),
                command.provider.clone(),
                command.connection_id.clone(),
                command.account_id.clone(),
                command.required_scopes.clone(),
                command.policy_version.clone(),
                command.timezone.clone(),
                command.idempotency_key.clone(),
                command.expires_in,
                scope_digest.clone(),
                None,
                now,
            )?,
            now,
        )?;
        self.store.update_mission_atomic(
            &mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "creator_hiring.listing_approval_requested",
                serde_json::json!({
                    "hiringId": hiring.id,
                    "effectId": effect_id,
                    "scopeDigest": scope_digest,
                }),
                now,
            )],
        )?;
        Ok(effect_id)
    }

    pub fn prepare_creator_invitation_effect(
        &mut self,
        command: &PrepareCreatorInvitationEffect,
        now: DateTime<Utc>,
    ) -> Result<EffectId, ApplicationError> {
        let mut hiring = self
            .store
            .load_creator_hiring(&command.project_id, &command.hiring_id)?;
        let expected_hiring_revision = hiring.state_revision;
        let candidate = hiring
            .candidates
            .iter()
            .find(|candidate| candidate.creator_id == command.creator_id)
            .cloned()
            .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
        let partner = self
            .store
            .load_partner(&command.project_id, &candidate.partner_id)?;
        let permission_evidence_digest = partner
            .permission_evidence_digest
            .clone()
            .filter(|_| partner.can_contact())
            .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
        if candidate.permission_evidence_digest.as_ref() != Some(&permission_evidence_digest) {
            return Err(ApplicationError::CreatorHiringEffectMismatch);
        }
        let scope_digest = hiring.invitation_scope_digest(&command.creator_id);
        hiring.prepare_invitation(
            &command.creator_id,
            command.effect_id.clone(),
            scope_digest.clone(),
            now,
        )?;
        let mut mission = self
            .store
            .load_mission(&command.project_id, &hiring.mission_id)?;
        let expected_mission_revision = mission.revision;
        let guard = CreatorContactEffectGuard {
            hiring_id: hiring.id.clone(),
            creator_id: command.creator_id.clone(),
            partner_id: candidate.partner_id.clone(),
            scope_digest: scope_digest.clone(),
            permission_evidence_digest,
        };
        let effect_id = mission.propose_effect(
            creator_recruitment_effect_spec(
                &hiring,
                Some(&candidate),
                command.effect_id.clone(),
                command.actor_id.clone(),
                command.provider.clone(),
                command.connection_id.clone(),
                command.account_id.clone(),
                command.required_scopes.clone(),
                command.policy_version.clone(),
                command.timezone.clone(),
                command.idempotency_key.clone(),
                command.expires_in,
                scope_digest.clone(),
                Some(guard),
                now,
            )?,
            now,
        )?;
        self.store.update_creator_hiring_and_mission_atomic(
            &hiring,
            expected_hiring_revision,
            &mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "creator_hiring.invitation_prepared",
                serde_json::json!({
                    "hiringId": hiring.id,
                    "creatorId": command.creator_id,
                    "effectId": effect_id,
                    "scopeDigest": scope_digest,
                }),
                now,
            )],
            &[PendingEvent::new(
                "creator_hiring.invitation_approval_requested",
                serde_json::json!({
                    "hiringId": hiring.id,
                    "creatorId": command.creator_id,
                    "effectId": effect_id,
                    "scopeDigest": scope_digest,
                }),
                now,
            )],
        )?;
        Ok(effect_id)
    }

    pub fn record_verified_creator_listing(
        &mut self,
        project_id: &ProjectId,
        hiring_id: &CreatorHiringId,
        effect_id: &EffectId,
        now: DateTime<Utc>,
    ) -> Result<CreatorHiring, ApplicationError> {
        let mut hiring = self.store.load_creator_hiring(project_id, hiring_id)?;
        let expected_revision = hiring.state_revision;
        let mut mission = self.store.load_mission(project_id, &hiring.mission_id)?;
        let expected_mission_revision = mission.revision;
        let proof = verified_creator_external_proof(
            &mission,
            effect_id,
            "creator.task.publish",
            &EffectClass::ExternalWrite,
            &hiring.listing_scope_digest(),
        )?;
        hiring.record_verified_listing(proof, now)?;
        mission.continue_after_verified_effect(effect_id, now)?;
        self.store.update_creator_hiring_and_mission_atomic(
            &hiring,
            expected_revision,
            &mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "creator_hiring.listing_verified",
                serde_json::json!({
                    "hiringId": hiring.id,
                    "effectId": effect_id,
                    "offerDigest": hiring.offer_digest(),
                }),
                now,
            )],
            &[PendingEvent::new(
                "mission.verified_journey_continued",
                serde_json::json!({
                    "effectId": effect_id,
                    "checkpoint": "creator_task_and_bounty",
                }),
                now,
            )],
        )?;
        Ok(hiring)
    }

    pub fn record_verified_creator_invitation(
        &mut self,
        project_id: &ProjectId,
        hiring_id: &CreatorHiringId,
        creator_id: &CreatorId,
        effect_id: &EffectId,
        now: DateTime<Utc>,
    ) -> Result<CreatorHiring, ApplicationError> {
        let mut hiring = self.store.load_creator_hiring(project_id, hiring_id)?;
        let expected_revision = hiring.state_revision;
        let mut mission = self.store.load_mission(project_id, &hiring.mission_id)?;
        let expected_mission_revision = mission.revision;
        let scope_digest = hiring.invitation_scope_digest(creator_id);
        let proof = verified_creator_external_proof(
            &mission,
            effect_id,
            "partner.engage",
            &EffectClass::Outreach,
            &scope_digest,
        )?;
        let guard = mission
            .effect(effect_id)?
            .creator_contact_guard
            .as_ref()
            .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
        if guard.hiring_id != *hiring_id || guard.creator_id != *creator_id {
            return Err(ApplicationError::CreatorHiringEffectMismatch);
        }
        hiring.record_verified_invitation(creator_id, proof, now)?;
        mission.continue_after_verified_effect(effect_id, now)?;
        self.store.update_creator_hiring_and_mission_atomic(
            &hiring,
            expected_revision,
            &mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "creator_hiring.invitation_verified",
                serde_json::json!({
                    "hiringId": hiring.id,
                    "creatorId": creator_id,
                    "effectId": effect_id,
                    "scopeDigest": scope_digest,
                }),
                now,
            )],
            &[PendingEvent::new(
                "mission.verified_journey_continued",
                serde_json::json!({
                    "effectId": effect_id,
                    "checkpoint": "outreach_sample_agreement",
                }),
                now,
            )],
        )?;
        Ok(hiring)
    }

