    pub fn review_creator_deliverable(
        &mut self,
        command: ReviewCreatorDeliverable,
        now: DateTime<Utc>,
    ) -> Result<CreatorTask, ApplicationError> {
        if command.expected_task_revision == 0
            || command.expected_deliverable_revision == 0
            || command.review_id.as_str().trim().is_empty()
            || command.reviewer_id.as_str().trim().is_empty()
            || !matches!(
                command.decision,
                ReviewDecision::Accept | ReviewDecision::RequestRevision
            )
        {
            return Err(ApplicationError::CreatorDeliverableReviewCommandMismatch);
        }
        let mut task = self
            .store
            .load_creator_task(&command.project_id, &command.task_id)?;
        if task.project_id != command.project_id || task.mission_id != command.mission_id {
            return Err(ApplicationError::CreatorDeliverableReviewCommandMismatch);
        }
        if task.state_revision != command.expected_task_revision {
            return Err(ApplicationError::CreatorTaskRevisionMismatch {
                expected: command.expected_task_revision,
                actual: task.state_revision,
            });
        }
        let deliverable = task
            .deliverables
            .iter()
            .find(|item| item.id == command.deliverable_id)
            .ok_or(ApplicationError::CreatorDeliverableReviewUnavailable)?;
        if deliverable.revision != command.expected_deliverable_revision
            || deliverable.status != DeliverableStatus::ReadyForReview
        {
            return Err(ApplicationError::CreatorDeliverableReviewUnavailable);
        }
        let expected_revision = task.state_revision;
        task.review_deliverable(
            &command.deliverable_id,
            DeliverableReviewInput {
                id: command.review_id.clone(),
                reviewer_id: command.reviewer_id,
                decision: command.decision.clone(),
                acceptance_checks: command.acceptance_checks,
                notes: command.notes,
            },
            now,
        )?;
        self.store.update_creator_task(
            &task,
            expected_revision,
            "creator.deliverable_reviewed",
            &serde_json::json!({
                "taskId": task.id,
                "deliverableId": command.deliverable_id,
                "reviewId": command.review_id,
                "decision": command.decision,
            }),
            now,
        )?;
        Ok(task)
    }

    pub fn prepare_creator_payout(
        &mut self,
        command: &PrepareCreatorPayout,
        now: DateTime<Utc>,
    ) -> Result<(PayoutAuthorization, EffectId), ApplicationError> {
        let mut task = self
            .store
            .load_creator_task(&command.project_id, &command.task_id)?;
        let authorization = self.ensure_creator_payout_authorization(&mut task, command, now)?;

        let mut mission = self
            .store
            .load_mission(&command.project_id, &task.mission_id)?;
        if mission.tenant_id != task.tenant_id || mission.id != task.mission_id {
            return Err(ApplicationError::CreatorStateInvariant);
        }
        if let Some(existing) = mission
            .effects
            .iter()
            .find(|effect| effect.id == command.effect_id)
        {
            if existing.payload_digest == authorization.scope_digest
                && existing.idempotency_key == authorization.idempotency_key
            {
                return Ok((authorization, existing.id.clone()));
            }
            return Err(ApplicationError::CreatorPayoutEffectMismatch);
        }
        let expected_mission_revision = mission.revision;
        let effect_id = mission.propose_effect(
            creator_payout_effect_spec(command, &authorization, now)?,
            now,
        )?;
        let approval_digest = mission.effect(&effect_id)?.approval_digest();
        self.store.update_mission_atomic(
            &mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "creator.payout_effect_proposed",
                serde_json::json!({
                    "taskId": task.id,
                    "payoutId": authorization.payout_id,
                    "effectId": effect_id,
                    "approvalDigest": approval_digest,
                    "payloadDigest": authorization.scope_digest,
                }),
                now,
            )],
        )?;
        Ok((authorization, effect_id))
    }

    fn ensure_creator_payout_authorization(
        &mut self,
        task: &mut CreatorTask,
        command: &PrepareCreatorPayout,
        now: DateTime<Utc>,
    ) -> Result<PayoutAuthorization, ApplicationError> {
        if let Some(existing) = task
            .payout_authorizations
            .iter()
            .find(|authorization| authorization.payout_id == command.payout_id)
            .cloned()
        {
            return Ok(existing);
        }
        let expected_revision = task.state_revision;
        let authorization = task.payout_authorization(
            command.payout_id.clone(),
            &command.milestone_id,
            &command.eligibility,
            now,
        )?;
        self.store.update_creator_task(
            task,
            expected_revision,
            "creator.payout_authorized",
            &serde_json::json!({
                "taskId": task.id,
                "payoutId": authorization.payout_id,
                "milestoneId": authorization.milestone_id,
                "amountMinor": authorization.amount.amount_minor,
                "currency": authorization.amount.currency,
                "scopeDigest": authorization.scope_digest,
            }),
            now,
        )?;
        Ok(authorization)
    }

    pub fn record_verified_creator_payout(
        &mut self,
        project_id: &ProjectId,
        task_id: &CreatorTaskId,
        effect_id: &EffectId,
        now: DateTime<Utc>,
    ) -> Result<CreatorTask, ApplicationError> {
        let mut task = self.store.load_creator_task(project_id, task_id)?;
        let expected_revision = task.state_revision;
        let mission = self.store.load_mission(project_id, &task.mission_id)?;
        let effect = mission.effect(effect_id)?;
        let changed = project_verified_creator_payout(&mut task, effect, now)?;
        if !changed {
            return Ok(task);
        }
        let receipt = effect
            .receipt
            .as_ref()
            .ok_or(ApplicationError::CreatorPayoutEffectMismatch)?;
        let verification = effect
            .verification
            .as_ref()
            .ok_or(ApplicationError::CreatorPayoutEffectMismatch)?;
        self.store.update_creator_task(
            &task,
            expected_revision,
            "creator.payout_verified",
            &serde_json::json!({
                "taskId": task.id,
                "effectId": effect_id,
                "provider": receipt.provider,
                "externalId": receipt.external_id,
                "verifiedAt": verification.observed_at,
            }),
            now,
        )?;
        Ok(task)
    }

    #[allow(clippy::too_many_arguments)]
    pub fn reconcile_creator_payout(
        &mut self,
        broker: &mut EffectBroker,
        project_id: &ProjectId,
        task_id: &CreatorTaskId,
        effect_id: &EffectId,
        reconciler: &mut impl EffectReconciler,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, CreatorTask, BrokerResult), ApplicationError> {
        let task = self.store.load_creator_task(project_id, task_id)?;
        let expected_task_revision = task.state_revision;
        let mut mission = self.store.load_mission(project_id, &task.mission_id)?;
        if mission.tenant_id != task.tenant_id
            || mission.project_id != task.project_id
            || mission.id != task.mission_id
        {
            return Err(ApplicationError::CreatorStateInvariant);
        }
        validate_creator_payout_effect_binding(&task, mission.effect(effect_id)?)?;
        let mission_before = mission.clone();
        let expected_mission_revision = mission.revision;
        let bound_result = match broker.reconcile_uncertain_authority_bound(
            &mut mission,
            effect_id,
            &mut self.store,
            reconciler,
            verifier,
            now,
        ) {
            Ok(result) => result,
            Err(bound_error) => {
                let projection_committed = bound_error.projection_committed();
                let (error, authority) = bound_error.into_parts();
                self.persist_effect_error(
                    &mut mission,
                    &error,
                    EffectProjectionPersistence {
                        mission_before: &mission_before,
                        expected_mission_revision,
                        conversation_guard: None,
                        effect_id,
                        authority: &authority,
                        projection_committed,
                    },
                )?;
                return Err(error.into());
            }
        };
        let projection_committed = bound_result.projection_committed();
        let (result, authority) = bound_result.into_parts();
        self.persist_creator_payout_completion(
            effect_id,
            CreatorPayoutCompletion {
                task,
                expected_task_revision,
                mission,
                mission_before,
                expected_mission_revision,
                result,
                authority,
                projection_committed,
            },
        )
    }

    fn persist_creator_payout_completion(
        &mut self,
        effect_id: &EffectId,
        completion: CreatorPayoutCompletion,
    ) -> Result<(Mission, CreatorTask, BrokerResult), ApplicationError> {
        let CreatorPayoutCompletion {
            mut task,
            expected_task_revision,
            mission,
            mission_before,
            expected_mission_revision,
            result,
            authority,
            projection_committed,
        } = completion;
        let route = accepted_effect_projection_route(&authority)?;
        if !projection_committed {
            if mission != mission_before || route != AcceptedEffectProjectionRoute::Empty {
                return Err(BrokerError::InvalidAuthorityClock.into());
            }
            return Ok((mission, task, result));
        }
        if mission == mission_before || route == AcceptedEffectProjectionRoute::Empty {
            return Err(BrokerError::InvalidAuthorityClock.into());
        }
        let Some(verification_completion) = authority.verification() else {
            return Err(BrokerError::InvalidAuthorityClock.into());
        };
        let projection_at = verification_completion.operation_at();
        let changed = match project_verified_creator_payout(
            &mut task,
            mission.effect(effect_id)?,
            projection_at,
        ) {
            Ok(changed) => changed,
            Err(error) => {
                self.persist_effect_success(
                    &mission,
                    &result,
                    EffectProjectionPersistence {
                        mission_before: &mission_before,
                        expected_mission_revision,
                        conversation_guard: None,
                        effect_id,
                        authority: &authority,
                        projection_committed,
                    },
                )?;
                return Err(error);
            }
        };
        if !changed {
            self.persist_effect_success(
                &mission,
                &result,
                EffectProjectionPersistence {
                    mission_before: &mission_before,
                    expected_mission_revision,
                    conversation_guard: None,
                    effect_id,
                    authority: &authority,
                    projection_committed,
                },
            )?;
            return Ok((mission, task, result));
        }
        let (mission_events, task_event) = match route {
            AcceptedEffectProjectionRoute::Reconciliation => (
                effect_reconciliation_events(mission.effect(effect_id)?, &result, &authority)?,
                creator_payout_reconciliation_event(
                    &task,
                    effect_id,
                    &result,
                    verification_completion,
                )?,
            ),
            AcceptedEffectProjectionRoute::ProviderReceipt
            | AcceptedEffectProjectionRoute::VerificationOnly => (
                effect_accepted_boundary_events(mission.effect(effect_id)?, &authority)?,
                creator_payout_verification_event(
                    &task,
                    effect_id,
                    &result,
                    verification_completion,
                )?,
            ),
            AcceptedEffectProjectionRoute::Empty
            | AcceptedEffectProjectionRoute::ProviderTerminal { .. } => {
                return Err(BrokerError::InvalidAuthorityClock.into());
            }
        };
        self.store.update_creator_task_and_mission_atomic(
            &task,
            expected_task_revision,
            &task_event,
            &mission,
            expected_mission_revision,
            &mission_events,
        )?;
        Ok((mission, task, result))
    }

    pub fn load_creator_task(
        &self,
        project_id: &ProjectId,
        task_id: &CreatorTaskId,
    ) -> Result<CreatorTask, ApplicationError> {
        Ok(self.store.load_creator_task(project_id, task_id)?)
    }

    /// Adopts the latest SQLCipher-private assistant message from one
    /// definitively completed Runtime turn. IDs and content are derived from
    /// the durable turn ledger, so a Desktop caller cannot swap the payload or
    /// attach a result to another Mission/generation.
    pub fn adopt_runtime_turn_draft(
        &mut self,
        command: &AdoptRuntimeTurnDraft,
        now: DateTime<Utc>,
    ) -> Result<RuntimeDraftAdoption, ApplicationError> {
        let attempt = self
            .store
            .load_runtime_turn_attempt(&command.project_id, &command.runtime_turn_attempt_id)?;
        if !matches!(
            attempt.scope.purpose,
            RuntimeTurnPurpose::Agent | RuntimeTurnPurpose::Followup
        ) || attempt.scope.mission_id != command.mission_id
            || attempt.scope.project_id != command.project_id
        {
            return Err(ApplicationError::RuntimeDraftScopeMismatch);
        }
        if attempt.status != RuntimeTurnStatus::Completed {
            return Err(ApplicationError::RuntimeDraftTurnNotCompleted);
        }
        let private_message = self
            .store
            .load_latest_runtime_turn_private_message(
                &command.project_id,
                &command.runtime_turn_attempt_id,
            )?
            .ok_or(ApplicationError::RuntimeDraftMessageMissing)?;
        let capsule = self
            .store
            .load_context_capsule(&command.project_id, &attempt.scope.capsule_id)?;
        if capsule.worker_generation != attempt.scope.worker_generation {
            return Err(ApplicationError::RuntimeDraftScopeMismatch);
        }
        self.adopt_verified_mission_draft(
            &command.project_id,
            &command.mission_id,
            command.expected_conversation_revision,
            VerifiedMissionDraft {
                origin: MissionDraftOrigin::ApplicationRuntime(attempt.id),
                generation: attempt.scope.worker_generation,
                capsule,
                body: private_message.body,
                body_digest: private_message.body_digest,
            },
            now,
        )
    }

    /// Adopt one definitively completed, SQLCipher-durable Cordis turn as the
    /// Mission draft. The provider body is derived by [`CordisMissionDraft`]
    /// from the typed Session log; this command only supplies Domain scope and
    /// optimistic concurrency facts.
    pub fn adopt_cordis_session_draft(
        &mut self,
        command: &AdoptCordisSessionDraft,
        draft: CordisMissionDraft,
        now: DateTime<Utc>,
    ) -> Result<RuntimeDraftAdoption, ApplicationError> {
        let CordisMissionDraft {
            session_id,
            turn,
            provider,
            model,
            system_prompt_digest,
            body,
            body_digest,
            user_message_id,
        } = draft;
        let user_message_attempt = cordis_mission_user_message_attempt(
            &user_message_id,
            &command.mission_id,
            command.generation,
        )?
        .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
        if command.generation == 0 || session_id != command.mission_id.as_str() {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        }
        let ids = LocalMissionRuntimeIds::for_mission_attempt(
            &command.mission_id,
            command.generation,
            user_message_attempt,
        );
        let capsule = self
            .store
            .load_context_capsule(&command.project_id, &ids.capsule_id)?;
        let assembly = self
            .store
            .load_context_assembly_manifest(&command.project_id, &ids.assembly_id)?;
        let profile = assembly
            .tokenizer_profile
            .as_ref()
            .ok_or(ApplicationError::CordisDraftScopeMismatch)?;
        if assembly.project_id != command.project_id
            || assembly.mission_id != command.mission_id
            || assembly.capsule_id != capsule.id
            || assembly.worker_generation != command.generation
            || assembly.prompt_digest.as_deref() != Some(system_prompt_digest.as_str())
            || profile.provider != provider
            || profile.model != model
            || capsule.worker_generation != command.generation
        {
            return Err(ApplicationError::CordisDraftScopeMismatch);
        }
        assembly.validate_dispatchable()?;
        self.adopt_verified_mission_draft(
            &command.project_id,
            &command.mission_id,
            command.expected_conversation_revision,
            VerifiedMissionDraft {
                origin: MissionDraftOrigin::CordisSession { session_id, turn },
                generation: command.generation,
                capsule,
                body,
                body_digest,
            },
            now,
        )
    }

    #[allow(
        clippy::too_many_lines,
        reason = "one shared recoverable boundary atomically adopts either verified Runtime or Cordis draft evidence without duplicating authority transitions"
    )]
    fn adopt_verified_mission_draft(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        expected_conversation_revision: u64,
        draft: VerifiedMissionDraft,
        now: DateTime<Utc>,
    ) -> Result<RuntimeDraftAdoption, ApplicationError> {
        let VerifiedMissionDraft {
            origin,
            generation,
            capsule,
            body,
            body_digest,
        } = draft;
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        if capsule.mission_id != mission.id
            || capsule.worker_generation != generation
            || capsule.task_id.as_str().trim().is_empty()
        {
            return Err(origin.scope_error());
        }
        let mut conversation = self
            .store
            .load_mission_conversation(project_id, mission_id)?;
        let identity = origin.identity();
        let work_product_id = WorkProductId::from_stable(identity.clone());
        let conversation_message_id =
            MissionConversationMessageId::from_stable(format!("mission-message:{identity}"));
        let idempotency_key = format!("{identity}:{body_digest}");

        if let Some(work_product) = mission
            .work_products
            .iter()
            .find(|work_product| work_product.id == work_product_id)
            .cloned()
        {
            let manifest = self
                .store
                .load_work_product_manifest(project_id, &work_product_id)?;
            let message = conversation
                .messages
                .iter()
                .find(|message| message.id == conversation_message_id)
                .cloned()
                .ok_or_else(|| origin.replay_error())?;
            if work_product.body != body
                || message.body != body
                || message.content_digest != body_digest
                || message.idempotency_key != idempotency_key
                || message.work_product_id.as_ref() != Some(&work_product_id)
                || manifest.work_product_id != work_product_id
            {
                return Err(origin.replay_error());
            }
            let branch = self
                .store
                .load_context_branch(project_id, &capsule.branch_id)?;
            let handle = self.store.load_worker_handle(
                project_id,
                &capsule.workspace_id,
                &capsule.worker_id,
            )?;
            let lease = self
                .store
                .load_worker_lease(project_id, &capsule.worker_lease_id)?;
            if capsule.status != ContextCapsuleStatus::Accepted
                || !matches!(
                    branch.status,
                    ContextBranchStatus::Completed | ContextBranchStatus::Merged
                )
                || handle.status != WorkerHandleStatus::Completed
                || lease.status != WorkerLeaseStatus::Released
            {
                return Err(origin.replay_error());
            }
            return Ok(RuntimeDraftAdoption {
                mission,
                manifest,
                work_product,
                conversation,
                message,
            });
        }

        if conversation.revision != expected_conversation_revision {
            return Err(ApplicationError::MissionConversationRevisionMismatch {
                expected: expected_conversation_revision,
                actual: conversation.revision,
            });
        }
        let latest_user_sequence = conversation
            .messages
            .iter()
            .rev()
            .find(|message| message.role == MissionConversationRole::User)
            .map(|message| message.sequence)
            .ok_or_else(|| origin.conversation_advanced_error())?;
        if latest_user_sequence != generation {
            return Err(origin.conversation_advanced_error());
        }

        let expected_mission_revision = mission.revision;
        mission.record_work_product(
            WorkProduct::draft(
                work_product_id.clone(),
                origin.title(),
                body.clone(),
                BTreeSet::new(),
            ),
            now,
        )?;
        let work_product = mission
            .work_products
            .iter()
            .find(|work_product| work_product.id == work_product_id)
            .cloned()
            .ok_or_else(|| MissionError::UnknownWorkProduct(work_product_id.clone()))?;
        let preview = body.chars().take(4_000).collect::<String>();
        let manifest = WorkProductManifest::create(
            mission.tenant_id.clone(),
            mission.project_id.clone(),
            mission.id.clone(),
            &work_product,
            "runtime_draft",
            WorkProductDependencies {
                fact_ids: BTreeSet::new(),
                evidence_ids: BTreeSet::new(),
                task_ids: BTreeSet::from([capsule.task_id.clone()]),
            },
            None,
            WorkProductPreview::new("text/plain", preview)?,
            BTreeSet::from(["/body".into()]),
            now,
        )?;
        let prior_conversation_revision = conversation.revision;
        let (message, appended) = conversation.append_runtime_draft(
            conversation_message_id,
            body,
            work_product_id,
            idempotency_key,
            &mission,
            now,
        )?;
        if !appended {
            return Err(origin.replay_error());
        }
        let result_size_bytes =
            u64::try_from(work_product.body.len()).map_err(|_| origin.scope_error())?;
        let expected_capsule_revision = capsule.revision;
        let mut submitted_capsule = capsule;
        submitted_capsule.submit_result(
            generation,
            ContextReturnReceipt {
                schema_id: submitted_capsule.return_contract.schema_id.clone(),
                schema_version: submitted_capsule.return_contract.schema_version,
                result_digest: body_digest.clone(),
                result_size_bytes,
                evidence_ids: BTreeSet::new(),
                artifact_digests: BTreeSet::from([manifest.artifact_digest.clone()]),
                uncertainty_digest: sha256(origin.uncertainty_label()),
                next_recommendation_digest: None,
                submitted_at: now,
            },
            now,
        )?;
        let mut accepted_capsule = submitted_capsule.clone();
        accepted_capsule.accept_result(now)?;
        let mut branch = self
            .store
            .load_context_branch(project_id, &accepted_capsule.branch_id)?;
        let expected_branch_revision = branch.revision;
        branch.complete_for_capsule(&accepted_capsule, now)?;
        let mut handle = self.store.load_worker_handle(
            project_id,
            &accepted_capsule.workspace_id,
            &accepted_capsule.worker_id,
        )?;
        let expected_handle_revision = handle.revision;
        handle.complete(&accepted_capsule, now)?;
        let mut lease = self
            .store
            .load_worker_lease(project_id, &accepted_capsule.worker_lease_id)?;
        let expected_lease_revision = lease.revision;
        let lease_token_digest = lease.lease_token_digest.clone();
        lease.release(generation, &lease_token_digest, now)?;
        self.store.finalize_runtime_draft_with_conversation_atomic(
            &mission,
            expected_mission_revision,
            &manifest,
            &conversation,
            prior_conversation_revision,
            &submitted_capsule,
            &accepted_capsule,
            expected_capsule_revision,
            &branch,
            expected_branch_revision,
            &handle,
            expected_handle_revision,
            &lease,
            expected_lease_revision,
            &[
                PendingEvent::new(
                    "work_product.created",
                    serde_json::json!({
                        "workProductId": manifest.work_product_id,
                        "workProductType": manifest.work_product_type,
                        "manifestVersion": manifest.version,
                        "manifestDigest": manifest.manifest_digest,
                        "draftSource": origin.kind(),
                        "cordisSessionId": origin.cordis_session_id(),
                        "cordisTurn": origin.cordis_turn(),
                        "runtimeTurnAttemptId": origin.runtime_turn_id(),
                        "runtimeMessageDigest": body_digest,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "mission.conversation_message_recorded",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "messageId": message.id,
                        "sequence": message.sequence,
                        "role": message.role,
                        "kind": message.kind,
                        "contentDigest": message.content_digest,
                        "missionRevision": message.mission_revision,
                        "checkpointId": message.checkpoint_id,
                        "workProductId": message.work_product_id,
                        "draftSource": origin.kind(),
                        "cordisSessionId": origin.cordis_session_id(),
                        "cordisTurn": origin.cordis_turn(),
                        "runtimeTurnAttemptId": origin.runtime_turn_id(),
                        "authorityChanged": false,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "context.capsule_result_accepted",
                    serde_json::json!({
                        "capsuleId": accepted_capsule.id,
                        "branchId": branch.id,
                        "workerId": handle.worker_id,
                        "workerGeneration": accepted_capsule.worker_generation,
                        "resultDigest": body_digest,
                        "capsuleRevision": accepted_capsule.revision,
                        "branchRevision": branch.revision,
                        "handleRevision": handle.revision,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "context.worker_released",
                    serde_json::json!({
                        "workerLeaseId": lease.id,
                        "workerId": lease.worker_id,
                        "generation": lease.generation,
                        "status": lease.status,
                        "revision": lease.revision,
                    }),
                    now,
                ),
            ],
            now,
        )?;
        Ok(RuntimeDraftAdoption {
            mission,
            manifest,
            work_product,
            conversation,
            message,
        })
    }
    pub fn record_research(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        packet: ResearchPacket,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let ResearchPacket {
            work_product_id,
            title,
            body,
            work_product_type,
            fact_ids,
            task_ids,
            file_digest,
            preview_media_type,
            preview,
            editable_scopes,
            evidence,
        } = packet;
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        let expected_revision = mission.revision;
        let mut evidence_ids = Vec::with_capacity(evidence.len());
        for input in evidence {
            evidence_ids.push(input.id.clone());
            mission.record_evidence(
                Evidence {
                    id: input.id,
                    title: input.title,
                    source_uri: input.source_uri,
                    observed_at: now,
                    confidence: input.confidence,
                    status: EvidenceStatus::Confirmed,
                    content_digest: sha256(input.content.as_bytes()),
                },
                now,
            )?;
        }
        mission.record_work_product(
            WorkProduct::draft(work_product_id.clone(), title, body, evidence_ids),
            now,
        )?;
        let work_product = mission
            .work_products
            .iter()
            .find(|product| product.id == work_product_id)
            .ok_or_else(|| MissionError::UnknownWorkProduct(work_product_id.clone()))?;
        let manifest = WorkProductManifest::create(
            mission.tenant_id.clone(),
            mission.project_id.clone(),
            mission.id.clone(),
            work_product,
            work_product_type,
            WorkProductDependencies {
                fact_ids,
                evidence_ids: work_product.evidence_ids.clone(),
                task_ids,
            },
            file_digest,
            WorkProductPreview::new(preview_media_type, preview)?,
            editable_scopes,
            now,
        )?;
        self.store.create_work_product_manifest_atomic(
            &mission,
            expected_revision,
            &manifest,
            &[
                PendingEvent::new(
                    "evidence.ready",
                    serde_json::json!({
                        "count": mission.evidence.len(),
                        "provenanceCoverage": if mission.evidence.is_empty() { 0.0 } else { 1.0 }
                    }),
                    now,
                ),
                PendingEvent::new(
                    "work_product.created",
                    serde_json::json!({
                        "workProductId": manifest.work_product_id,
                        "workProductType": manifest.work_product_type,
                        "manifestVersion": manifest.version,
                        "manifestDigest": manifest.manifest_digest,
                        "evidenceCount": mission.evidence.len(),
                    }),
                    now,
                ),
            ],
        )?;
        Ok(mission)
    }

    pub fn load_work_product_manifest(
        &self,
        project_id: &ProjectId,
        work_product_id: &WorkProductId,
    ) -> Result<WorkProductManifest, ApplicationError> {
        Ok(self
            .store
            .load_work_product_manifest(project_id, work_product_id)?)
    }

    pub fn revise_work_product(
        &mut self,
        command: ReviseWorkProduct,
        now: DateTime<Utc>,
    ) -> Result<WorkProductMutation, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        require_mission_revision(&mission, command.expected_mission_revision)?;
        let previous = mission
            .work_products
            .iter()
            .find(|product| product.id == command.work_product_id)
            .cloned()
            .ok_or_else(|| MissionError::UnknownWorkProduct(command.work_product_id.clone()))?;
        let previous_manifest = self
            .store
            .load_work_product_manifest(&command.project_id, &command.work_product_id)?;
        require_manifest_version(&previous_manifest, command.expected_manifest_version)?;
        let revised = previous.revise_content(
            command.title,
            command.body,
            command.evidence_ids.iter().cloned(),
        )?;
        mission.revise_work_product(revised.clone(), now)?;
        let manifest = previous_manifest.revise(
            &revised,
            WorkProductDependencies {
                fact_ids: command.fact_ids,
                evidence_ids: command.evidence_ids,
                task_ids: command.task_ids,
            },
            command.file_digest,
            WorkProductPreview::new(command.preview_media_type, command.preview)?,
            command.editable_scopes,
            now,
        )?;
        self.store.revise_work_product_manifest_atomic(
            &mission,
            command.expected_mission_revision,
            &manifest,
            command.expected_manifest_version,
            &[PendingEvent::new(
                "work_product.revised",
                serde_json::json!({
                    "workProductId": revised.id,
                    "workProductRevision": revised.revision,
                    "manifestVersion": manifest.version,
                    "manifestDigest": manifest.manifest_digest,
                }),
                now,
            )],
        )?;
        Ok(WorkProductMutation {
            mission,
            manifest,
            work_product: revised,
        })
    }

    pub fn accept_work_product(
        &mut self,
        command: &AcceptWorkProduct,
        now: DateTime<Utc>,
    ) -> Result<WorkProductMutation, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        require_mission_revision(&mission, command.expected_mission_revision)?;
        let previous = mission
            .work_products
            .iter()
            .find(|product| product.id == command.work_product_id)
            .cloned()
            .ok_or_else(|| MissionError::UnknownWorkProduct(command.work_product_id.clone()))?;
        let previous_manifest = self
            .store
            .load_work_product_manifest(&command.project_id, &command.work_product_id)?;
        require_manifest_version(&previous_manifest, command.expected_manifest_version)?;
        let accepted = previous.accept()?;
        mission.revise_work_product(accepted.clone(), now)?;
        let manifest = previous_manifest.revise(
            &accepted,
            previous_manifest.dependencies.clone(),
            previous_manifest.file_digest.clone(),
            previous_manifest.preview.clone(),
            previous_manifest.editable_scopes.clone(),
            now,
        )?;
        self.store.revise_work_product_manifest_atomic(
            &mission,
            command.expected_mission_revision,
            &manifest,
            command.expected_manifest_version,
            &[PendingEvent::new(
                "work_product.accepted",
                serde_json::json!({
                    "workProductId": accepted.id,
                    "workProductRevision": accepted.revision,
                    "manifestVersion": manifest.version,
                    "manifestDigest": manifest.manifest_digest,
                    "adoptionStatus": manifest.adoption_status,
                }),
                now,
            )],
        )?;
        Ok(WorkProductMutation {
            mission,
            manifest,
            work_product: accepted,
        })
    }

    pub fn propose_preview_effect(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        command: ProposePreviewEffect,
        now: DateTime<Utc>,
    ) -> Result<EffectId, ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        self.persist_preview_effect(mission, command, now)
    }

    /// Propose one preview Effect only at the exact caller-observed Mission
    /// revision. Desktop uses this entry point after Cordis admits the typed
    /// proposal; it still creates Domain state only and never invokes a
    /// provider, Effect Ledger, Receipt, or Verification path.
    pub fn propose_preview_effect_at_revision(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        expected_mission_revision: u64,
        command: ProposePreviewEffect,
        now: DateTime<Utc>,
    ) -> Result<EffectId, ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        require_mission_revision(&mission, expected_mission_revision)?;
        self.persist_preview_effect(mission, command, now)
    }

    fn persist_preview_effect(
        &mut self,
        mut mission: Mission,
        command: ProposePreviewEffect,
        now: DateTime<Utc>,
    ) -> Result<EffectId, ApplicationError> {
        if mission
            .effects
            .iter()
            .any(|effect| effect.id == command.effect_id)
        {
            return Err(ApplicationError::DuplicatePreviewEffectId(
                command.effect_id,
            ));
        }
        let expected_revision = mission.revision;
        let effect_id = mission.propose_effect(
            EffectSpec {
                id: command.effect_id,
                actor_id: command.actor_id,
                capability: command.capability,
                provider: command.provider,
                connection_id: command.connection_id,
                account_id: command.account_id,
                required_scopes: command.required_scopes,
                effect_class: EffectClass::ExternalWrite,
                description: command.description,
                target_resource: command.target_resource,
                audience_digest: command.audience_digest,
                payload_digest: command.payload_digest,
                asset_digests: command.asset_digests,
                scheduled_for: command.scheduled_for,
                timezone: command.timezone,
                consent: command.consent,
                consent_record_id: command.consent_record_id,
                consent_requirement: command.consent_requirement,
                conversation_guard: None,
                creator_contact_guard: None,
                policy_version: command.policy_version,
                risk: EffectRisk::Low,
                idempotency_key: command.idempotency_key,
                amount: command.amount,
                expires_at: now + command.expires_in,
            },
            now,
        )?;
        let effect = mission.effect(&effect_id)?;
        let event_payload = serde_json::json!({
            "effectId": effect_id,
            "scopeDigest": effect.approval_digest(),
            "amountMinor": effect.amount.amount_minor,
            "currency": effect.amount.currency
        });
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new("approval.requested", event_payload, now)],
        )?;
        Ok(effect_id)
    }

    pub fn approve_effect(
        &mut self,
        broker: &EffectBroker,
        project_id: &ProjectId,
        mission_id: &MissionId,
        effect_id: &EffectId,
        actor_id: ActorId,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        let expected_revision = mission.revision;
        broker.approve(&mut mission, effect_id, actor_id, &self.store, now)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "approval.decided",
                serde_json::json!({"effectId": effect_id, "decision": "approved"}),
                now,
            )],
        )?;
        Ok(mission)
    }

    /// Grants Domain Kernel Approval for one Proposed Effect using the exact
    /// frozen digest and Mission revision. The window cannot stamp a SAMPLE
    /// digest. Success never executes the Effect or mints a Receipt.
    pub fn approve_proposed_effect(
        &mut self,
        broker: &EffectBroker,
        command: ApproveProposedEffect,
        actor_id: ActorId,
        now: DateTime<Utc>,
    ) -> Result<ProposedEffectApprovalGrant, ApplicationError> {
        if command.expected_mission_revision == 0
            || command.effect_id.as_str().trim().is_empty()
            || !is_sha256_text(&command.expected_scope_digest)
        {
            return Err(ApplicationError::ProposedEffectApprovalCommandMismatch);
        }
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        {
            let effect = mission.effect(&command.effect_id)?;
            if effect.status != EffectStatus::Proposed {
                let replayed_approval = effect.approval.clone().filter(|approval| {
                    approval.decision == ApprovalDecision::Approved
                        && approval.scope_digest == command.expected_scope_digest
                        && approval.scope_digest == effect.approval_digest()
                        && now < approval.valid_until
                });
                return if let Some(approval) = replayed_approval {
                    Ok(ProposedEffectApprovalGrant {
                        mission,
                        effect_id: command.effect_id,
                        approval,
                        replayed: true,
                    })
                } else {
                    Err(ApplicationError::ProposedEffectApprovalUnavailable)
                };
            }
            if mission.stage != MissionStage::WaitingApproval {
                return Err(ApplicationError::ProposedEffectApprovalUnavailable);
            }
            if effect.approval_digest() != command.expected_scope_digest {
                return Err(ApplicationError::ProposedEffectApprovalDigestMismatch);
            }
        }
        let expected_revision = mission.revision;
        broker.approve(&mut mission, &command.effect_id, actor_id, &self.store, now)?;
        let approval = mission
            .effect(&command.effect_id)?
            .approval
            .clone()
            .ok_or(ApplicationError::ProposedEffectApprovalUnavailable)?;
        if approval.decision != ApprovalDecision::Approved
            || approval.scope_digest != command.expected_scope_digest
            || now >= approval.valid_until
        {
            return Err(ApplicationError::ProposedEffectApprovalUnavailable);
        }
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "approval.decided",
                serde_json::json!({"effectId": command.effect_id, "decision": "approved"}),
                now,
            )],
        )?;
        Ok(ProposedEffectApprovalGrant {
            mission,
            effect_id: command.effect_id,
            approval,
            replayed: false,
        })
    }

    #[allow(clippy::too_many_arguments)]
    pub fn execute_effect(
        &mut self,
        broker: &mut EffectBroker,
        project_id: &ProjectId,
        mission_id: &MissionId,
        effect_id: &EffectId,
        executor: &mut impl EffectExecutor,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, BrokerResult), ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        self.execute_loaded_effect(broker, mission, effect_id, executor, verifier, now)
    }

    /// Executes one exact, currently Approved Effect after re-reading the
    /// Mission CAS and approval-time Broker authorization from durable state.
    /// A stale/swapped command fails before the Broker can call its executor.
    pub fn execute_approved_effect_at_revision(
        &mut self,
        broker: &mut EffectBroker,
        command: &ExecuteApprovedEffect,
        executor: &mut impl EffectExecutor,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, BrokerResult), ApplicationError> {
        if command.expected_mission_revision == 0
            || command.effect_id.as_str().trim().is_empty()
            || !is_sha256_text(&command.expected_scope_digest)
            || !is_sha256_text(&command.expected_broker_authorization_digest)
        {
            return Err(ApplicationError::EffectExecutionCommandMismatch);
        }
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        let effect = mission.effect(&command.effect_id)?;
        let approval = effect
            .approval
            .as_ref()
            .ok_or(ApplicationError::EffectExecutionAuthorityMismatch)?;
        if effect.status != EffectStatus::Approved
            || approval.decision != ApprovalDecision::Approved
            || approval.scope_digest != effect.approval_digest()
            || approval.scope_digest != command.expected_scope_digest
            || approval.permission_digest != command.expected_broker_authorization_digest
        {
            return Err(ApplicationError::EffectExecutionAuthorityMismatch);
        }
        self.execute_loaded_effect(broker, mission, &command.effect_id, executor, verifier, now)
    }

    #[allow(clippy::too_many_arguments)]
    fn execute_loaded_effect(
        &mut self,
        broker: &mut EffectBroker,
        mut mission: Mission,
        effect_id: &EffectId,
        executor: &mut impl EffectExecutor,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, BrokerResult), ApplicationError> {
        let mission_before = mission.clone();
        let expected_revision = mission.revision;
        let effect_before_execution = mission.effect(effect_id)?.clone();
        let conversation_guard = effect_before_execution.conversation_guard.clone();
        let bound_result = match broker.execute_and_verify_authority_bound(
            &mut mission,
            effect_id,
            &mut self.store,
            executor,
            verifier,
            now,
        ) {
            Ok(result) => result,
            Err(bound_error) => {
                let projection_committed = bound_error.projection_committed();
                let (error, authority) = bound_error.into_parts();
                self.persist_effect_error(
                    &mut mission,
                    &error,
                    EffectProjectionPersistence {
                        mission_before: &mission_before,
                        expected_mission_revision: expected_revision,
                        conversation_guard: conversation_guard.as_ref(),
                        effect_id,
                        authority: &authority,
                        projection_committed,
                    },
                )?;
                return Err(error.into());
            }
        };
        let projection_committed = bound_result.projection_committed();
        let (result, authority) = bound_result.into_parts();
        self.persist_effect_success(
            &mission,
            &result,
            EffectProjectionPersistence {
                mission_before: &mission_before,
                expected_mission_revision: expected_revision,
                conversation_guard: conversation_guard.as_ref(),
                effect_id,
                authority: &authority,
                projection_committed,
            },
        )?;
        Ok((mission, result))
    }

    /// Verifies one durable N15 receipt with a fresh independent source. This
    /// route never acquires an execution/reconciliation capability and emits
    /// at most one redacted verification event; it does not touch
    /// Conversation, Outcome, Connected, or E4 state.
    // Command fencing, Broker invocation, durable projection, and the single
    // redacted event form one atomic application boundary.
    #[allow(clippy::too_many_lines)]
    pub fn verify_recorded_receipt_at_revision(
        &mut self,
        broker: &mut EffectBroker,
        command: &VerifyRecordedReceiptAtRevision,
        binding: &ReceiptVerificationClaimBinding,
        source: &mut impl ReceiptVerificationSource,
        now: DateTime<Utc>,
    ) -> Result<(Mission, IndependentVerificationResult), ApplicationError> {
        if command.expected_mission_revision == 0
            || command.effect_id.as_str().trim().is_empty()
            || command.expected_receipt_id.as_str().trim().is_empty()
            || !is_canonical_sha256_text(&command.expected_receipt_request_digest)
            || !is_canonical_sha256_text(&command.expected_receipt_response_digest)
            || !is_canonical_sha256_text(&command.expected_receipt_binding_digest)
            || !is_canonical_sha256_text(&command.expected_n15_evidence_digest)
            || !is_canonical_sha256_text(&command.expected_observation_authority_digest)
            || !is_canonical_sha256_text(&command.expected_source_binding_digest)
            || !is_canonical_sha256_text(&command.expected_scope_digest)
            || !is_canonical_sha256_text(&command.expected_broker_authorization_digest)
        {
            return Err(ApplicationError::EffectVerificationCommandMismatch);
        }
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        let effect = mission
            .effect(&command.effect_id)
            .map_err(|_| ApplicationError::EffectVerificationAuthorityMismatch)?;
        let approval = effect
            .approval
            .as_ref()
            .ok_or(ApplicationError::EffectVerificationAuthorityMismatch)?;
        let receipt = effect
            .receipt
            .as_ref()
            .ok_or(ApplicationError::EffectVerificationAuthorityMismatch)?;
        let status_shape_is_valid = match effect.status {
            EffectStatus::ReceiptRecorded => effect.verification.is_none(),
            EffectStatus::VerificationRequired | EffectStatus::Verified | EffectStatus::Failed => {
                effect.verification.is_some()
            }
            _ => false,
        };
        if !status_shape_is_valid
            || approval.decision != ApprovalDecision::Approved
            || approval.scope_digest != effect.approval_digest()
            || approval.scope_digest != command.expected_scope_digest
            || approval.permission_digest != command.expected_broker_authorization_digest
            || receipt.id != command.expected_receipt_id
            || receipt.accepted_at != command.expected_receipt_accepted_at
            || receipt.provider != effect.provider
            || receipt.request_digest != command.expected_receipt_request_digest
            || receipt.response_digest != command.expected_receipt_response_digest
            || command.expected_n15_evidence_digest != receipt.response_digest
            || binding.approval_scope_digest() != command.expected_scope_digest
            || binding.broker_authorization_digest() != command.expected_broker_authorization_digest
            || binding.receipt_binding_digest() != command.expected_receipt_binding_digest
            || binding.observation_authority_digest()
                != command.expected_observation_authority_digest
            || binding.source_binding_digest() != command.expected_source_binding_digest
            || binding.validate_for(effect, receipt).is_err()
            || canonical_verifier_id(source.verifier_id()).is_none()
            || source.source_binding_digest() != command.expected_source_binding_digest
        {
            return Err(ApplicationError::EffectVerificationAuthorityMismatch);
        }

        let mission_before = mission.clone();
        let result = broker.verify_recorded_receipt(
            &mut mission,
            &command.effect_id,
            &mut self.store,
            binding,
            source,
            now,
        )?;
        let projected_effect = mission.effect(&command.effect_id).map_err(|_| {
            ApplicationError::Broker(BrokerError::DurableProjectionRecoveryRequired)
        })?;
        let expected_status = match result.verification.status {
            VerificationStatus::Confirmed => EffectStatus::Verified,
            VerificationStatus::Rejected => EffectStatus::Failed,
            VerificationStatus::Inconclusive => EffectStatus::VerificationRequired,
        };
        if projected_effect.receipt.as_ref() != Some(&result.receipt)
            || projected_effect.verification.as_ref() != Some(&result.verification)
            || projected_effect.status != expected_status
        {
            return Err(ApplicationError::Broker(
                BrokerError::DurableProjectionRecoveryRequired,
            ));
        }
        if mission != mission_before {
            let event_type = match result.verification.status {
                VerificationStatus::Confirmed => "effect.reconciliation_verified",
                VerificationStatus::Rejected => "effect.reconciliation_verification_rejected",
                VerificationStatus::Inconclusive => {
                    "effect.reconciliation_verification_inconclusive"
                }
            };
            let event = PendingEvent::new(
                event_type,
                serde_json::json!({
                    "effectId": command.effect_id,
                    "verificationId": result.verification.id,
                    "status": result.verification.status,
                    "readOnlyReconciliation": true,
                    "providerExecutionReplayed": false,
                    "verificationDeferred": false,
                    "independent": true,
                    "authoritySequence": result.completion().sequence(),
                }),
                result.completion().operation_at(),
            );
            self.store
                .update_mission_atomic(&mission, command.expected_mission_revision, &[event])
                .map_err(|_| {
                    ApplicationError::Broker(BrokerError::DurableProjectionRecoveryRequired)
                })?;
        }
        Ok((mission, result))
    }

    #[allow(clippy::too_many_arguments)]
    pub fn reconcile_effect(
        &mut self,
        broker: &mut EffectBroker,
        project_id: &ProjectId,
        mission_id: &MissionId,
        effect_id: &EffectId,
        reconciler: &mut impl EffectReconciler,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, BrokerResult), ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        self.reconcile_loaded_effect(broker, mission, effect_id, reconciler, verifier, now)
    }

    /// Reconcile one exact durable uncertain Effect after re-reading its
    /// Mission revision and original Approval/Broker authorization.
    ///
    /// The method accepts no executor and enters only the Broker's existing
    /// read-reconciliation path. A stale or swapped command fails before the
    /// reconciler or verifier can be called.
    pub fn reconcile_uncertain_effect_at_revision(
        &mut self,
        broker: &mut EffectBroker,
        command: &ReconcileUncertainEffect,
        reconciler: &mut impl EffectReconciler,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, BrokerResult), ApplicationError> {
        if command.expected_mission_revision == 0
            || command.effect_id.as_str().trim().is_empty()
            || !is_canonical_sha256_text(&command.expected_scope_digest)
            || !is_canonical_sha256_text(&command.expected_broker_authorization_digest)
        {
            return Err(ApplicationError::EffectReconciliationCommandMismatch);
        }
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        let effect = mission.effect(&command.effect_id)?;
        let approval = effect
            .approval
            .as_ref()
            .ok_or(ApplicationError::EffectReconciliationAuthorityMismatch)?;
        if effect.status != EffectStatus::VerificationRequired
            || approval.decision != ApprovalDecision::Approved
            || approval.scope_digest != effect.approval_digest()
            || approval.scope_digest != command.expected_scope_digest
            || approval.permission_digest != command.expected_broker_authorization_digest
        {
            return Err(ApplicationError::EffectReconciliationAuthorityMismatch);
        }
        self.reconcile_loaded_effect(
            broker,
            mission,
            &command.effect_id,
            reconciler,
            verifier,
            now,
        )
    }

    /// Projects one exact receipt-only provider recovery. This path accepts no
    /// verifier and cannot represent NotExecuted, ProviderRejected, or a
    /// generic uncertain observation as a successful result.
    pub fn reconcile_uncertain_receipt_at_revision(
        &mut self,
        broker: &mut EffectBroker,
        command: &ReconcileUncertainEffect,
        reconciler: &mut impl EffectReceiptReconciler,
        now: DateTime<Utc>,
    ) -> Result<(Mission, ReceiptReconciliationResult), ApplicationError> {
        if command.expected_mission_revision == 0
            || command.effect_id.as_str().trim().is_empty()
            || !is_canonical_sha256_text(&command.expected_scope_digest)
            || !is_canonical_sha256_text(&command.expected_broker_authorization_digest)
        {
            return Err(ApplicationError::EffectReconciliationCommandMismatch);
        }
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        let effect = mission.effect(&command.effect_id)?;
        let approval = effect
            .approval
            .as_ref()
            .ok_or(ApplicationError::EffectReconciliationAuthorityMismatch)?;
        if !matches!(
            effect.status,
            EffectStatus::VerificationRequired | EffectStatus::ReceiptRecorded
        ) || (effect.status == EffectStatus::ReceiptRecorded
            && (effect.receipt.is_none() || effect.verification.is_some()))
            || approval.decision != ApprovalDecision::Approved
            || approval.scope_digest != effect.approval_digest()
            || approval.scope_digest != command.expected_scope_digest
            || approval.permission_digest != command.expected_broker_authorization_digest
        {
            return Err(ApplicationError::EffectReconciliationAuthorityMismatch);
        }
        let mission_before = mission.clone();
        let expected_revision = mission.revision;
        let conversation_guard = effect.conversation_guard.clone();
        let bound = broker
            .reconcile_uncertain_receipt_authority_bound(
                &mut mission,
                &command.effect_id,
                &mut self.store,
                reconciler,
                now,
            )
            .map_err(|bound_error| {
                let projection_committed = bound_error.projection_committed();
                let (error, authority) = bound_error.into_parts();
                if projection_committed
                    || mission != mission_before
                    || authority.latest_accepted().is_some()
                {
                    return ApplicationError::EffectReceiptRecoveryProjectionMismatch;
                }
                error.into()
            })?;
        let projection_committed = bound.projection_committed();
        let (result, authority) = bound.into_parts();
        if !projection_committed {
            if mission != mission_before
                || mission.effect(&command.effect_id)?.receipt.as_ref() != Some(&result.receipt)
            {
                return Err(ApplicationError::EffectReceiptRecoveryProjectionMismatch);
            }
            return Ok((mission, result));
        }
        let effect = mission.effect(&command.effect_id)?;
        if effect.status != EffectStatus::ReceiptRecorded
            || effect.receipt.as_ref() != Some(&result.receipt)
            || effect.verification.is_some()
            || authority.reconciliation().is_none()
            || authority.verification().is_some()
        {
            return Err(ApplicationError::EffectReceiptRecoveryProjectionMismatch);
        }
        let events = vec![effect_receipt_found_event(effect, &result, &authority)?];
        self.persist_reconciled_receipt_boundaries(
            &mission,
            expected_revision,
            conversation_guard.as_ref(),
            &command.effect_id,
            &authority,
            &events,
        )?;
        Ok((mission, result))
    }

    #[allow(clippy::too_many_arguments)]
    fn reconcile_loaded_effect(
        &mut self,
        broker: &mut EffectBroker,
        mut mission: Mission,
        effect_id: &EffectId,
        reconciler: &mut impl EffectReconciler,
        verifier: &mut impl EffectVerifier,
        now: DateTime<Utc>,
    ) -> Result<(Mission, BrokerResult), ApplicationError> {
        let mission_before = mission.clone();
        let expected_revision = mission.revision;
        let conversation_guard = mission.effect(effect_id)?.conversation_guard.clone();
        let bound_result = match broker.reconcile_uncertain_authority_bound(
            &mut mission,
            effect_id,
            &mut self.store,
            reconciler,
            verifier,
            now,
        ) {
            Ok(result) => result,
            Err(bound_error) => {
                let projection_committed = bound_error.projection_committed();
                let (error, authority) = bound_error.into_parts();
                self.persist_effect_error(
                    &mut mission,
                    &error,
                    EffectProjectionPersistence {
                        mission_before: &mission_before,
                        expected_mission_revision: expected_revision,
                        conversation_guard: conversation_guard.as_ref(),
                        effect_id,
                        authority: &authority,
                        projection_committed,
                    },
                )?;
                return Err(error.into());
            }
        };
        let projection_committed = bound_result.projection_committed();
        let (result, authority) = bound_result.into_parts();
        self.persist_effect_success(
            &mission,
            &result,
            EffectProjectionPersistence {
                mission_before: &mission_before,
                expected_mission_revision: expected_revision,
                conversation_guard: conversation_guard.as_ref(),
                effect_id,
                authority: &authority,
                projection_committed,
            },
        )?;
        Ok((mission, result))
    }

    fn persist_reconciliation_success(
        &mut self,
        mission: &Mission,
        expected_mission_revision: u64,
        conversation_guard: Option<&ConversationEffectGuard>,
        effect_id: &EffectId,
        result: &BrokerResult,
        authority: &EffectCompletionAuthority,
    ) -> Result<(), ApplicationError> {
        let events = effect_reconciliation_events(mission.effect(effect_id)?, result, authority)?;
        self.persist_reconciled_receipt_boundaries(
            mission,
            expected_mission_revision,
            conversation_guard,
            effect_id,
            authority,
            &events,
        )
    }

    fn persist_reconciled_receipt_boundaries(
        &mut self,
        mission: &Mission,
        expected_mission_revision: u64,
        conversation_guard: Option<&ConversationEffectGuard>,
        effect_id: &EffectId,
        authority: &EffectCompletionAuthority,
        events: &[PendingEvent],
    ) -> Result<(), ApplicationError> {
        let reconciliation_completion = authority
            .reconciliation()
            .ok_or(BrokerError::InvalidAuthorityClock)?;
        let receipt = mission
            .effect(effect_id)?
            .receipt
            .as_ref()
            .ok_or(BrokerError::InvalidAuthorityClock)?;
        let Some(guard) = conversation_guard else {
            self.store
                .update_mission_atomic(mission, expected_mission_revision, events)?;
            return Ok(());
        };
        let mut conversation = self
            .store
            .load_conversation(&mission.project_id, &guard.conversation_id)?;
        let expected_conversation_revision = conversation.revision;
        let provider_event_digest = provider_receipt_event_digest(receipt);
        conversation.record_reconciled_agent_reply(
            effect_id,
            receipt.id.clone(),
            provider_event_digest.clone(),
            guard.control_generation,
            receipt.accepted_at,
            reconciliation_completion.operation_at(),
        )?;
        self.store.update_conversation_and_mission_atomic(
            &conversation,
            expected_conversation_revision,
            mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "conversation.reply_reconciled_sent",
                serde_json::json!({
                    "conversationId": conversation.id,
                    "effectId": effect_id,
                    "receiptId": receipt.id,
                    "providerEventDigest": provider_event_digest,
                    "originalControlGeneration": guard.control_generation,
                    "readOnlyReconciliation": true,
                    "authoritySequence": reconciliation_completion.sequence(),
                }),
                reconciliation_completion.operation_at(),
            )],
            events,
        )?;
        Ok(())
    }

    fn persist_effect_success(
        &mut self,
        mission: &Mission,
        result: &BrokerResult,
        context: EffectProjectionPersistence<'_>,
    ) -> Result<(), ApplicationError> {
        let route = accepted_effect_projection_route(context.authority)?;
        if !context.projection_committed {
            return if mission == context.mission_before
                && route == AcceptedEffectProjectionRoute::Empty
            {
                Ok(())
            } else {
                Err(BrokerError::InvalidAuthorityClock.into())
            };
        }
        if mission == context.mission_before || route == AcceptedEffectProjectionRoute::Empty {
            return Err(BrokerError::InvalidAuthorityClock.into());
        }
        match route {
            AcceptedEffectProjectionRoute::Reconciliation => self.persist_reconciliation_success(
                mission,
                context.expected_mission_revision,
                context.conversation_guard,
                context.effect_id,
                result,
                context.authority,
            ),
            AcceptedEffectProjectionRoute::ProviderReceipt
            | AcceptedEffectProjectionRoute::VerificationOnly => self.persist_execution_boundaries(
                mission,
                context.expected_mission_revision,
                context.conversation_guard,
                context.effect_id,
                context.authority,
            ),
            AcceptedEffectProjectionRoute::Empty => Err(BrokerError::InvalidAuthorityClock.into()),
            AcceptedEffectProjectionRoute::ProviderTerminal { .. } => {
                Err(BrokerError::InvalidAuthorityClock.into())
            }
        }
    }

    fn persist_effect_error(
        &mut self,
        mission: &mut Mission,
        error: &BrokerError,
        context: EffectProjectionPersistence<'_>,
    ) -> Result<(), ApplicationError> {
        let route = accepted_effect_projection_route(context.authority)?;
        if !context.projection_committed {
            return if mission == context.mission_before {
                Ok(())
            } else {
                Err(BrokerError::InvalidAuthorityClock.into())
            };
        }
        if mission == context.mission_before || route == AcceptedEffectProjectionRoute::Empty {
            return Err(BrokerError::InvalidAuthorityClock.into());
        }
        match route {
            AcceptedEffectProjectionRoute::ProviderTerminal { completion } => self
                .persist_interrupted_effect(
                    mission,
                    context.expected_mission_revision,
                    context.conversation_guard,
                    context.effect_id,
                    completion,
                ),
            AcceptedEffectProjectionRoute::ProviderReceipt
            | AcceptedEffectProjectionRoute::VerificationOnly => self.persist_execution_boundaries(
                mission,
                context.expected_mission_revision,
                context.conversation_guard,
                context.effect_id,
                context.authority,
            ),
            AcceptedEffectProjectionRoute::Reconciliation => self.persist_reconciliation_error(
                mission,
                context.expected_mission_revision,
                context.conversation_guard,
                context.effect_id,
                error,
                context.authority,
            ),
            AcceptedEffectProjectionRoute::Empty => Err(BrokerError::InvalidAuthorityClock.into()),
        }
    }

    fn persist_reconciliation_error(
        &mut self,
        mission: &Mission,
        expected_mission_revision: u64,
        conversation_guard: Option<&ConversationEffectGuard>,
        effect_id: &EffectId,
        error: &BrokerError,
        authority: &EffectCompletionAuthority,
    ) -> Result<(), ApplicationError> {
        let reconciliation_completion = authority
            .reconciliation()
            .ok_or(BrokerError::InvalidAuthorityClock)?;
        let mission_events =
            effect_reconciliation_error_events(mission.effect(effect_id)?, error, authority)?;
        if mission.effect(effect_id)?.receipt.is_some() {
            return self.persist_reconciled_receipt_boundaries(
                mission,
                expected_mission_revision,
                conversation_guard,
                effect_id,
                authority,
                &mission_events,
            );
        }
        let Some(guard) = conversation_guard else {
            self.store.update_mission_atomic(
                mission,
                expected_mission_revision,
                &mission_events,
            )?;
            return Ok(());
        };
        let mut conversation = self
            .store
            .load_conversation(&mission.project_id, &guard.conversation_id)?;
        let expected_conversation_revision = conversation.revision;
        let conversation_event_type = project_conversation_reconciliation_error(
            &mut conversation,
            mission,
            effect_id,
            guard.control_generation,
            reconciliation_completion.operation_at(),
        )?;
        self.store.update_conversation_and_mission_atomic(
            &conversation,
            expected_conversation_revision,
            mission,
            expected_mission_revision,
            &[PendingEvent::new(
                conversation_event_type,
                serde_json::json!({
                    "conversationId": conversation.id,
                    "effectId": effect_id,
                    "effectStatus": mission.effect(effect_id)?.status,
                    "originalControlGeneration": guard.control_generation,
                    "readOnlyReconciliation": true,
                    "authoritySequence": reconciliation_completion.sequence(),
                }),
                reconciliation_completion.operation_at(),
            )],
            &mission_events,
        )?;
        Ok(())
    }

    fn persist_execution_boundaries(
        &mut self,
        mission: &Mission,
        expected_mission_revision: u64,
        conversation_guard: Option<&ConversationEffectGuard>,
        effect_id: &EffectId,
        authority: &EffectCompletionAuthority,
    ) -> Result<(), ApplicationError> {
        let events = effect_accepted_boundary_events(mission.effect(effect_id)?, authority)?;
        let Some(provider_completion) = authority.provider() else {
            self.store
                .update_mission_atomic(mission, expected_mission_revision, &events)?;
            return Ok(());
        };
        let effect = mission.effect(effect_id)?;
        let receipt = effect
            .receipt
            .as_ref()
            .ok_or(BrokerError::InvalidAuthorityClock)?;
        let Some(guard) = conversation_guard else {
            self.store
                .update_mission_atomic(mission, expected_mission_revision, &events)?;
            return Ok(());
        };
        let mut conversation = self
            .store
            .load_conversation(&mission.project_id, &guard.conversation_id)?;
        let expected_conversation_revision = conversation.revision;
        let provider_event_digest = provider_receipt_event_digest(receipt);
        conversation.record_agent_reply(
            effect_id,
            receipt.id.clone(),
            provider_event_digest.clone(),
            guard.control_generation,
            receipt.accepted_at,
            provider_completion.operation_at(),
        )?;
        self.store.update_conversation_and_mission_atomic(
            &conversation,
            expected_conversation_revision,
            mission,
            expected_mission_revision,
            &[PendingEvent::new(
                "conversation.reply_sent",
                serde_json::json!({
                    "conversationId": conversation.id,
                    "effectId": effect_id,
                    "receiptId": receipt.id,
                    "providerEventDigest": provider_event_digest,
                    "controlGeneration": guard.control_generation,
                    "authoritySequence": provider_completion.sequence(),
                }),
                provider_completion.operation_at(),
            )],
            &events,
        )?;
        Ok(())
    }

    fn persist_interrupted_effect(
        &mut self,
        mission: &mut Mission,
        expected_mission_revision: u64,
        conversation_guard: Option<&ConversationEffectGuard>,
        effect_id: &EffectId,
        completion: EffectCompletionPoint,
    ) -> Result<(), ApplicationError> {
        let now = completion.operation_at();
        if matches!(
            mission.effect(effect_id)?.status,
            EffectStatus::Executing | EffectStatus::ReceiptRecorded
        ) {
            mission.mark_effect_uncertain(effect_id, now)?;
        }
        let mission_event = PendingEvent::new(
            "effect.execution_interrupted",
            serde_json::json!({
                "effectId": effect_id,
                "status": mission.effect(effect_id)?.status,
                "requiresReconciliation": matches!(
                    mission.effect(effect_id)?.status,
                    EffectStatus::VerificationRequired
                ),
                "authoritySequence": completion.sequence(),
            }),
            now,
        );
        let Some(guard) = conversation_guard else {
            self.store.update_mission_atomic(
                mission,
                expected_mission_revision,
                &[mission_event],
            )?;
            return Ok(());
        };
        let mut conversation = self
            .store
            .load_conversation(&mission.project_id, &guard.conversation_id)?;
        let expected_conversation_revision = conversation.revision;
        let effect = mission.effect(effect_id)?;
        let receipt = effect.receipt.as_ref();
        let provider_event_digest = receipt.map(provider_receipt_event_digest);
        let conversation_event_type = if effect.status == EffectStatus::Failed && receipt.is_none()
        {
            conversation.mark_agent_reply_failed(effect_id, guard.control_generation, now)?;
            "conversation.reply_failed"
        } else {
            conversation.mark_agent_reply_uncertain(
                effect_id,
                guard.control_generation,
                receipt.map(|value| value.id.clone()),
                provider_event_digest.clone(),
                now,
            )?;
            "conversation.reply_uncertain"
        };
        self.store.update_conversation_and_mission_atomic(
            &conversation,
            expected_conversation_revision,
            mission,
            expected_mission_revision,
            &[PendingEvent::new(
                conversation_event_type,
                serde_json::json!({
                    "conversationId": conversation.id,
                    "effectId": effect_id,
                    "effectStatus": effect.status,
                    "receiptId": receipt.map(|value| &value.id),
                    "providerEventDigest": provider_event_digest,
                    "controlGeneration": guard.control_generation,
                    "authoritySequence": completion.sequence(),
                }),
                now,
            )],
            &[mission_event],
        )?;
        Ok(())
    }

    pub fn prepare_local_mission_runtime_context(
        &mut self,
        command: PrepareLocalMissionRuntimeContext,
        session: &ProjectContextMaterialSession,
        tokenizer: &impl ContextTokenizer,
        now: DateTime<Utc>,
    ) -> Result<PreparedLocalMissionRuntimeContext, ApplicationError> {
        self.prepare_local_mission_runtime_context_scoped(
            command, session, tokenizer, false, 1, now,
        )
    }

    /// Refresh the exact Mission foundation for a closed native Cordis retry
    /// while retaining the generation's bounded worker authority. Each attempt
    /// gets an append-only compaction/checkpoint/assembly identity, so a Mission
    /// change committed by a successful tool call cannot silently reuse the
    /// preceding attempt's stale prompt.
    pub fn prepare_local_mission_runtime_retry_context(
        &mut self,
        command: PrepareLocalMissionRuntimeContext,
        attempt: u64,
        session: &ProjectContextMaterialSession,
        tokenizer: &impl ContextTokenizer,
        now: DateTime<Utc>,
    ) -> Result<PreparedLocalMissionRuntimeContext, ApplicationError> {
        if attempt < 2 {
            return Err(ApplicationError::LocalRuntimeContextScopeMismatch);
        }
        self.prepare_local_mission_runtime_context_scoped(
            command, session, tokenizer, false, attempt, now,
        )
    }

    /// Prepare a reusable auxiliary Context/worker authority for Cordis
    /// compaction without reopening or replacing the ordinary Mission worker.
    pub fn prepare_local_mission_compaction_runtime_context(
        &mut self,
        command: PrepareLocalMissionRuntimeContext,
        session: &ProjectContextMaterialSession,
        tokenizer: &impl ContextTokenizer,
        now: DateTime<Utc>,
    ) -> Result<PreparedLocalMissionRuntimeContext, ApplicationError> {
        self.prepare_local_mission_runtime_context_scoped(command, session, tokenizer, true, 1, now)
    }

    /// Reopen the exact existing Mission worker for a same-Agent background
    /// completion follow-up. The original assembly remains immutable; the new
    /// direct prompt is bound later by its own Runtime turn scope.
    pub fn prepare_local_mission_runtime_followup_context(
        &self,
        command: &PrepareLocalMissionRuntimeContext,
        now: DateTime<Utc>,
    ) -> Result<PreparedLocalMissionRuntimeContext, ApplicationError> {
        if command.generation == 0 {
            return Err(ApplicationError::LocalRuntimeContextScopeMismatch);
        }
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if mission.project_id != command.project_id
            || mission.id != command.mission_id
            || mission.stage != MissionStage::Running
            || mission.contract.valid_until <= now
        {
            return Err(ApplicationError::LocalRuntimeMissionNotSchedulable);
        }
        let ids = LocalMissionRuntimeIds::for_mission(&mission.id, command.generation);
        let workspace = self
            .store
            .load_context_workspace(&command.project_id, &ids.workspace_id)?;
        workspace.validate_for(&mission, now)?;
        if workspace.generation != command.generation
            || workspace.policy_version != "desktop-local-runtime/v1"
        {
            return Err(ApplicationError::LocalRuntimeContextConflict);
        }
        let capsule = self
            .store
            .load_context_capsule(&command.project_id, &ids.capsule_id)?;
        let branch = self
            .store
            .load_context_branch(&command.project_id, &ids.branch_id)?;
        let lease = self
            .store
            .load_worker_lease(&command.project_id, &ids.worker_lease_id)?;
        let handle = self.store.load_worker_handle(
            &command.project_id,
            &ids.workspace_id,
            &ids.worker_id,
        )?;
        let mailbox = self
            .store
            .load_worker_mailbox(&command.project_id, &ids.mailbox_id)?;
        let facts = self
            .store
            .load_context_capsule_facts(&command.project_id, &capsule.id)?;
        branch.validate_for_workspace(&workspace, now)?;
        lease.validate_for(&workspace, &branch, now)?;
        capsule.validate_for(&workspace, &branch, &lease, &mission, &facts, now)?;
        handle.validate_for(&workspace, &branch, &lease, &capsule, None, now)?;
        mailbox.validate_for(&handle, now)?;
        if branch.status != ContextBranchStatus::Active
            || lease.status != WorkerLeaseStatus::Active
            || capsule.status != ContextCapsuleStatus::Claimed
            || handle.status != WorkerHandleStatus::Attached
        {
            return Err(ApplicationError::LocalRuntimeContextConflict);
        }
        let manifest = self
            .store
            .load_context_assembly_manifest(&command.project_id, &ids.assembly_id)?;
        manifest.validate_dispatchable()?;
        let checkpoint = self
            .store
            .load_context_checkpoint(&command.project_id, &manifest.checkpoint_id)?;
        if manifest.tenant_id != mission.tenant_id
            || manifest.project_id != command.project_id
            || manifest.mission_id != mission.id
            || manifest.workspace_id != workspace.id
            || manifest.capsule_id != capsule.id
            || manifest.capsule_revision != capsule.revision
            || manifest.branch_id != branch.id
            || manifest.branch_revision != branch.revision
            || manifest.worker_id != handle.worker_id
            || manifest.worker_generation != command.generation
            || manifest.worker_lease_id != lease.id
            || manifest.worker_lease_revision != lease.revision
            || manifest.checkpoint_id != checkpoint.id
            || manifest.checkpoint_digest != checkpoint.digest()?
            || manifest.capsule_authority_digest != capsule.authority_digest
        {
            return Err(ApplicationError::LocalRuntimeContextConflict);
        }
        Ok(PreparedLocalMissionRuntimeContext {
            ids,
            capsule,
            handle,
            mailbox,
            assembly: ContextAssemblyOutcome {
                manifest,
                envelope: None,
            },
        })
    }

    #[allow(
        clippy::too_many_lines,
        reason = "one transactionally recoverable orchestration boundary materializes the exact initial Mission, Context, Capsule, Worker, and Assembly closure"
    )]
    fn prepare_local_mission_runtime_context_scoped(
        &mut self,
        command: PrepareLocalMissionRuntimeContext,
        session: &ProjectContextMaterialSession,
        tokenizer: &impl ContextTokenizer,
        compaction: bool,
        context_attempt: u64,
        now: DateTime<Utc>,
    ) -> Result<PreparedLocalMissionRuntimeContext, ApplicationError> {
        if command.generation == 0
            || context_attempt == 0
            || (compaction && context_attempt != 1)
            || session.project_id() != &command.project_id
        {
            return Err(ApplicationError::LocalRuntimeContextScopeMismatch);
        }
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let current_checkpoint_route = mission.definition.as_ref().and_then(|definition| {
            definition
                .current_checkpoint()
                .and_then(|checkpoint| checkpoint.route.as_ref())
        });
        if let Some(route) = current_checkpoint_route
            && route.executor != MissionCheckpointExecutor::Runtime
        {
            return Err(ApplicationError::LocalRuntimeCheckpointExecutorMismatch {
                executor: route.executor,
            });
        }
        let task = mission
            .tasks
            .iter()
            .find(|task| {
                task.status == TaskStatus::Running
                    && mission
                        .contract
                        .enabled_capabilities
                        .contains(&task.capability)
                    && current_checkpoint_route
                        .is_none_or(|route| task.capability == route.capability_id)
            })
            .ok_or(ApplicationError::LocalRuntimeMissionNotSchedulable)?;
        let capability = task.capability.clone();
        if mission.stage != MissionStage::Running || mission.contract.valid_until <= now {
            return Err(ApplicationError::LocalRuntimeMissionNotSchedulable);
        }
        let conversation = match self
            .store
            .load_mission_conversation(&command.project_id, &command.mission_id)
        {
            Ok(conversation) => Some(conversation),
            Err(StorageError::ScopedRecordNotFound {
                kind: "mission conversation",
                ..
            }) if mission.definition.is_none() => None,
            Err(error) => return Err(error.into()),
        };
        let latest_user_message = conversation.as_ref().and_then(|conversation| {
            conversation
                .messages
                .iter()
                .rev()
                .find(|message| message.role == MissionConversationRole::User)
        });
        if latest_user_message.is_some_and(|message| message.sequence != command.generation) {
            return Err(ApplicationError::LocalRuntimeContextScopeMismatch);
        }

        let context_generation = if compaction {
            LOCAL_COMPACTION_GENERATION_OFFSET
                .checked_add(command.generation)
                .filter(|generation| i64::try_from(*generation).is_ok())
                .ok_or(ApplicationError::LocalRuntimeContextScopeMismatch)?
        } else {
            command.generation
        };
        let ids = if compaction {
            LocalMissionRuntimeIds::for_compaction(&mission.id, context_generation)
        } else {
            LocalMissionRuntimeIds::for_mission_attempt(
                &mission.id,
                context_generation,
                context_attempt,
            )
        };
        let policy_version = if compaction {
            "desktop-cordis-compaction-runtime/v1"
        } else {
            "desktop-local-runtime/v1"
        };
        let tokenizer_profile = tokenizer.profile()?;
        let summary = Zeroizing::new(serde_json::to_string(&serde_json::json!({
            "schema": "hartevo.local-mission-checkpoint/v1",
            "missionId": mission.id,
            "title": mission.title,
            "goal": mission.contract.goal,
            "nonGoals": mission.contract.non_goals,
            "constraints": mission.contract.constraints,
            "stopConditions": mission.contract.stop_conditions,
            "completionConditions": mission.contract.completion_conditions,
            "manifestId": mission.definition.as_ref().map(|definition| &definition.manifest_id),
            "catalogDigest": mission.definition.as_ref().map(|definition| &definition.catalog_digest),
            "checkpointId": mission.definition.as_ref().and_then(|definition| definition.current_checkpoint().map(|checkpoint| &checkpoint.id)),
            "conversationId": conversation.as_ref().map(|conversation| &conversation.id),
            "conversationRevision": conversation.as_ref().map(|conversation| conversation.revision),
            "conversation": conversation.as_ref().map(|conversation| &conversation.messages),
            "activeUserMessageSequence": latest_user_message.map(|message| message.sequence),
            "runtimePurpose": if compaction { "cordis_compaction" } else { "agent" },
            "effectAuthority": "none; local Runtime must return a typed draft only",
        }))?);
        let source = Zeroizing::new(serde_json::to_string(&(&mission, &conversation))?);
        let summary_token_count = tokenizer.count_tokens(summary.as_str())?;
        let source_token_count = tokenizer.count_tokens(source.as_str())?;
        if source_token_count <= summary_token_count {
            return Err(ApplicationError::LocalRuntimeContextConflict);
        }
        let summary_descriptor = session.put_text(summary.as_str())?;

        let workspace = match self
            .store
            .load_context_workspace(&command.project_id, &ids.workspace_id)
        {
            Ok(workspace) => {
                if workspace.project_id != command.project_id
                    || workspace.mission_id != command.mission_id
                    || workspace.generation != context_generation
                    || workspace.policy_version != policy_version
                    || workspace.capability_authority != BTreeSet::from([capability.clone()])
                    || workspace.data_policy != ContextDataPolicy::BusinessOnly
                {
                    return Err(ApplicationError::LocalRuntimeContextConflict);
                }
                workspace.validate_for(&mission, now)?;
                workspace
            }
            Err(StorageError::ScopedRecordNotFound { .. }) => {
                let deadline_at =
                    std::cmp::min(mission.contract.valid_until, now + Duration::hours(4));
                self.create_context_workspace(
                    CreateContextWorkspace {
                        id: ids.workspace_id.clone(),
                        working_set_id: ids.working_set_id.clone(),
                        continuation_ledger_id: ids.continuation_ledger_id.clone(),
                        project_id: command.project_id.clone(),
                        mission_id: command.mission_id.clone(),
                        generation: context_generation,
                        policy_version: policy_version.into(),
                        capability_authority: BTreeSet::from([capability.clone()]),
                        budget: ContextBudget {
                            token_limit: 65_536,
                            cost_limit: mission.contract.budget.clone(),
                            deadline_at,
                            max_depth: 1,
                            max_concurrency: 1,
                        },
                        data_policy: ContextDataPolicy::BusinessOnly,
                    },
                    now,
                )?
            }
            Err(error) => return Err(error.into()),
        };

        let foundation = match self
            .store
            .load_context_checkpoint(&command.project_id, &ids.checkpoint_id)
        {
            Ok(checkpoint) => {
                let latest = self
                    .store
                    .load_latest_context_checkpoint(&command.project_id, &ids.workspace_id)?
                    .ok_or(ApplicationError::LocalRuntimeContextConflict)?;
                let compaction = self
                    .store
                    .load_context_compaction(&command.project_id, &ids.compaction_id)?;
                if latest.id != checkpoint.id
                    || checkpoint.mission_id != mission.id
                    || checkpoint.mission_revision != mission.revision
                    || compaction.summary_ref != summary_descriptor.storage_ref
                    || compaction.summary_digest != summary_descriptor.content_digest
                    || compaction.summary_byte_len != summary_descriptor.byte_len
                {
                    return Err(ApplicationError::LocalRuntimeContextConflict);
                }
                self.context_foundation_snapshot(
                    &command.project_id,
                    &ids.workspace_id,
                    context_attempt,
                    now,
                )?
            }
            Err(StorageError::ScopedRecordNotFound { .. }) => {
                let working_set = self
                    .store
                    .load_context_working_set(&command.project_id, &ids.working_set_id)?;
                let continuation = self.store.load_context_continuation_ledger(
                    &command.project_id,
                    &ids.continuation_ledger_id,
                )?;
                let provider_route_digest = sha256(
                    serde_json::to_vec(&(
                        &tokenizer_profile.provider,
                        &tokenizer_profile.model,
                        &tokenizer_profile.model_revision,
                    ))?
                    .as_slice(),
                );
                self.compact_context_workspace(
                    CompactContextWorkspace {
                        project_id: command.project_id.clone(),
                        workspace_id: ids.workspace_id.clone(),
                        compaction_id: ids.compaction_id.clone(),
                        checkpoint_id: ids.checkpoint_id.clone(),
                        expected_working_set_revision: working_set.revision,
                        expected_continuation_ledger_revision: continuation.revision,
                        source_first_sequence: context_attempt,
                        source_last_sequence: context_attempt,
                        source_trace_digest: sha256(source.as_bytes()),
                        source_token_count,
                        retained_tail_start: context_attempt
                            .checked_add(1)
                            .ok_or(ApplicationError::LocalRuntimeContextScopeMismatch)?,
                        summary_ref: summary_descriptor.storage_ref.clone(),
                        summary_digest: summary_descriptor.content_digest.clone(),
                        summary_byte_len: summary_descriptor.byte_len,
                        summary_token_count,
                        provenance_evidence_ids: BTreeSet::new(),
                        model_digest: sha256(&serde_json::to_vec(&tokenizer_profile)?),
                        provider_route_digest,
                        config_digest: sha256(policy_version.as_bytes()),
                        worker_graph_digest: sha256(&serde_json::to_vec(&ids)?),
                        resume_cursor_digest: sha256(
                            format!("hartevo.local-runtime-cursor/{context_attempt}").as_bytes(),
                        ),
                        trace_tail_sequence: context_attempt
                            .checked_add(1)
                            .ok_or(ApplicationError::LocalRuntimeContextScopeMismatch)?,
                        sync_version: context_attempt,
                    },
                    now,
                )?
            }
            Err(error) => return Err(error.into()),
        };

        let capsule = match self
            .store
            .load_context_capsule(&command.project_id, &ids.capsule_id)
        {
            Ok(capsule) => capsule,
            Err(StorageError::ScopedRecordNotFound { .. }) => {
                let lease_token_digest = fresh_local_runtime_secret_digest()?;
                let initial_mapping_digest = fresh_local_runtime_secret_digest()?;
                let worker_deadline =
                    std::cmp::min(workspace.budget.deadline_at, now + Duration::minutes(90));
                self.issue_context_capsule(
                    IssueContextCapsule {
                        id: ids.capsule_id.clone(),
                        project_id: command.project_id.clone(),
                        workspace_id: ids.workspace_id.clone(),
                        parent_branch_id: None,
                        branch_id: ids.branch_id.clone(),
                        fork_reason: if compaction {
                            "reusable bounded Cordis compaction Runtime".into()
                        } else {
                            "initial bounded local Runtime turn".into()
                        },
                        scope_digest: sha256(&serde_json::to_vec(&(
                            &command.project_id,
                            &command.mission_id,
                            context_generation,
                            policy_version,
                            &capability,
                            latest_user_message.map(|message| &message.content_digest),
                        ))?),
                        merge_policy: ContextMergePolicy::TypedResultOnly,
                        worker_lease_id: ids.worker_lease_id.clone(),
                        worker_id: ids.worker_id.clone(),
                        parent_worker_id: None,
                        worker_generation: context_generation,
                        lease_token_digest,
                        runtime_mapping_digest: Some(initial_mapping_digest),
                        lease_expires_at: worker_deadline,
                        task_id: task.id.clone(),
                        child_goal: latest_user_message.map_or_else(
                            || mission.contract.goal.clone(),
                            |message| message.body.clone(),
                        ),
                        required_facts: BTreeSet::new(),
                        capabilities: BTreeSet::from([capability]),
                        budget: ContextBudget {
                            token_limit: 32_768,
                            cost_limit: workspace.budget.cost_limit.clone(),
                            deadline_at: worker_deadline,
                            max_depth: 1,
                            max_concurrency: 1,
                        },
                        inputs: ContextInputRefs::default(),
                        return_contract: ContextReturnContract {
                            schema_id: if compaction {
                                "hartevo.cordis.compaction-summary".into()
                            } else {
                                "hartevo.runtime.work-product-draft".into()
                            },
                            schema_version: 1,
                            required_fields: if compaction {
                                BTreeSet::from(["summary".into()])
                            } else {
                                BTreeSet::from(["draft".into(), "uncertainty".into()])
                            },
                            allowed_artifact_types: BTreeSet::from([if compaction {
                                "compaction_summary".into()
                            } else {
                                "runtime_draft".into()
                            }]),
                            evidence_required: false,
                            uncertainty_required: true,
                            max_result_bytes: 4 * 1024 * 1024,
                        },
                        capsule_expires_at: worker_deadline,
                        mailbox_id: ids.mailbox_id.clone(),
                        mailbox_capacity: 16,
                    },
                    now,
                )?
                .capsule
            }
            Err(error) => return Err(error.into()),
        };
        if capsule.project_id != command.project_id
            || capsule.mission_id != command.mission_id
            || capsule.workspace_id != ids.workspace_id
            || capsule.worker_id != ids.worker_id
            || capsule.worker_generation != context_generation
        {
            return Err(ApplicationError::LocalRuntimeContextConflict);
        }
        let capsule = match capsule.status {
            ContextCapsuleStatus::Issued => self.claim_context_capsule(
                &command.project_id,
                &ids.capsule_id,
                capsule.revision,
                context_generation,
                now,
            )?,
            ContextCapsuleStatus::Claimed => capsule,
            _ => return Err(ApplicationError::LocalRuntimeContextConflict),
        };
        let branch = self
            .store
            .load_context_branch(&command.project_id, &ids.branch_id)?;
        let lease = self
            .store
            .load_worker_lease(&command.project_id, &ids.worker_lease_id)?;
        let handle = self.store.load_worker_handle(
            &command.project_id,
            &ids.workspace_id,
            &ids.worker_id,
        )?;
        let mailbox = self
            .store
            .load_worker_mailbox(&command.project_id, &ids.mailbox_id)?;
        let assembly = self.assemble_runtime_context(
            AssembleRuntimeContext {
                id: ids.assembly_id.clone(),
                project_id: command.project_id,
                workspace_id: ids.workspace_id.clone(),
                capsule_id: ids.capsule_id.clone(),
                expected_capsule_revision: capsule.revision,
                expected_branch_revision: branch.revision,
                expected_worker_lease_revision: lease.revision,
                expected_checkpoint_id: foundation.checkpoint.id,
                foundation_sync_version: foundation.sync_version,
                policy: ContextAssemblyPolicy {
                    version: 1,
                    max_prompt_tokens: 24_576,
                    reserved_output_tokens: 4_096,
                    max_prompt_bytes: 4 * 1024 * 1024,
                    max_optional_frames: 32,
                    max_gap_records: 64,
                },
            },
            session,
            tokenizer,
            now,
        )?;
        Ok(PreparedLocalMissionRuntimeContext {
            ids,
            capsule,
            handle,
            mailbox,
            assembly,
        })
    }

    pub fn create_context_workspace(
        &mut self,
        command: CreateContextWorkspace,
        now: DateTime<Utc>,
    ) -> Result<ContextWorkspace, ApplicationError> {
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let workspace = ContextWorkspace::create(
            command.id,
            &mission,
            command.generation,
            command.policy_version,
            command.capability_authority,
            command.budget,
            command.data_policy,
            now,
        )?;
        let working_set = ContextWorkingSet::create(command.working_set_id, &workspace, now)?;
        let continuation_ledger =
            ContinuationLedger::create(command.continuation_ledger_id, &workspace, now)?;
        self.store.create_context_workspace(
            &workspace,
            &working_set,
            &continuation_ledger,
            &[PendingEvent::new(
                "context.workspace_created",
                serde_json::json!({
                    "workspaceId": workspace.id,
                    "missionId": workspace.mission_id,
                    "generation": workspace.generation,
                    "capabilityCount": workspace.capability_authority.len(),
                    "maxDepth": workspace.budget.max_depth,
                    "maxConcurrency": workspace.budget.max_concurrency,
                    "workingSetId": working_set.id,
                    "continuationLedgerId": continuation_ledger.id,
                }),
                now,
            )],
            now,
        )?;
        Ok(workspace)
    }

    pub fn replace_context_working_set(
        &mut self,
        command: ReplaceContextWorkingSet,
        now: DateTime<Utc>,
    ) -> Result<ContextWorkingSet, ApplicationError> {
        let mut working_set = self
            .store
            .load_context_working_set(&command.project_id, &command.working_set_id)?;
        if working_set.revision != command.expected_revision {
            return Err(ApplicationError::ContextWorkingSetRevisionMismatch {
                expected: command.expected_revision,
                actual: working_set.revision,
            });
        }
        let workspace = self
            .store
            .load_context_workspace(&command.project_id, &working_set.workspace_id)?;
        working_set.replace_items(command.items, &workspace, now)?;
        let item_digest = sha256(&serde_json::to_vec(&working_set.items)?);
        self.store.update_context_working_set(
            &working_set,
            command.expected_revision,
            &[PendingEvent::new(
                "context.working_set_replaced",
                serde_json::json!({
                    "workingSetId": working_set.id,
                    "workspaceId": working_set.workspace_id,
                    "generation": working_set.generation,
                    "revision": working_set.revision,
                    "itemCount": working_set.items.len(),
                    "itemDigest": item_digest,
                }),
                now,
            )],
            now,
        )?;
        Ok(working_set)
    }

    pub fn append_context_continuation(
        &mut self,
        command: AppendContextContinuation,
        now: DateTime<Utc>,
    ) -> Result<(ContinuationLedger, ContinuationEntry), ApplicationError> {
        let mut ledger = self.store.load_context_continuation_ledger(
            &command.project_id,
            &command.continuation_ledger_id,
        )?;
        if ledger.revision != command.expected_revision {
            return Err(ApplicationError::ContextContinuationRevisionMismatch {
                expected: command.expected_revision,
                actual: ledger.revision,
            });
        }
        let workspace = self
            .store
            .load_context_workspace(&command.project_id, &ledger.workspace_id)?;
        let mission = self
            .store
            .load_mission(&command.project_id, &ledger.mission_id)?;
        let entry = ledger.append(command.entry, &workspace, &mission, now)?;
        self.store.append_context_continuation(
            &ledger,
            command.expected_revision,
            &[PendingEvent::new(
                "context.continuation_appended",
                serde_json::json!({
                    "continuationLedgerId": ledger.id,
                    "workspaceId": ledger.workspace_id,
                    "sequence": entry.sequence,
                    "missionRevision": entry.mission_revision,
                    "kind": entry.kind,
                    "subjectDigest": sha256(entry.subject_id.as_bytes()),
                    "payloadDigest": entry.payload_digest,
                    "revision": ledger.revision,
                }),
                now,
            )],
            now,
        )?;
        Ok((ledger, entry))
    }

    #[allow(clippy::too_many_lines)]
    pub fn compact_context_workspace(
        &mut self,
        command: CompactContextWorkspace,
        now: DateTime<Utc>,
    ) -> Result<ContextFoundationSnapshot, ApplicationError> {
        let workspace = self
            .store
            .load_context_workspace(&command.project_id, &command.workspace_id)?;
        let mission = self
            .store
            .load_mission(&command.project_id, &workspace.mission_id)?;
        let truth_facts = self
            .store
            .load_current_truth_facts_for_project(&command.project_id)?;
        let (working_set_id, continuation_ledger_id) = self
            .store
            .load_context_foundation_ids(&command.project_id, &command.workspace_id)?;
        let working_set = self
            .store
            .load_context_working_set(&command.project_id, &working_set_id)?;
        let continuation_ledger = self
            .store
            .load_context_continuation_ledger(&command.project_id, &continuation_ledger_id)?;
        if working_set.revision != command.expected_working_set_revision {
            return Err(ApplicationError::ContextWorkingSetRevisionMismatch {
                expected: command.expected_working_set_revision,
                actual: working_set.revision,
            });
        }
        if continuation_ledger.revision != command.expected_continuation_ledger_revision {
            return Err(ApplicationError::ContextContinuationRevisionMismatch {
                expected: command.expected_continuation_ledger_revision,
                actual: continuation_ledger.revision,
            });
        }
        let previous_compaction = self
            .store
            .load_latest_context_compaction(&command.project_id, &command.workspace_id)?;
        let previous_checkpoint = self
            .store
            .load_latest_context_checkpoint(&command.project_id, &command.workspace_id)?;
        let compaction = ContextCompactionRecord::create(
            command.compaction_id,
            &workspace,
            &mission,
            &truth_facts,
            previous_compaction.as_ref(),
            command.source_first_sequence,
            command.source_last_sequence,
            command.source_trace_digest,
            command.source_token_count,
            command.retained_tail_start,
            command.summary_ref,
            command.summary_digest,
            command.summary_byte_len,
            command.summary_token_count,
            command.provenance_evidence_ids,
            command.model_digest,
            command.provider_route_digest,
            command.config_digest,
            now,
        )?;
        let checkpoint = ContextCheckpoint::create(
            command.checkpoint_id,
            &workspace,
            &mission,
            &truth_facts,
            &working_set,
            &continuation_ledger,
            &compaction,
            previous_checkpoint.as_ref(),
            command.worker_graph_digest,
            command.resume_cursor_digest,
            command.trace_tail_sequence,
            now,
        )?;
        self.store.append_context_compaction_checkpoint(
            &compaction,
            &checkpoint,
            &[
                PendingEvent::new(
                    "context.compaction_recorded",
                    serde_json::json!({
                        "workspaceId": workspace.id,
                        "compactionId": compaction.id,
                        "ordinal": compaction.ordinal,
                        "sourceFirstSequence": compaction.source_first_sequence,
                        "sourceLastSequence": compaction.source_last_sequence,
                        "summaryDigest": compaction.summary_digest,
                        "invariantDigest": compaction.invariant_digest,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "context.checkpoint_recorded",
                    serde_json::json!({
                        "workspaceId": workspace.id,
                        "checkpointId": checkpoint.id,
                        "ordinal": checkpoint.ordinal,
                        "missionRevision": checkpoint.mission_revision,
                        "workingSetRevision": checkpoint.working_set_revision,
                        "continuationLedgerRevision": checkpoint.continuation_ledger_revision,
                        "invariantDigest": checkpoint.invariant_digest,
                    }),
                    now,
                ),
            ],
            now,
        )?;
        self.store
            .load_context_foundation_snapshot(
                &command.project_id,
                &command.workspace_id,
                command.sync_version,
                now,
            )
            .map_err(ApplicationError::from)
    }

    pub fn context_foundation_snapshot(
        &self,
        project_id: &ProjectId,
        workspace_id: &ContextWorkspaceId,
        sync_version: u64,
        now: DateTime<Utc>,
    ) -> Result<ContextFoundationSnapshot, ApplicationError> {
        Ok(self.store.load_context_foundation_snapshot(
            project_id,
            workspace_id,
            sync_version,
            now,
        )?)
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the application boundary receives independent resolver and tokenizer implementations without giving either storage authority"
    )]
    pub fn assemble_runtime_context(
        &mut self,
        command: AssembleRuntimeContext,
        resolver: &impl ContextMaterialResolver,
        tokenizer: &impl ContextTokenizer,
        now: DateTime<Utc>,
    ) -> Result<ContextAssemblyOutcome, ApplicationError> {
        let persisted = match self
            .store
            .load_context_assembly_manifest(&command.project_id, &command.id)
        {
            Ok(manifest) => Some(manifest),
            Err(StorageError::ScopedRecordNotFound { .. }) => None,
            Err(error) => return Err(error.into()),
        };
        let capsule = self
            .store
            .load_context_capsule(&command.project_id, &command.capsule_id)?;
        if capsule.workspace_id != command.workspace_id {
            return Err(ApplicationError::ContextAssemblyScopeMismatch);
        }
        if capsule.revision != command.expected_capsule_revision {
            return Err(ApplicationError::ContextCapsuleRevisionMismatch {
                expected: command.expected_capsule_revision,
                actual: capsule.revision,
            });
        }
        let branch_lineage = self
            .store
            .load_context_branch_lineage(&command.project_id, &capsule.branch_id)?;
        let branch = branch_lineage
            .last()
            .ok_or(ApplicationError::ContextAssemblyScopeMismatch)?;
        if branch.revision != command.expected_branch_revision {
            return Err(ApplicationError::ContextBranchRevisionMismatch {
                expected: command.expected_branch_revision,
                actual: branch.revision,
            });
        }
        let worker_lease = self
            .store
            .load_worker_lease(&command.project_id, &capsule.worker_lease_id)?;
        if worker_lease.revision != command.expected_worker_lease_revision {
            return Err(ApplicationError::WorkerLeaseRevisionMismatch {
                expected: command.expected_worker_lease_revision,
                actual: worker_lease.revision,
            });
        }
        let foundation = self.store.load_context_foundation_snapshot(
            &command.project_id,
            &command.workspace_id,
            command.foundation_sync_version,
            now,
        )?;
        if foundation.checkpoint.id != command.expected_checkpoint_id {
            return Err(ApplicationError::ContextAssemblyCheckpointMismatch);
        }
        let previous_compaction = if foundation.compaction.ordinal > 1 {
            self.store.load_context_compaction_by_ordinal(
                &command.project_id,
                &command.workspace_id,
                foundation.compaction.ordinal - 1,
            )?
        } else {
            None
        };
        let previous_checkpoint = if foundation.checkpoint.ordinal > 1 {
            self.store.load_context_checkpoint_by_ordinal(
                &command.project_id,
                &command.workspace_id,
                foundation.checkpoint.ordinal - 1,
            )?
        } else {
            None
        };
        let mission = self
            .store
            .load_mission(&command.project_id, &foundation.workspace.mission_id)?;
        let request = ContextAssemblyRequest {
            id: command.id,
            mission: &mission,
            foundation: &foundation,
            previous_compaction: previous_compaction.as_ref(),
            previous_checkpoint: previous_checkpoint.as_ref(),
            branch_lineage: &branch_lineage,
            worker_lease: &worker_lease,
            capsule: &capsule,
            policy: command.policy,
            now,
        };
        let mut outcome = ContextAssembler::assemble(&request, resolver, tokenizer)?;
        if let Some(persisted) = persisted {
            outcome.manifest.created_at = persisted.created_at;
            if outcome.manifest != persisted {
                return Err(ApplicationError::ContextAssemblyIdempotencyConflict);
            }
            outcome.manifest = persisted;
            return Ok(outcome);
        }
        self.store
            .record_context_assembly_manifest(&outcome.manifest)?;
        Ok(outcome)
    }

    pub fn load_context_assembly_manifest(
        &self,
        project_id: &ProjectId,
        id: &ContextAssemblyId,
    ) -> Result<hartevo_context_fabric::ContextAssemblyManifest, ApplicationError> {
        Ok(self.store.load_context_assembly_manifest(project_id, id)?)
    }

    #[allow(clippy::too_many_lines)]
    pub fn issue_context_capsule(
        &mut self,
        command: IssueContextCapsule,
        now: DateTime<Utc>,
    ) -> Result<ContextCapsuleSyncSnapshot, ApplicationError> {
        let workspace = self
            .store
            .load_context_workspace(&command.project_id, &command.workspace_id)?;
        let mission = self
            .store
            .load_mission(&workspace.project_id, &workspace.mission_id)?;
        let mut branch_lineage = if let Some(parent_id) = &command.parent_branch_id {
            self.store
                .load_context_branch_lineage(&workspace.project_id, parent_id)?
        } else {
            Vec::new()
        };
        let branch = ContextBranch::create(
            command.branch_id,
            &workspace,
            branch_lineage.last(),
            command.fork_reason,
            command.scope_digest,
            command.merge_policy,
            now,
        )?;
        branch_lineage.push(branch.clone());
        let worker_lease = WorkerLease::issue(
            command.worker_lease_id,
            &workspace,
            &branch,
            command.worker_id,
            command.worker_generation,
            command.lease_token_digest,
            command.runtime_mapping_digest,
            command.lease_expires_at,
            now,
        )?;
        let facts = command
            .required_facts
            .iter()
            .map(|grant| {
                self.store.load_truth_fact_revision(
                    &workspace.project_id,
                    &grant.fact_id,
                    grant.version,
                )
            })
            .collect::<Result<Vec<_>, _>>()?;
        let capsule = ContextCapsule::issue(
            command.id,
            &workspace,
            &branch,
            &worker_lease,
            &mission,
            command.child_goal,
            command.task_id,
            command.required_facts,
            &facts,
            command.capabilities,
            command.budget,
            command.inputs,
            command.return_contract,
            command.capsule_expires_at,
            now,
        )?;
        let parent_handle = command
            .parent_worker_id
            .as_ref()
            .map(|worker_id| {
                self.store
                    .load_worker_handle(&workspace.project_id, &workspace.id, worker_id)
            })
            .transpose()?;
        let worker_handle = WorkerHandle::create(
            &workspace,
            &branch,
            &worker_lease,
            &capsule,
            parent_handle.as_ref(),
            now,
        )?;
        let worker_mailbox = WorkerMailbox::create(
            command.mailbox_id,
            &worker_handle,
            command.mailbox_capacity,
            now,
        )?;
        self.store.issue_context_capsule_bundle(
            &workspace,
            &branch_lineage,
            &worker_lease,
            &capsule,
            &worker_handle,
            &worker_mailbox,
            &facts,
            &[PendingEvent::new(
                "context.capsule_issued",
                serde_json::json!({
                    "capsuleId": capsule.id,
                    "workspaceId": capsule.workspace_id,
                    "branchId": capsule.branch_id,
                    "workerId": capsule.worker_id,
                    "workerGeneration": capsule.worker_generation,
                    "authorityDigest": capsule.authority_digest,
                    "factCount": capsule.required_facts.len(),
                    "capabilityCount": capsule.capabilities.len(),
                    "mailboxId": worker_mailbox.id,
                    "mailboxCapacity": worker_mailbox.max_pending,
                }),
                now,
            )],
            now,
        )?;
        Ok(ContextCapsuleSyncSnapshot {
            sync_version: 1,
            workspace,
            branch_lineage,
            worker_lease,
            facts,
            capsule,
        })
    }

    #[cfg(test)]
    fn detach_context_worker(
        &mut self,
        command: &DetachContextWorker,
        now: DateTime<Utc>,
    ) -> Result<WorkerHandle, ApplicationError> {
        let mut handle = self.store.load_worker_handle(
            &command.project_id,
            &command.workspace_id,
            &command.worker_id,
        )?;
        require_context_worker_handle_revision(&handle, command.expected_handle_revision)?;
        handle.detach(command.attachment_epoch, now)?;
        self.store.update_worker_handle(
            &handle,
            command.expected_handle_revision,
            &[PendingEvent::new(
                "context.worker_detached",
                serde_json::json!({
                    "workspaceId": handle.workspace_id,
                    "workerId": handle.worker_id,
                    "attachmentEpoch": handle.attachment_epoch,
                    "cursor": handle.cursor,
                    "revision": handle.revision,
                }),
                now,
            )],
            now,
        )?;
        Ok(handle)
    }

    #[cfg(test)]
    fn reattach_context_worker(
        &mut self,
        command: ReattachContextWorker,
        now: DateTime<Utc>,
    ) -> Result<(WorkerHandle, WorkerMailbox), ApplicationError> {
        if self
            .store
            .load_active_runtime_recovery_for_worker(
                &command.project_id,
                &command.workspace_id,
                &command.worker_id,
            )?
            .is_some()
        {
            return Err(ApplicationError::RuntimeRecoveryRequired);
        }
        let mut handle = self.store.load_worker_handle(
            &command.project_id,
            &command.workspace_id,
            &command.worker_id,
        )?;
        require_context_worker_handle_revision(&handle, command.expected_handle_revision)?;
        let mut mailbox = self.store.load_worker_mailbox_for_handle(
            &command.project_id,
            &command.workspace_id,
            &command.worker_id,
        )?;
        require_context_worker_mailbox_revision(&mailbox, command.expected_mailbox_revision)?;
        handle.reattach(
            command.attachment_epoch,
            command.runtime_mapping_digest,
            now,
        )?;
        let recovered = mailbox.recover_after_reattach(&handle, now)?;
        let event = PendingEvent::new(
            "context.worker_reattached",
            serde_json::json!({
                "workspaceId": handle.workspace_id,
                "workerId": handle.worker_id,
                "attachmentEpoch": handle.attachment_epoch,
                "cursor": handle.cursor,
                "requeuedInFlight": recovered,
                "handleRevision": handle.revision,
                "mailboxRevision": mailbox.revision,
            }),
            now,
        );
        if recovered {
            self.store.update_worker_handle_and_mailbox(
                &handle,
                command.expected_handle_revision,
                &mailbox,
                command.expected_mailbox_revision,
                &[event],
                now,
            )?;
        } else {
            self.store.update_worker_handle(
                &handle,
                command.expected_handle_revision,
                &[event],
                now,
            )?;
        }
        Ok((handle, mailbox))
    }

    pub fn recover_context_worker_runtime(
        &mut self,
        command: RecoverContextWorkerRuntime,
        runtime_command: &RuntimeCommand,
        now: DateTime<Utc>,
    ) -> Result<ManagedContextRuntime, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let project = self.store.load_project(&command.project_id)?;
        let workspace_root = validate_runtime_workspace(&project, runtime_command)?;
        let runtime_config_digest = runtime_recovery_config_digest(
            runtime_command,
            command.model.as_deref(),
            &workspace_root,
        )?;
        let checkpoint = self
            .store
            .load_latest_context_checkpoint(&command.project_id, &command.workspace_id)?
            .ok_or(ApplicationError::RuntimeRecoveryCheckpointRequired)?;
        let attached = self.store.load_worker_handle(
            &command.project_id,
            &command.workspace_id,
            &command.worker_id,
        )?;
        require_context_worker_handle_revision(&attached, command.expected_handle_revision)?;
        if attached.attachment_epoch != command.attachment_epoch {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let mailbox = self.store.load_worker_mailbox_for_handle(
            &command.project_id,
            &command.workspace_id,
            &command.worker_id,
        )?;
        require_context_worker_mailbox_revision(&mailbox, command.expected_mailbox_revision)?;
        if self
            .store
            .load_active_runtime_recovery_for_worker(
                &command.project_id,
                &command.workspace_id,
                &command.worker_id,
            )?
            .is_some()
        {
            return Err(ApplicationError::RuntimeRecoveryAlreadyActive);
        }

        let mut detached = attached.clone();
        detached.detach(command.attachment_epoch, now)?;
        let attempt = RuntimeRecoveryAttempt::prepare(
            command.id,
            &attached,
            &detached,
            &checkpoint,
            runtime_config_digest,
            command.strategy,
            command.resume_thread_id.as_deref(),
            command.max_process_attempts,
            now,
        )?;
        self.store.begin_runtime_recovery(
            &detached,
            command.expected_handle_revision,
            &attempt,
            &[PendingEvent::new(
                "context.runtime_recovery_prepared",
                serde_json::json!({
                    "recoveryId": attempt.id,
                    "workspaceId": attempt.workspace_id,
                    "workerId": attempt.worker_id,
                    "workerGeneration": attempt.worker_generation,
                    "sourceAttachmentEpoch": attempt.source_attachment_epoch,
                    "targetAttachmentEpoch": attempt.target_attachment_epoch,
                    "checkpointId": attempt.checkpoint_id,
                    "checkpointDigest": attempt.checkpoint_digest,
                    "runtimeConfigDigest": attempt.runtime_config_digest,
                    "strategy": attempt.initial_strategy,
                    "maxProcessAttempts": attempt.max_process_attempts,
                }),
                now,
            )],
            now,
        )?;
        self.run_prepared_runtime_recovery(
            attempt,
            detached,
            mailbox,
            runtime_command,
            &workspace_root,
            command.model.as_deref(),
            command.resume_thread_id.as_deref(),
            command.health_timeout,
            command.thread_timeout,
            now,
        )
    }

    pub fn retry_context_worker_runtime(
        &mut self,
        command: RetryContextWorkerRuntime,
        runtime_command: &RuntimeCommand,
        now: DateTime<Utc>,
    ) -> Result<ManagedContextRuntime, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let project = self.store.load_project(&command.project_id)?;
        let workspace_root = validate_runtime_workspace(&project, runtime_command)?;
        let expected_config_digest = runtime_recovery_config_digest(
            runtime_command,
            command.model.as_deref(),
            &workspace_root,
        )?;
        let mut attempt = self
            .store
            .load_runtime_recovery(&command.project_id, &command.recovery_id)?;
        if attempt.revision != command.expected_attempt_revision {
            return Err(ApplicationError::RuntimeRecoveryRevisionMismatch {
                expected: command.expected_attempt_revision,
                actual: attempt.revision,
            });
        }
        if attempt.runtime_config_digest != expected_config_digest || attempt.status.is_terminal() {
            return Err(ApplicationError::RuntimeRecoveryNotRetryable);
        }
        let handle = self.store.load_worker_handle(
            &attempt.project_id,
            &attempt.workspace_id,
            &attempt.worker_id,
        )?;
        require_context_worker_handle_revision(&handle, command.expected_handle_revision)?;
        let mailbox = self.store.load_worker_mailbox_for_handle(
            &attempt.project_id,
            &attempt.workspace_id,
            &attempt.worker_id,
        )?;
        require_context_worker_mailbox_revision(&mailbox, command.expected_mailbox_revision)?;

        let orphan_bound_thread = attempt.runtime_thread_id.clone();
        let resuming_orphan_bound_thread = orphan_bound_thread.is_some();
        if let (Some(bound), Some(requested)) = (
            orphan_bound_thread.as_deref(),
            command.resume_thread_id.as_deref(),
        ) && bound != requested
        {
            return Err(ApplicationError::RuntimeRecoveryResumeThreadMismatch);
        }
        let resume_thread_id = orphan_bound_thread.or(command.resume_thread_id);
        validate_recovery_resume_thread(
            &attempt,
            resume_thread_id.as_deref(),
            resuming_orphan_bound_thread,
        )?;
        if matches!(
            attempt.status,
            RuntimeRecoveryStatus::Spawned
                | RuntimeRecoveryStatus::Healthy
                | RuntimeRecoveryStatus::ThreadBound
        ) {
            let expected_revision = attempt.revision;
            attempt.record_process_failure(
                RuntimeRecoveryFailureClass::CoordinatorRestart,
                sha256(b"runtime-coordinator-restarted-without-live-process-handle"),
                now,
            )?;
            self.persist_runtime_recovery_transition(
                &attempt,
                expected_revision,
                "context.runtime_recovery_orphan_fenced",
                now,
            )?;
        }
        if attempt.status != RuntimeRecoveryStatus::Prepared {
            return Err(ApplicationError::RuntimeRecoveryNotRetryable);
        }
        self.run_prepared_runtime_recovery(
            attempt,
            handle,
            mailbox,
            runtime_command,
            &workspace_root,
            command.model.as_deref(),
            resume_thread_id.as_deref(),
            command.health_timeout,
            command.thread_timeout,
            now,
        )
    }

