fn build_context_capsule_sync_snapshot(
    store: &ProjectStore,
    project_id: &ProjectId,
    capsule_id: &ContextCapsuleId,
    sync_version: u64,
    now: DateTime<Utc>,
) -> Result<ContextCapsuleSyncSnapshot, ApplicationError> {
    let project = store.load_project(project_id)?;
    let capsule = store.load_context_capsule(project_id, capsule_id)?;
    let mission = store.load_mission(project_id, &capsule.mission_id)?;
    let snapshot = ContextCapsuleSyncSnapshot {
        sync_version,
        workspace: store.load_context_workspace(project_id, &capsule.workspace_id)?,
        branch_lineage: store.load_context_branch_lineage(project_id, &capsule.branch_id)?,
        worker_lease: store.load_worker_lease(project_id, &capsule.worker_lease_id)?,
        facts: store.load_context_capsule_facts(project_id, capsule_id)?,
        capsule,
    };
    snapshot.validate_for(&project, &mission, capsule_id.as_str(), now)?;
    Ok(snapshot)
}

