struct DeviceAttachmentSpec {
    method: DeviceAttachmentMethod,
    source_recipient: KeyRecipient,
    device_id: DeviceId,
    authorization: KeyAdministrationAuthorization,
    idempotency_key_digest: String,
    intent_digest: String,
}

fn device_attachment_idempotency_digest(
    project: &Project,
    idempotency_key: &str,
) -> Result<String, ApplicationError> {
    if idempotency_key.is_empty() {
        return Err(ApplicationError::InvalidDeviceAttachment);
    }
    Ok(sha256(&serde_json::to_vec(&serde_json::json!({
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "operation": "project_device_attachment",
        "idempotencyKey": idempotency_key,
    }))?))
}

fn key_bootstrap_idempotency_digest(
    project: &Project,
    kind: KeyBootstrapOperationKind,
    idempotency_key: &str,
) -> Result<String, ApplicationError> {
    if idempotency_key.is_empty() {
        return Err(ApplicationError::InvalidDeviceHandoff);
    }
    Ok(sha256(&serde_json::to_vec(&serde_json::json!({
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "operationKind": kind.as_str(),
        "idempotencyKey": idempotency_key,
    }))?))
}

const fn key_bootstrap_cell(cell: DataCell) -> KeyBootstrapCell {
    match cell {
        DataCell::Us => KeyBootstrapCell::Us,
        DataCell::Eu => KeyBootstrapCell::Eu,
    }
}

fn require_bootstrap_operation_cell(
    operation: &LocalKeyBootstrapOperation,
    cell: DataCell,
) -> Result<(), ApplicationError> {
    if operation.cell != key_bootstrap_cell(cell) {
        return Err(ApplicationError::KeyBootstrapOperationNotDispatchable);
    }
    Ok(())
}

fn load_optional_key_bootstrap_operation(
    store: &ProjectStore,
    project_id: &ProjectId,
    kind: KeyBootstrapOperationKind,
    idempotency_key_digest: &str,
) -> Result<Option<LocalKeyBootstrapOperation>, ApplicationError> {
    match store.load_key_bootstrap_operation(project_id, kind, idempotency_key_digest) {
        Ok(operation) => Ok(Some(operation)),
        Err(StorageError::ScopedRecordNotFound { .. }) => Ok(None),
        Err(error) => Err(error.into()),
    }
}

fn device_handoff_private_key_reference(
    project: &Project,
    device_id: &DeviceId,
    idempotency_key_digest: &str,
    revision: u64,
) -> SecretReference {
    SecretReference {
        tenant_id: project.tenant_id.clone(),
        project_id: project.id.clone(),
        provider: "os-native".into(),
        account_scope: KeyRecipient::Device(device_id.clone()).stable_scope(),
        purpose: format!("device_handoff_x25519_private:{idempotency_key_digest}"),
        version: revision,
    }
}

fn validate_device_handoff_private_reference(
    reference: &SecretReference,
    project: &Project,
    device_id: &DeviceId,
) -> Result<(), ApplicationError> {
    if reference.tenant_id != project.tenant_id
        || reference.project_id != project.id
        || reference.provider != "os-native"
        || reference.account_scope != KeyRecipient::Device(device_id.clone()).stable_scope()
        || !reference
            .purpose
            .starts_with("device_handoff_x25519_private:")
        || reference.version == 0
    {
        return Err(ApplicationError::KeyReferenceScopeMismatch);
    }
    Ok(())
}

fn get_or_create_device_handoff_private_key(
    secret_store: &impl SecretStore,
    reference: &SecretReference,
) -> Result<(KeyMaterial, bool), ApplicationError> {
    match secret_store.get(reference) {
        Ok(secret) => Ok((KeyMaterial::from_secret(&secret)?, false)),
        Err(SecretStoreError::SecretNotFound) => {
            let key = DeviceKeyAgreementCrypto::generate_private_key()?;
            secret_store.put(reference, &key.to_secret())?;
            Ok((key, true))
        }
        Err(error) => Err(error.into()),
    }
}

#[allow(clippy::too_many_arguments)]
fn device_attachment_intent_digest(
    project: &Project,
    keyring: &ProjectKeyring,
    method: DeviceAttachmentMethod,
    source_recipient: &KeyRecipient,
    source_reference_digest: Option<&str>,
    device_id: &DeviceId,
    authorization: &KeyAdministrationAuthorization,
    expected_keyring_revision: u64,
) -> Result<String, ApplicationError> {
    if expected_keyring_revision == 0 || device_id.as_str().trim().is_empty() {
        return Err(ApplicationError::InvalidDeviceAttachment);
    }
    Ok(sha256(&serde_json::to_vec(&serde_json::json!({
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "projectMode": keyring.mode,
        "method": method,
        "sourceRecipient": source_recipient,
        "sourceReferenceDigest": source_reference_digest,
        "deviceId": device_id,
        "keyVersion": keyring.active_key_version,
        "expectedKeyringRevision": expected_keyring_revision,
        "authorizedBy": authorization.actor_id,
        "authorizationEvidenceDigest": authorization.evidence_digest,
    }))?))
}

