fn open_project_key_with_recovery_secret(
    keyring: &ProjectKeyring,
    recovery_recipient: &KeyRecipient,
    recovery_secret: &SecretBytes,
    now: DateTime<Utc>,
) -> Result<KeyMaterial, ApplicationError> {
    if keyring.mode != ProjectEncryptionMode::PersonalE2ee
        || !matches!(recovery_recipient, KeyRecipient::Recovery(_))
    {
        return Err(ApplicationError::InvalidDeviceAttachment);
    }
    let envelope = keyring.active_envelope_for(recovery_recipient, now)?;
    let expected_reference = SecretReference {
        tenant_id: keyring.tenant_id.clone(),
        project_id: keyring.project_id.clone(),
        provider: "user-recovery".into(),
        account_scope: recovery_recipient.stable_scope(),
        purpose: format!("project_recovery_key:{}", envelope.id),
        version: keyring.active_key_version,
    };
    if expected_reference.credential_id()? != envelope.wrapping_key_reference_digest {
        return Err(ApplicationError::KeyReferenceScopeMismatch);
    }
    let context = EnvelopeContext {
        tenant_id: keyring.tenant_id.clone(),
        project_id: keyring.project_id.clone(),
        key_version: keyring.active_key_version,
        recipient: recovery_recipient.clone(),
        purpose: "project_content_key".into(),
        expires_at: None,
    };
    Ok(EnvelopeCrypto::open_key(
        &envelope.sealed_key,
        &KeyMaterial::from_secret(recovery_secret)?,
        &context,
    )?)
}

fn validate_encryption_provisioning(
    command: &ProvisionProjectEncryption,
) -> Result<(), ApplicationError> {
    let valid = match command.mode {
        ProjectEncryptionMode::PersonalE2ee => {
            matches!(command.primary_recipient, KeyRecipient::Device(_))
                && command
                    .recovery_recipient_id
                    .as_deref()
                    .is_some_and(|id| !id.trim().is_empty())
        }
        ProjectEncryptionMode::TeamEnvelope => {
            matches!(
                command.primary_recipient,
                KeyRecipient::Device(_) | KeyRecipient::Member(_)
            ) && command.recovery_recipient_id.is_none()
        }
    };
    if valid {
        Ok(())
    } else {
        Err(ApplicationError::InvalidEncryptionProvisioning)
    }
}

struct KeyEnvelopeBuildSpec {
    tenant: TenantId,
    project: ProjectId,
    envelope: KeyEnvelopeId,
    version: u64,
    recipient: KeyRecipient,
    wrapping_reference_digest: String,
    expires_at: Option<DateTime<Utc>>,
}

fn seal_project_key_envelope(
    spec: KeyEnvelopeBuildSpec,
    project_key: &KeyMaterial,
    wrapping_key: &KeyMaterial,
    now: DateTime<Utc>,
) -> Result<KeyEnvelope, ApplicationError> {
    let context = EnvelopeContext {
        tenant_id: spec.tenant.clone(),
        project_id: spec.project.clone(),
        key_version: spec.version,
        recipient: spec.recipient.clone(),
        purpose: "project_content_key".into(),
        expires_at: spec.expires_at,
    };
    Ok(KeyEnvelope {
        id: spec.envelope,
        tenant_id: spec.tenant,
        project_id: spec.project,
        key_version: spec.version,
        recipient: spec.recipient,
        wrapping_key_reference_digest: spec.wrapping_reference_digest,
        sealed_key: EnvelopeCrypto::seal_key(project_key, wrapping_key, &context)?,
        created_at: now,
        expires_at: spec.expires_at,
        revoked_at: None,
    })
}

fn require_keyring_revision(
    keyring: &ProjectKeyring,
    expected: u64,
) -> Result<(), ApplicationError> {
    if keyring.revision == expected {
        Ok(())
    } else {
        Err(ApplicationError::KeyringRevisionMismatch {
            expected,
            actual: keyring.revision,
        })
    }
}

fn validate_key_administration(
    authorization: &KeyAdministrationAuthorization,
    authorizing_recipient: Option<&KeyRecipient>,
) -> Result<(), ApplicationError> {
    if authorization.actor_id.as_str().trim().is_empty()
        || !is_sha256_text(&authorization.evidence_digest)
        || authorizing_recipient.is_some_and(|recipient| {
            !matches!(recipient, KeyRecipient::Device(_) | KeyRecipient::Member(_))
        })
    {
        return Err(ApplicationError::InvalidKeyAdministrationAuthorization);
    }
    Ok(())
}

fn is_sha256_text(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn is_canonical_sha256_text(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
}

fn validate_key_reference(
    tenant_id: &TenantId,
    project_id: &ProjectId,
    recipient_key: &RecipientKeyReference,
    key_version: u64,
) -> Result<(), ApplicationError> {
    let reference = &recipient_key.reference;
    if &reference.tenant_id != tenant_id
        || &reference.project_id != project_id
        || reference.account_scope != recipient_key.recipient.stable_scope()
        || reference.version != key_version
        || !reference.purpose.starts_with("project_")
    {
        return Err(ApplicationError::KeyReferenceScopeMismatch);
    }
    Ok(())
}

fn open_active_project_key(
    secret_store: &impl SecretStore,
    keyring: &ProjectKeyring,
    authorizing_key: &RecipientKeyReference,
    now: DateTime<Utc>,
) -> Result<KeyMaterial, ApplicationError> {
    validate_key_reference(
        &keyring.tenant_id,
        &keyring.project_id,
        authorizing_key,
        keyring.active_key_version,
    )?;
    let envelope = keyring.active_envelope_for(&authorizing_key.recipient, now)?;
    open_project_key_from_envelope(secret_store, authorizing_key, envelope)
}

fn open_project_key_for_version(
    secret_store: &impl SecretStore,
    keyring: &ProjectKeyring,
    authorizing_key: &RecipientKeyReference,
    key_version: u64,
    now: DateTime<Utc>,
) -> Result<KeyMaterial, ApplicationError> {
    validate_key_reference(
        &keyring.tenant_id,
        &keyring.project_id,
        authorizing_key,
        key_version,
    )?;
    let envelope =
        keyring.available_envelope_for_version(&authorizing_key.recipient, key_version, now)?;
    open_project_key_from_envelope(secret_store, authorizing_key, envelope)
}

fn open_project_key_from_envelope(
    secret_store: &impl SecretStore,
    authorizing_key: &RecipientKeyReference,
    envelope: &KeyEnvelope,
) -> Result<KeyMaterial, ApplicationError> {
    if authorizing_key.reference.credential_id()? != envelope.wrapping_key_reference_digest {
        return Err(ApplicationError::KeyReferenceScopeMismatch);
    }
    let wrapping_key = KeyMaterial::from_secret(&secret_store.get(&authorizing_key.reference)?)?;
    let context = EnvelopeContext {
        tenant_id: envelope.tenant_id.clone(),
        project_id: envelope.project_id.clone(),
        key_version: envelope.key_version,
        recipient: envelope.recipient.clone(),
        purpose: "project_content_key".into(),
        expires_at: envelope.expires_at,
    };
    Ok(EnvelopeCrypto::open_key(
        &envelope.sealed_key,
        &wrapping_key,
        &context,
    )?)
}

fn seal_recipient_envelope(
    secret_store: &impl SecretStore,
    project: &Project,
    key_version: u64,
    recipient_key: RecipientKeyReference,
    expires_at: Option<DateTime<Utc>>,
    project_key: &KeyMaterial,
    now: DateTime<Utc>,
) -> Result<(KeyEnvelope, ProjectKeySecretReference), ApplicationError> {
    validate_key_reference(&project.tenant_id, &project.id, &recipient_key, key_version)?;
    let wrapping_key = KeyMaterial::from_secret(&secret_store.get(&recipient_key.reference)?)?;
    let reference = recipient_key.reference;
    let envelope = seal_project_key_envelope(
        KeyEnvelopeBuildSpec {
            tenant: project.tenant_id.clone(),
            project: project.id.clone(),
            envelope: KeyEnvelopeId::new(),
            version: key_version,
            recipient: recipient_key.recipient,
            wrapping_reference_digest: reference.credential_id()?,
            expires_at,
        },
        project_key,
        &wrapping_key,
        now,
    )?;
    let binding = ProjectKeySecretReference::bind(&envelope, reference)?;
    Ok((envelope, binding))
}

fn sync_target_revision(
    precondition: MutationPrecondition,
    tombstone: bool,
) -> Result<u64, ApplicationError> {
    match (precondition, tombstone) {
        (MutationPrecondition::CreateOnly, true) | (MutationPrecondition::ExactRevision(0), _) => {
            Err(ApplicationError::InvalidSyncOperation)
        }
        (MutationPrecondition::CreateOnly, false) => Ok(1),
        (MutationPrecondition::ExactRevision(revision), _) => revision
            .checked_add(1)
            .ok_or(ApplicationError::InvalidSyncOperation),
    }
}

const fn project_data_cell(cell: DataCell) -> ProjectDataCell {
    match cell {
        DataCell::Us => ProjectDataCell::Us,
        DataCell::Eu => ProjectDataCell::Eu,
    }
}

fn validate_project_sync_cell(project: &Project, cell: DataCell) -> Result<(), ApplicationError> {
    if project.data_cell == Some(project_data_cell(cell)) {
        Ok(())
    } else {
        Err(ApplicationError::ProjectDataCellMismatch)
    }
}

fn require_mission_revision(mission: &Mission, expected: u64) -> Result<(), ApplicationError> {
    if mission.revision != expected {
        return Err(ApplicationError::MissionRevisionMismatch {
            expected,
            actual: mission.revision,
        });
    }
    Ok(())
}

fn require_manifest_version(
    manifest: &WorkProductManifest,
    expected: u64,
) -> Result<(), ApplicationError> {
    if manifest.version != expected {
        return Err(ApplicationError::WorkProductManifestVersionMismatch {
            expected,
            actual: manifest.version,
        });
    }
    Ok(())
}

fn require_applied_project_registration(
    store: &ProjectStore,
    project: &Project,
    cell: DataCell,
) -> Result<(), ApplicationError> {
    validate_project_sync_cell(project, cell)?;
    let registration = store
        .load_project_cloud_registration(&project.id)
        .map_err(|error| match error {
            StorageError::ScopedRecordNotFound { .. } => {
                ApplicationError::ProjectCloudRegistrationRequired
            }
            other => ApplicationError::Storage(other),
        })?;
    if registration.status != ProjectCloudRegistrationStatus::Applied
        || registration.cell != cell.as_str()
    {
        return Err(ApplicationError::ProjectCloudRegistrationRequired);
    }
    Ok(())
}

const fn project_encryption_mode_name(mode: &ProjectEncryptionMode) -> &'static str {
    match mode {
        ProjectEncryptionMode::PersonalE2ee => "personal_e2ee",
        ProjectEncryptionMode::TeamEnvelope => "team_envelope",
    }
}

struct ProjectRegistrationBuildSpec<'a> {
    project: &'a Project,
    keyring: &'a ProjectKeyring,
    cell: DataCell,
    project_key: &'a KeyMaterial,
    context: &'a ContentEncryptionContext,
    plaintext: &'a SecretBytes,
    idempotency_key_digest: String,
    intent_digest: String,
    authorization: &'a KeyAdministrationAuthorization,
    now: DateTime<Utc>,
}

fn build_project_registration(
    spec: ProjectRegistrationBuildSpec<'_>,
) -> Result<LocalProjectCloudRegistration, ApplicationError> {
    let encrypted = ContentCrypto::seal(spec.plaintext.as_slice(), spec.project_key, spec.context)?;
    let registration = CloudProjectRegistration {
        scope: CellScope {
            cell: spec.cell,
            tenant_id: spec.project.tenant_id.clone(),
        },
        project_id: spec.project.id.clone(),
        encryption_mode: spec.keyring.mode.clone(),
        remote_execution_opt_in: spec.keyring.remote_execution_opt_in,
        metadata_digest: encrypted.content_digest.clone(),
        initial_payload: EncryptedPayload {
            key_version: spec.keyring.active_key_version,
            nonce: encrypted.nonce,
            ciphertext: encrypted.ciphertext,
            aad_digest: encrypted.aad_digest,
            content_digest: encrypted.content_digest,
        },
        idempotency_key_digest: spec.idempotency_key_digest.clone(),
        created_at: spec.now,
    };
    let request = serde_json::to_value(&registration)?;
    Ok(LocalProjectCloudRegistration {
        tenant_id: spec.project.tenant_id.clone(),
        project_id: spec.project.id.clone(),
        cell: spec.cell.as_str().into(),
        encryption_mode: project_encryption_mode_name(&spec.keyring.mode).into(),
        remote_execution_opt_in: spec.keyring.remote_execution_opt_in,
        idempotency_key_digest: spec.idempotency_key_digest,
        intent_digest: spec.intent_digest,
        request_digest: canonical_sha256(&request)?,
        key_version: spec.keyring.active_key_version,
        content_digest: registration.metadata_digest,
        request,
        authorized_by: spec.authorization.actor_id.to_string(),
        authorization_evidence_digest: spec.authorization.evidence_digest.clone(),
        status: ProjectCloudRegistrationStatus::Prepared,
        remote_revision: None,
        remote_duplicate: false,
        last_error_code: None,
        revision: 1,
        created_at: spec.now,
        updated_at: spec.now,
    })
}

fn project_registration_idempotency_digest(
    project: &Project,
    cell: DataCell,
    idempotency_key: &str,
) -> Result<String, ApplicationError> {
    canonical_sha256(&serde_json::json!({
        "operation": "project_cloud_registration",
        "cell": cell,
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "idempotencyKey": idempotency_key,
    }))
}

fn prepared_project_registration_from_outcome(
    outcome: LocalProjectCloudRegistrationPrepareOutcome,
) -> Result<PreparedProjectCloudRegistration, ApplicationError> {
    prepared_project_registration_from_local(outcome.registration, outcome.duplicate)
}

fn prepared_project_registration_from_local(
    local: LocalProjectCloudRegistration,
    duplicate: bool,
) -> Result<PreparedProjectCloudRegistration, ApplicationError> {
    if local.request_digest != canonical_sha256(&local.request)? {
        return Err(ApplicationError::ProjectRegistrationResultMismatch);
    }
    let registration: CloudProjectRegistration = serde_json::from_value(local.request.clone())?;
    if registration.scope.cell.as_str() != local.cell
        || registration.scope.tenant_id != local.tenant_id
        || registration.project_id != local.project_id
        || project_encryption_mode_name(&registration.encryption_mode) != local.encryption_mode
        || registration.remote_execution_opt_in != local.remote_execution_opt_in
        || registration.idempotency_key_digest != local.idempotency_key_digest
        || registration.initial_payload.key_version != local.key_version
        || registration.initial_payload.content_digest != local.content_digest
        || registration.metadata_digest != local.content_digest
    {
        return Err(ApplicationError::ProjectRegistrationResultMismatch);
    }
    Ok(PreparedProjectCloudRegistration {
        local,
        registration,
        duplicate,
    })
}

enum OutboundSyncPlan {
    Replay(LocalSyncOperation),
    Prepare(LocalSyncOperation),
}

fn validate_outbound_sync_command(
    store: &ProjectStore,
    command: &PrepareEncryptedSyncOperation,
    now: DateTime<Utc>,
) -> Result<Project, ApplicationError> {
    if command.idempotency_key.trim().is_empty() || command.object_id.trim().is_empty() {
        return Err(ApplicationError::InvalidSyncOperation);
    }
    let project = store.load_project(&command.project_id)?;
    if project.storage_mode != StorageMode::LocalEncryptedSync {
        return Err(ApplicationError::SyncRequiresEncryptedProject);
    }
    require_applied_project_registration(store, &project, command.cell)?;
    if !command.tombstone {
        store.ensure_sync_object_not_deleted(
            &project.id,
            command.object_kind.as_str(),
            &command.object_id,
        )?;
    }
    validate_sync_document(
        &command.document,
        &project,
        &command.object_id,
        command.object_kind,
        command.tombstone,
    )?;
    validate_outbound_sync_document(OutboundDocumentValidation {
        store,
        document: &command.document,
        project: &project,
        object_id: &command.object_id,
        object_kind: command.object_kind,
        tombstone: command.tombstone,
        target_revision: sync_target_revision(command.precondition, command.tombstone)?,
        now,
    })?;
    Ok(project)
}

fn plan_outbound_encrypted_sync(
    store: &ProjectStore,
    secret_store: &impl SecretStore,
    project: &Project,
    command: PrepareEncryptedSyncOperation,
    now: DateTime<Utc>,
) -> Result<OutboundSyncPlan, ApplicationError> {
    let plaintext = SecretBytes::new(serde_json::to_vec(&command.document)?)?;
    let keyring = store.load_project_keyring(&command.project_id)?;
    let project_key =
        open_active_project_key(secret_store, &keyring, &command.authorizing_key, now)?;
    let target_revision = sync_target_revision(command.precondition, command.tombstone)?;
    let context = sync_content_context(
        command.cell,
        project,
        &command.object_id,
        command.object_kind,
        target_revision,
        keyring.active_key_version,
        command.tombstone,
    );
    let intent_digest = ContentCrypto::intent_digest(plaintext.as_slice(), &project_key, &context)?;
    let idempotency_key_digest =
        sync_idempotency_digest(project, command.cell, command.idempotency_key.trim())?;
    match store.load_local_sync_operation(&project.id, &idempotency_key_digest) {
        Ok(existing) if existing.intent_digest == intent_digest => {
            return Ok(OutboundSyncPlan::Replay(existing));
        }
        Ok(_) => return Err(ApplicationError::SyncIdempotencyConflict),
        Err(StorageError::ScopedRecordNotFound { .. }) => {}
        Err(error) => return Err(error.into()),
    }

    let encrypted = ContentCrypto::seal(plaintext.as_slice(), &project_key, &context)?;
    let mutation = EncryptedSyncMutation {
        scope: CellScope {
            cell: command.cell,
            tenant_id: project.tenant_id.clone(),
        },
        project_id: project.id.clone(),
        object_id: command.object_id,
        object_kind: command.object_kind,
        precondition: command.precondition,
        payload: EncryptedPayload {
            key_version: keyring.active_key_version,
            nonce: encrypted.nonce,
            ciphertext: encrypted.ciphertext,
            aad_digest: encrypted.aad_digest,
            content_digest: encrypted.content_digest,
        },
        tombstone: command.tombstone,
        idempotency_key_digest: idempotency_key_digest.clone(),
        recorded_at: now,
    };
    Ok(OutboundSyncPlan::Prepare(
        local_sync_operation_for_mutation(
            project,
            &mutation,
            idempotency_key_digest,
            intent_digest,
            target_revision,
            now,
        )?,
    ))
}

fn local_sync_operation_for_mutation(
    project: &Project,
    mutation: &EncryptedSyncMutation,
    idempotency_key_digest: String,
    intent_digest: String,
    target_revision: u64,
    now: DateTime<Utc>,
) -> Result<LocalSyncOperation, ApplicationError> {
    let request = serde_json::to_value(mutation)?;
    Ok(LocalSyncOperation {
        tenant_id: project.tenant_id.clone(),
        project_id: project.id.clone(),
        idempotency_key_digest,
        intent_digest,
        request_digest: canonical_sha256(&request)?,
        cell: mutation.scope.cell.as_str().into(),
        object_id: mutation.object_id.clone(),
        object_kind: mutation.object_kind.as_str().into(),
        target_revision,
        key_version: mutation.payload.key_version,
        content_digest: mutation.payload.content_digest.clone(),
        tombstone: mutation.tombstone,
        request,
        status: LocalSyncStatus::Prepared,
        remote_revision: None,
        remote_duplicate: false,
        last_error_code: None,
        revision: 1,
        created_at: now,
        updated_at: now,
    })
}

fn validate_inbound_sync_project(
    store: &ProjectStore,
    project: &Project,
    object: &EncryptedSyncObject,
) -> Result<(), ApplicationError> {
    if project.storage_mode != StorageMode::LocalEncryptedSync {
        return Err(ApplicationError::SyncRequiresEncryptedProject);
    }
    require_applied_project_registration(store, project, object.scope.cell)?;
    validate_remote_sync_scope(project, object)
}

fn stage_inbound_sync_object(
    store: &mut ProjectStore,
    project: &Project,
    command: &IngestEncryptedSyncObject,
    now: DateTime<Utc>,
) -> Result<LocalInboundSyncStageOutcome, ApplicationError> {
    let request = serde_json::to_value(&command.object)?;
    Ok(store.stage_local_inbound_sync_object(
        &LocalInboundSyncEnvelope {
            tenant_id: project.tenant_id.clone(),
            project_id: project.id.clone(),
            cell: command.object.scope.cell.as_str().into(),
            object_id: command.object.object_id.clone(),
            object_kind: command.object.object_kind.as_str().into(),
            remote_revision: command.object.revision,
            key_version: command.object.payload.key_version,
            content_digest: command.object.payload.content_digest.clone(),
            tombstone: command.object.tombstone,
            request_digest: canonical_sha256(&request)?,
            request,
            remote_recorded_at: command.object.recorded_at,
        },
        command.expected_remote_revision,
        now,
    )?)
}

struct AuthenticatedInboundSync {
    persisted: EncryptedSyncObject,
    document: SyncDocument,
    validation_digest: String,
}

fn authenticate_staged_sync_object(
    store: &ProjectStore,
    secret_store: &impl SecretStore,
    authorizing_key: &RecipientKeyReference,
    project: &Project,
    staged: &LocalInboundSyncObject,
    now: DateTime<Utc>,
) -> Result<AuthenticatedInboundSync, ApplicationError> {
    // Reopen the exact SQLCipher envelope so a caller cannot stage one body
    // and ask the projector to authenticate a different one.
    let persisted: EncryptedSyncObject = serde_json::from_value(staged.envelope.request.clone())?;
    validate_remote_sync_scope(project, &persisted)?;
    validate_local_inbound_matches_remote(staged, &persisted)?;
    let keyring = store.load_project_keyring(&project.id)?;
    let project_key = open_project_key_for_version(
        secret_store,
        &keyring,
        authorizing_key,
        persisted.payload.key_version,
        now,
    )?;
    let context = sync_content_context(
        persisted.scope.cell,
        project,
        &persisted.object_id,
        persisted.object_kind,
        persisted.revision,
        persisted.payload.key_version,
        persisted.tombstone,
    );
    let plaintext = ContentCrypto::open(
        &EncryptedContent {
            nonce: persisted.payload.nonce.clone(),
            ciphertext: persisted.payload.ciphertext.clone(),
            aad_digest: persisted.payload.aad_digest.clone(),
            content_digest: persisted.payload.content_digest.clone(),
        },
        &project_key,
        &context,
    )?;
    let document: SyncDocument = serde_json::from_slice(plaintext.as_slice())?;
    validate_sync_document(
        &document,
        project,
        &persisted.object_id,
        persisted.object_kind,
        persisted.tombstone,
    )?;
    let validation_digest =
        ContentCrypto::intent_digest(plaintext.as_slice(), &project_key, &context)?;
    Ok(AuthenticatedInboundSync {
        persisted,
        document,
        validation_digest,
    })
}

fn project_authenticated_sync_tombstone(
    store: &mut ProjectStore,
    project: &Project,
    authenticated: &AuthenticatedInboundSync,
    expected_local_revision: u64,
    now: DateTime<Utc>,
) -> Result<LocalInboundSyncObject, ApplicationError> {
    let remote = &authenticated.persisted;
    if remote.object_kind != SyncObjectKind::ContextCapsule {
        return Err(ApplicationError::SyncDeletionUnsupported(
            remote.object_kind,
        ));
    }
    let tombstone: DeletionTombstone = serde_json::from_value(authenticated.document.body.clone())?;
    tombstone.validate(now)?;
    if tombstone.tenant_id != project.tenant_id
        || tombstone.project_id != project.id
        || tombstone.object_id != remote.object_id
        || tombstone.object_kind != remote.object_kind.as_str()
        || tombstone
            .prior_object_revision
            .checked_add(1)
            .ok_or(ApplicationError::InvalidSyncDeletion)?
            != remote.revision
    {
        return Err(ApplicationError::InvalidSyncDeletion);
    }
    Ok(store.apply_local_inbound_context_capsule_tombstone(
        &tombstone,
        &remote.object_id,
        expected_local_revision,
        remote.revision,
        &authenticated.validation_digest,
        now,
    )?)
}

#[allow(
    clippy::too_many_lines,
    reason = "the exhaustive inbound dispatcher keeps every authenticated SyncObjectKind projector visible"
)]
fn project_authenticated_sync_document(
    store: &mut ProjectStore,
    project: &Project,
    authenticated: &AuthenticatedInboundSync,
    expected_local_revision: u64,
    now: DateTime<Utc>,
) -> Result<LocalInboundSyncObject, ApplicationError> {
    let remote = &authenticated.persisted;
    let local = match remote.object_kind {
        SyncObjectKind::ProjectMetadata => {
            let metadata: ProjectMetadataSnapshot =
                serde_json::from_value(authenticated.document.body.clone())?;
            let projected = metadata.project_over(project)?;
            store.apply_local_inbound_project_metadata(
                &projected,
                &remote.object_id,
                expected_local_revision,
                remote.revision,
                &authenticated.validation_digest,
                now,
            )?
        }
        SyncObjectKind::Mission => {
            let mission: Mission = serde_json::from_value(authenticated.document.body.clone())?;
            validate_synced_mission_snapshot(&mission, project, &remote.object_id)?;
            store.apply_local_inbound_mission(
                &mission,
                &remote.object_id,
                expected_local_revision,
                remote.revision,
                &authenticated.validation_digest,
                now,
            )?
        }
        SyncObjectKind::ProjectTruth => {
            let fact: TruthFact = serde_json::from_value(authenticated.document.body.clone())?;
            validate_synced_truth_fact(&fact, project, &remote.object_id, now)?;
            store.apply_local_inbound_truth_fact(
                &fact,
                &remote.object_id,
                expected_local_revision,
                remote.revision,
                &authenticated.validation_digest,
                now,
            )?
        }
        SyncObjectKind::WorkProduct => {
            let snapshot: WorkProductSyncSnapshot =
                serde_json::from_value(authenticated.document.body.clone())?;
            snapshot.validate_for(project, &remote.object_id)?;
            if snapshot.manifest.version != remote.revision {
                return Err(ApplicationError::InvalidSyncDocument);
            }
            store.apply_local_inbound_work_product(
                &snapshot.manifest,
                &snapshot.work_product,
                &remote.object_id,
                expected_local_revision,
                remote.revision,
                &authenticated.validation_digest,
                now,
            )?
        }
        SyncObjectKind::Conversation => project_authenticated_conversation(
            store,
            project,
            authenticated,
            expected_local_revision,
            now,
        )?,
        SyncObjectKind::ConnectionMetadata => {
            let snapshot: ConnectionMetadataSyncSnapshot =
                serde_json::from_value(authenticated.document.body.clone())?;
            snapshot.validate_for(project, &remote.object_id)?;
            if snapshot.sync_version != remote.revision {
                return Err(ApplicationError::InvalidSyncDocument);
            }
            store.apply_local_inbound_connection_metadata(
                &snapshot.connection,
                &remote.object_id,
                expected_local_revision,
                remote.revision,
                &authenticated.validation_digest,
                now,
            )?
        }
        SyncObjectKind::CreatorWork => project_authenticated_creator_work(
            store,
            project,
            authenticated,
            expected_local_revision,
            now,
        )?,
        SyncObjectKind::OutcomeLedger => project_authenticated_outcome_ledger(
            store,
            project,
            authenticated,
            expected_local_revision,
            now,
        )?,
        SyncObjectKind::ContextCapsule => project_authenticated_context_capsule(
            store,
            project,
            authenticated,
            expected_local_revision,
            now,
        )?,
    };
    Ok(local)
}

