    #[derive(Clone, Copy)]
    enum CatalogCheckpointFixtureTiming {
        Staggered,
        Exact,
    }

    impl CatalogCheckpointFixtureTiming {
        fn step_at(self, started_at: DateTime<Utc>, step: i64) -> DateTime<Utc> {
            match self {
                Self::Staggered => started_at + Duration::milliseconds(step * 10),
                Self::Exact => started_at,
            }
        }

        fn offset(self, at: DateTime<Utc>, milliseconds: i64) -> DateTime<Utc> {
            match self {
                Self::Staggered => at + Duration::milliseconds(milliseconds),
                Self::Exact => at,
            }
        }
    }

    fn complete_catalog_checkpoint_dag(
        service: &mut ApplicationService,
        project_id: &ProjectId,
        mission_id: &MissionId,
        started_at: DateTime<Utc>,
    ) {
        complete_catalog_checkpoint_dag_with_timing(
            service,
            project_id,
            mission_id,
            started_at,
            CatalogCheckpointFixtureTiming::Staggered,
        );
    }

    fn complete_catalog_checkpoint_dag_at_exact_time(
        service: &mut ApplicationService,
        project_id: &ProjectId,
        mission_id: &MissionId,
        phase_at: DateTime<Utc>,
    ) {
        complete_catalog_checkpoint_dag_with_timing(
            service,
            project_id,
            mission_id,
            phase_at,
            CatalogCheckpointFixtureTiming::Exact,
        );
        assert_eq!(
            service
                .load_mission(project_id, mission_id)
                .expect("exact-time completed Catalog Mission")
                .updated_at,
            phase_at
        );
    }

    fn complete_catalog_checkpoint_dag_with_timing(
        service: &mut ApplicationService,
        project_id: &ProjectId,
        mission_id: &MissionId,
        started_at: DateTime<Utc>,
        timing: CatalogCheckpointFixtureTiming,
    ) {
        let mut step = 0_i64;
        loop {
            let mission = service
                .load_mission(project_id, mission_id)
                .expect("Catalog Mission");
            let Some(checkpoint) = mission
                .definition
                .as_ref()
                .and_then(MissionDefinition::current_checkpoint)
                .cloned()
            else {
                break;
            };
            let begin_at = timing.step_at(started_at, step);
            if checkpoint.status == MissionCheckpointStatus::Ready {
                service
                    .begin_mission_checkpoint(project_id, mission_id, &checkpoint.id, begin_at)
                    .expect("begin Catalog Checkpoint");
            }
            let completion = prepare_catalog_checkpoint_oracle_evidence_with_timing(
                service,
                project_id,
                mission_id,
                &checkpoint.id,
                step,
                timing.offset(begin_at, 1),
                timing,
            );
            if checkpoint.route.as_ref().is_some_and(|route| {
                route.completion_policy
                    == Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
            }) {
                let current = service
                    .load_mission(project_id, mission_id)
                    .expect("Human Checkpoint Mission");
                let current_checkpoint_revision = current
                    .definition
                    .as_ref()
                    .and_then(MissionDefinition::current_checkpoint)
                    .map(|current_checkpoint| current_checkpoint.revision)
                    .expect("Human Checkpoint revision");
                let conversation_revision = service
                    .mission_conversation(project_id, mission_id)
                    .expect("Human Checkpoint Conversation")
                    .revision;
                service
                    .confirm_human_mission_checkpoint(
                        ConfirmHumanMissionCheckpoint {
                            project_id: project_id.clone(),
                            mission_id: mission_id.clone(),
                            checkpoint_id: checkpoint.id.clone(),
                            message_id: MissionConversationMessageId::from_stable(format!(
                                "fixture-human-confirmation:{}:{}:{step}",
                                mission_id.as_str(),
                                checkpoint.id
                            )),
                            body: format!("Confirm deterministic fixture {}", checkpoint.id),
                            idempotency_key: format!(
                                "fixture-human-confirmation:{}:{}:{step}",
                                mission_id.as_str(),
                                checkpoint.id
                            ),
                            work_product_ids: completion.work_product_ids,
                            expected_mission_revision: current.revision,
                            expected_checkpoint_revision: current_checkpoint_revision,
                            expected_conversation_revision: conversation_revision,
                        },
                        completion.verified_at,
                    )
                    .expect("confirm Human Catalog Checkpoint");
            } else if checkpoint
                .route
                .as_ref()
                .is_some_and(|route| route.executor == MissionCheckpointExecutor::Application)
            {
                let current = service
                    .load_mission(project_id, mission_id)
                    .expect("Application Checkpoint Mission");
                service
                    .complete_mission_checkpoint_trusted(current, &checkpoint.id, completion)
                    .expect("complete test-fixture Application Checkpoint");
            } else {
                service
                    .complete_mission_checkpoint(project_id, mission_id, &checkpoint.id, completion)
                    .expect("complete Catalog Checkpoint");
            }
            step += 1;
        }
    }

    fn advance_vm11_application_routes_to_human_decision(
        service: &mut ApplicationService,
        project_id: &ProjectId,
        mission_id: &MissionId,
        started_at: DateTime<Utc>,
    ) -> MissionCheckpointDispatch {
        for step in 0_i64..10 {
            let dispatch = service
                .dispatch_current_mission_checkpoint(
                    project_id,
                    mission_id,
                    started_at + Duration::seconds(step),
                )
                .expect("VM-11 dispatch");
            if dispatch.executor == MissionCheckpointExecutor::Human {
                assert_eq!(dispatch.checkpoint_id, "continue_stop_scale_test");
                return dispatch;
            }
            let execution = service
                .execute_application_mission_checkpoint(
                    ExecuteApplicationMissionCheckpoint {
                        project_id: project_id.clone(),
                        mission_id: mission_id.clone(),
                        checkpoint_id: dispatch.checkpoint_id,
                        expected_mission_revision: dispatch.mission_revision,
                        expected_checkpoint_revision: dispatch.checkpoint_revision,
                    },
                    started_at + Duration::seconds(step),
                )
                .expect("source-fenced VM-11 Application route");
            assert!(matches!(
                execution,
                ApplicationMissionCheckpointExecution::Completed {
                    replayed: false,
                    ..
                }
            ));
        }
        panic!("VM-11 did not reach its Human decision within the manifest bound")
    }

    /// Builds real Domain evidence for a Catalog Checkpoint while keeping Provider
    /// execution out of scheduler/dispatch test setup. The fixture follows the same
    /// WorkProduct and Effect state machines and persists one auditable preparation
    /// event before the production completion command evaluates the frozen Oracles.
    fn prepare_catalog_checkpoint_oracle_evidence(
        service: &mut ApplicationService,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        nonce: i64,
        prepared_at: DateTime<Utc>,
    ) -> MissionCheckpointCompletion {
        prepare_catalog_checkpoint_oracle_evidence_with_timing(
            service,
            project_id,
            mission_id,
            checkpoint_id,
            nonce,
            prepared_at,
            CatalogCheckpointFixtureTiming::Staggered,
        )
    }

    #[allow(
        clippy::too_many_lines,
        reason = "this test fixture materializes each deterministic Oracle evidence type through its real Domain state machine before returning one exact completion proof"
    )]
    fn prepare_catalog_checkpoint_oracle_evidence_with_timing(
        service: &mut ApplicationService,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        nonce: i64,
        prepared_at: DateTime<Utc>,
        timing: CatalogCheckpointFixtureTiming,
    ) -> MissionCheckpointCompletion {
        let mut mission = service
            .load_mission(project_id, mission_id)
            .expect("Catalog Mission evidence preparation");
        let expected_revision = mission.revision;
        let (route, cycle, checkpoint_revision) = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == checkpoint_id)
                    .and_then(|checkpoint| {
                        checkpoint
                            .route
                            .clone()
                            .map(|route| (route, definition.cycle, checkpoint.revision))
                    })
            })
            .expect("contracted Checkpoint route");
        assert!(route.is_contracted());
        let fixture_key = format!(
            "{}:{}:{}:{}:{nonce}",
            mission_id.as_str(),
            cycle,
            checkpoint_id,
            checkpoint_revision
        );
        let needs_running_evidence = route.oracle_ids.contains("work_product")
            || route.completion_policy == Some(MissionCheckpointCompletionPolicy::VerifiedEffect);
        if needs_running_evidence && mission.stage == MissionStage::Verifying {
            let prior_verified_effect_id = mission
                .effects
                .iter()
                .rev()
                .find(|effect| effect.status == EffectStatus::Verified)
                .map(|effect| effect.id.clone())
                .expect("a verifying fixture Mission must name its prior verified Effect");
            mission
                .continue_after_verified_effect(&prior_verified_effect_id, prepared_at)
                .expect("continue after prior verified Effect before preparing new evidence");
        }
        let mut work_product_ids = BTreeSet::new();
        if route.oracle_ids.contains("work_product") {
            let evidence_id = EvidenceId::from_stable(format!("fixture-evidence-{fixture_key}"));
            mission
                .record_evidence(
                    Evidence {
                        id: evidence_id.clone(),
                        title: format!("Checkpoint evidence: {checkpoint_id}"),
                        source_uri: format!("fixture://checkpoint/{fixture_key}"),
                        observed_at: prepared_at,
                        confidence: 1.0,
                        status: EvidenceStatus::Confirmed,
                        content_digest: sha256(format!("evidence:{fixture_key}").as_bytes()),
                    },
                    prepared_at,
                )
                .expect("record Checkpoint evidence");
            let work_product_id =
                WorkProductId::from_stable(format!("fixture-work-product-{fixture_key}"));
            mission
                .record_work_product(
                    WorkProduct::draft(
                        work_product_id.clone(),
                        format!("Checkpoint work product: {checkpoint_id}"),
                        format!("Deterministic fixture artifact for {fixture_key}"),
                        [evidence_id],
                    ),
                    timing.offset(prepared_at, 1),
                )
                .expect("record Checkpoint WorkProduct");
            work_product_ids.insert(work_product_id);
        }

        let mut effect_ids = BTreeSet::new();
        if route.completion_policy == Some(MissionCheckpointCompletionPolicy::VerifiedEffect) {
            let effect_id = EffectId::from_stable(format!("fixture-effect-{fixture_key}"));
            let proposed_at = timing.offset(prepared_at, 2);
            mission
                .propose_effect(
                    EffectSpec {
                        id: effect_id.clone(),
                        actor_id: ActorId::from("fixture-operator"),
                        capability: route.capability_id.clone(),
                        provider: "fixture-provider".into(),
                        connection_id: None,
                        account_id: None,
                        required_scopes: BTreeSet::new(),
                        effect_class: EffectClass::ExternalWrite,
                        description: format!("Execute fixture route {checkpoint_id}"),
                        target_resource: format!("fixture://target/{fixture_key}"),
                        audience_digest: None,
                        payload_digest: sha256(format!("payload:{fixture_key}").as_bytes()),
                        asset_digests: BTreeSet::new(),
                        scheduled_for: None,
                        timezone: "UTC".into(),
                        consent: ConsentState::NotRequired,
                        consent_record_id: None,
                        consent_requirement: None,
                        conversation_guard: None,
                        creator_contact_guard: None,
                        policy_version: "fixture-policy-v1".into(),
                        risk: EffectRisk::Low,
                        idempotency_key: format!("fixture-effect:{fixture_key}"),
                        amount: Money::zero(mission.contract.budget.currency.clone()),
                        expires_at: proposed_at + Duration::minutes(5),
                    },
                    proposed_at,
                )
                .expect("propose fixture Effect");
            let decided_at = timing.offset(prepared_at, 3);
            let scope_digest = mission
                .effect(&effect_id)
                .expect("fixture Effect")
                .approval_digest();
            let valid_until = mission
                .approval_valid_until(&effect_id, decided_at)
                .expect("fixture approval window");
            mission
                .approve_effect(
                    &effect_id,
                    Approval {
                        id: ApprovalId::from_stable(format!("fixture-approval-{fixture_key}")),
                        decision: ApprovalDecision::Approved,
                        decided_by: ActorId::from("fixture-approver"),
                        decided_at,
                        valid_until,
                        scope_digest,
                        permission_digest: sha256(format!("permission:{fixture_key}").as_bytes()),
                    },
                )
                .expect("approve fixture Effect");
            mission
                .begin_effect(&effect_id, timing.offset(prepared_at, 4))
                .expect("begin fixture Effect");
            let receipt_id = ReceiptId::from_stable(format!("fixture-receipt-{fixture_key}"));
            let request_digest = mission
                .effect(&effect_id)
                .expect("executing fixture Effect")
                .approval_digest();
            mission
                .record_receipt(
                    &effect_id,
                    Receipt {
                        id: receipt_id.clone(),
                        provider: "fixture-provider".into(),
                        external_id: format!("fixture-external-{fixture_key}"),
                        accepted_at: timing.offset(prepared_at, 5),
                        request_digest,
                        response_digest: sha256(format!("response:{fixture_key}").as_bytes()),
                    },
                )
                .expect("record fixture Receipt");
            mission
                .record_verification(
                    &effect_id,
                    Verification {
                        id: VerificationId::from_stable(format!(
                            "fixture-verification-{fixture_key}"
                        )),
                        status: VerificationStatus::Confirmed,
                        verifier: "fixture-independent-verifier".into(),
                        independent: true,
                        observed_at: timing.offset(prepared_at, 6),
                        evidence_digest: sha256(format!("verification:{fixture_key}").as_bytes()),
                        receipt_id,
                    },
                )
                .expect("independently verify fixture Effect");
            effect_ids.insert(effect_id);
        } else if route.completion_policy
            != Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
            && mission.stage != MissionStage::Verifying
        {
            mission
                .begin_checkpoint_verification(checkpoint_id, timing.offset(prepared_at, 6))
                .expect("begin deterministic Checkpoint verification");
        }

        if mission.revision > expected_revision {
            service
                .store
                .update_mission_atomic(
                    &mission,
                    expected_revision,
                    &[PendingEvent::new(
                        "test.checkpoint_oracle_evidence_prepared",
                        serde_json::json!({
                            "missionId": mission_id,
                            "checkpointId": checkpoint_id,
                            "cycle": cycle,
                            "checkpointRevision": checkpoint_revision,
                            "oracleIds": route.oracle_ids,
                            "workProductCount": work_product_ids.len(),
                            "effectCount": effect_ids.len(),
                        }),
                        timing.offset(prepared_at, 6),
                    )],
                )
                .expect("persist fixture Oracle evidence");
        } else {
            assert!(
                mission.stage == MissionStage::Verifying
                    || (mission.stage == MissionStage::Running
                        && route.completion_policy
                            == Some(MissionCheckpointCompletionPolicy::HumanConfirmation))
            );
        }
        let verified_at = timing.offset(prepared_at, 7);
        let application_evidence = if route.executor == MissionCheckpointExecutor::Application {
            let definition = mission.definition.as_ref().expect("Catalog definition");
            let verifying_checkpoint = definition
                .checkpoints
                .iter()
                .find(|checkpoint| checkpoint.id == checkpoint_id)
                .expect("verifying Application Checkpoint");
            let sources = route
                .oracle_ids
                .iter()
                .map(|oracle_id| MissionCheckpointOracleSource {
                    source_kind: format!("test_fixture_{oracle_id}"),
                    source_id: fixture_key.clone(),
                    source_revision: checkpoint_revision,
                    projection_digest: sha256(
                        format!("fixture-source:{fixture_key}:{oracle_id}").as_bytes(),
                    ),
                    oracle_ids: BTreeSet::from([oracle_id.clone()]),
                })
                .collect::<BTreeSet<_>>();
            Some(MissionCheckpointApplicationEvidence {
                schema_version: MissionCheckpointApplicationEvidence::SCHEMA_VERSION,
                handler_id: "test.catalog-application-evidence/v1".into(),
                tenant_id: mission.tenant_id.clone(),
                project_id: mission.project_id.clone(),
                mission_id: mission.id.clone(),
                manifest_id: definition.manifest_id.clone(),
                manifest_version: definition.manifest_version,
                catalog_digest: definition.catalog_digest.clone(),
                cycle: definition.cycle,
                checkpoint_id: checkpoint_id.into(),
                dispatch_mission_revision: expected_revision,
                dispatch_checkpoint_revision: checkpoint_revision,
                verification_mission_revision: mission.revision,
                verification_checkpoint_revision: verifying_checkpoint.revision,
                capability_id: route.capability_id.clone(),
                executor: route.executor,
                completion_policy: route.completion_policy.expect("contracted route"),
                sources,
                observed_at: verified_at,
            })
        } else {
            None
        };
        let evidence_digest = application_evidence.as_ref().map_or_else(
            || sha256(format!("checkpoint-proof:{fixture_key}").as_bytes()),
            MissionCheckpointApplicationEvidence::digest,
        );
        MissionCheckpointCompletion {
            oracle_ids: route.oracle_ids,
            work_product_ids,
            effect_ids,
            application_evidence,
            evidence_digest,
            verified_at,
        }
    }

    #[cfg(unix)]
    const RUNTIME_CONTEXT_SUMMARY: &str =
        "PRIVATE-RUNTIME-SUMMARY::resume from the verified checkpoint only";

    #[cfg(unix)]
    const RUNTIME_TOKENIZER_JSON: &str = r#"{
      "version":"1.0",
      "truncation":null,
      "padding":null,
      "added_tokens":[],
      "normalizer":null,
      "pre_tokenizer":{"type":"WhitespaceSplit"},
      "post_processor":null,
      "decoder":null,
      "model":{
        "type":"WordLevel",
        "vocab":{"<unk>":0,"PRIVATE-RUNTIME-SUMMARY::resume":1,"from":2,"the":3,"verified":4,"checkpoint":5,"only":6},
        "unk_token":"<unk>"
      }
    }"#;

    #[test]
    fn every_machine_registered_application_handler_exists_in_this_binary() {
        let catalog = Catalog::load().expect("valid catalog");
        assert!(!catalog.application_handlers.handlers.is_empty());
        assert!(catalog.application_handlers.handlers.iter().all(|handler| {
            compiled_application_checkpoint_handler(&handler.handler_id).is_some()
        }));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one VM-00 contract test proves three local Project checkpoints, Project/Keyring fencing, recoverable provisioning, content-free evidence, atomic handoffs, exact replay, and stale-command refusal"
    )]
    fn vm00_local_identity_inventory_and_encryption_are_fenced_replayable_and_advance_without_outcome()
     {
        let workspace = tempfile::tempdir().expect("project workspace");
        let secrets = MemorySecretStore::default();
        let device_id = DeviceId::from("vm00-local-encryption-device");
        let private_workspace = workspace.path().to_string_lossy().into_owned();
        let private_project_name = "PRIVATE-VM00-PROJECT::local customer workspace";
        let private_project_description = "PRIVATE-VM00-DESCRIPTION::never enter evidence";
        let private_goal = "PRIVATE-VM00-GOAL::resume the exact local project";
        let project_id = ProjectId::from("vm00-local-identity-project");
        let mission_id = MissionId::from("vm00-local-identity-mission");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("vm00-local-identity-tenant"),
                    id: project_id.clone(),
                    name: private_project_name.into(),
                    description: private_project_description.into(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("local project");
        service
            .start_catalog_mission(
                StartCatalogMission {
                    id: mission_id.clone(),
                    first_task_id: TaskId::from("vm00-local-identity-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-00".into(),
                    mode: OperatingMode::BuildOnce,
                    parent_mission_id: None,
                    title: Some("Current local state".into()),
                    goal: private_goal.into(),
                    market: "US".into(),
                    language: "en-US".into(),
                    audience: "owner".into(),
                    timezone: "America/New_York".into(),
                    kpis: catalog_count_kpis(),
                    budget: Money::zero(CurrencyCode::parse("USD").expect("USD")),
                },
                now() + Duration::milliseconds(1),
            )
            .expect("VM-00 Mission");

        let dispatch = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(2),
            )
            .expect("identity dispatch");
        assert_eq!(dispatch.checkpoint_id, "identity.resolve");
        assert_eq!(
            dispatch.application_handler_status,
            Some(ApplicationCheckpointHandlerStatus::Implemented)
        );
        assert_eq!(
            dispatch.application_handler_id.as_deref(),
            Some(VM00_LOCAL_PROJECT_IDENTITY_HANDLER_ID)
        );
        let command = ExecuteApplicationMissionCheckpoint {
            project_id: project_id.clone(),
            mission_id: mission_id.clone(),
            checkpoint_id: dispatch.checkpoint_id.clone(),
            expected_mission_revision: dispatch.mission_revision,
            expected_checkpoint_revision: dispatch.checkpoint_revision,
        };
        let execution = service
            .execute_application_mission_checkpoint(
                command.clone(),
                now() + Duration::milliseconds(3),
            )
            .expect("local identity completion");
        let ApplicationMissionCheckpointExecution::Completed {
            outcome_ledger_revision,
            replayed,
            next_dispatch: Some(next_dispatch),
            ..
        } = execution
        else {
            panic!("VM-00 identity must complete and advance")
        };
        assert_eq!(outcome_ledger_revision, 1);
        assert!(!replayed);
        assert_eq!(next_dispatch.checkpoint_id, "project_inventory");
        assert_eq!(
            next_dispatch.executor,
            MissionCheckpointExecutor::Application
        );
        assert_eq!(
            next_dispatch.application_handler_status,
            Some(ApplicationCheckpointHandlerStatus::Implemented)
        );
        assert_eq!(
            next_dispatch.application_handler_id.as_deref(),
            Some(VM00_LOCAL_PROJECT_INVENTORY_HANDLER_ID)
        );

        let mission = service
            .load_mission(&project_id, &mission_id)
            .expect("advanced VM-00 Mission");
        let completion = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == "identity.resolve")
            })
            .and_then(|checkpoint| checkpoint.completion.as_ref())
            .expect("identity completion");
        assert!(completion.work_product_ids.is_empty());
        assert!(completion.effect_ids.is_empty());
        let evidence = completion
            .application_evidence
            .as_ref()
            .expect("content-free Application evidence");
        assert_eq!(evidence.handler_id, VM00_LOCAL_PROJECT_IDENTITY_HANDLER_ID);
        assert_eq!(
            evidence
                .sources
                .iter()
                .map(|source| source.source_kind.as_str())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["mission_checkpoint", "mission_contract", "project_scope"])
        );
        assert_eq!(
            evidence
                .sources
                .iter()
                .find(|source| source.source_kind == "project_scope")
                .map(|source| source.source_revision),
            Some(1)
        );
        let events = service
            .mission_events(&project_id, &mission_id)
            .expect("content-free Mission events");
        let event_json = serde_json::to_string(&events).expect("event JSON");
        for private_value in [
            private_project_name,
            private_project_description,
            private_goal,
            private_workspace.as_str(),
        ] {
            assert!(!event_json.contains(private_value));
        }

        let event_count = events.len();
        assert!(matches!(
            service
                .execute_application_mission_checkpoint(
                    command.clone(),
                    now() + Duration::milliseconds(4),
                )
                .expect("exact replay"),
            ApplicationMissionCheckpointExecution::Completed { replayed: true, .. }
        ));
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events after replay")
                .len(),
            event_count
        );
        assert!(matches!(
            service.execute_application_mission_checkpoint(
                ExecuteApplicationMissionCheckpoint {
                    expected_checkpoint_revision: command
                        .expected_checkpoint_revision
                        .saturating_add(1),
                    ..command
                },
                now() + Duration::milliseconds(5),
            ),
            Err(ApplicationError::ApplicationCheckpointReplayMismatch)
        ));

        let inventory_command = ExecuteApplicationMissionCheckpoint {
            project_id: project_id.clone(),
            mission_id: mission_id.clone(),
            checkpoint_id: next_dispatch.checkpoint_id,
            expected_mission_revision: next_dispatch.mission_revision,
            expected_checkpoint_revision: next_dispatch.checkpoint_revision,
        };
        let inventory_execution = service
            .execute_application_mission_checkpoint(
                inventory_command.clone(),
                now() + Duration::milliseconds(6),
            )
            .expect("local Project inventory completion");
        let ApplicationMissionCheckpointExecution::Completed {
            outcome_ledger_revision,
            replayed,
            next_dispatch: Some(encryption_dispatch),
            ..
        } = inventory_execution
        else {
            panic!("VM-00 Project inventory must complete and advance")
        };
        assert_eq!(outcome_ledger_revision, 1);
        assert!(!replayed);
        assert_eq!(
            encryption_dispatch.checkpoint_id,
            "encryption_workspace_ready"
        );
        assert_eq!(
            encryption_dispatch.executor,
            MissionCheckpointExecutor::Application
        );
        assert_eq!(
            encryption_dispatch.application_handler_status,
            Some(ApplicationCheckpointHandlerStatus::Implemented)
        );
        assert_eq!(
            encryption_dispatch.application_handler_id.as_deref(),
            Some(VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID)
        );

        let mission = service
            .load_mission(&project_id, &mission_id)
            .expect("VM-00 Mission after inventory");
        let inventory_completion = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == "project_inventory")
            })
            .and_then(|checkpoint| checkpoint.completion.as_ref())
            .expect("Project inventory completion");
        assert!(inventory_completion.work_product_ids.is_empty());
        assert!(inventory_completion.effect_ids.is_empty());
        let inventory_evidence = inventory_completion
            .application_evidence
            .as_ref()
            .expect("content-free Project inventory evidence");
        assert_eq!(
            inventory_evidence.handler_id,
            VM00_LOCAL_PROJECT_INVENTORY_HANDLER_ID
        );
        assert_eq!(
            inventory_evidence
                .sources
                .iter()
                .map(|source| source.source_kind.as_str())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["mission_checkpoint", "project_inventory"])
        );
        assert_eq!(
            inventory_evidence
                .sources
                .iter()
                .find(|source| source.source_kind == "project_inventory")
                .map(|source| source.source_revision),
            Some(1)
        );
        let events = service
            .mission_events(&project_id, &mission_id)
            .expect("content-free Project inventory events");
        let event_json = serde_json::to_string(&events).expect("event JSON");
        assert!(event_json.contains(VM00_LOCAL_PROJECT_INVENTORY_HANDLER_ID));
        for private_value in [
            private_project_name,
            private_project_description,
            private_goal,
            private_workspace.as_str(),
        ] {
            assert!(!event_json.contains(private_value));
        }

        let event_count = events.len();
        assert!(matches!(
            service
                .execute_application_mission_checkpoint(
                    inventory_command.clone(),
                    now() + Duration::milliseconds(7),
                )
                .expect("exact inventory replay"),
            ApplicationMissionCheckpointExecution::Completed { replayed: true, .. }
        ));
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events after inventory replay")
                .len(),
            event_count
        );
        assert!(matches!(
            service.execute_application_mission_checkpoint(
                ExecuteApplicationMissionCheckpoint {
                    expected_mission_revision: inventory_command
                        .expected_mission_revision
                        .saturating_add(1),
                    ..inventory_command
                },
                now() + Duration::milliseconds(8),
            ),
            Err(ApplicationError::ApplicationCheckpointReplayMismatch)
        ));

        let encryption_command = ExecuteApplicationMissionCheckpoint {
            project_id: project_id.clone(),
            mission_id: mission_id.clone(),
            checkpoint_id: encryption_dispatch.checkpoint_id,
            expected_mission_revision: encryption_dispatch.mission_revision,
            expected_checkpoint_revision: encryption_dispatch.checkpoint_revision,
        };
        let missing = service
            .execute_application_mission_checkpoint(
                encryption_command.clone(),
                now() + Duration::milliseconds(9),
            )
            .expect("missing encryption is a recoverable block");
        assert!(matches!(
            missing,
            ApplicationMissionCheckpointExecution::Blocked {
                code,
                outcome_ledger_revision: 0,
                replayed: false,
                ..
            } if code == "project_encryption_not_provisioned"
        ));
        let blocked_event_count = service
            .mission_events(&project_id, &mission_id)
            .expect("events after missing encryption")
            .len();
        assert!(matches!(
            service
                .execute_application_mission_checkpoint(
                    encryption_command,
                    now() + Duration::milliseconds(10),
                )
                .expect("exact blocked replay"),
            ApplicationMissionCheckpointExecution::Blocked { replayed: true, .. }
        ));
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events after blocked replay")
                .len(),
            blocked_event_count
        );

        service
            .provision_project_encryption(
                &secrets,
                ProvisionProjectEncryption {
                    project_id: project_id.clone(),
                    mode: ProjectEncryptionMode::TeamEnvelope,
                    primary_recipient: KeyRecipient::Device(device_id.clone()),
                    recovery_recipient_id: None,
                },
                now() + Duration::milliseconds(11),
            )
            .expect("explicit project encryption provisioning");
        let recovered_dispatch = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(12),
            )
            .expect("blocked encryption dispatch after provisioning");
        assert_eq!(
            recovered_dispatch.checkpoint_id,
            "encryption_workspace_ready"
        );
        assert_eq!(
            recovered_dispatch.state,
            MissionCheckpointDispatchState::Blocked
        );
        let recovered_command = ExecuteApplicationMissionCheckpoint {
            project_id: project_id.clone(),
            mission_id: mission_id.clone(),
            checkpoint_id: recovered_dispatch.checkpoint_id,
            expected_mission_revision: recovered_dispatch.mission_revision,
            expected_checkpoint_revision: recovered_dispatch.checkpoint_revision,
        };
        let recovered = service
            .execute_application_mission_checkpoint(
                recovered_command.clone(),
                now() + Duration::milliseconds(13),
            )
            .expect("ready encryption completion");
        let ApplicationMissionCheckpointExecution::Completed {
            outcome_ledger_revision,
            replayed,
            next_dispatch: Some(entitlement_dispatch),
            ..
        } = recovered
        else {
            panic!("VM-00 encryption readiness must complete and advance")
        };
        assert_eq!(outcome_ledger_revision, 1);
        assert!(!replayed);
        assert_eq!(entitlement_dispatch.checkpoint_id, "entitlement_and_wallet");
        assert_eq!(
            entitlement_dispatch.executor,
            MissionCheckpointExecutor::EffectBroker
        );
        assert_eq!(
            entitlement_dispatch.state,
            MissionCheckpointDispatchState::Ready
        );

        let mission = service
            .load_mission(&project_id, &mission_id)
            .expect("VM-00 Mission after encryption readiness");
        assert!(mission.effects.is_empty());
        let encryption_completion = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == "encryption_workspace_ready")
            })
            .and_then(|checkpoint| checkpoint.completion.as_ref())
            .expect("encryption readiness completion");
        assert!(encryption_completion.work_product_ids.is_empty());
        assert!(encryption_completion.effect_ids.is_empty());
        let encryption_evidence = encryption_completion
            .application_evidence
            .as_ref()
            .expect("content-free encryption evidence");
        assert_eq!(
            encryption_evidence.handler_id,
            VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID
        );
        assert_eq!(
            encryption_evidence
                .sources
                .iter()
                .map(|source| source.source_kind.as_str())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(["mission_checkpoint", "project_keyring"])
        );
        assert_eq!(
            encryption_evidence
                .sources
                .iter()
                .find(|source| source.source_kind == "project_keyring")
                .map(|source| source.source_revision),
            Some(1)
        );
        let events = service
            .mission_events(&project_id, &mission_id)
            .expect("content-free encryption events");
        let event_json = serde_json::to_string(&events).expect("event JSON");
        assert!(event_json.contains(VM00_LOCAL_ENCRYPTION_WORKSPACE_READY_HANDLER_ID));
        assert!(!event_json.contains(device_id.as_str()));
        for private_value in [
            private_project_name,
            private_project_description,
            private_goal,
            private_workspace.as_str(),
        ] {
            assert!(!event_json.contains(private_value));
        }
        let event_count = events.len();
        assert!(matches!(
            service
                .execute_application_mission_checkpoint(
                    recovered_command,
                    now() + Duration::milliseconds(14),
                )
                .expect("exact encryption replay"),
            ApplicationMissionCheckpointExecution::Completed { replayed: true, .. }
        ));
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events after encryption replay")
                .len(),
            event_count
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one focused failure-path test proves revoked active recipients force rotation, preserve the current checkpoint, and emit no partial effect"
    )]
    fn vm00_encryption_rotation_required_blocks_without_partial_advance() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let secrets = MemorySecretStore::default();
        let device_id = DeviceId::from("vm00-rotation-device");
        let project_id = ProjectId::from("vm00-rotation-project");
        let mission_id = MissionId::from("vm00-rotation-mission");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("vm00-rotation-tenant"),
                    id: project_id.clone(),
                    name: "Rotation-required VM-00".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("local project");
        service
            .provision_project_encryption(
                &secrets,
                ProvisionProjectEncryption {
                    project_id: project_id.clone(),
                    mode: ProjectEncryptionMode::TeamEnvelope,
                    primary_recipient: KeyRecipient::Device(device_id.clone()),
                    recovery_recipient_id: None,
                },
                now() + Duration::milliseconds(1),
            )
            .expect("project keyring");
        service
            .start_catalog_mission(
                StartCatalogMission {
                    id: mission_id.clone(),
                    first_task_id: TaskId::from("vm00-rotation-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-00".into(),
                    mode: OperatingMode::BuildOnce,
                    parent_mission_id: None,
                    title: None,
                    goal: "Stop when encryption needs rotation".into(),
                    market: "US".into(),
                    language: "en-US".into(),
                    audience: "owner".into(),
                    timezone: "UTC".into(),
                    kpis: catalog_count_kpis(),
                    budget: Money::zero(CurrencyCode::parse("USD").expect("USD")),
                },
                now() + Duration::milliseconds(2),
            )
            .expect("VM-00 Mission");

        for offset in [3_i64, 4] {
            let dispatch = service
                .dispatch_current_mission_checkpoint(
                    &project_id,
                    &mission_id,
                    now() + Duration::milliseconds(offset),
                )
                .expect("VM-00 Application dispatch");
            assert!(matches!(
                service
                    .execute_application_mission_checkpoint(
                        ExecuteApplicationMissionCheckpoint {
                            project_id: project_id.clone(),
                            mission_id: mission_id.clone(),
                            checkpoint_id: dispatch.checkpoint_id,
                            expected_mission_revision: dispatch.mission_revision,
                            expected_checkpoint_revision: dispatch.checkpoint_revision,
                        },
                        now() + Duration::milliseconds(offset),
                    )
                    .expect("VM-00 Application completion"),
                ApplicationMissionCheckpointExecution::Completed {
                    replayed: false,
                    ..
                }
            ));
        }

        let mut keyring = service
            .store
            .load_project_keyring(&project_id)
            .expect("ready keyring");
        let expected_keyring_revision = keyring.revision;
        keyring
            .revoke_recipient(
                &KeyRecipient::Device(device_id.clone()),
                now() + Duration::milliseconds(5),
            )
            .expect("revoke active device");
        service
            .store
            .update_project_keyring(
                &keyring,
                expected_keyring_revision,
                "project_keyring.recipient_revoked",
                &serde_json::json!({"rotationRequired": true}),
                now() + Duration::milliseconds(5),
            )
            .expect("persist rotation requirement");

        let dispatch = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(6),
            )
            .expect("encryption dispatch");
        assert_eq!(dispatch.checkpoint_id, "encryption_workspace_ready");
        let mission_before = service
            .load_mission(&project_id, &mission_id)
            .expect("Mission before rotation block");
        let event_count = service
            .mission_events(&project_id, &mission_id)
            .expect("events before rotation block")
            .len();
        let blocked = service
            .execute_application_mission_checkpoint(
                ExecuteApplicationMissionCheckpoint {
                    project_id: project_id.clone(),
                    mission_id: mission_id.clone(),
                    checkpoint_id: dispatch.checkpoint_id,
                    expected_mission_revision: dispatch.mission_revision,
                    expected_checkpoint_revision: dispatch.checkpoint_revision,
                },
                now() + Duration::milliseconds(6),
            )
            .expect("rotation-required block");
        assert!(matches!(
            blocked,
            ApplicationMissionCheckpointExecution::Blocked {
                code,
                outcome_ledger_revision: 2,
                replayed: false,
                ..
            } if code == "project_encryption_rotation_required"
        ));
        let mission_after = service
            .load_mission(&project_id, &mission_id)
            .expect("Mission after rotation block");
        assert!(mission_after.revision > mission_before.revision);
        assert_eq!(mission_after.stage, MissionStage::Blocked);
        assert!(mission_after.effects.is_empty());
        assert!(
            mission_after
                .definition
                .as_ref()
                .and_then(|definition| definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| { checkpoint.id == "encryption_workspace_ready" }))
                .is_some_and(|checkpoint| checkpoint.completion.is_none())
        );
        let events = service
            .mission_events(&project_id, &mission_id)
            .expect("events after rotation block");
        assert_eq!(events.len(), event_count + 1);
        let event_json = serde_json::to_string(&events).expect("event JSON");
        assert!(event_json.contains("project_encryption_rotation_required"));
        assert!(!event_json.contains(device_id.as_str()));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the negative VM-00 Journey proves malformed persisted inventory cannot partially advance Mission state or append events"
    )]
    fn vm00_project_inventory_rejects_invalid_roots_without_partial_advance() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("vm00-invalid-inventory-project");
        let mission_id = MissionId::from("vm00-invalid-inventory-mission");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("vm00-invalid-inventory-tenant"),
                    id: project_id.clone(),
                    name: "Invalid inventory fixture".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalExisting,
                },
                now(),
            )
            .expect("local project");
        service
            .start_catalog_mission(
                StartCatalogMission {
                    id: mission_id.clone(),
                    first_task_id: TaskId::from("vm00-invalid-inventory-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-00".into(),
                    mode: OperatingMode::BuildOnce,
                    parent_mission_id: None,
                    title: None,
                    goal: "Verify only a valid local inventory".into(),
                    market: "US".into(),
                    language: "en-US".into(),
                    audience: "owner".into(),
                    timezone: "America/New_York".into(),
                    kpis: catalog_count_kpis(),
                    budget: Money::zero(CurrencyCode::parse("USD").expect("USD")),
                },
                now() + Duration::milliseconds(1),
            )
            .expect("VM-00 Mission");
        let identity_dispatch = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(2),
            )
            .expect("identity dispatch");
        let identity_execution = service
            .execute_application_mission_checkpoint(
                ExecuteApplicationMissionCheckpoint {
                    project_id: project_id.clone(),
                    mission_id: mission_id.clone(),
                    checkpoint_id: identity_dispatch.checkpoint_id,
                    expected_mission_revision: identity_dispatch.mission_revision,
                    expected_checkpoint_revision: identity_dispatch.checkpoint_revision,
                },
                now() + Duration::milliseconds(3),
            )
            .expect("identity completion");
        let ApplicationMissionCheckpointExecution::Completed {
            next_dispatch: Some(inventory_dispatch),
            ..
        } = identity_execution
        else {
            panic!("identity must advance to inventory")
        };

        let mut invalid_project = service
            .store
            .load_project(&project_id)
            .expect("persisted project");
        invalid_project.workspace_roots = vec![PathBuf::from("relative-workspace")];
        invalid_project.revision = invalid_project.revision.saturating_add(1);
        service
            .store
            .save_project(&invalid_project)
            .expect("persist invalid legacy-compatible inventory fixture");
        let mission_before = service
            .load_mission(&project_id, &mission_id)
            .expect("Mission before invalid inventory");
        let event_count = service
            .mission_events(&project_id, &mission_id)
            .expect("events before invalid inventory")
            .len();
        let invalid_execution = service.execute_application_mission_checkpoint(
            ExecuteApplicationMissionCheckpoint {
                project_id: project_id.clone(),
                mission_id: mission_id.clone(),
                checkpoint_id: inventory_dispatch.checkpoint_id,
                expected_mission_revision: inventory_dispatch.mission_revision,
                expected_checkpoint_revision: inventory_dispatch.checkpoint_revision,
            },
            now() + Duration::milliseconds(4),
        );
        assert!(
            matches!(
                &invalid_execution,
                Err(ApplicationError::ApplicationCheckpointCommandMismatch)
            ),
            "unexpected invalid inventory result: {invalid_execution:?}"
        );
        let mission_after = service
            .load_mission(&project_id, &mission_id)
            .expect("Mission after invalid inventory");
        assert_eq!(mission_after.revision, mission_before.revision);
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events after invalid inventory")
                .len(),
            event_count
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the atomic contract test proves four independent rejection boundaries and verifies that none creates partial Mission state"
    )]
    fn catalog_contract_rejects_missing_kpi_missing_parent_and_vm11_inheritance_drift_atomically() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("catalog-contract-negative-project");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("catalog-contract-negative-tenant"),
                    id: project_id.clone(),
                    name: "Catalog contract negatives".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");

        let missing_kpi = service
            .start_catalog_mission(
                StartCatalogMission {
                    id: MissionId::from("missing-kpi-mission"),
                    first_task_id: TaskId::from("missing-kpi-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-07".into(),
                    mode: OperatingMode::OneOffDecision,
                    parent_mission_id: None,
                    title: None,
                    goal: "Decide only from explicit evidence".into(),
                    market: "US".into(),
                    language: "en-US".into(),
                    audience: "owner".into(),
                    timezone: "America/New_York".into(),
                    kpis: BTreeMap::new(),
                    budget: Money::zero(CurrencyCode::parse("USD").expect("USD")),
                },
                now(),
            )
            .expect_err("Catalog Mission without KPI must be rejected");
        assert!(matches!(
            missing_kpi,
            ApplicationError::CatalogMissionKpiRequired
        ));

        let missing_parent = service
            .start_catalog_mission(
                StartCatalogMission {
                    id: MissionId::from("missing-parent-vm11"),
                    first_task_id: TaskId::from("missing-parent-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-11".into(),
                    mode: OperatingMode::OneOffDecision,
                    parent_mission_id: None,
                    title: None,
                    goal: "Recompute one source Mission".into(),
                    market: "US".into(),
                    language: "en-US".into(),
                    audience: "owner".into(),
                    timezone: "America/New_York".into(),
                    kpis: catalog_count_kpis(),
                    budget: Money::zero(CurrencyCode::parse("USD").expect("USD")),
                },
                now(),
            )
            .expect_err("VM-11 without parent must be rejected");
        assert!(matches!(
            missing_parent,
            ApplicationError::CatalogMissionParentRequired
        ));
        assert!(
            service.desktop_inventory().expect("inventory").projects[0]
                .missions
                .is_empty()
        );

        let parent_id = MissionId::from("contract-source-parent");
        let parent = start_vm11_parent(
            &mut service,
            &project_id,
            parent_id.clone(),
            "US",
            "en-US",
            "owner",
            "America/New_York",
            Money::zero(CurrencyCode::parse("USD").expect("USD")),
        );
        let inherited_contract_drift = service
            .start_catalog_mission(
                StartCatalogMission {
                    id: MissionId::from("drifted-vm11"),
                    first_task_id: TaskId::from("drifted-vm11-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-11".into(),
                    mode: parent.contract.mode.clone(),
                    parent_mission_id: Some(parent_id.clone()),
                    title: None,
                    goal: "Recompute one source Mission".into(),
                    market: "DE".into(),
                    language: parent.contract.language.clone(),
                    audience: parent.contract.audience.clone(),
                    timezone: parent.contract.timezone.clone(),
                    kpis: parent.contract.kpis.clone(),
                    budget: parent.contract.budget.clone(),
                },
                now(),
            )
            .expect_err("VM-11 cannot silently drift from its parent contract");
        assert!(matches!(
            inherited_contract_drift,
            ApplicationError::CatalogMissionParentContractMismatch
        ));

        let mut stale_catalog_parent = service
            .load_mission(&project_id, &parent_id)
            .expect("parent Mission");
        let expected_parent_revision = stale_catalog_parent.revision;
        stale_catalog_parent
            .definition
            .as_mut()
            .expect("Catalog parent definition")
            .catalog_digest = "0".repeat(64);
        stale_catalog_parent.revision += 1;
        service
            .store
            .update_mission_atomic(
                &stale_catalog_parent,
                expected_parent_revision,
                &[PendingEvent::new(
                    "mission.catalog_revision_rebased",
                    serde_json::json!({
                        "missionId": parent_id,
                        "catalogDigest": "0".repeat(64),
                    }),
                    now(),
                )],
            )
            .expect("persist stale Catalog parent fixture");

        let stale_catalog_parent = service
            .start_catalog_mission(
                StartCatalogMission {
                    id: MissionId::from("stale-catalog-parent-vm11"),
                    first_task_id: TaskId::from("stale-catalog-parent-vm11-task"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-11".into(),
                    mode: parent.contract.mode,
                    parent_mission_id: Some(parent_id),
                    title: None,
                    goal: "Recompute one source Mission".into(),
                    market: parent.contract.market,
                    language: parent.contract.language,
                    audience: parent.contract.audience,
                    timezone: parent.contract.timezone,
                    kpis: parent.contract.kpis,
                    budget: parent.contract.budget,
                },
                now(),
            )
            .expect_err("VM-11 cannot inherit a parent compiled against a stale Catalog");
        assert!(matches!(
            stale_catalog_parent,
            ApplicationError::CatalogMissionParentContractMismatch
        ));
        let missions = service
            .desktop_inventory()
            .expect("inventory after rejection")
            .projects[0]
            .missions
            .clone();
        assert_eq!(missions.len(), 1);
        assert_eq!(missions[0].mission_id.as_str(), "contract-source-parent");
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the contract test covers all twelve Catalog routes and their exact authority, checkpoint, Conversation, privacy, and event projections"
    )]
    fn all_twelve_catalog_missions_compile_exact_authority_and_content_free_events() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("catalog-routing-project");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("catalog-routing-tenant"),
                    id: project_id.clone(),
                    name: "Catalog routing".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");
        let catalog = Catalog::load().expect("catalog");
        let snapshot = catalog.snapshot().expect("snapshot");

        for manifest in &catalog.missions.missions {
            let mode = match manifest.modes.first().map(String::as_str) {
                Some("build_once") => OperatingMode::BuildOnce,
                Some("continuous_operator") => OperatingMode::ContinuousOperator,
                Some("campaign") => OperatingMode::Campaign,
                Some("continuous_relationship") => OperatingMode::ContinuousRelationship,
                Some("one_off_decision") => OperatingMode::OneOffDecision,
                _ => panic!("validated operating mode"),
            };
            let private_goal = format!(
                "PRIVATE-CATALOG-GOAL::{}::operate only inside the confirmed contract",
                manifest.id
            );
            let mission_id = MissionId::from_stable(format!("catalog-mission-{}", manifest.id));
            let parent_mission_id =
                (manifest.id == "VM-11").then(|| MissionId::from_stable("catalog-mission-VM-07"));
            let mission = service
                .start_catalog_mission(
                    StartCatalogMission {
                        id: mission_id.clone(),
                        first_task_id: TaskId::from_stable(format!("catalog-task-{}", manifest.id)),
                        project_id: project_id.clone(),
                        manifest_id: manifest.id.clone(),
                        mode: mode.clone(),
                        parent_mission_id,
                        title: None,
                        goal: private_goal.clone(),
                        market: "DE".into(),
                        language: "de".into(),
                        audience: "confirmed buyers".into(),
                        timezone: "Europe/Berlin".into(),
                        kpis: catalog_count_kpis(),
                        budget: Money::zero(CurrencyCode::parse("EUR").expect("EUR")),
                    },
                    now(),
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "Catalog Mission {} failed to compile: {error:?}",
                        manifest.id
                    )
                });
            let definition = mission.definition.as_ref().expect("definition");
            assert_eq!(
                (
                    definition.manifest_id.as_str(),
                    definition.manifest_version,
                    definition.catalog_digest.as_str(),
                    &definition.operating_mode,
                ),
                (
                    manifest.id.as_str(),
                    manifest.version,
                    snapshot.digest.as_str(),
                    &mode,
                )
            );
            assert_eq!(
                definition.capability_ids,
                manifest.capability_ids.iter().cloned().collect()
            );
            assert_eq!(
                definition.required_artifact_types,
                manifest.required_artifacts.iter().cloned().collect()
            );
            assert_eq!(
                definition.oracle_ids,
                manifest.oracle_ids.iter().cloned().collect()
            );
            assert_eq!(definition.checkpoints.len(), manifest.checkpoint_ids.len());
            assert_eq!(
                definition
                    .checkpoints
                    .iter()
                    .map(|checkpoint| {
                        let route = checkpoint.route.as_ref().expect("Checkpoint route");
                        (
                            checkpoint.id.as_str(),
                            route.capability_id.as_str(),
                            route.executor,
                        )
                    })
                    .collect::<Vec<_>>(),
                manifest
                    .checkpoint_routes
                    .iter()
                    .map(|route| (
                        route.checkpoint_id.as_str(),
                        route.capability_id.as_str(),
                        MissionCheckpointExecutor::try_from(route.executor.as_str())
                            .expect("validated executor"),
                    ))
                    .collect::<Vec<_>>()
            );
            if manifest.id == "VM-08" {
                assert_eq!(manifest.version, 4);
                let first_checkpoint = definition
                    .checkpoints
                    .first()
                    .expect("VM-08 first Checkpoint");
                let first_route = first_checkpoint.route.as_ref().expect("VM-08 first route");
                assert_eq!(
                    (
                        first_checkpoint.id.as_str(),
                        first_checkpoint.status,
                        first_route.capability_id.as_str(),
                        first_route.executor,
                        first_route.completion_policy,
                    ),
                    (
                        "seller_account_market_identity",
                        MissionCheckpointStatus::Running,
                        "marketplace.read",
                        MissionCheckpointExecutor::Runtime,
                        Some(MissionCheckpointCompletionPolicy::WorkProduct),
                    )
                );
                assert_eq!(
                    mission
                        .tasks
                        .first()
                        .map(|task| { (task.capability.as_str(), task.status.clone(),) }),
                    Some(("marketplace.read", TaskStatus::Running))
                );
                let readback_checkpoint = definition
                    .checkpoints
                    .get(7)
                    .expect("VM-08 effect/readback Checkpoint");
                let readback_route = readback_checkpoint
                    .route
                    .as_ref()
                    .expect("VM-08 effect/readback route");
                assert_eq!(
                    (
                        readback_checkpoint.id.as_str(),
                        readback_checkpoint.status,
                        readback_route.capability_id.as_str(),
                        readback_route.executor,
                        readback_route.completion_policy,
                    ),
                    (
                        "listing_write_readback",
                        MissionCheckpointStatus::Pending,
                        "marketplace.write",
                        MissionCheckpointExecutor::EffectBroker,
                        Some(MissionCheckpointCompletionPolicy::EffectReadbackV2),
                    )
                );
            }
            assert_eq!(
                definition
                    .current_checkpoint()
                    .map(|checkpoint| (checkpoint.id.as_str(), checkpoint.status)),
                manifest
                    .checkpoint_ids
                    .first()
                    .map(|checkpoint| (checkpoint.as_str(), MissionCheckpointStatus::Running))
            );
            assert_eq!(
                mission.contract.enabled_capabilities,
                definition.capability_ids
            );
            assert!(
                mission
                    .contract
                    .enabled_capabilities
                    .is_disjoint(&mission.contract.forbidden_capabilities)
            );
            assert_eq!(mission.stage, MissionStage::Running);
            assert_eq!(
                mission.tasks.first().map(|task| task.capability.as_str()),
                manifest
                    .checkpoint_routes
                    .first()
                    .map(|route| route.capability_id.as_str())
            );
            if manifest.id == "VM-10" {
                assert_eq!(
                    mission.tasks.first().map(|task| task.capability.as_str()),
                    Some("webhook.ingest")
                );
                assert_ne!(
                    mission.tasks.first().map(|task| task.capability.as_str()),
                    definition.capability_ids.iter().next().map(String::as_str)
                );
            }
            let conversation = service
                .mission_conversation(&project_id, &mission_id)
                .expect("Catalog Mission Conversation");
            assert_eq!(conversation.revision, 1);
            assert_eq!(conversation.messages.len(), 1);
            assert_eq!(conversation.messages[0].body, private_goal);
            let event_json = serde_json::to_string(
                &service
                    .mission_events(&project_id, &mission_id)
                    .expect("events"),
            )
            .expect("event JSON");
            assert!(!event_json.contains(&private_goal));
            assert!(event_json.contains("mission.catalog_bound"));
            assert!(event_json.contains("mission.checkpoint_started"));
        }

        let projections = service
            .desktop_inventory()
            .expect("inventory")
            .projects
            .into_iter()
            .find(|project| project.project_id == project_id)
            .expect("project")
            .missions;
        assert_eq!(projections.len(), 12);
        assert!(projections.iter().all(|projection| {
            projection.manifest_id.is_some()
                && projection.manifest_version.is_some()
                && projection.catalog_digest.as_deref() == Some(snapshot.digest.as_str())
                && projection.current_checkpoint_id.is_some()
                && projection.current_checkpoint_status == Some(MissionCheckpointStatus::Running)
                && projection.current_checkpoint_capability_id.is_some()
                && projection.current_checkpoint_executor.is_some()
                && projection.completed_checkpoint_count == 0
                && projection.checkpoint_count > 0
                && projection.conversation_revision == Some(1)
                && projection.conversation_messages.len() == 1
                && projection.conversation_messages[0].body.is_empty()
                && projection.title.is_empty()
                && projection.goal.is_empty()
                && projection.outcome_summary.is_none()
        }));
    }

