    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the crash-recovery test proves exact exited-claim cleanup, privacy projection, attempt fencing, a second commit-gap crash, and idempotent replay end to end"
    )]
    fn startup_reconciliation_reconciles_exact_exited_runtime_process_claim() {
        let mut fixture = runtime_recovery_fixture();
        let attached = fixture
            .service
            .context_worker_handle(
                &fixture.project_id,
                &fixture.workspace_id,
                &fixture.worker_id,
            )
            .expect("attached handle");
        let mut detached = attached.clone();
        detached
            .detach(attached.attachment_epoch, now() + Duration::seconds(6))
            .expect("detach worker");
        let checkpoint = fixture
            .service
            .store
            .load_context_checkpoint(
                &fixture.project_id,
                &ContextCheckpointId::from("checkpoint-runtime-recovery"),
            )
            .expect("checkpoint");
        let mut recovery = RuntimeRecoveryAttempt::prepare(
            RuntimeRecoveryAttemptId::from("recovery-runtime-process-orphan"),
            &attached,
            &detached,
            &checkpoint,
            "1".repeat(64),
            RuntimeResumeStrategy::StartNew,
            None,
            3,
            now() + Duration::seconds(6),
        )
        .expect("prepare recovery");
        fixture
            .service
            .store
            .begin_runtime_recovery(
                &detached,
                attached.revision,
                &recovery,
                &[PendingEvent::new(
                    "context.runtime_recovery_prepared",
                    serde_json::json!({"runtimeRecoveryId": recovery.id}),
                    now() + Duration::seconds(6),
                )],
                now() + Duration::seconds(6),
            )
            .expect("persist recovery");

        let program = std::env::current_exe().expect("test executable");
        let mut command = RuntimeCommand::new(
            &program,
            fixture.workspace.path().canonicalize().expect("workspace"),
        );
        command.expected_program_sha256 = Some(sha256(
            &std::fs::read(&program).expect("read test executable"),
        ));
        let launch_token = generate_runtime_launch_token(&command).expect("launch token");
        let launch = prepare_runtime_launch(&command, &launch_token).expect("launch spec");
        let mut claim = RuntimeProcessClaim::prepare(
            &recovery,
            launch.program_sha256().to_owned(),
            launch_token.clone(),
            launch.executable_path().to_string_lossy().into_owned(),
            launch.executable_path_digest().to_owned(),
            now() + Duration::seconds(7),
        )
        .expect("prepare process claim");
        fixture
            .service
            .store
            .prepare_runtime_process_claim(
                &claim,
                &[PendingEvent::new(
                    "context.runtime_process_launch_prepared",
                    serde_json::json!({
                        "runtimeRecoveryId": recovery.id,
                        "launchTokenDigest": claim.launch_token_digest,
                        "launchExecutablePathDigest": claim.launch_executable_path_digest,
                    }),
                    now() + Duration::seconds(7),
                )],
                now() + Duration::seconds(7),
            )
            .expect("persist process claim");
        let expected_recovery_revision = recovery.revision;
        let expected_claim_revision = claim.revision;
        recovery
            .mark_spawned("2".repeat(64), now() + Duration::seconds(8))
            .expect("mark recovery spawned");
        claim
            .mark_spawned(
                RuntimeProcessIdentity {
                    process_id: u32::MAX,
                    started_at_epoch_seconds: 1,
                    executable_path_digest: launch.executable_path_digest().to_owned(),
                    runtime_instance_digest: "2".repeat(64),
                },
                now() + Duration::seconds(8),
            )
            .expect("mark claim spawned");
        fixture
            .service
            .store
            .mark_runtime_process_spawned(
                &recovery,
                expected_recovery_revision,
                &claim,
                expected_claim_revision,
                &[PendingEvent::new(
                    "context.runtime_recovery_spawned",
                    serde_json::json!({
                        "runtimeRecoveryId": recovery.id,
                        "launchTokenDigest": claim.launch_token_digest,
                    }),
                    now() + Duration::seconds(8),
                )],
                now() + Duration::seconds(8),
            )
            .expect("persist spawned process");
        let active_projection = fixture
            .service
            .desktop_runtime_activity()
            .expect("active process projection")
            .into_iter()
            .find(|activity| activity.mission_id == fixture.mission_id)
            .expect("Mission process projection");
        assert_eq!(
            active_projection.process_claim_status,
            Some(RuntimeProcessClaimStatus::Spawned)
        );
        assert_eq!(active_projection.process_cleanup_attempt_count, 0);
        assert!(active_projection.requires_reconciliation);
        let projection_json = serde_json::to_string(&active_projection).expect("projection JSON");
        assert!(!projection_json.contains(&launch_token));
        assert!(!projection_json.contains(launch.executable_path().to_string_lossy().as_ref()));

        let RuntimeRecoveryFixture {
            service,
            workspace,
            project_id,
            mission_id,
            ..
        } = fixture;
        let mut restarted = ApplicationService::new(service.store);
        let report = restarted
            .reconcile_runtime_processes_on_startup(now() + Duration::seconds(9))
            .expect("reconcile exact exited claim");
        assert_eq!(report.scanned_claims, 1);
        assert_eq!(report.terminated, 0);
        assert_eq!(report.already_exited, 1);
        assert_eq!(report.blocked, 0);
        assert_eq!(report.recovery_attempts_fenced, 1);
        let cleaned = restarted
            .store
            .load_runtime_process_claim(&project_id, &recovery.id, recovery.process_attempt)
            .expect("cleaned claim");
        assert_eq!(cleaned.status, RuntimeProcessClaimStatus::Exited);
        assert!(!launch.executable_path().exists());
        let cleaned_projection = restarted
            .desktop_runtime_activity()
            .expect("cleaned process projection")
            .into_iter()
            .find(|activity| activity.mission_id == mission_id)
            .expect("cleaned Mission projection");
        assert_eq!(
            cleaned_projection.process_claim_status,
            Some(RuntimeProcessClaimStatus::Exited)
        );
        assert_eq!(cleaned_projection.process_cleanup_attempt_count, 1);
        assert!(!cleaned_projection.requires_reconciliation);
        let fenced_recovery = restarted
            .store
            .load_runtime_recovery(&project_id, &recovery.id)
            .expect("fenced recovery");
        assert_eq!(fenced_recovery.status, RuntimeRecoveryStatus::Prepared);
        assert_eq!(fenced_recovery.process_attempt, 2);
        assert_eq!(fenced_recovery.failures.len(), 1);
        assert_eq!(
            fenced_recovery.failures[0].class,
            RuntimeRecoveryFailureClass::CoordinatorRestart
        );
        let events = serde_json::to_string(
            &restarted
                .mission_events(&project_id, &mission_id)
                .expect("events"),
        )
        .expect("event json");
        assert!(!events.contains(&launch_token));
        assert!(!events.contains(launch.executable_path().to_string_lossy().as_ref()));
        let terminal_launch_token = "7".repeat(64);
        let terminal_launch_path = workspace
            .path()
            .join(sha256(terminal_launch_token.as_bytes()))
            .join("interpreter")
            .to_string_lossy()
            .into_owned();
        let mut terminal_claim = RuntimeProcessClaim::prepare(
            &fenced_recovery,
            "8".repeat(64),
            terminal_launch_token.clone(),
            terminal_launch_path.clone(),
            sha256(terminal_launch_path.as_bytes()),
            now() + Duration::seconds(10),
        )
        .expect("prepare second process claim");
        restarted
            .store
            .prepare_runtime_process_claim(
                &terminal_claim,
                &[PendingEvent::new(
                    "context.runtime_process_launch_prepared",
                    serde_json::json!({
                        "runtimeRecoveryId": fenced_recovery.id,
                        "launchTokenDigest": terminal_claim.launch_token_digest,
                    }),
                    now() + Duration::seconds(10),
                )],
                now() + Duration::seconds(10),
            )
            .expect("persist second Claim");
        let terminal_expected_revision = terminal_claim.revision;
        terminal_claim
            .record_cleanup(
                RuntimeProcessCleanupDisposition::AlreadyExited,
                "9".repeat(64),
                now() + Duration::seconds(11),
            )
            .expect("persisted cleanup before Recovery accounting");
        restarted
            .store
            .update_runtime_process_claim(
                &terminal_claim,
                terminal_expected_revision,
                &[PendingEvent::new(
                    "context.runtime_process_reconciled",
                    serde_json::json!({
                        "runtimeRecoveryId": fenced_recovery.id,
                        "cleanupEvidenceDigest": "9".repeat(64),
                    }),
                    now() + Duration::seconds(11),
                )],
                now() + Duration::seconds(11),
            )
            .expect("commit Claim cleanup before simulated crash");

        let mut repaired = ApplicationService::new(restarted.store);
        let repaired_report = repaired
            .reconcile_runtime_processes_on_startup(now() + Duration::seconds(12))
            .expect("repair terminal Claim / active Recovery crash window");
        assert_eq!(repaired_report.scanned_claims, 1);
        assert_eq!(repaired_report.recovery_attempts_fenced, 1);
        assert_eq!(repaired_report.terminated, 0);
        assert_eq!(repaired_report.already_exited, 0);
        assert_eq!(repaired_report.blocked, 0);
        let repaired_recovery = repaired
            .store
            .load_runtime_recovery(&project_id, &recovery.id)
            .expect("repaired recovery");
        assert_eq!(repaired_recovery.status, RuntimeRecoveryStatus::Prepared);
        assert_eq!(repaired_recovery.process_attempt, 3);
        assert_eq!(repaired_recovery.failures.len(), 2);
        let repaired_events = serde_json::to_string(
            &repaired
                .mission_events(&project_id, &mission_id)
                .expect("repaired events"),
        )
        .expect("repaired event JSON");
        assert!(!repaired_events.contains(&terminal_launch_token));
        assert!(!repaired_events.contains(&terminal_launch_path));

        let replay = repaired
            .reconcile_runtime_processes_on_startup(now() + Duration::seconds(13))
            .expect("idempotent process reconciliation");
        assert_eq!(replay.scanned_claims, 0);
        repaired
            .reconcile_runtime_turns_on_startup(now() + Duration::seconds(13))
            .expect("turn reconciliation follows process cleanup");
        drop(workspace);
    }

    #[cfg(unix)]
    struct RuntimeContextResolver {
        calls: std::cell::Cell<usize>,
    }

    #[cfg(unix)]
    impl ContextMaterialResolver for RuntimeContextResolver {
        fn resolve(
            &self,
            reference: &ContextMaterialReference,
        ) -> Result<Option<ResolvedContextMaterial>, ContextAssemblyError> {
            self.calls.set(self.calls.get() + 1);
            Ok((reference.storage_ref
                == format!("cas://{}", sha256(RUNTIME_CONTEXT_SUMMARY.as_bytes())))
            .then(|| ResolvedContextMaterial::text(RUNTIME_CONTEXT_SUMMARY)))
        }
    }

    #[cfg(unix)]
    fn runtime_context_material_store(
        fixture: &RuntimeRecoveryFixture,
    ) -> LocalEncryptedContextMaterialStore {
        let store = LocalEncryptedContextMaterialStore::new(
            fixture.workspace.path(),
            fixture.tenant_id.clone(),
            fixture.project_id.clone(),
            1,
            KeyMaterial::from_bytes([17; 32]).expect("fixture project content key"),
        )
        .expect("project-scoped encrypted context CAS");
        let descriptor = store
            .put_text(RUNTIME_CONTEXT_SUMMARY)
            .expect("encrypted runtime summary");
        assert_eq!(
            descriptor.storage_ref,
            format!("cas://{}", sha256(RUNTIME_CONTEXT_SUMMARY.as_bytes()))
        );
        let record = std::fs::read(
            fixture
                .workspace
                .path()
                .join(".hartevo/context-material")
                .join(&descriptor.content_digest[..2])
                .join(format!("{}.hctx", descriptor.content_digest)),
        )
        .expect("encrypted context CAS record");
        assert!(
            !record
                .windows(RUNTIME_CONTEXT_SUMMARY.len())
                .any(|window| window == RUNTIME_CONTEXT_SUMMARY.as_bytes())
        );
        store
    }

    #[cfg(unix)]
    fn runtime_context_tokenizer() -> PinnedModelTokenizer {
        runtime_context_tokenizer_for("fixture-provider", "fixture-model")
    }

    #[cfg(unix)]
    fn runtime_context_tokenizer_for(provider: &str, model: &str) -> PinnedModelTokenizer {
        let bytes = RUNTIME_TOKENIZER_JSON.as_bytes();
        PinnedModelTokenizer::from_json_bytes(
            &PinnedTokenizerSpec {
                provider: provider.into(),
                model: model.into(),
                model_revision: "fixture-revision-v1".into(),
                expected_artifact_digest: sha256(bytes),
                add_special_tokens: false,
                request_overhead_tokens: 3,
                max_input_bytes: 100_000,
            },
            bytes,
        )
        .expect("digest-pinned runtime tokenizer")
    }

    #[cfg(unix)]
    fn assert_failed_generation_retirement_is_truthful(
        fixture: &mut RuntimeRecoveryFixture,
        retired: &RetiredContextRuntimeGeneration,
    ) {
        assert_eq!(retired.retired_generation, 7);
        assert_eq!(retired.next_generation, 8);
        assert_eq!(retired.branch_status, ContextBranchStatus::Abandoned);
        assert_eq!(retired.lease_status, WorkerLeaseStatus::Revoked);
        assert_eq!(retired.capsule_status, ContextCapsuleStatus::Cancelled);
        assert_eq!(retired.handle_status, WorkerHandleStatus::Cancelled);
        let terminal_handle = fixture
            .service
            .context_worker_handle(
                &fixture.project_id,
                &fixture.workspace_id,
                &fixture.worker_id,
            )
            .expect("terminal handle");
        assert_eq!(terminal_handle.status, WorkerHandleStatus::Cancelled);
        assert!(matches!(
            fixture.service.reattach_context_worker(
                ReattachContextWorker {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    worker_id: fixture.worker_id.clone(),
                    expected_handle_revision: terminal_handle.revision,
                    expected_mailbox_revision: 1,
                    attachment_epoch: terminal_handle.attachment_epoch,
                    runtime_mapping_digest: "c".repeat(64),
                },
                now() + Duration::seconds(5),
            ),
            Err(ApplicationError::Context(_))
        ));
        let mission = fixture
            .service
            .load_mission(&fixture.project_id, &fixture.mission_id)
            .expect("Mission remains truthful");
        assert_eq!(mission.stage, MissionStage::Running);
        assert!(mission.work_products.is_empty());
        assert!(mission.effects.is_empty());
        let events = fixture
            .service
            .mission_events(&fixture.project_id, &fixture.mission_id)
            .expect("retirement events");
        assert_eq!(
            events
                .iter()
                .filter(|event| event.event_type == "context.runtime_generation_retired")
                .count(),
            1
        );
        let event_json = serde_json::to_string(&events).expect("event JSON");
        assert!(!event_json.contains("/usr/bin/false"));
    }

    #[cfg(unix)]
    #[test]
    fn exhausted_runtime_recovery_atomically_retires_authority_without_fake_completion() {
        let mut fixture = runtime_recovery_fixture();
        let recovery_id = RuntimeRecoveryAttemptId::from("recovery-exhausted-retirement");
        let mut command = RuntimeCommand::new(
            PathBuf::from("/usr/bin/false"),
            fixture
                .workspace
                .path()
                .canonicalize()
                .expect("canonical workspace"),
        );
        command.shutdown_grace = StdDuration::from_millis(20);
        let failed = fixture.service.recover_context_worker_runtime(
            RecoverContextWorkerRuntime {
                id: recovery_id.clone(),
                project_id: fixture.project_id.clone(),
                workspace_id: fixture.workspace_id.clone(),
                worker_id: fixture.worker_id.clone(),
                expected_handle_revision: 1,
                expected_mailbox_revision: 1,
                attachment_epoch: 1,
                strategy: RuntimeResumeStrategy::StartNew,
                resume_thread_id: None,
                model: Some("fixture-model".into()),
                max_process_attempts: 1,
                health_timeout: StdDuration::from_millis(100),
                thread_timeout: StdDuration::from_millis(100),
            },
            &command,
            now() + Duration::seconds(3),
        );
        assert!(matches!(failed, Err(ApplicationError::Runtime(_))));
        let recovery = fixture
            .service
            .runtime_recovery_attempt(&fixture.project_id, &recovery_id)
            .expect("durable failed recovery");
        assert_eq!(recovery.status, RuntimeRecoveryStatus::Failed);
        assert_eq!(recovery.failures.len(), 1);
        let latest = fixture
            .service
            .latest_runtime_recovery_for_mission(&fixture.project_id, &fixture.mission_id)
            .expect("latest Mission recovery")
            .expect("failed recovery");
        assert_eq!(latest.id, recovery_id);
        assert!(
            fixture
                .service
                .latest_runtime_turn_for_mission(&fixture.project_id, &fixture.mission_id)
                .expect("latest Mission turn")
                .is_none()
        );

        let retirement = EnsureFailedLocalMissionRuntimeGenerationRetired {
            project_id: fixture.project_id.clone(),
            mission_id: fixture.mission_id.clone(),
            recovery_id: recovery_id.clone(),
            expected_recovery_revision: recovery.revision,
        };
        let retired = fixture
            .service
            .ensure_failed_local_mission_runtime_generation_retired(
                &retirement,
                now() + Duration::seconds(4),
            )
            .expect("atomic failed-generation retirement");
        let replay = fixture
            .service
            .ensure_failed_local_mission_runtime_generation_retired(
                &retirement,
                now() + Duration::seconds(5),
            )
            .expect("idempotent failed-generation retirement replay");
        assert_eq!(replay, retired);
        assert_failed_generation_retirement_is_truthful(&mut fixture, &retired);
    }

    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the journey proves pre-resolution revision fencing, transient content, redacted persistence, audit shape, and later-time idempotent replay"
    )]
    fn application_assembles_transient_context_and_persists_only_exact_redacted_manifest() {
        let mut fixture = runtime_recovery_fixture();
        let capsule = fixture
            .service
            .claim_context_capsule(
                &fixture.project_id,
                &ContextCapsuleId::from("capsule-runtime-recovery"),
                1,
                7,
                now() + Duration::seconds(3),
            )
            .expect("claimed capsule");
        let resolver = RuntimeContextResolver {
            calls: std::cell::Cell::new(0),
        };
        let tokenizer = runtime_context_tokenizer();
        let command = AssembleRuntimeContext {
            id: ContextAssemblyId::from("assembly-runtime-recovery"),
            project_id: fixture.project_id.clone(),
            workspace_id: fixture.workspace_id.clone(),
            capsule_id: capsule.id.clone(),
            expected_capsule_revision: capsule.revision,
            expected_branch_revision: 1,
            expected_worker_lease_revision: 1,
            expected_checkpoint_id: ContextCheckpointId::from("checkpoint-runtime-recovery"),
            foundation_sync_version: 2,
            policy: ContextAssemblyPolicy {
                version: 1,
                max_prompt_tokens: 1_500,
                reserved_output_tokens: 400,
                max_prompt_bytes: 100_000,
                max_optional_frames: 8,
                max_gap_records: 16,
            },
        };
        let mut stale = command.clone();
        stale.expected_capsule_revision -= 1;
        assert!(matches!(
            fixture.service.assemble_runtime_context(
                stale,
                &resolver,
                &tokenizer,
                now() + Duration::seconds(4),
            ),
            Err(ApplicationError::ContextCapsuleRevisionMismatch { .. })
        ));
        assert_eq!(resolver.calls.get(), 0);

        let material_store = runtime_context_material_store(&fixture);

        let outcome = fixture
            .service
            .assemble_runtime_context(
                command.clone(),
                &material_store,
                &tokenizer,
                now() + Duration::seconds(4),
            )
            .expect("assembled context");
        assert_eq!(outcome.manifest.status, ContextAssemblyStatus::Ready);
        let envelope = outcome.envelope.as_ref().expect("transient envelope");
        assert!(
            envelope
                .render_prompt()
                .expect("prompt")
                .contains(RUNTIME_CONTEXT_SUMMARY)
        );
        assert!(!format!("{outcome:?}").contains(RUNTIME_CONTEXT_SUMMARY));
        let persisted = fixture
            .service
            .load_context_assembly_manifest(&fixture.project_id, &command.id)
            .expect("durable manifest");
        assert_eq!(persisted, outcome.manifest);
        assert_eq!(persisted.capsule_revision, capsule.revision);
        assert_eq!(persisted.worker_lease_revision, 1);
        let persisted_json = serde_json::to_string(&persisted).expect("manifest json");
        assert!(!persisted_json.contains(RUNTIME_CONTEXT_SUMMARY));
        let events = fixture
            .service
            .mission_events(&fixture.project_id, &fixture.mission_id)
            .expect("context events");
        let assembly_events = events
            .iter()
            .filter(|event| event.event_type == "context.assembly_recorded")
            .collect::<Vec<_>>();
        assert_eq!(assembly_events.len(), 1);
        assert!(
            !serde_json::to_string(&assembly_events)
                .expect("event json")
                .contains(RUNTIME_CONTEXT_SUMMARY)
        );

        let replay = fixture
            .service
            .assemble_runtime_context(
                command,
                &material_store,
                &tokenizer,
                now() + Duration::seconds(5),
            )
            .expect("idempotent replay at a later wall-clock time");
        assert_eq!(replay.manifest, persisted);
        assert_eq!(
            fixture
                .service
                .mission_events(&fixture.project_id, &fixture.mission_id)
                .expect("events after replay")
                .iter()
                .filter(|event| event.event_type == "context.assembly_recorded")
                .count(),
            1
        );
    }

    #[cfg(unix)]
    fn delayed_fake_runtime_command(
        workspace: &Path,
        thread_id: &str,
        delay_seconds: &str,
    ) -> RuntimeCommand {
        let canonical_workspace = workspace.canonicalize().expect("canonical workspace");
        let initialize_response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "result": {}
        })
        .to_string();
        let thread_response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 2,
            "result": {
                "thread": {"id": thread_id},
                "cwd": canonical_workspace,
                "model": "fixture-model",
                "modelProvider": "fixture-provider",
                "approvalPolicy": "on-request",
                "approvalsReviewer": "user",
                "sandbox": "workspace-write"
            }
        })
        .to_string();
        let mut command = RuntimeCommand::new(PathBuf::from("/bin/sh"), canonical_workspace);
        command.args = vec![
            "-c".into(),
            "sleep \"$1\"; IFS= read -r _; printf '%s\\n' \"$2\"; IFS= read -r _; printf '%s\\n' \"$3\"; sleep 30".into(),
            "hartevo-fake-runtime".into(),
            delay_seconds.into(),
            initialize_response,
            thread_response,
        ];
        command.shutdown_grace = StdDuration::from_millis(50);
        command
    }

    #[cfg(unix)]
    fn checkpoint_bound_health_timeout_runtime_command(
        workspace: &Path,
        thread_id: &str,
    ) -> RuntimeCommand {
        let canonical_workspace = workspace.canonicalize().expect("canonical workspace");
        let first_process_marker = workspace.join(".hartevo-first-health-timeout");
        let initialize_response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "result": {}
        })
        .to_string();
        let thread_response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 2,
            "result": {
                "thread": {"id": thread_id},
                "cwd": canonical_workspace,
                "model": "fixture-model",
                "modelProvider": "fixture-provider",
                "approvalPolicy": "on-request",
                "approvalsReviewer": "user",
                "sandbox": "workspace-write"
            }
        })
        .to_string();
        let mut command = RuntimeCommand::new(PathBuf::from("/bin/sh"), canonical_workspace);
        command.args = vec![
            "-c".into(),
            "IFS= read -r _
if (set -C; : > \"$1\") 2>/dev/null; then
  IFS= read -r _
else
  printf '%s\\n' \"$2\"
  IFS= read -r _
  printf '%s\\n' \"$3\"
  sleep 30
fi"
            .into(),
            "hartevo-checkpoint-bound-runtime".into(),
            first_process_marker.to_string_lossy().into_owned(),
            initialize_response,
            thread_response,
        ];
        command
            .environment
            .insert("PATH".into(), "/usr/bin:/bin".into());
        command.shutdown_grace = StdDuration::from_millis(50);
        command
    }

