    #[cfg(unix)]
    fn turn_dispatch_fault_runtime_command(
        workspace: &Path,
        thread_id: &str,
        turn_response: Option<serde_json::Value>,
    ) -> RuntimeCommand {
        let canonical_workspace = workspace.canonicalize().expect("canonical workspace");
        let initialize_response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "result": {}
        })
        .to_string();
        let thread_response = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 2,
            "result": {
                "thread": {"id": thread_id},
                "cwd": canonical_workspace,
                "model": "fixture-model",
                "modelProvider": "fixture-provider",
                "approvalPolicy": "on-request",
                "approvalsReviewer": "user",
                "sandbox": "workspace-write"
            }
        })
        .to_string();
        let mut command = RuntimeCommand::new(PathBuf::from("/bin/sh"), canonical_workspace);
        command.args = if let Some(response) = turn_response {
            vec![
                "-c".into(),
                "IFS= read -r _; printf '%s\\n' \"$1\"; IFS= read -r _; printf '%s\\n' \"$2\"; IFS= read -r _; printf '%s\\n' \"$3\"; sleep 30".into(),
                "hartevo-fake-runtime".into(),
                initialize_response,
                thread_response,
                response.to_string(),
            ]
        } else {
            vec![
                "-c".into(),
                "IFS= read -r _; printf '%s\\n' \"$1\"; IFS= read -r _; printf '%s\\n' \"$2\"; IFS= read -r _; sleep 30".into(),
                "hartevo-fake-runtime".into(),
                initialize_response,
                thread_response,
            ]
        };
        command.shutdown_grace = StdDuration::from_millis(50);
        command
    }

    #[cfg(unix)]
    struct ReadyRuntimeTurnFixture {
        fixture: RuntimeRecoveryFixture,
        manifest: hartevo_context_fabric::ContextAssemblyManifest,
        envelope: RuntimeContextEnvelope,
        managed: ManagedContextRuntime,
    }

    #[cfg(unix)]
    fn ready_runtime_turn_fixture(
        runtime_command: impl FnOnce(&Path) -> RuntimeCommand,
    ) -> ReadyRuntimeTurnFixture {
        ready_runtime_turn_fixture_with_tokenizer(runtime_command, &runtime_context_tokenizer())
    }

    #[cfg(unix)]
    #[allow(
        clippy::too_many_lines,
        reason = "the fixture establishes the exact durable assembly and attached Runtime authority closure shared by tokenizer and dispatch fault replays"
    )]
    fn ready_runtime_turn_fixture_with_tokenizer(
        runtime_command: impl FnOnce(&Path) -> RuntimeCommand,
        tokenizer: &PinnedModelTokenizer,
    ) -> ReadyRuntimeTurnFixture {
        let mut fixture = runtime_recovery_fixture();
        let capsule = fixture
            .service
            .claim_context_capsule(
                &fixture.project_id,
                &ContextCapsuleId::from("capsule-runtime-recovery"),
                1,
                7,
                now() + Duration::seconds(3),
            )
            .expect("claimed capsule");
        let material_store = runtime_context_material_store(&fixture);
        let assembly = fixture
            .service
            .assemble_runtime_context(
                AssembleRuntimeContext {
                    id: ContextAssemblyId::from("assembly-runtime-turn-fault"),
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    capsule_id: capsule.id,
                    expected_capsule_revision: capsule.revision,
                    expected_branch_revision: 1,
                    expected_worker_lease_revision: 1,
                    expected_checkpoint_id: ContextCheckpointId::from(
                        "checkpoint-runtime-recovery",
                    ),
                    foundation_sync_version: 2,
                    policy: ContextAssemblyPolicy {
                        version: 1,
                        max_prompt_tokens: 1_500,
                        reserved_output_tokens: 400,
                        max_prompt_bytes: 100_000,
                        max_optional_frames: 8,
                        max_gap_records: 16,
                    },
                },
                &material_store,
                tokenizer,
                now() + Duration::seconds(4),
            )
            .expect("runtime assembly");
        let command = runtime_command(fixture.workspace.path());
        let managed = fixture
            .service
            .recover_context_worker_runtime(
                RecoverContextWorkerRuntime {
                    id: RuntimeRecoveryAttemptId::from("recovery-runtime-turn-fault"),
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    worker_id: fixture.worker_id.clone(),
                    expected_handle_revision: 1,
                    expected_mailbox_revision: 1,
                    attachment_epoch: 1,
                    strategy: RuntimeResumeStrategy::StartNew,
                    resume_thread_id: None,
                    model: Some(tokenizer.tokenizer_profile().model.clone()),
                    max_process_attempts: 2,
                    health_timeout: StdDuration::from_secs(1),
                    thread_timeout: StdDuration::from_secs(1),
                },
                &command,
                now() + Duration::seconds(5),
            )
            .expect("managed runtime");
        ReadyRuntimeTurnFixture {
            fixture,
            manifest: assembly.manifest,
            envelope: assembly.envelope.expect("transient envelope"),
            managed,
        }
    }

    #[cfg(unix)]
