    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one replay contrasts definitive rejection with the write-after-send timeout boundary and proves active-turn fencing"
    )]
    fn runtime_turn_rejection_is_failed_but_post_write_timeout_is_never_replayed() {
        let mut rejected = ready_runtime_turn_fixture(|workspace| {
            turn_dispatch_fault_runtime_command(
                workspace,
                "private-runtime-thread-rejected",
                Some(serde_json::json!({
                    "jsonrpc": "2.0",
                    "id": 3,
                    "error": {"code": -32001, "message": "PRIVATE-REJECTION"}
                })),
            )
        });
        let rejected_command = dispatch_command(
            &rejected,
            "turn-attempt-rejected",
            StdDuration::from_secs(1),
        );
        let rejected_outcome = rejected
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut rejected.managed,
                rejected_command,
                &rejected.envelope,
                now() + Duration::seconds(6),
            )
            .expect("durable rejection");
        assert_eq!(
            rejected_outcome.disposition,
            RuntimeTurnDispatchDisposition::Failed
        );
        assert_eq!(rejected_outcome.attempt.status, RuntimeTurnStatus::Failed);
        assert_eq!(
            rejected_outcome.attempt.failures[0].class,
            RuntimeTurnFailureClass::DispatchRejected
        );
        assert!(
            rejected
                .fixture
                .service
                .store
                .load_active_runtime_turn_for_worker(
                    &rejected.fixture.project_id,
                    &rejected.fixture.workspace_id,
                    &rejected.fixture.worker_id,
                )
                .expect("active query")
                .is_none()
        );
        assert!(
            rejected
                .managed
                .runtime
                .shutdown()
                .expect("shutdown")
                .forced
        );

        let mut uncertain = ready_runtime_turn_fixture(|workspace| {
            turn_dispatch_fault_runtime_command(workspace, "private-runtime-thread-timeout", None)
        });
        let uncertain_command = dispatch_command(
            &uncertain,
            "turn-attempt-timeout",
            StdDuration::from_millis(20),
        );
        let uncertain_outcome = uncertain
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut uncertain.managed,
                uncertain_command,
                &uncertain.envelope,
                now() + Duration::seconds(6),
            )
            .expect("durable uncertainty");
        assert_eq!(
            uncertain_outcome.disposition,
            RuntimeTurnDispatchDisposition::Uncertain
        );
        assert_eq!(
            uncertain_outcome.attempt.status,
            RuntimeTurnStatus::Uncertain
        );
        assert_eq!(
            uncertain_outcome.attempt.failures[0].class,
            RuntimeTurnFailureClass::DispatchUncertain
        );
        let uncertain_permit = uncertain
            .managed
            .scheduler_permit
            .clone()
            .expect("uncertain permit");
        assert!(matches!(
            uncertain
                .managed
                .scheduler_gate
                .require_current_permit(&uncertain_permit),
            Err(RuntimeSchedulerError::UncertainReplaySuppressed)
        ));
        let second_command = dispatch_command(
            &uncertain,
            "turn-attempt-forbidden-replay",
            StdDuration::from_millis(20),
        );
        assert!(matches!(
            uncertain.fixture.service.dispatch_context_runtime_turn(
                &mut uncertain.managed,
                second_command,
                &uncertain.envelope,
                now() + Duration::seconds(7),
            ),
            Err(ApplicationError::RuntimeTurnAlreadyActive)
        ));
        let fenced = uncertain
            .fixture
            .service
            .fence_orphaned_context_runtime_turn(
                &FenceOrphanedContextRuntimeTurn {
                    project_id: uncertain.fixture.project_id.clone(),
                    id: uncertain_outcome.attempt.id.clone(),
                    expected_revision: uncertain_outcome.attempt.revision,
                },
                now() + Duration::seconds(8),
            )
            .expect("uncertain fence is idempotent");
        assert_eq!(fenced, uncertain_outcome.attempt);
        assert!(
            uncertain
                .managed
                .runtime
                .shutdown()
                .expect("shutdown")
                .forced
        );
    }

    #[cfg(unix)]
    #[test]
    fn compaction_runtime_turn_is_recoverable_but_never_a_mission_draft() {
        let prompt = "PRIVATE CORDIS COMPACTION INPUT";
        let mut ready = ready_runtime_turn_fixture(|workspace| {
            completed_stream_fake_runtime_command(
                workspace,
                "private-runtime-thread-compaction",
                "private-runtime-turn-compaction",
                "PRIVATE-COMPACTION-SUMMARY",
                "PRIVATE-COMPACTION-SUMMARY",
            )
        });
        let turn_id = RuntimeTurnAttemptId::from("turn-attempt-cordis-compaction");
        let command = dispatch_command(&ready, turn_id.as_str(), StdDuration::from_secs(1));
        let dispatch = ready
            .fixture
            .service
            .dispatch_context_runtime_compaction_turn(
                &mut ready.managed,
                command,
                prompt,
                now() + Duration::seconds(6),
            )
            .expect("compaction dispatch");
        assert_eq!(
            dispatch.attempt.scope.purpose,
            RuntimeTurnPurpose::Compaction
        );
        assert_eq!(
            dispatch.attempt.scope.prompt_digest,
            sha256(prompt.as_bytes())
        );
        assert!(
            ready
                .fixture
                .service
                .latest_runtime_turn_for_mission(
                    &ready.fixture.project_id,
                    &ready.fixture.mission_id,
                )
                .expect("ordinary Agent turn query")
                .is_none()
        );

        let mut revision = dispatch.attempt.revision;
        for index in 0..5 {
            let observation = ready
                .fixture
                .service
                .observe_context_runtime_turn(
                    &mut ready.managed,
                    &ObserveContextRuntimeTurn {
                        project_id: ready.fixture.project_id.clone(),
                        id: turn_id.clone(),
                        expected_revision: revision,
                        event_timeout: StdDuration::from_secs(1),
                    },
                    now() + Duration::seconds(7 + index),
                )
                .expect("compaction observation");
            revision = observation.attempt.revision;
        }
        let completed = ready
            .fixture
            .service
            .runtime_turn_attempt(&ready.fixture.project_id, &turn_id)
            .expect("completed compaction turn");
        assert_eq!(completed.status, RuntimeTurnStatus::Completed);
        assert!(matches!(
            ready.fixture.service.adopt_runtime_turn_draft(
                &AdoptRuntimeTurnDraft {
                    project_id: ready.fixture.project_id.clone(),
                    mission_id: ready.fixture.mission_id.clone(),
                    runtime_turn_attempt_id: turn_id,
                    expected_conversation_revision: 1,
                },
                now() + Duration::seconds(13),
            ),
            Err(ApplicationError::RuntimeDraftScopeMismatch)
        ));
        ready
            .fixture
            .service
            .shutdown_managed_context_runtime(ready.managed, now() + Duration::seconds(14))
            .expect("bounded compaction shutdown");
    }

    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one replay proves stale, taken-over, uncertain, completed, and fresh-retry permit fencing"
    )]
    fn runtime_turn_requires_a_current_scheduler_permit_and_retries_only_with_a_fresh_one() {
        let mut rejected = ready_runtime_turn_fixture(|workspace| {
            turn_dispatch_fault_runtime_command(
                workspace,
                "private-runtime-thread-scheduler-rejected",
                Some(serde_json::json!({
                    "jsonrpc": "2.0",
                    "id": 3,
                    "error": {"code": -32001, "message": "PRIVATE-REJECTION"}
                })),
            )
        });
        let rejected_command = dispatch_command(
            &rejected,
            "turn-attempt-scheduler-rejected",
            StdDuration::from_secs(1),
        );
        let rejected_outcome = rejected
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut rejected.managed,
                rejected_command,
                &rejected.envelope,
                now() + Duration::seconds(6),
            )
            .expect("durable rejection");
        assert_eq!(
            rejected_outcome.disposition,
            RuntimeTurnDispatchDisposition::Failed
        );
        let stale_permit = rejected
            .managed
            .scheduler_permit
            .clone()
            .expect("failed dispatch keeps the consumed permit until retry");
        assert!(matches!(
            rejected
                .managed
                .scheduler_gate
                .require_current_permit(&stale_permit),
            Err(RuntimeSchedulerError::AttemptPermitLost)
        ));
        let mapping = rejected.managed.scheduler_gate.binding().mapping().clone();
        let retry_permit = rejected
            .managed
            .scheduler_gate
            .authorize_turn(stale_permit.attempt_id_digest(), &mapping)
            .expect("failed retry uses a fresh permit only");
        assert_ne!(stale_permit, retry_permit);
        assert!(matches!(
            rejected
                .managed
                .scheduler_gate
                .require_current_permit(&stale_permit),
            Err(RuntimeSchedulerError::AttemptPermitLost)
        ));
        rejected
            .managed
            .scheduler_gate
            .require_current_permit(&retry_permit)
            .expect("fresh permit is current");
        rejected
            .managed
            .scheduler_gate
            .record_failed(&retry_permit)
            .expect("close fresh permit");
        assert!(
            rejected
                .managed
                .runtime
                .shutdown()
                .expect("shutdown")
                .forced
        );

        let mut completed = ready_runtime_turn_fixture(|workspace| {
            completed_stream_fake_runtime_command(
                workspace,
                "private-runtime-thread-scheduler-complete",
                "private-runtime-turn-scheduler-complete",
                "PRIVATE-SCHEDULER-COMPLETE",
                "PRIVATE-SCHEDULER-COMPLETE",
            )
        });
        let completed_turn_id = RuntimeTurnAttemptId::from("turn-attempt-scheduler-complete");
        let completed_command = dispatch_command(
            &completed,
            completed_turn_id.as_str(),
            StdDuration::from_secs(1),
        );
        let dispatch = completed
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut completed.managed,
                completed_command,
                &completed.envelope,
                now() + Duration::seconds(6),
            )
            .expect("completed stream dispatch");
        let current_permit = completed
            .managed
            .scheduler_permit
            .clone()
            .expect("running permit");
        completed
            .managed
            .scheduler_gate
            .require_current_permit(&current_permit)
            .expect("running permit is current");
        let mut revision = dispatch.attempt.revision;
        for index in 0..5 {
            let observation = completed
                .fixture
                .service
                .observe_context_runtime_turn(
                    &mut completed.managed,
                    &ObserveContextRuntimeTurn {
                        project_id: completed.fixture.project_id.clone(),
                        id: completed_turn_id.clone(),
                        expected_revision: revision,
                        event_timeout: StdDuration::from_secs(1),
                    },
                    now() + Duration::seconds(7 + index),
                )
                .expect("completed stream observation");
            revision = observation.attempt.revision;
        }
        assert_eq!(
            completed
                .fixture
                .service
                .runtime_turn_attempt(&completed.fixture.project_id, &completed_turn_id)
                .expect("completed turn")
                .status,
            RuntimeTurnStatus::Completed
        );
        assert!(matches!(
            completed
                .managed
                .scheduler_gate
                .require_current_permit(&current_permit),
            Err(RuntimeSchedulerError::CompletedReplaySuppressed)
        ));
        completed
            .managed
            .scheduler_gate
            .take_over(
                LeaseFence {
                    owner_digest: sha256(b"taken-over-owner"),
                    token_digest: sha256(b"taken-over-token"),
                    generation: current_permit.fence().generation + 1,
                },
                {
                    let mut next = completed.managed.mapping.clone();
                    next.runtime_turn_id = None;
                    next.runtime_generation += 1;
                    next.runtime_instance_digest = sha256(b"taken-over-instance");
                    next.runtime_thread_id = "taken-over-thread".into();
                    next
                },
            )
            .expect("takeover");
        assert!(matches!(
            completed
                .managed
                .scheduler_gate
                .require_current_permit(&current_permit),
            Err(RuntimeSchedulerError::LeaseFenceLost)
        ));
        assert!(
            completed
                .managed
                .runtime
                .shutdown()
                .expect("shutdown")
                .forced
        );
    }

    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the E2 journey crosses assembly, recovery, durable dispatch, streaming, exact local approval, interrupt, terminal evidence, redaction, and process cleanup"
    )]
    fn context_runtime_turn_is_durable_streamed_interruptible_and_content_free() {
        let mut fixture = runtime_recovery_fixture();
        let capsule = fixture
            .service
            .claim_context_capsule(
                &fixture.project_id,
                &ContextCapsuleId::from("capsule-runtime-recovery"),
                1,
                7,
                now() + Duration::seconds(3),
            )
            .expect("claimed capsule");
        let material_store = runtime_context_material_store(&fixture);
        let tokenizer = runtime_context_tokenizer();
        let assembly = fixture
            .service
            .assemble_runtime_context(
                AssembleRuntimeContext {
                    id: ContextAssemblyId::from("assembly-runtime-turn"),
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    capsule_id: capsule.id,
                    expected_capsule_revision: capsule.revision,
                    expected_branch_revision: 1,
                    expected_worker_lease_revision: 1,
                    expected_checkpoint_id: ContextCheckpointId::from(
                        "checkpoint-runtime-recovery",
                    ),
                    foundation_sync_version: 2,
                    policy: ContextAssemblyPolicy {
                        version: 1,
                        max_prompt_tokens: 1_500,
                        reserved_output_tokens: 400,
                        max_prompt_bytes: 100_000,
                        max_optional_frames: 8,
                        max_gap_records: 16,
                    },
                },
                &material_store,
                &tokenizer,
                now() + Duration::seconds(4),
            )
            .expect("runtime assembly");
        let envelope = assembly.envelope.expect("transient envelope");
        let runtime_command = turn_lifecycle_fake_runtime_command(
            fixture.workspace.path(),
            "private-runtime-thread-application",
            "private-runtime-turn-application",
        );
        let mut managed = fixture
            .service
            .recover_context_worker_runtime(
                RecoverContextWorkerRuntime {
                    id: RuntimeRecoveryAttemptId::from("recovery-runtime-turn"),
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    worker_id: fixture.worker_id.clone(),
                    expected_handle_revision: 1,
                    expected_mailbox_revision: 1,
                    attachment_epoch: 1,
                    strategy: RuntimeResumeStrategy::StartNew,
                    resume_thread_id: None,
                    model: Some("fixture-model".into()),
                    max_process_attempts: 2,
                    health_timeout: StdDuration::from_secs(1),
                    thread_timeout: StdDuration::from_secs(1),
                },
                &runtime_command,
                now() + Duration::seconds(5),
            )
            .expect("managed runtime");
        let turn_id = RuntimeTurnAttemptId::from("turn-attempt-application");
        let expected_handle_revision = managed.handle.revision;
        let expected_recovery_revision = managed.recovery.revision;
        let attachment_epoch = managed.handle.attachment_epoch;
        let dispatch = fixture
            .service
            .dispatch_context_runtime_turn(
                &mut managed,
                DispatchContextRuntimeTurn {
                    id: turn_id.clone(),
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    assembly_id: assembly.manifest.id,
                    expected_assembly_revision: assembly.manifest.revision,
                    expected_handle_revision,
                    expected_recovery_revision,
                    attachment_epoch,
                    response_timeout: StdDuration::from_secs(1),
                },
                &envelope,
                now() + Duration::seconds(6),
            )
            .expect("durable dispatch");
        assert_eq!(
            dispatch.disposition,
            RuntimeTurnDispatchDisposition::Running
        );
        assert_eq!(dispatch.attempt.status, RuntimeTurnStatus::Running);
        assert!(!format!("{:?}", dispatch.attempt).contains("private-runtime-turn-application"));

        let started = fixture
            .service
            .observe_context_runtime_turn(
                &mut managed,
                &ObserveContextRuntimeTurn {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: dispatch.attempt.revision,
                    event_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(7),
            )
            .expect("turn started");
        assert_eq!(
            started.kind,
            ContextRuntimeTurnObservationKind::Event(MappedTurnEventKind::TurnStarted)
        );
        let item = fixture
            .service
            .observe_context_runtime_turn(
                &mut managed,
                &ObserveContextRuntimeTurn {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: started.attempt.revision,
                    event_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(8),
            )
            .expect("item streamed");
        assert_eq!(
            item.kind,
            ContextRuntimeTurnObservationKind::Event(MappedTurnEventKind::ItemStarted)
        );
        let text_delta = fixture
            .service
            .observe_context_runtime_turn(
                &mut managed,
                &ObserveContextRuntimeTurn {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: item.attempt.revision,
                    event_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(9),
            )
            .expect("assistant text delta");
        assert_eq!(
            text_delta.kind,
            ContextRuntimeTurnObservationKind::Event(MappedTurnEventKind::AgentMessageDelta)
        );
        let transient_delta = text_delta
            .agent_message_delta
            .as_ref()
            .expect("transient assistant text delta");
        assert_eq!(transient_delta.as_str(), "PRIVATE-RUNTIME-STREAM");
        assert!(!format!("{text_delta:?}").contains("PRIVATE-RUNTIME-STREAM"));
        let durable_deltas = fixture
            .service
            .runtime_turn_private_text_deltas(&fixture.project_id, &turn_id)
            .expect("durable assistant text deltas");
        assert_eq!(durable_deltas.len(), 1);
        assert_eq!(durable_deltas[0].delta, "PRIVATE-RUNTIME-STREAM");
        assert_eq!(
            durable_deltas[0].evidence_sequence,
            text_delta.attempt.revision
        );
        let approval = fixture
            .service
            .observe_context_runtime_turn(
                &mut managed,
                &ObserveContextRuntimeTurn {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: text_delta.attempt.revision,
                    event_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(10),
            )
            .expect("local approval");
        assert_eq!(
            approval.attempt.status,
            RuntimeTurnStatus::WaitingLocalApproval
        );
        let request = approval
            .local_approval_request
            .expect("transient exact approval request");
        let approved = fixture
            .service
            .respond_context_runtime_local_approval(
                &mut managed,
                &RespondContextRuntimeLocalApproval {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: approval.attempt.revision,
                    request,
                    approved: true,
                },
                now() + Duration::seconds(11),
            )
            .expect("approval response");
        assert_eq!(approved.status, RuntimeTurnStatus::Running);
        let interrupt = fixture
            .service
            .interrupt_context_runtime_turn(
                &mut managed,
                &InterruptContextRuntimeTurn {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: approved.revision,
                    response_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(12),
            )
            .expect("interrupt accepted");
        assert_eq!(interrupt.status, RuntimeTurnStatus::InterruptRequested);
        let terminal = fixture
            .service
            .observe_context_runtime_turn(
                &mut managed,
                &ObserveContextRuntimeTurn {
                    project_id: fixture.project_id.clone(),
                    id: turn_id.clone(),
                    expected_revision: interrupt.revision,
                    event_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(13),
            )
            .expect("terminal notification");
        assert_eq!(terminal.attempt.status, RuntimeTurnStatus::Interrupted);
        assert!(managed.mapping.runtime_turn_id.is_none());
        assert_eq!(
            fixture
                .service
                .runtime_turn_attempt(&fixture.project_id, &turn_id)
                .expect("durable turn"),
            terminal.attempt
        );
        let events_json = serde_json::to_string(
            &fixture
                .service
                .mission_events(&fixture.project_id, &fixture.mission_id)
                .expect("mission events"),
        )
        .expect("events serialize");
        for secret in [
            RUNTIME_CONTEXT_SUMMARY,
            "PRIVATE-RUNTIME-STREAM",
            "PRIVATE-RUNTIME-COMMAND",
            "private-runtime-thread-application",
            "private-runtime-turn-application",
        ] {
            assert!(!events_json.contains(secret));
        }
        assert!(events_json.contains("runtime_turn"));
        assert!(managed.runtime.shutdown().expect("shutdown").forced);
    }

    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one deterministic replay contrasts exact stream adoption with fail-closed completed-body mismatch across the same durable protocol boundary"
    )]
    fn completed_stream_requires_exact_delta_reassembly_before_private_message_adoption() {
        let exact_body = "PRIVATE-EXACT-STREAM";
        let mut exact = ready_runtime_turn_fixture(|workspace| {
            completed_stream_fake_runtime_command(
                workspace,
                "private-runtime-thread-exact",
                "private-runtime-turn-exact",
                exact_body,
                exact_body,
            )
        });
        let exact_turn_id = RuntimeTurnAttemptId::from("turn-attempt-stream-exact");
        let dispatch_request =
            dispatch_command(&exact, exact_turn_id.as_str(), StdDuration::from_secs(1));
        let dispatch = exact
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut exact.managed,
                dispatch_request,
                &exact.envelope,
                now() + Duration::seconds(6),
            )
            .expect("exact stream dispatch");
        let mut revision = dispatch.attempt.revision;
        let expected = [
            MappedTurnEventKind::TurnStarted,
            MappedTurnEventKind::ItemStarted,
            MappedTurnEventKind::AgentMessageDelta,
            MappedTurnEventKind::ItemCompleted,
            MappedTurnEventKind::TurnCompleted(RuntimeTurnCompletionStatus::Completed),
        ];
        let mut terminal = None;
        for (index, expected_kind) in expected.into_iter().enumerate() {
            let observation = exact
                .fixture
                .service
                .observe_context_runtime_turn(
                    &mut exact.managed,
                    &ObserveContextRuntimeTurn {
                        project_id: exact.fixture.project_id.clone(),
                        id: exact_turn_id.clone(),
                        expected_revision: revision,
                        event_timeout: StdDuration::from_secs(1),
                    },
                    now() + Duration::seconds(7 + i64::try_from(index).expect("bounded index")),
                )
                .expect("exact stream observation");
            assert_eq!(
                observation.kind,
                ContextRuntimeTurnObservationKind::Event(expected_kind.clone())
            );
            if expected_kind == MappedTurnEventKind::AgentMessageDelta {
                assert_eq!(
                    observation
                        .agent_message_delta
                        .as_ref()
                        .expect("exact transient delta")
                        .as_str(),
                    exact_body
                );
            }
            if expected_kind == MappedTurnEventKind::ItemCompleted {
                assert_eq!(
                    observation
                        .agent_message
                        .as_ref()
                        .expect("exact completed message")
                        .as_str(),
                    exact_body
                );
            }
            revision = observation.attempt.revision;
            terminal = Some(observation.attempt);
        }
        assert_eq!(
            terminal.expect("exact terminal").status,
            RuntimeTurnStatus::Completed
        );
        assert_eq!(
            exact
                .fixture
                .service
                .latest_runtime_turn_private_message(&exact.fixture.project_id, &exact_turn_id)
                .expect("exact private message")
                .expect("adoptable exact message")
                .body,
            exact_body
        );
        assert!(exact.managed.runtime.shutdown().expect("shutdown").forced);

        let mut mismatched = ready_runtime_turn_fixture(|workspace| {
            completed_stream_fake_runtime_command(
                workspace,
                "private-runtime-thread-mismatch",
                "private-runtime-turn-mismatch",
                "PRIVATE-STREAMED-BODY",
                "PRIVATE-DIFFERENT-BODY",
            )
        });
        let mismatch_turn_id = RuntimeTurnAttemptId::from("turn-attempt-stream-mismatch");
        let dispatch_request = dispatch_command(
            &mismatched,
            mismatch_turn_id.as_str(),
            StdDuration::from_secs(1),
        );
        let dispatch = mismatched
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut mismatched.managed,
                dispatch_request,
                &mismatched.envelope,
                now() + Duration::seconds(6),
            )
            .expect("mismatch stream dispatch");
        let mut revision = dispatch.attempt.revision;
        for index in 0..3 {
            let observation = mismatched
                .fixture
                .service
                .observe_context_runtime_turn(
                    &mut mismatched.managed,
                    &ObserveContextRuntimeTurn {
                        project_id: mismatched.fixture.project_id.clone(),
                        id: mismatch_turn_id.clone(),
                        expected_revision: revision,
                        event_timeout: StdDuration::from_secs(1),
                    },
                    now() + Duration::seconds(7 + index),
                )
                .expect("pre-mismatch stream observation");
            revision = observation.attempt.revision;
        }
        let mismatch = mismatched
            .fixture
            .service
            .observe_context_runtime_turn(
                &mut mismatched.managed,
                &ObserveContextRuntimeTurn {
                    project_id: mismatched.fixture.project_id.clone(),
                    id: mismatch_turn_id.clone(),
                    expected_revision: revision,
                    event_timeout: StdDuration::from_secs(1),
                },
                now() + Duration::seconds(10),
            )
            .expect("deterministic mismatch fence");
        assert_eq!(mismatch.kind, ContextRuntimeTurnObservationKind::Uncertain);
        assert_eq!(mismatch.attempt.status, RuntimeTurnStatus::Uncertain);
        assert!(mismatched.managed.mapping.runtime_turn_id.is_none());
        assert!(
            mismatched
                .fixture
                .service
                .latest_runtime_turn_private_message(
                    &mismatched.fixture.project_id,
                    &mismatch_turn_id,
                )
                .expect("mismatch private message query")
                .is_none()
        );
        assert!(
            mismatched
                .managed
                .runtime
                .shutdown()
                .expect("shutdown")
                .forced
        );
    }

    #[cfg(unix)]
    #[test]
    #[ignore = "requires the pinned HARTEVO_TEST_OPENINTERPRETER_BIN package and an isolated writable HARTEVO_TEST_OPENINTERPRETER_HOME"]
    #[allow(
        clippy::too_many_lines,
        reason = "the explicit real-process replay crosses encrypted Context assembly, durable recovery, protocol dispatch, failure observation, redaction, and cleanup"
    )]
    fn real_openinterpreter_credentialless_turn_is_durably_failed_not_completed() {
        let program = std::env::var_os("HARTEVO_TEST_OPENINTERPRETER_BIN")
            .map(PathBuf::from)
            .expect("HARTEVO_TEST_OPENINTERPRETER_BIN");
        let runtime_home = std::env::var_os("HARTEVO_TEST_OPENINTERPRETER_HOME")
            .map(PathBuf::from)
            .expect("HARTEVO_TEST_OPENINTERPRETER_HOME");
        let verified = hartevo_runtime_adapter::verify_pinned_runtime_artifact(
            &program,
            hartevo_runtime_adapter::host_openinterpreter_target().expect("host target"),
        )
        .expect("verified release package");
        let tokenizer = runtime_context_tokenizer_for("openai", "gpt-5.6-sol");
        let mut ready = ready_runtime_turn_fixture_with_tokenizer(
            |workspace| {
                verified
                    .runtime_command(workspace, &runtime_home)
                    .expect("pinned isolated runtime command")
            },
            &tokenizer,
        );
        let turn_id = RuntimeTurnAttemptId::from("turn-real-runtime-credentialless");
        let command = dispatch_command(&ready, turn_id.as_str(), StdDuration::from_secs(10));
        let dispatch = ready
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut ready.managed,
                command,
                &ready.envelope,
                now() + Duration::seconds(6),
            )
            .expect("real durable dispatch");
        assert_eq!(dispatch.attempt.status, RuntimeTurnStatus::Running);

        let mut revision = dispatch.attempt.revision;
        let mut terminal = None;
        for offset in 0..64 {
            let observation = ready
                .fixture
                .service
                .observe_context_runtime_turn(
                    &mut ready.managed,
                    &ObserveContextRuntimeTurn {
                        project_id: ready.fixture.project_id.clone(),
                        id: turn_id.clone(),
                        expected_revision: revision,
                        event_timeout: StdDuration::from_secs(45),
                    },
                    now() + Duration::seconds(7 + offset),
                )
                .expect("real runtime observation");
            revision = observation.attempt.revision;
            if observation.attempt.status.is_terminal() {
                terminal = Some(observation.attempt);
                break;
            }
        }
        let terminal = terminal.expect("real runtime terminal");
        assert_eq!(terminal.status, RuntimeTurnStatus::Failed);
        assert_eq!(
            ready
                .fixture
                .service
                .runtime_turn_attempt(&ready.fixture.project_id, &turn_id)
                .expect("durable real turn"),
            terminal
        );
        assert!(ready.managed.mapping.runtime_turn_id.is_none());
        let events = serde_json::to_string(
            &ready
                .fixture
                .service
                .mission_events(&ready.fixture.project_id, &ready.fixture.mission_id)
                .expect("real runtime events"),
        )
        .expect("event JSON");
        assert!(!events.contains(RUNTIME_CONTEXT_SUMMARY));
        assert!(!events.contains("Return a short plain-text readiness response"));
        assert!(events.contains("context.runtime_turn"));
        ready.managed.runtime.shutdown().expect("runtime shutdown");
    }

    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the E2 replay proves timeout persistence, direct-reattach fencing, forged-thread rejection, exact retry, attachment, redaction, and process cleanup"
    )]
    fn runtime_recovery_is_checkpoint_bound_retryable_and_thread_redacted() {
        let mut fixture = runtime_recovery_fixture();
        let runtime_thread_id = "private-runtime-thread-recovery";
        let runtime_command = checkpoint_bound_health_timeout_runtime_command(
            fixture.workspace.path(),
            runtime_thread_id,
        );
        let recovery_id = RuntimeRecoveryAttemptId::from("recovery-runtime-health-timeout");
        let first_result = fixture.service.recover_context_worker_runtime(
            RecoverContextWorkerRuntime {
                id: recovery_id.clone(),
                project_id: fixture.project_id.clone(),
                workspace_id: fixture.workspace_id.clone(),
                worker_id: fixture.worker_id.clone(),
                expected_handle_revision: 1,
                expected_mailbox_revision: 1,
                attachment_epoch: 1,
                strategy: RuntimeResumeStrategy::StartNew,
                resume_thread_id: None,
                model: Some("fixture-model".into()),
                max_process_attempts: 2,
                health_timeout: StdDuration::from_millis(20),
                thread_timeout: StdDuration::from_secs(1),
            },
            &runtime_command,
            now() + Duration::seconds(3),
        );
        assert!(matches!(
            first_result,
            Err(ApplicationError::Runtime(
                AdapterError::HealthCheckTimedOut { .. }
            ))
        ));
        let retryable = fixture
            .service
            .runtime_recovery_attempt(&fixture.project_id, &recovery_id)
            .expect("durable retryable failure");
        assert_eq!(retryable.status, RuntimeRecoveryStatus::Prepared);
        assert_eq!(retryable.process_attempt, 2);
        assert_eq!(retryable.failures.len(), 1);
        assert_eq!(
            retryable.failures[0].class,
            RuntimeRecoveryFailureClass::Health
        );
        let detached = fixture
            .service
            .context_worker_handle(
                &fixture.project_id,
                &fixture.workspace_id,
                &fixture.worker_id,
            )
            .expect("detached worker");
        assert_eq!(
            detached.status,
            hartevo_domain_kernel::WorkerHandleStatus::Detached
        );
        assert_eq!(detached.revision, 2);
        assert!(matches!(
            fixture.service.reattach_context_worker(
                ReattachContextWorker {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    worker_id: fixture.worker_id.clone(),
                    expected_handle_revision: detached.revision,
                    expected_mailbox_revision: 1,
                    attachment_epoch: 1,
                    runtime_mapping_digest: "c".repeat(64),
                },
                now() + Duration::seconds(4),
            ),
            Err(ApplicationError::RuntimeRecoveryRequired)
        ));
        assert!(matches!(
            fixture.service.retry_context_worker_runtime(
                RetryContextWorkerRuntime {
                    project_id: fixture.project_id.clone(),
                    recovery_id: recovery_id.clone(),
                    expected_attempt_revision: retryable.revision,
                    expected_handle_revision: detached.revision,
                    expected_mailbox_revision: 1,
                    resume_thread_id: Some("forged-thread-id".into()),
                    model: Some("fixture-model".into()),
                    health_timeout: StdDuration::from_secs(2),
                    thread_timeout: StdDuration::from_secs(2),
                },
                &runtime_command,
                now() + Duration::seconds(4),
            ),
            Err(ApplicationError::RuntimeRecoveryResumeThreadMismatch)
        ));
        assert_eq!(
            fixture
                .service
                .runtime_recovery_attempt(&fixture.project_id, &recovery_id)
                .expect("forged retry cannot mutate the ledger"),
            retryable
        );

        let managed = fixture
            .service
            .retry_context_worker_runtime(
                RetryContextWorkerRuntime {
                    project_id: fixture.project_id.clone(),
                    recovery_id: recovery_id.clone(),
                    expected_attempt_revision: retryable.revision,
                    expected_handle_revision: detached.revision,
                    expected_mailbox_revision: 1,
                    resume_thread_id: None,
                    model: Some("fixture-model".into()),
                    health_timeout: StdDuration::from_secs(2),
                    thread_timeout: StdDuration::from_secs(2),
                },
                &runtime_command,
                now() + Duration::seconds(5),
            )
            .expect("retry exact runtime configuration");
        let ManagedContextRuntime {
            recovery,
            mapping,
            handle,
            mailbox,
            runtime,
            ..
        } = managed;
        assert_eq!(recovery.status, RuntimeRecoveryStatus::Attached);
        assert_eq!(recovery.process_attempt, 2);
        assert_eq!(mapping.runtime_thread_id, runtime_thread_id);
        assert_eq!(mapping.runtime_generation, 2);
        assert_eq!(handle.attachment_epoch, 2);
        assert_eq!(
            handle.runtime_mapping_digest,
            recovery.runtime_mapping_digest
        );
        assert_eq!(mailbox.id, fixture.mailbox_id);
        let events = serde_json::to_string(
            &fixture
                .service
                .mission_events(&fixture.project_id, &fixture.mission_id)
                .expect("runtime recovery events"),
        )
        .expect("events serialize");
        assert!(!events.contains(runtime_thread_id));
        assert!(events.contains("context.runtime_recovery_attached"));
        let shutdown = runtime.shutdown().expect("bounded process-tree shutdown");
        assert!(shutdown.forced);
    }

