    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the fail-closed Review fence is asserted as one exact Offer-to-Review journey"
    )]
    fn review_creator_deliverable_fails_closed_on_stale_revision_and_wrong_decision() {
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        let ids = CreatorRecoveryIds {
            tenant_id: TenantId::from("tenant-review-fence"),
            project_id: ProjectId::from("project-review-fence"),
            mission_id: MissionId::from("mission-review-fence"),
            task_id: CreatorTaskId::from("task-review-fence"),
            milestone_id: CreatorMilestoneId::from("milestone-review-fence"),
            deliverable_id: DeliverableId::from("deliverable-review-fence"),
            creator_id: CreatorId::from("creator-review-fence"),
            connection_id: ConnectionId::from("connection-review-fence"),
            effect: EffectId::from("effect-review-fence"),
        };
        let base = now();
        create_creator_recovery_scope(&mut service, &ids, base);
        register_creator_recovery_connection(&mut service, &ids, base);
        fund_and_accept_creator_recovery_task(&mut service, &ids, base);
        service
            .submit_creator_deliverable(
                SubmitCreatorDeliverable {
                    project_id: ids.project_id.clone(),
                    task_id: ids.task_id.clone(),
                    deliverable: CreatorDeliverableInput {
                        id: ids.deliverable_id.clone(),
                        milestone_id: ids.milestone_id.clone(),
                        artifact_uri: "cas://creator/review-fence".into(),
                        media_type: "application/zip".into(),
                        size_bytes: 1_024,
                        content_digest: "7".repeat(64),
                        uploaded_at: base + Duration::minutes(4),
                        assessment: DeliverableAssessment {
                            scanner: "review-fence-scanner".into(),
                            clean: true,
                            assessed_at: base + Duration::minutes(4),
                            evidence_digest: "8".repeat(64),
                        },
                        rights: RightsAttestation {
                            ownership_or_license: "creator original".into(),
                            source_manifest_digest: "9".repeat(64),
                            permitted_use: "campaign recovery use".into(),
                            verified: true,
                        },
                    },
                },
                base + Duration::minutes(4),
            )
            .expect("submit review-fence deliverable");
        let submitted = service
            .load_creator_task(&ids.project_id, &ids.task_id)
            .expect("submitted review-fence task");
        let projected = service
            .projection(&ids.project_id, &ids.mission_id, WorkSurface::Orchestrator)
            .expect("review-fence projection");
        let creator_work = projected
            .creator_work
            .as_ref()
            .expect("creator work projection");
        let reviewable = creator_work
            .reviewable
            .as_ref()
            .expect("uploaded deliverable is reviewable");
        assert_eq!(creator_work.task_id, ids.task_id);
        assert_eq!(
            creator_work.expected_task_revision,
            submitted.state_revision
        );
        assert_eq!(reviewable.deliverable_id, ids.deliverable_id);
        assert_eq!(reviewable.expected_deliverable_revision, 1);
        assert_eq!(reviewable.content_digest, "7".repeat(64));
        assert_eq!(
            reviewable.acceptance_checks,
            vec![
                "Matches the approved scope".to_owned(),
                "Includes the source manifest".to_owned(),
            ]
        );

        let mut command = ReviewCreatorDeliverable {
            project_id: ids.project_id.clone(),
            mission_id: ids.mission_id.clone(),
            task_id: ids.task_id.clone(),
            deliverable_id: ids.deliverable_id.clone(),
            expected_task_revision: submitted.state_revision,
            expected_deliverable_revision: 1,
            review_id: ReviewId::from("review-fence"),
            reviewer_id: ActorId::from("review-fence-reviewer"),
            decision: ReviewDecision::Reject,
            acceptance_checks: vec![
                AcceptanceCheck {
                    requirement: "Matches the approved scope".into(),
                    satisfied: true,
                    evidence: "scope-check".into(),
                },
                AcceptanceCheck {
                    requirement: "Includes the source manifest".into(),
                    satisfied: true,
                    evidence: "manifest-check".into(),
                },
            ],
            notes: "typed ReviewDecision only".into(),
        };
        assert!(matches!(
            service.review_creator_deliverable(command.clone(), base + Duration::minutes(5)),
            Err(ApplicationError::CreatorDeliverableReviewCommandMismatch)
        ));
        command.decision = ReviewDecision::Accept;
        command.expected_task_revision = submitted.state_revision.saturating_sub(1);
        assert!(matches!(
            service.review_creator_deliverable(command.clone(), base + Duration::minutes(5)),
            Err(ApplicationError::CreatorTaskRevisionMismatch { expected, actual })
                if expected == submitted.state_revision.saturating_sub(1)
                    && actual == submitted.state_revision
        ));
        command.expected_task_revision = submitted.state_revision;
        command.deliverable_id = DeliverableId::from("deliverable-does-not-exist");
        assert!(matches!(
            service.review_creator_deliverable(command.clone(), base + Duration::minutes(5)),
            Err(ApplicationError::CreatorDeliverableReviewUnavailable)
        ));
        command.deliverable_id = ids.deliverable_id.clone();
        service
            .review_creator_deliverable(command, base + Duration::minutes(5))
            .expect("accept exact uploaded revision");
        let accepted = service
            .projection(&ids.project_id, &ids.mission_id, WorkSurface::Orchestrator)
            .expect("accepted projection")
            .creator_work
            .expect("accepted creator work");
        assert!(accepted.reviewable.is_none());
        assert_eq!(accepted.accepted_deliverable_count, 1);
        assert!(!accepted.payout_verified);
        assert_eq!(
            accepted.status,
            hartevo_domain_kernel::CreatorTaskStatus::SettlementPending
        );
    }

    #[test]
    fn desktop_projection_reads_validated_manifest_preview_without_artifact_body() {
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        let workspace = tempfile::tempdir().expect("workspace");
        let secrets = MemorySecretStore::default();
        let device_id = DeviceId::from("desktop-work-product-device");
        let project_id = ProjectId::from("desktop-work-product-project");
        let mission_id = MissionId::from("desktop-work-product-mission");
        let task_id = TaskId::from("desktop-work-product-task");
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("desktop-work-product-tenant"),
                    id: project_id.clone(),
                    name: "Manifest projection".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalExisting,
                },
                now(),
            )
            .expect("project");
        service
            .start_mission(
                StartMission {
                    id: mission_id.clone(),
                    research_task_id: task_id.clone(),
                    project_id: project_id.clone(),
                    title: Some("Manifest-backed Mission".into()),
                    prompt: "Create a reviewable artifact without external effects".into(),
                },
                now(),
            )
            .expect("mission");
        service
            .provision_project_encryption(
                &secrets,
                ProvisionProjectEncryption {
                    project_id: project_id.clone(),
                    mode: ProjectEncryptionMode::TeamEnvelope,
                    primary_recipient: KeyRecipient::Device(device_id.clone()),
                    recovery_recipient_id: None,
                },
                now(),
            )
            .expect("device keyring");
        let private_body = "private full artifact body that must not enter the Desktop projection";
        let preview = "Evidence-backed preview from the persisted manifest";
        service
            .record_research(
                &project_id,
                &mission_id,
                ResearchPacket {
                    work_product_id: WorkProductId::from("desktop-work-product-1"),
                    title: "Launch evidence pack".into(),
                    body: private_body.into(),
                    work_product_type: "document.evidence_pack".into(),
                    fact_ids: BTreeSet::new(),
                    task_ids: BTreeSet::from([task_id]),
                    file_digest: None,
                    preview_media_type: "text/plain".into(),
                    preview: preview.into(),
                    editable_scopes: BTreeSet::from(["/body".into()]),
                    evidence: vec![EvidenceInput {
                        id: EvidenceId::from("desktop-work-product-evidence"),
                        title: "Persisted evidence".into(),
                        source_uri: "fixture://desktop/work-product".into(),
                        confidence: 1.0,
                        content: "private source content".into(),
                    }],
                },
                now() + Duration::minutes(1),
            )
            .expect("manifested work product");

        let metadata_projection = service
            .projection(&project_id, &mission_id, WorkSurface::WorkProduct)
            .expect("metadata projection");
        assert_eq!(metadata_projection.work_product_count, 1);
        assert!(metadata_projection.work_products.is_empty());
        let metadata_visible =
            serde_json::to_string(&metadata_projection).expect("metadata projection JSON");
        assert!(!metadata_visible.contains(preview));
        assert!(!metadata_visible.contains(private_body));

        let unlocked = service
            .desktop_unlocked_project(&secrets, &project_id, &device_id, now())
            .expect("device-unlocked projection");
        let projection = unlocked
            .missions
            .iter()
            .find(|mission| mission.mission_id == mission_id)
            .expect("unlocked Mission projection");
        assert_eq!(projection.work_product_count, 1);
        assert_eq!(projection.work_products.len(), 1);
        assert_desktop_work_product_projection(&projection.work_products[0], preview);
        let visible = serde_json::to_string(projection).expect("projection JSON");
        assert!(visible.contains(preview));
        assert!(!visible.contains(private_body));

        let inventory = service.desktop_inventory().expect("Desktop inventory");
        assert!(inventory.projects[0].missions[0].work_products.is_empty());
    }

    fn assert_desktop_work_product_projection(product: &WorkProductProjection, preview: &str) {
        assert_eq!(product.title, "Launch evidence pack");
        assert_eq!(product.preview_text, preview);
        assert_eq!(product.preview_media_type, "text/plain");
        assert_eq!(product.manifest_version, 1);
        assert_eq!(product.work_product_revision, 1);
        assert_eq!(product.evidence_count, 1);
        assert_eq!(product.editable_scope_count, 1);
        assert_eq!(product.adoption_status, WorkProductStatus::ReadyForReview);
    }

    #[derive(Debug)]
    struct CountingRelationshipExecutor {
        calls: usize,
        accepted_at: DateTime<Utc>,
    }

    impl EffectExecutor for CountingRelationshipExecutor {
        fn execute(
            &mut self,
            effect: &hartevo_domain_kernel::Effect,
        ) -> Result<Receipt, ProviderFailure> {
            self.calls += 1;
            Ok(Receipt {
                id: ReceiptId::from("relationship-receipt-1"),
                provider: effect.provider.clone(),
                external_id: "gmail-message-1".into(),
                accepted_at: self.accepted_at,
                request_digest: effect.approval_digest(),
                response_digest: "8".repeat(64),
            })
        }
    }

    #[derive(Debug)]
    struct RelationshipVerifier {
        observed_at: DateTime<Utc>,
    }

    impl EffectVerifier for RelationshipVerifier {
        fn verify(
            &mut self,
            _effect: &hartevo_domain_kernel::Effect,
            receipt: &Receipt,
        ) -> Verification {
            Verification {
                id: VerificationId::from("relationship-verification-1"),
                status: VerificationStatus::Confirmed,
                verifier: "gmail-message-readback".into(),
                independent: true,
                observed_at: self.observed_at,
                evidence_digest: "9".repeat(64),
                receipt_id: receipt.id.clone(),
            }
        }
    }

    #[derive(Debug)]
    struct CountingRecoveryVerifier {
        calls: usize,
        status: VerificationStatus,
        observed_at: DateTime<Utc>,
    }

    impl EffectVerifier for CountingRecoveryVerifier {
        fn verify(
            &mut self,
            _effect: &hartevo_domain_kernel::Effect,
            receipt: &Receipt,
        ) -> Verification {
            self.calls += 1;
            Verification {
                id: VerificationId::from("recovery-verification"),
                status: self.status.clone(),
                verifier: "recovery-readback".into(),
                independent: true,
                observed_at: self.observed_at,
                evidence_digest: "6".repeat(64),
                receipt_id: receipt.id.clone(),
            }
        }
    }

    #[derive(Debug, Default)]
    struct MismatchedReceiptVerifier {
        calls: usize,
    }

    impl EffectVerifier for MismatchedReceiptVerifier {
        fn verify(
            &mut self,
            _effect: &hartevo_domain_kernel::Effect,
            _receipt: &Receipt,
        ) -> Verification {
            self.calls += 1;
            Verification {
                id: VerificationId::from("mismatched-recovery-verification"),
                status: VerificationStatus::Confirmed,
                verifier: "mismatched-recovery-readback".into(),
                independent: true,
                observed_at: Utc::now(),
                evidence_digest: "5".repeat(64),
                receipt_id: ReceiptId::from("wrong-receipt"),
            }
        }
    }

    #[derive(Debug, Default)]
    struct UncertainRelationshipExecutor {
        calls: usize,
    }

    impl EffectExecutor for UncertainRelationshipExecutor {
        fn execute(
            &mut self,
            _effect: &hartevo_domain_kernel::Effect,
        ) -> Result<Receipt, ProviderFailure> {
            self.calls += 1;
            Err(ProviderFailure::Uncertain(
                "provider acceptance could not be determined".into(),
            ))
        }
    }

    #[derive(Debug)]
    struct RelationshipReconciler {
        calls: usize,
        receipt: Receipt,
        observed_at: DateTime<Utc>,
    }

    impl EffectReconciler for RelationshipReconciler {
        fn reconcile(
            &mut self,
            _effect: &hartevo_domain_kernel::Effect,
        ) -> ReconciliationObservation {
            self.calls += 1;
            ReconciliationObservation::ReceiptFound {
                receipt: self.receipt.clone(),
                evidence_digest: "d".repeat(64),
                observed_at: self.observed_at,
            }
        }
    }

    #[derive(Debug)]
    struct FixedReconciler {
        calls: usize,
        observation: ReconciliationObservation,
    }

    impl EffectReconciler for FixedReconciler {
        fn reconcile(
            &mut self,
            _effect: &hartevo_domain_kernel::Effect,
        ) -> ReconciliationObservation {
            self.calls += 1;
            self.observation.clone()
        }
    }

