    #[test]
    fn application_persists_reconciled_not_executed_and_blocks_provider_replay() {
        let UncertainPreviewFixture {
            mut service,
            mut broker,
            project_id,
            mission_id,
            effect_id,
        } = uncertain_preview_fixture("not-executed");
        let evidence_digest = "a".repeat(64);
        let mut reconciler = FixedReconciler {
            calls: 0,
            observation: ReconciliationObservation::NotExecuted {
                evidence_digest: evidence_digest.clone(),
                observed_at: now() + Duration::seconds(4),
            },
        };
        let mut verifier = RelationshipVerifier {
            observed_at: now() + Duration::seconds(4),
        };
        assert!(matches!(
            service.reconcile_effect(
                &mut broker,
                &project_id,
                &mission_id,
                &effect_id,
                &mut reconciler,
                &mut verifier,
                now() + Duration::seconds(4),
            ),
            Err(ApplicationError::Broker(BrokerError::ProviderNotExecuted {
                evidence_digest: stored,
            })) if stored == evidence_digest
        ));
        assert_eq!(reconciler.calls, 1);
        let terminal_mission = service
            .load_mission(&project_id, &mission_id)
            .expect("terminal mission");
        assert_eq!(
            terminal_mission.effect(&effect_id).expect("effect").status,
            EffectStatus::Reconciled
        );
        let mut forbidden_replay = CountingRelationshipExecutor {
            calls: 0,
            accepted_at: now() + Duration::seconds(5),
        };
        let events_before_replay = service
            .mission_events(&project_id, &mission_id)
            .expect("events before terminal execute replay");
        let outbox_before_replay = all_outbox_snapshot(&service);
        let replay = service
            .execute_effect(
                &mut broker,
                &project_id,
                &mission_id,
                &effect_id,
                &mut forbidden_replay,
                &mut verifier,
                now() + Duration::seconds(5),
            )
            .expect_err("terminal reconciliation remains non-replayable");
        assert!(matches!(
            replay,
            ApplicationError::Broker(BrokerError::ProviderNotExecuted {
                evidence_digest: stored,
            }) if stored == evidence_digest
        ));
        assert_eq!(forbidden_replay.calls, 0);
        assert_eq!(
            service
                .load_mission(&project_id, &mission_id)
                .expect("terminal Mission after exact execute replay"),
            terminal_mission
        );
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events after terminal execute replay"),
            events_before_replay
        );
        assert_eq!(all_outbox_snapshot(&service), outbox_before_replay);
        let events = service
            .mission_events(&project_id, &mission_id)
            .expect("events");
        let reconciliation_event = events
            .iter()
            .find(|event| event.event_type == "effect.reconciled_not_executed")
            .expect("reconciliation event");
        assert_eq!(reconciliation_event.payload["authoritySequence"], 1);
        assert_eq!(
            terminal_mission.updated_at,
            reconciliation_event.recorded_at
        );
        assert_ne!(
            reconciliation_event.recorded_at,
            now() + Duration::seconds(4)
        );
        assert_event_outbox_time(&service, reconciliation_event);
    }

    #[test]
    fn application_persists_reconciliation_dead_letter_and_blocks_provider_replay() {
        let UncertainPreviewFixture {
            mut service,
            broker,
            project_id,
            mission_id,
            effect_id,
        } = uncertain_preview_fixture("dead-letter");
        let mut broker = broker
            .with_reconciliation_policy(ReconciliationPolicy {
                version: "application-dead-letter-v1".into(),
                max_attempts: 1,
                retry_delay_seconds: 60,
            })
            .expect("bounded policy");
        let mut reconciler = FixedReconciler {
            calls: 0,
            observation: ReconciliationObservation::StillUncertain {
                reason: "Provider lookup remains ambiguous".into(),
                evidence_digest: "b".repeat(64),
                observed_at: now() + Duration::seconds(4),
            },
        };
        let mut verifier = RelationshipVerifier {
            observed_at: now() + Duration::seconds(4),
        };
        assert!(matches!(
            service.reconcile_effect(
                &mut broker,
                &project_id,
                &mission_id,
                &effect_id,
                &mut reconciler,
                &mut verifier,
                now() + Duration::seconds(4),
            ),
            Err(ApplicationError::Broker(
                BrokerError::ReconciliationDeadLetter { attempts: 1, .. }
            ))
        ));
        assert_eq!(reconciler.calls, 1);
        assert_eq!(
            service
                .load_mission(&project_id, &mission_id)
                .expect("dead-letter mission")
                .effect(&effect_id)
                .expect("effect")
                .status,
            EffectStatus::DeadLetter
        );
        let mut forbidden_replay = CountingRelationshipExecutor {
            calls: 0,
            accepted_at: now() + Duration::seconds(5),
        };
        assert!(matches!(
            service.execute_effect(
                &mut broker,
                &project_id,
                &mission_id,
                &effect_id,
                &mut forbidden_replay,
                &mut verifier,
                now() + Duration::seconds(5),
            ),
            Err(ApplicationError::Broker(
                BrokerError::DurableProjectionRecoveryRequired
            ))
        ));
        assert_eq!(forbidden_replay.calls, 0);
        assert!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("events")
                .iter()
                .any(|event| event.event_type == "effect.reconciliation_dead_lettered")
        );
    }

