    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the application replay proves private-key isolation, exact ciphertext reuse, Claim-before-decrypt, attachment CAS, bootstrap publication, receipt, and idempotent replay"
    )]
    fn device_handoff_preparation_is_durable_claim_first_and_keeps_private_key_out_of_sqlcipher() {
        let mut fixture = setup_team_key_fixture();
        complete_local_project_registration(&mut fixture);
        let bootstrap = fixture
            .service
            .prepare_project_keyring_bootstrap(
                &fixture.secrets,
                PrepareProjectKeyringBootstrap {
                    cell: DataCell::Eu,
                    project_id: fixture.project.clone(),
                    previous_keyring_revision: None,
                    authorizing_key: fixture.primary_key.clone(),
                    authorization: key_admin_authorization(),
                    idempotency_key: "initial-keyring-bootstrap".into(),
                },
                now() + Duration::minutes(2),
            )
            .expect("prepare initial keyring bootstrap");
        assert_eq!(bootstrap.payload.keyring.revision, 1);
        assert_eq!(
            bootstrap.operation.status,
            KeyBootstrapOperationStatus::Prepared
        );

        let registered = fixture
            .service
            .prepare_device_public_key_registration(
                &fixture.secrets,
                RegisterDeviceBootstrapKey {
                    cell: DataCell::Eu,
                    project_id: fixture.project.clone(),
                    device_id: DeviceId::from("device-target"),
                    authorization: key_admin_authorization(),
                    idempotency_key: "target-public-key-v1".into(),
                },
                now() + Duration::minutes(3),
            )
            .expect("prepare target public key registration");
        assert!(!registered.duplicate);
        let private_key = KeyMaterial::from_secret(
            &fixture
                .secrets
                .get(&registered.private_key_reference)
                .expect("target X25519 private key only in secret store"),
        )
        .expect("private key material");
        assert_eq!(
            DeviceKeyAgreementCrypto::public_key(&private_key),
            registered.registration.public_key
        );
        let registration_ledger = serde_json::to_string(&registered.operation.request)
            .expect("serialize registration ledger");
        assert!(!registration_ledger.contains("privateKey"));
        assert!(!registration_ledger.contains("recoverySecret"));

        let grant = fixture
            .service
            .prepare_device_handoff_grant(
                &fixture.secrets,
                PrepareDeviceHandoffGrant {
                    cell: DataCell::Eu,
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 1,
                    authorizing_key: fixture.primary_key.clone(),
                    target_registration: registered.registration.clone(),
                    authorization: key_admin_authorization(),
                    expires_at: now() + Duration::hours(1),
                    idempotency_key: "target-handoff-v1".into(),
                },
                now() + Duration::minutes(4),
            )
            .expect("prepare encrypted handoff grant");
        let grant_replay = fixture
            .service
            .prepare_device_handoff_grant(
                &fixture.secrets,
                PrepareDeviceHandoffGrant {
                    cell: DataCell::Eu,
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 1,
                    authorizing_key: fixture.primary_key.clone(),
                    target_registration: registered.registration,
                    authorization: key_admin_authorization(),
                    expires_at: now() + Duration::hours(1),
                    idempotency_key: "target-handoff-v1".into(),
                },
                now() + Duration::minutes(5),
            )
            .expect("replay exact handoff ciphertext");
        assert!(grant_replay.duplicate);
        assert_eq!(grant_replay.payload, grant.payload);
        assert_eq!(
            grant_replay.operation.request_digest,
            grant.operation.request_digest
        );

        let claim = fixture
            .service
            .prepare_device_handoff_claim(
                &fixture.secrets,
                &PrepareDeviceHandoffClaim {
                    cell: DataCell::Eu,
                    project_id: fixture.project.clone(),
                    grant: grant.payload.clone(),
                    target_private_key_reference: registered.private_key_reference.clone(),
                    idempotency_key: "target-handoff-claim-v1".into(),
                },
                now() + Duration::minutes(6),
            )
            .expect("durably prepare claim before decrypting");
        assert_eq!(
            claim.payload.target_device_id,
            DeviceId::from("device-target")
        );
        assert_eq!(
            claim.operation.kind,
            KeyBootstrapOperationKind::HandoffClaim
        );
        assert_eq!(
            claim.operation.status,
            KeyBootstrapOperationStatus::Prepared
        );

        let apply_command = ApplyClaimedDeviceHandoff {
            cell: DataCell::Eu,
            project_id: fixture.project.clone(),
            grant: grant.payload.clone(),
            claim: claim.payload.clone(),
            source_bootstrap: bootstrap.payload.clone(),
            target_private_key_reference: registered.private_key_reference.clone(),
        };
        assert!(matches!(
            fixture.service.apply_claimed_device_handoff(
                &fixture.secrets,
                &apply_command,
                now() + Duration::minutes(7),
            ),
            Err(ApplicationError::DeviceHandoffClaimRequired)
        ));
        fixture
            .service
            .store
            .mark_key_bootstrap_operation_applied(
                &claim.operation,
                None,
                Some(grant.payload.context.grant_id.to_string()),
                now() + Duration::minutes(7),
            )
            .expect("record simulated durable remote Claim");
        let applied = fixture
            .service
            .apply_claimed_device_handoff(
                &fixture.secrets,
                &apply_command,
                now() + Duration::minutes(8),
            )
            .expect("decrypt only after Claim and attach exact device envelope");
        assert_eq!(
            (
                applied.attachment.attachment.method,
                applied.attachment.attachment.status,
                applied.attachment.keyring.revision,
                applied.next_bootstrap.payload.previous_keyring_revision,
            ),
            (
                DeviceAttachmentMethod::PublicKeyHandoff,
                DeviceAttachmentStatus::Applied,
                2,
                Some(1),
            )
        );
        assert_eq!(applied.consumption.payload.claim_id, claim.payload.claim_id);
        assert_eq!(
            applied.consumption.payload.result_keyring_revision,
            applied.next_bootstrap.payload.keyring.revision
        );
        let target_project_key = open_active_project_key(
            &fixture.secrets,
            &applied.attachment.keyring,
            &RecipientKeyReference {
                recipient: KeyRecipient::Device(DeviceId::from("device-target")),
                reference: applied.attachment.device_key_reference.clone(),
            },
            now() + Duration::minutes(8),
        )
        .expect("normal target device envelope opens claimed project key");
        let source_project_key = open_active_project_key(
            &fixture.secrets,
            &applied.attachment.keyring,
            &fixture.primary_key,
            now() + Duration::minutes(8),
        )
        .expect("source envelope still opens same project key");
        assert_eq!(
            target_project_key.to_secret().as_slice(),
            source_project_key.to_secret().as_slice()
        );

        let replay = fixture
            .service
            .apply_claimed_device_handoff(
                &fixture.secrets,
                &apply_command,
                now() + Duration::minutes(9),
            )
            .expect("restart-safe claimed handoff replay");
        assert!(replay.attachment.duplicate);
        assert!(replay.next_bootstrap.duplicate);
        assert!(replay.consumption.duplicate);
        assert_eq!(replay.consumption.payload, applied.consumption.payload);
    }

