    fn establish_synced_truth(fixture: &mut TeamKeyFixture) -> (TruthFact, TruthSource) {
        let source = TruthSource {
            provider: "first-party".into(),
            source_uri: "fixture://truth/private".into(),
            source_digest: "4".repeat(64),
            evidence_ids: BTreeSet::from([EvidenceId::from("truth-evidence")]),
            captured_by: ActorId::from("truth-owner"),
            captured_at: now(),
        };
        let fact = TruthFact::create(
            hartevo_domain_kernel::FactId::from("truth-sync-1"),
            fixture.tenant.clone(),
            fixture.project.clone(),
            "launch.private_claim",
            Some(TruthValue::Text("private unreleased claim".into())),
            vec![],
            TruthStatus::Confirmed,
            Some(source.clone()),
            "DE",
            "de",
            now(),
            now(),
            None,
            Decimal::ONE,
            now(),
        )
        .expect("truth fact");
        fixture
            .service
            .create_truth_fact(fact.clone(), now())
            .expect("persist truth");
        let prepared = fixture
            .service
            .prepare_encrypted_sync_operation(
                &fixture.secrets,
                prepare_truth_sync_command(
                    fixture,
                    &fact,
                    MutationPrecondition::CreateOnly,
                    "truth-v1",
                ),
                now() + Duration::minutes(1),
            )
            .expect("prepare truth v1");
        assert!(
            !serde_json::to_string(&prepared.local)
                .expect("truth sync ledger")
                .contains("private unreleased claim")
        );
        let ingested = fixture
            .service
            .ingest_encrypted_sync_object(
                &fixture.secrets,
                &IngestEncryptedSyncObject {
                    object: remote_sync_object(&prepared),
                    authorizing_key: fixture.primary_key.clone(),
                    expected_remote_revision: None,
                },
                now() + Duration::minutes(1),
            )
            .expect("project truth v1");
        assert_eq!(ingested.local.projection_revision, Some(1));
        (fact, source)
    }

