    #[test]
    fn project_cell_selection_and_cloud_registration_are_one_exact_saga() {
        let mut fixture = setup_team_key_fixture();
        let prepared = fixture
            .service
            .prepare_project_cloud_registration(
                &fixture.secrets,
                &project_registration_command(&fixture, DataCell::Eu),
                now() + Duration::minutes(1),
            )
            .expect("prepare project registration");
        assert!(!prepared.duplicate);
        assert_eq!(
            prepared.local.status,
            ProjectCloudRegistrationStatus::Prepared
        );
        let selected = fixture
            .service
            .store
            .load_project(&fixture.project)
            .expect("selected project");
        assert_eq!(
            (selected.data_cell, selected.revision),
            (Some(ProjectDataCell::Eu), 2)
        );
        assert!(
            !serde_json::to_string(&prepared.local)
                .expect("registration ledger")
                .contains("Team key lifecycle")
        );
        assert_eq!(
            decrypt_registered_project(&fixture, &prepared),
            ProjectMetadataSnapshot::from_project(&selected)
        );
        assert!(
            !serde_json::to_string(&decrypt_registered_project(&fixture, &prepared))
                .expect("project metadata snapshot")
                .contains("workspaceRoots")
        );

        let replay = fixture
            .service
            .prepare_project_cloud_registration(
                &fixture.secrets,
                &project_registration_command(&fixture, DataCell::Eu),
                now() + Duration::minutes(2),
            )
            .expect("exact registration replay");
        assert!(replay.duplicate);
        assert_eq!(replay.registration, prepared.registration);
        assert!(matches!(
            fixture.service.prepare_project_cloud_registration(
                &fixture.secrets,
                &project_registration_command(&fixture, DataCell::Us),
                now() + Duration::minutes(2),
            ),
            Err(ApplicationError::Project(ProjectError::DataCellIsImmutable))
        ));
        assert!(matches!(
            fixture.service.record_project_cloud_registration_applied(
                &fixture.project,
                1,
                &CloudMutationResult {
                    object_revision: 2,
                    event_sequence: 1,
                    outbox_sequence: 1,
                    duplicate: false,
                },
                now() + Duration::minutes(3),
            ),
            Err(ApplicationError::ProjectRegistrationResultMismatch)
        ));
        let applied = fixture
            .service
            .record_project_cloud_registration_applied(
                &fixture.project,
                1,
                &CloudMutationResult {
                    object_revision: 1,
                    event_sequence: 1,
                    outbox_sequence: 1,
                    duplicate: false,
                },
                now() + Duration::minutes(3),
            )
            .expect("registration applied");
        assert_eq!(
            (applied.status, applied.remote_revision),
            (ProjectCloudRegistrationStatus::Applied, Some(1))
        );
    }

