    fn create_creator_withdrawal_scope(
        service: &mut ApplicationService,
        ids: &CreatorWithdrawalIds,
    ) {
        service
            .create_project(
                CreateProject {
                    tenant_id: ids.tenant.clone(),
                    id: ids.project.clone(),
                    name: "Creator permission withdrawal".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-creator-withdrawal"),
                    storage_mode: StorageMode::LocalExisting,
                },
                now(),
            )
            .expect("project");
        let mission = service
            .start_creator_work_mission(
                StartCreatorWorkMission {
                    id: ids.mission.clone(),
                    project_id: ids.project.clone(),
                    task_id: TaskId::from("task-creator-withdrawal"),
                    title: "Creator invitation".into(),
                    goal: "Invite only while permission remains current".into(),
                    mode: OperatingMode::ContinuousRelationship,
                },
                now(),
            )
            .expect("mission");
        assert_eq!(mission.contract.mode, OperatingMode::ContinuousRelationship);
        assert!(mission.contract.cadence.is_some());
        service
            .create_partner(
                Partner::create(
                    ids.partner.clone(),
                    ids.tenant.clone(),
                    ids.project.clone(),
                    None,
                    None,
                    "Creator who may withdraw",
                    PartnerSupplyClass::HartevoOptIn,
                    ContactPermission::ExplicitOptIn,
                    Some("1".repeat(64)),
                )
                .expect("partner"),
                now(),
            )
            .expect("persist partner");
    }

    fn connect_creator_withdrawal_network(
        service: &mut ApplicationService,
        ids: &CreatorWithdrawalIds,
    ) {
        service
            .register_connection(
                Connection::register(
                    ids.connection.clone(),
                    ids.tenant.clone(),
                    ids.project.clone(),
                    "hartevo-opt-in",
                    AccountId::from("creator-network-account"),
                    "creator-network-account",
                    ["creator.invite.write".into()],
                    now(),
                )
                .expect("connection"),
                now(),
            )
            .expect("persist connection");
        service
            .record_connection_probe(
                &ids.project,
                &ids.connection,
                ConnectionProbe {
                    outcome: ProbeOutcome::Successful,
                    observed_external_account_id: "creator-network-account".into(),
                    granted_scopes: BTreeSet::from(["creator.invite.write".into()]),
                    probed_at: now(),
                    valid_until: now() + Duration::days(30),
                    credential_expires_at: now() + Duration::days(30),
                    evidence_digest: "2".repeat(64),
                },
                now(),
            )
            .expect("probe");
    }

