    fn signed_application_recipe_release(
        candidate_signer: &ring::signature::Ed25519KeyPair,
        release_signer: &ring::signature::Ed25519KeyPair,
        selector_digest: String,
        origin_digest: String,
        now: DateTime<Utc>,
    ) -> BrowserRecipeRelease {
        use hartevo_browser_adapter::{
            BrowserActionKind, BrowserActionRisk, BrowserActionSurface,
            BrowserRecipeEvaluationEvidence, BrowserRecipeManifest, BrowserRecipePromotion,
            BrowserRecipeStep,
        };

        let manifest = BrowserRecipeManifest {
            schema_version: 1,
            id: BrowserRecipeId::from("application-durable-publish"),
            version: 1,
            provider: "fixture-provider".into(),
            origin_digest,
            capability: "channel.publish".into(),
            effect_class: EffectClass::ExternalWrite,
            steps: vec![BrowserRecipeStep {
                sequence: 1,
                kind: BrowserActionKind::Click,
                surface: BrowserActionSurface::Semantic,
                risk: BrowserActionRisk::PotentialExternalWrite,
                selector_digest,
            }],
            publisher_key_id: "application-candidate-key".into(),
            created_at: now - Duration::hours(1),
            expires_at: now + Duration::days(30),
        };
        let candidate_payload =
            BrowserRecipeCandidate::signing_payload(&manifest).expect("candidate signing payload");
        let candidate = BrowserRecipeCandidate::new(
            manifest,
            hex::encode(candidate_signer.sign(&candidate_payload).as_ref()),
        )
        .expect("signed candidate");
        let evidence = BrowserRecipeEvaluationEvidence {
            v1_dataset_revision: "application-recipe-v1-holdout".into(),
            v1_result_digest: "8".repeat(64),
            v1_passed: 9,
            v1_total: 10,
            v2_dataset_revision: "application-recipe-v2-shadow".into(),
            v2_result_digest: "9".repeat(64),
            v2_passed: 4,
            v2_total: 5,
            safety_suite_digest: "a".repeat(64),
            contamination_audit_digest: "b".repeat(64),
            rollback_strategy_digest: "c".repeat(64),
            promotion_approval_digest: "d".repeat(64),
        };
        let candidate_digest = candidate.digest().expect("candidate digest");
        let promoted_at = now - Duration::minutes(30);
        let expires_at = now + Duration::days(20);
        let promotion_payload = BrowserRecipePromotion::signing_payload(
            &candidate_digest,
            &evidence,
            "application-release-key",
            promoted_at,
            expires_at,
        )
        .expect("promotion signing payload");
        BrowserRecipeRelease {
            candidate,
            promotion: BrowserRecipePromotion {
                schema_version: 1,
                candidate_digest,
                evidence,
                release_key_id: "application-release-key".into(),
                promoted_at,
                expires_at,
                signature_hex: hex::encode(release_signer.sign(&promotion_payload).as_ref()),
            },
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one Journey proves Application registration, SQLCipher restart, Fake Host resolution, prepared-plan authorization, Effect dispatch, and durable revocation"
    )]
    fn durable_recipe_application_journey_reauthorizes_after_restart_and_honors_revocation() {
        use hartevo_browser_adapter::{
            BrowserActionBatch, BrowserElementRef, BrowserNavigationPolicy,
            BrowserRecipeKeyPurpose, BrowserStableLocator, FakeBrowserEffectExecutor,
            FakeBrowserHost, FakeBrowserPage,
        };
        use hartevo_domain_kernel::{
            Approval, ApprovalDecision, ApprovalId, BrowserActionBatchId, BrowserSnapshotId,
        };
        use hartevo_storage::DatabaseKey;
        use ring::signature::{Ed25519KeyPair, KeyPair};

        let directory = tempfile::tempdir().expect("application recipe directory");
        let database_path = directory.path().join("application-recipe.sqlite3");
        let key = DatabaseKey::new([71; 32]).expect("database key");
        let store = ProjectStore::open(&database_path, &key).expect("encrypted store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let recipe_id = BrowserRecipeId::from("application-durable-publish");
        let policy = BrowserNavigationPolicy::https_only(["https://example.com"])
            .expect("navigation policy");
        let origin_digest = sha256(b"https://example.com");
        let locator = BrowserStableLocator::exact_accessible_name(
            &fixture.workspace,
            fixture.workspace.active_tab_id.clone(),
            &policy,
            origin_digest.clone(),
            "button",
            "Publish draft",
            now(),
        )
        .expect("stable locator");
        let candidate_signer =
            Ed25519KeyPair::from_seed_unchecked(&[23; 32]).expect("candidate signer");
        let release_signer =
            Ed25519KeyPair::from_seed_unchecked(&[29; 32]).expect("release signer");
        for (key_id, purpose, signer, evidence) in [
            (
                "application-candidate-key",
                BrowserRecipeKeyPurpose::CandidatePublisher,
                &candidate_signer,
                "e".repeat(64),
            ),
            (
                "application-release-key",
                BrowserRecipeKeyPurpose::ProductionRelease,
                &release_signer,
                "f".repeat(64),
            ),
        ] {
            fixture
                .service
                .install_browser_recipe_trust_key(
                    InstallBrowserRecipeTrustKey {
                        project_id: fixture.project_id.clone(),
                        key: TrustedBrowserRecipeKey::new(
                            key_id,
                            purpose,
                            signer.public_key().as_ref(),
                            now() - Duration::days(1),
                            now() + Duration::days(400),
                        )
                        .expect("trusted recipe key"),
                        installation_evidence_digest: evidence,
                    },
                    now(),
                )
                .expect("install recipe trust key");
        }
        let release = signed_application_recipe_release(
            &candidate_signer,
            &release_signer,
            locator.selector_digest().to_owned(),
            origin_digest.clone(),
            now(),
        );
        fixture
            .service
            .register_browser_recipe_candidate(
                RegisterBrowserRecipeCandidate {
                    project_id: fixture.project_id.clone(),
                    candidate: release.candidate.clone(),
                },
                now(),
            )
            .expect("register candidate");
        fixture
            .service
            .register_browser_recipe_release(
                RegisterBrowserRecipeRelease {
                    project_id: fixture.project_id.clone(),
                    release,
                },
                now(),
            )
            .expect("register release");
        fixture
            .service
            .activate_browser_recipe_release(
                &ActivateBrowserRecipeRelease {
                    project_id: fixture.project_id.clone(),
                    recipe_id: recipe_id.clone(),
                    version: 1,
                    expected_active_version: None,
                    activation_evidence_digest: "0".repeat(64),
                },
                now(),
            )
            .expect("activate release");
        let project_id = fixture.project_id.clone();
        let profile_id = fixture.profile.id.clone();
        let workspace_id = fixture.workspace.id.clone();
        let tab_id = fixture.workspace.active_tab_id.clone();
        drop(fixture.service);

        let mut restarted = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("application restart"),
        );
        let profile = restarted
            .load_browser_profile(&project_id, &profile_id)
            .expect("restored profile");
        let workspace = restarted
            .load_browser_workspace(&project_id, &workspace_id)
            .expect("restored workspace");
        let mut host = FakeBrowserHost::new();
        host.register_workspace(
            profile.clone(),
            workspace.clone(),
            vec![FakeBrowserPage {
                tab_id: tab_id.clone(),
                identity_digest: workspace.expected_identity_digest.clone(),
                url_digest: "4".repeat(64),
                origin_digest,
                content_digest: "5".repeat(64),
                redaction_digest: "6".repeat(64),
                document_generation: 1,
                prompt_risk: hartevo_browser_adapter::BrowserPromptRisk::None,
                element_refs: vec![BrowserElementRef {
                    reference: "application-recipe-publish".into(),
                    locator_digest: locator.selector_digest().to_owned(),
                    visible: true,
                    unique: true,
                }],
            }],
        )
        .expect("register restored Fake Host");
        let proof = workspace
            .agent_lease_proof(now() + Duration::seconds(1))
            .expect("restored lease");
        let resolution = host
            .resolve_stable_locator(
                &workspace.id,
                &proof,
                BrowserSnapshotId::from("snapshot-application-recipe"),
                &tab_id,
                &policy,
                &locator,
                now() + Duration::seconds(1),
            )
            .expect("resolve after restart");
        let action = BrowserAction::semantic_click(1, &resolution).expect("recipe action");
        let prepared = restarted
            .prepare_active_browser_recipe(
                PrepareActiveBrowserRecipe {
                    project_id: project_id.clone(),
                    recipe_id: recipe_id.clone(),
                    profile_id,
                    workspace_id,
                    policy_digest: policy.evidence_digest().to_owned(),
                    resolved_actions: vec![ResolvedBrowserRecipeAction {
                        action: action.clone(),
                        resolution: resolution.clone(),
                    }],
                    expires_at: now() + Duration::minutes(10),
                },
                now() + Duration::seconds(1),
            )
            .expect("prepare from durable Recipe registry");
        let mut effect = Effect {
            id: EffectId::from("effect-application-recipe"),
            tenant_id: workspace.tenant_id.clone(),
            project_id: workspace.project_id.clone(),
            mission_id: workspace.mission_id.clone(),
            actor_id: ActorId::from("user-application-recipe"),
            capability: prepared.plan.capability.clone(),
            provider: prepared.plan.provider.clone(),
            connection_id: None,
            account_id: Some(profile.identity.account_id.clone()),
            required_scopes: BTreeSet::new(),
            effect_class: prepared.plan.effect_class.clone(),
            description: "Publish one reviewed fixture draft".into(),
            target_resource: "https://example.com/reviewed-draft".into(),
            audience_digest: Some("1".repeat(64)),
            payload_digest: prepared.plan.effect_payload_digest.clone(),
            asset_digests: BTreeSet::new(),
            scheduled_for: None,
            timezone: "UTC".into(),
            consent: ConsentState::NotRequired,
            consent_record_id: None,
            consent_requirement: None,
            conversation_guard: None,
            creator_contact_guard: None,
            policy_version: "application-recipe-policy-v1".into(),
            risk: EffectRisk::Medium,
            idempotency_key: "application-recipe-publish-v1".into(),
            amount: Money::zero(CurrencyCode::parse("USD").expect("USD")),
            expires_at: now() + Duration::minutes(10),
            status: EffectStatus::Approved,
            approval: None,
            receipt: None,
            verification: None,
        };
        let scope_digest = effect.approval_digest();
        effect.approval = Some(Approval {
            id: ApprovalId::from("approval-application-recipe"),
            decision: ApprovalDecision::Approved,
            decided_by: ActorId::from("user-application-recipe"),
            decided_at: now() + Duration::seconds(1),
            valid_until: now() + Duration::minutes(10),
            scope_digest,
            permission_digest: "2".repeat(64),
        });
        let batch = BrowserActionBatch::for_recipe_effect(
            BrowserActionBatchId::from("batch-application-recipe"),
            &profile,
            &workspace,
            proof,
            policy.evidence_digest().to_owned(),
            vec![action.clone()],
            &prepared.plan,
            &prepared.runtime_state.registry,
            &prepared.runtime_state.trust,
            &effect,
            now() + Duration::seconds(1),
            now() + Duration::minutes(5),
        )
        .expect("build durable Recipe batch");
        let authorization = hartevo_browser_adapter::BrowserRecipeExecutionAuthorization::new(
            prepared.plan.clone(),
            &prepared.runtime_state.registry,
            &prepared.runtime_state.trust,
            &batch,
            now() + Duration::seconds(1),
        )
        .expect("runtime authorization");
        authorization
            .validate_resolution(&action, &resolution)
            .expect("dynamic resolution revalidation");
        let mut executor = FakeBrowserEffectExecutor::new_for_recipe(
            &mut host,
            batch.clone(),
            prepared.plan.clone(),
            &prepared.runtime_state.registry,
            &prepared.runtime_state.trust,
            now() + Duration::seconds(1),
        )
        .expect("authorized Fake Host executor");
        let receipt = executor.execute(&effect).expect("execute exact Effect");
        assert_eq!(receipt.request_digest, batch.plan_digest);
        drop(executor);

        restarted
            .revoke_browser_recipe_trust_key(
                RevokeBrowserRecipeTrustKey {
                    project_id: project_id.clone(),
                    key_id: "application-release-key".into(),
                    expected_revision: 1,
                    revocation_evidence_digest: "3".repeat(64),
                },
                now() + Duration::seconds(2),
            )
            .expect("persist release-key revocation");
        drop(prepared);
        drop(restarted);
        let final_restart = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("final application restart"),
        );
        assert!(matches!(
            final_restart.prepare_active_browser_recipe(
                PrepareActiveBrowserRecipe {
                    project_id,
                    recipe_id,
                    profile_id: profile.id,
                    workspace_id: workspace.id,
                    policy_digest: policy.evidence_digest().to_owned(),
                    resolved_actions: vec![ResolvedBrowserRecipeAction { action, resolution }],
                    expires_at: now() + Duration::minutes(10),
                },
                now() + Duration::seconds(3),
            ),
            Err(ApplicationError::Browser(BrowserError::RecipeKeyRevoked))
        ));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the journey proves encrypted restart recovery and both sides of one in-flight Host handoff"
    )]
    fn browser_application_handoff_hard_stops_then_recovers_across_restart() {
        use hartevo_browser_adapter::{
            BrowserAction, BrowserActionBatch, BrowserActionKind, BrowserActionRisk,
            BrowserActionSurface,
        };
        use hartevo_domain_kernel::{BrowserActionBatchId, BrowserSnapshotId};
        use hartevo_storage::DatabaseKey;

        let directory = tempfile::tempdir().expect("browser application directory");
        let database_path = directory.path().join("browser-application.sqlite3");
        let key = DatabaseKey::new([29; 32]).expect("database key");
        let store = ProjectStore::open(&database_path, &key).expect("encrypted store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let mut host = registered_browser_host(&fixture.profile, &fixture.workspace);
        let old_proof = fixture
            .workspace
            .agent_lease_proof(now())
            .expect("old proof");
        let snapshot = host
            .observe(
                &fixture.workspace.id,
                &old_proof,
                BrowserSnapshotId::from("snapshot-browser-application-1"),
                &fixture.workspace.active_tab_id,
                now(),
            )
            .expect("snapshot");
        let actions = [1, 2]
            .into_iter()
            .map(|sequence| BrowserAction {
                sequence,
                kind: BrowserActionKind::Verify,
                surface: BrowserActionSurface::Semantic,
                risk: BrowserActionRisk::ReadOnly,
                tab_id: fixture.workspace.active_tab_id.clone(),
                snapshot_id: Some(snapshot.id.clone()),
                element_ref: None,
                target_origin_digest: sha256(b"https://example.com"),
                payload_digest: "9".repeat(64),
            })
            .collect::<Vec<_>>();
        let batch = BrowserActionBatch::read_only(
            BrowserActionBatchId::from("batch-browser-application"),
            &fixture.profile,
            &fixture.workspace,
            old_proof.clone(),
            "a".repeat(64),
            actions,
            now(),
            now() + Duration::minutes(5),
        )
        .expect("read batch");
        let mut cursor = host
            .begin_read_only_batch(&batch, now())
            .expect("begin read batch");
        assert!(
            host.execute_next(&mut cursor, now())
                .expect("first action")
                .is_some()
        );

        let taken_over = fixture
            .service
            .take_over_browser_workspace(
                &mut host,
                TakeOverBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 1,
                    expected_generation: 1,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-application-2"),
                    evidence_digest: "b".repeat(64),
                },
                now() + Duration::seconds(1),
            )
            .expect("user takeover");
        assert_eq!(
            taken_over.control_state,
            hartevo_browser_adapter::BrowserControlState::UserControlled
        );
        assert_eq!(
            host.execute_next(&mut cursor, now() + Duration::seconds(1))
                .expect_err("old in-flight cursor is hard-stopped")
                .code(),
            "BROWSER_CONTROL_LEASE_LOST"
        );

        assert_eq!(
            fixture
                .service
                .load_live_browser_workspace_for_mission(&fixture.project_id, &fixture.mission_id)
                .expect("live workspace after takeover")
                .expect("one Mission-bound workspace")
                .id,
            fixture.workspace.id
        );

        let continued = fixture
            .service
            .continue_browser_workspace(
                &mut host,
                ContinueBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 2,
                    expected_generation: 2,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-application-3"),
                    lease_expires_at: now() + Duration::hours(1),
                    evidence_digest: "c".repeat(64),
                },
                now() + Duration::seconds(2),
            )
            .expect("explicit continue");
        assert_eq!(continued.lease_generation, 3);
        assert!(
            continued
                .agent_lease_proof(now() + Duration::seconds(2))
                .is_ok()
        );
        assert!(
            continued
                .validate_agent_lease(&old_proof, now() + Duration::seconds(2))
                .is_err()
        );
        assert_eq!(
            fixture
                .service
                .load_browser_workspace(&fixture.project_id, &fixture.workspace.id)
                .expect("durable continued workspace"),
            continued
        );

        let project_id = fixture.project_id.clone();
        let mission_id = fixture.mission_id.clone();
        let profile_id = fixture.profile.id.clone();
        let workspace_id = fixture.workspace.id.clone();
        drop(fixture);
        drop(host);
        let restarted = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("restarted encrypted store"),
        );
        let restored_profile = restarted
            .load_browser_profile(&project_id, &profile_id)
            .expect("restored profile");
        let restored_workspace = restarted
            .load_browser_workspace(&project_id, &workspace_id)
            .expect("restored workspace");
        assert_eq!(restored_profile.id, profile_id);
        assert_eq!(restored_workspace.mission_id, mission_id);
        assert_eq!(restored_workspace.lease_generation, 3);
        assert_eq!(
            restored_workspace.control_state,
            hartevo_browser_adapter::BrowserControlState::AgentControlled
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one ownership lifecycle test covers both paused owner classes"
    )]
    fn browser_application_pause_resume_preserves_owner_class() {
        let directory = tempfile::tempdir().expect("browser pause directory");
        let store = ProjectStore::in_memory().expect("store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let mut host = registered_browser_host(&fixture.profile, &fixture.workspace);

        let paused_agent = fixture
            .service
            .pause_browser_workspace(
                &mut host,
                PauseBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 1,
                    expected_generation: 1,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-pause-2"),
                    evidence_digest: "b".repeat(64),
                },
                now() + Duration::seconds(1),
            )
            .expect("pause agent-owned workspace");
        assert_eq!(paused_agent.control_state, BrowserControlState::PausedAgent);
        assert!(paused_agent.agent_lease_expires_at.is_none());

        let resumed_agent = fixture
            .service
            .resume_browser_workspace(
                &mut host,
                ResumeBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 2,
                    expected_generation: 2,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-pause-3"),
                    agent_lease_expires_at: Some(now() + Duration::hours(1)),
                    evidence_digest: "c".repeat(64),
                },
                now() + Duration::seconds(2),
            )
            .expect("resume agent-owned workspace");
        assert_eq!(
            resumed_agent.control_state,
            BrowserControlState::AgentControlled
        );

        let taken_over = fixture
            .service
            .take_over_browser_workspace(
                &mut host,
                TakeOverBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 3,
                    expected_generation: 3,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-pause-4"),
                    evidence_digest: "d".repeat(64),
                },
                now() + Duration::seconds(3),
            )
            .expect("take over resumed agent workspace");
        assert_eq!(
            taken_over.control_state,
            BrowserControlState::UserControlled
        );

        let paused_user = fixture
            .service
            .pause_browser_workspace(
                &mut host,
                PauseBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 4,
                    expected_generation: 4,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-pause-5"),
                    evidence_digest: "e".repeat(64),
                },
                now() + Duration::seconds(4),
            )
            .expect("pause user-owned workspace");
        assert_eq!(paused_user.control_state, BrowserControlState::PausedUser);

        let resumed_user = fixture
            .service
            .resume_browser_workspace(
                &mut host,
                ResumeBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 5,
                    expected_generation: 5,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-pause-6"),
                    agent_lease_expires_at: None,
                    evidence_digest: "f".repeat(64),
                },
                now() + Duration::seconds(5),
            )
            .expect("resume user-owned workspace");
        assert_eq!(
            resumed_user.control_state,
            BrowserControlState::UserControlled
        );
        assert_eq!(
            (resumed_user.revision, resumed_user.lease_generation),
            (6, 6)
        );
        assert!(resumed_user.agent_lease_expires_at.is_none());
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one journey proves exact browser prefix persistence, restart, tamper rejection, idempotent acknowledgement, and suffix-only recovery"
    )]
    fn browser_batch_receipt_survives_restart_and_resumes_only_exact_suffix() {
        use hartevo_browser_adapter::{
            BrowserActionKind, BrowserActionRisk, BrowserActionSurface, BrowserBatchReceiptState,
        };
        use hartevo_domain_kernel::BrowserSnapshotId;
        use hartevo_storage::DatabaseKey;

        let directory = tempfile::tempdir().expect("batch receipt directory");
        let database_path = directory.path().join("browser-batch-receipt.sqlite3");
        let key = DatabaseKey::new([83; 32]).expect("database key");
        let store = ProjectStore::open(&database_path, &key).expect("encrypted store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let mut host = registered_browser_host(&fixture.profile, &fixture.workspace);
        let proof = fixture
            .workspace
            .agent_lease_proof(now())
            .expect("lease proof");
        let snapshot = host
            .observe(
                &fixture.workspace.id,
                &proof,
                BrowserSnapshotId::from("snapshot-browser-batch-receipt"),
                &fixture.workspace.active_tab_id,
                now(),
            )
            .expect("initial snapshot");
        let actions = [1, 2]
            .into_iter()
            .map(|sequence| BrowserAction {
                sequence,
                kind: BrowserActionKind::Verify,
                surface: BrowserActionSurface::Semantic,
                risk: BrowserActionRisk::ReadOnly,
                tab_id: fixture.workspace.active_tab_id.clone(),
                snapshot_id: Some(snapshot.id.clone()),
                element_ref: None,
                target_origin_digest: sha256(b"https://example.com"),
                payload_digest: "9".repeat(64),
            })
            .collect::<Vec<_>>();
        let batch = BrowserActionBatch::read_only(
            BrowserActionBatchId::from("batch-browser-durable-prefix"),
            &fixture.profile,
            &fixture.workspace,
            proof,
            "a".repeat(64),
            actions,
            now(),
            now() + Duration::minutes(5),
        )
        .expect("read-only batch");
        let mut cursor = host
            .begin_read_only_batch(&batch, now())
            .expect("begin batch");
        let first = host
            .execute_next(&mut cursor, now())
            .expect("first action")
            .expect("first result");
        assert_eq!(first.action_sequence, 1);
        let receipt = cursor.receipt().expect("first prefix receipt");
        assert_eq!(receipt.state, BrowserBatchReceiptState::Active);

        let mut tampered = receipt.clone();
        tampered.result_digest = "f".repeat(64);
        assert!(matches!(
            fixture.service.acknowledge_browser_batch_receipt(
                AcknowledgeBrowserBatchReceipt {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 1,
                    batch: batch.clone(),
                    receipt: tampered,
                },
                now() + Duration::seconds(1),
            ),
            Err(ApplicationError::Browser(BrowserError::InvalidBatchReceipt))
        ));

        let acknowledge = AcknowledgeBrowserBatchReceipt {
            project_id: fixture.project_id.clone(),
            workspace_id: fixture.workspace.id.clone(),
            expected_revision: 1,
            batch: batch.clone(),
            receipt: receipt.clone(),
        };
        let acknowledged = fixture
            .service
            .acknowledge_browser_batch_receipt(acknowledge.clone(), now() + Duration::seconds(1))
            .expect("persist exact prefix");
        assert_eq!(acknowledged.revision, 2);
        assert_eq!(
            fixture
                .service
                .acknowledge_browser_batch_receipt(acknowledge, now() + Duration::seconds(1),)
                .expect("exact acknowledgement replay")
                .revision,
            2
        );

        let project_id = fixture.project_id.clone();
        let profile_id = fixture.profile.id.clone();
        let workspace_id = fixture.workspace.id.clone();
        drop(host);
        drop(fixture);
        let mut restarted = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("application restart"),
        );
        let restored_profile = restarted
            .load_browser_profile(&project_id, &profile_id)
            .expect("restored profile");
        let restored_workspace = restarted
            .load_browser_workspace(&project_id, &workspace_id)
            .expect("restored workspace");
        let restored_receipt = restarted
            .load_browser_batch_receipt(&project_id, &workspace_id, &batch.id)
            .expect("load receipt")
            .expect("durable receipt");
        assert_eq!(restored_receipt, receipt);

        let mut restarted_host = registered_browser_host(&restored_profile, &restored_workspace);
        restarted_host
            .observe(
                &workspace_id,
                &restored_workspace
                    .agent_lease_proof(now() + Duration::seconds(2))
                    .expect("restored lease"),
                snapshot.id,
                &restored_workspace.active_tab_id,
                now() + Duration::seconds(2),
            )
            .expect("restored live snapshot");
        let mut resumed = restarted_host
            .resume_read_only_batch(&batch, &restored_receipt, now() + Duration::seconds(2))
            .expect("resume exact prefix");
        let second = restarted_host
            .execute_next(&mut resumed, now() + Duration::seconds(2))
            .expect("execute suffix")
            .expect("second result");
        assert_eq!(second.action_sequence, 2);
        assert!(
            restarted_host
                .execute_next(&mut resumed, now() + Duration::seconds(2))
                .expect("complete suffix")
                .is_none()
        );
        let completed = resumed.receipt().expect("completed receipt");
        assert_eq!(completed.completed_action_count, 2);
        assert_eq!(completed.state, BrowserBatchReceiptState::Completed);
        let completed_workspace = restarted
            .acknowledge_browser_batch_receipt(
                AcknowledgeBrowserBatchReceipt {
                    project_id: project_id.clone(),
                    workspace_id: workspace_id.clone(),
                    expected_revision: 2,
                    batch,
                    receipt: completed.clone(),
                },
                now() + Duration::seconds(3),
            )
            .expect("persist completed prefix");
        assert_eq!(completed_workspace.revision, 3);
        assert_eq!(
            restarted
                .load_browser_batch_receipt(
                    &project_id,
                    &workspace_id,
                    &BrowserActionBatchId::from("batch-browser-durable-prefix"),
                )
                .expect("reload completed receipt"),
            Some(completed)
        );
    }

    struct ApplicationCleanFileScanner;

    impl FileSafetyScanner for ApplicationCleanFileScanner {
        fn scan(
            &mut self,
            request: &hartevo_browser_adapter::FileScanRequest<'_>,
        ) -> Result<hartevo_browser_adapter::FileScanReport, BrowserError> {
            Ok(hartevo_browser_adapter::FileScanReport {
                scanner_id: "application-fixture-scanner".into(),
                scanner_version: "v1".into(),
                decision: hartevo_browser_adapter::FileScanDecision::Clean,
                evidence_digest: sha256(
                    format!(
                        "{}:{}:{:?}",
                        request.content_digest, request.byte_count, request.detected_type
                    )
                    .as_bytes(),
                ),
                scanned_at: request.observed_at,
            })
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one journey proves file staging, SQLCipher CAS, two process restarts, exact claim, and terminal cleanup"
    )]
    fn durable_browser_file_upload_survives_restart_and_is_consumed_exactly_once() {
        use std::fs;
        #[cfg(unix)]
        use std::os::unix::fs::PermissionsExt;

        use hartevo_storage::DatabaseKey;

        let directory = tempfile::tempdir().expect("file application directory");
        let database_path = directory.path().join("file-application.sqlite3");
        let broker_root = directory.path().join("durable-file-broker");
        fs::create_dir(&broker_root).expect("broker root");
        #[cfg(unix)]
        fs::set_permissions(&broker_root, fs::Permissions::from_mode(0o700))
            .expect("private broker root");
        let key = DatabaseKey::new([53; 32]).expect("database key");
        let store = ProjectStore::open(&database_path, &key).expect("encrypted store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let project_id = fixture.project_id.clone();
        let mission_id = fixture.mission_id.clone();
        let workspace_id = fixture.workspace.id.clone();
        let proof = fixture
            .workspace
            .agent_lease_proof(now())
            .expect("lease proof");
        let (mut broker, initial) = fixture
            .service
            .open_durable_browser_file_broker(&project_id, &broker_root)
            .expect("open durable broker");
        assert!(initial.is_healthy());
        let source = directory.path().join("private-customer-deliverable.json");
        fs::write(
            &source,
            br#"{"customer":"private@example.com","status":"ready"}"#,
        )
        .expect("source file");
        let grant_id = BrowserFileGrantId::from("grant-browser-file-application");
        let prepare = PrepareBrowserFileUpload {
            project_id: project_id.clone(),
            workspace_id: workspace_id.clone(),
            grant_id: grant_id.clone(),
            lease_proof: proof.clone(),
            source_path: source.clone(),
            expected_type: BrowserFileType::Json,
            authorization_evidence_digest: "4".repeat(64),
            expires_at: now() + Duration::minutes(10),
        };
        let prepare_debug = format!("{prepare:?}");
        assert!(!prepare_debug.contains(source.to_string_lossy().as_ref()));
        assert!(!prepare_debug.contains(proof.lease_id.as_str()));
        let prepared = fixture
            .service
            .prepare_browser_file_upload(
                &mut broker,
                prepare,
                now(),
                &mut ApplicationCleanFileScanner,
            )
            .expect("prepare and persist file grant");
        assert_eq!(
            prepared.state,
            hartevo_browser_adapter::BrowserFileGrantState::Prepared
        );
        assert_eq!(
            fixture
                .service
                .load_browser_file_grant(&project_id, &grant_id)
                .expect("durable prepared grant"),
            prepared
        );

        drop(broker);
        drop(fixture.service);
        let mut restarted = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("first application restart"),
        );
        let (mut broker, reconciliation) = restarted
            .open_durable_browser_file_broker(&project_id, &broker_root)
            .expect("restore prepared file broker");
        assert_eq!(reconciliation.restored_active_grants, 1);
        assert!(reconciliation.is_healthy());
        assert!(matches!(
            restarted.claim_browser_file_upload(
                &mut broker,
                ClaimBrowserFileUpload {
                    project_id: project_id.clone(),
                    workspace_id: workspace_id.clone(),
                    grant_id: grant_id.clone(),
                    claim_id: BrowserFileClaimId::from("claim-browser-file-wrong-payload"),
                    lease_proof: proof.clone(),
                    action_payload_digest: "9".repeat(64),
                    expected_revision: 1,
                },
                now() + Duration::seconds(1),
            ),
            Err(ApplicationError::Browser(BrowserError::InvalidFileGrant))
        ));
        let claim_id = BrowserFileClaimId::from("claim-browser-file-application");
        let handle = restarted
            .claim_browser_file_upload(
                &mut broker,
                ClaimBrowserFileUpload {
                    project_id: project_id.clone(),
                    workspace_id: workspace_id.clone(),
                    grant_id: grant_id.clone(),
                    claim_id: claim_id.clone(),
                    lease_proof: proof.clone(),
                    action_payload_digest: prepared.upload_payload_digest.clone(),
                    expected_revision: 1,
                },
                now() + Duration::seconds(1),
            )
            .expect("claim after restart");
        let staged_path = handle.staged_path().to_path_buf();
        assert!(staged_path.exists());
        assert_eq!(
            restarted
                .load_browser_file_grant(&project_id, &grant_id)
                .expect("durable leased grant")
                .state,
            hartevo_browser_adapter::BrowserFileGrantState::Leased
        );
        drop(handle);
        drop(broker);
        drop(restarted);

        let mut second_restart = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("second application restart"),
        );
        let (mut broker, reconciliation) = second_restart
            .open_durable_browser_file_broker(&project_id, &broker_root)
            .expect("restore leased file broker");
        assert_eq!(reconciliation.restored_active_grants, 1);
        let consumed = second_restart
            .complete_browser_file_upload(
                &mut broker,
                CompleteBrowserFileUpload {
                    project_id: project_id.clone(),
                    workspace_id: workspace_id.clone(),
                    grant_id: grant_id.clone(),
                    claim_id,
                    lease_proof: proof,
                    completion_evidence_digest: "5".repeat(64),
                    expected_revision: 2,
                },
                now() + Duration::seconds(2),
            )
            .expect("persist terminal state before deleting the staged file");
        assert_eq!(
            consumed.state,
            hartevo_browser_adapter::BrowserFileGrantState::Consumed
        );
        assert!(!staged_path.exists());
        drop(broker);
        drop(second_restart);

        let final_restart = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("final application restart"),
        );
        let (_broker, reconciliation) = final_restart
            .open_durable_browser_file_broker(&project_id, &broker_root)
            .expect("restore terminal broker state");
        assert_eq!(reconciliation.restored_terminal_grants, 1);
        assert!(reconciliation.is_healthy());
        assert_eq!(
            final_restart
                .load_browser_file_grant(&project_id, &grant_id)
                .expect("final durable grant"),
            consumed
        );
        let audit = serde_json::to_string(
            &final_restart
                .mission_events(&project_id, &mission_id)
                .expect("mission audit"),
        )
        .expect("serialize audit");
        assert!(!audit.contains("private@example.com"));
        assert!(!audit.contains("private-customer-deliverable.json"));
        assert!(!audit.contains("application-fixture-scanner"));
        assert!(!audit.contains("claim-browser-file-application"));
    }

    #[cfg(target_os = "macos")]
    #[test]
    #[ignore = "requires HARTEVO_TEST_CHROME_BINARY and permission to launch the installed browser"]
    #[allow(
        clippy::too_many_lines,
        reason = "one environment smoke proves the real SQLCipher, Application handoff, and Chromium pipe boundary across restart"
    )]
    fn real_chromium_application_handoff_and_restart_smoke() {
        use std::fs;
        use std::os::unix::fs::PermissionsExt;

        use hartevo_browser_adapter::{ChromiumLaunchConfig, ManagedChromiumHost};
        use hartevo_domain_kernel::BrowserSnapshotId;
        use hartevo_storage::DatabaseKey;

        let executable = std::env::var_os("HARTEVO_TEST_CHROME_BINARY")
            .map(PathBuf::from)
            .expect("HARTEVO_TEST_CHROME_BINARY is required");
        let directory = tempfile::tempdir().expect("real Chromium application directory");
        let database_path = directory.path().join("real-chromium-application.sqlite3");
        let profile_root = directory.path().join("chromium-profiles");
        fs::create_dir(&profile_root).expect("create private Chromium profile root");
        fs::set_permissions(&profile_root, fs::Permissions::from_mode(0o700))
            .expect("make Chromium profile root private");
        let key = DatabaseKey::new([47; 32]).expect("database key");
        let store = ProjectStore::open(&database_path, &key).expect("encrypted store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let profile_id = fixture.profile.id.clone();
        let workspace_id = fixture.workspace.id.clone();
        let project_id = fixture.project_id.clone();
        let tab_id = fixture.workspace.active_tab_id.clone();
        let old_proof = fixture
            .workspace
            .agent_lease_proof(now())
            .expect("initial durable lease proof");
        let config = ChromiumLaunchConfig::new(&executable, profile_root, true)
            .expect("validated Chromium launch config")
            .with_macos_mock_keychain_for_test()
            .expect("explicit macOS test credential store");
        let mut host =
            ManagedChromiumHost::spawn(fixture.profile.clone(), fixture.workspace.clone(), &config)
                .expect("spawn Chromium from durable application state");
        let health = host.health().expect("Chromium pipe health");
        assert!(health.product.contains("Chrome") || health.product.contains("Chromium"));
        assert!(!health.protocol_version.is_empty());
        assert_eq!(
            health.credential_store_mode,
            hartevo_browser_adapter::ChromiumCredentialStoreMode::MacOsMockForTest
        );
        host.attach_about_blank_tab(&tab_id, &old_proof, now())
            .expect("attach managed about:blank tab");
        let initial_snapshot = host
            .observe_ax(
                &tab_id,
                &old_proof,
                BrowserSnapshotId::from("snapshot-real-application-initial"),
                now(),
            )
            .expect("observe initial AX tree");
        assert_eq!(initial_snapshot.workspace_id, workspace_id);

        let taken_over = fixture
            .service
            .take_over_browser_workspace(
                &mut host,
                TakeOverBrowserWorkspace {
                    project_id: project_id.clone(),
                    workspace_id: workspace_id.clone(),
                    expected_revision: 1,
                    expected_generation: 1,
                    new_lease_id: BrowserControlLeaseId::from("lease-real-chromium-application-2"),
                    evidence_digest: "d".repeat(64),
                },
                now() + Duration::seconds(1),
            )
            .expect("persist and enforce user takeover");
        assert_eq!(
            taken_over.control_state,
            hartevo_browser_adapter::BrowserControlState::UserControlled
        );
        assert_eq!(
            host.observe_ax(
                &tab_id,
                &old_proof,
                BrowserSnapshotId::from("snapshot-real-application-fenced"),
                now() + Duration::seconds(1),
            )
            .expect_err("the old proof must be fenced before another protocol action")
            .code(),
            "BROWSER_CONTROL_LEASE_LOST"
        );

        drop(fixture.service);
        let mut restarted = ApplicationService::new(
            ProjectStore::open(&database_path, &key)
                .expect("reopen encrypted store after takeover"),
        );
        let restored_profile = restarted
            .load_browser_profile(&project_id, &profile_id)
            .expect("restore profile after application restart");
        let restored_takeover = restarted
            .load_browser_workspace(&project_id, &workspace_id)
            .expect("restore takeover after application restart");
        assert_eq!(restored_profile.id, profile_id);
        assert_eq!(restored_takeover, taken_over);

        let continued = restarted
            .continue_browser_workspace(
                &mut host,
                ContinueBrowserWorkspace {
                    project_id: project_id.clone(),
                    workspace_id: workspace_id.clone(),
                    expected_revision: 2,
                    expected_generation: 2,
                    new_lease_id: BrowserControlLeaseId::from("lease-real-chromium-application-3"),
                    lease_expires_at: now() + Duration::hours(1),
                    evidence_digest: "e".repeat(64),
                },
                now() + Duration::seconds(2),
            )
            .expect("explicitly continue the real Host after restart");
        let new_proof = continued
            .agent_lease_proof(now() + Duration::seconds(2))
            .expect("continued lease proof");
        let resumed_snapshot = host
            .observe_ax(
                &tab_id,
                &new_proof,
                BrowserSnapshotId::from("snapshot-real-application-resumed"),
                now() + Duration::seconds(2),
            )
            .expect("observe again only after explicit continue");
        assert_eq!(
            resumed_snapshot.lease_generation,
            continued.lease_generation
        );
        assert_eq!(
            restarted
                .load_browser_workspace(&project_id, &workspace_id)
                .expect("load durable resumed state"),
            continued
        );

        drop(restarted);
        let second_restart = ApplicationService::new(
            ProjectStore::open(&database_path, &key).expect("second encrypted-store restart"),
        );
        assert_eq!(
            second_restart
                .load_browser_workspace(&project_id, &workspace_id)
                .expect("restore resumed state after the second restart"),
            continued
        );
        let shutdown = host
            .shutdown()
            .expect("shut down the Chromium process group");
        assert!(shutdown.success);
    }

    struct ConflictingTakeoverHost {
        fake: hartevo_browser_adapter::FakeBrowserHost,
        database_path: PathBuf,
        key_bytes: [u8; 32],
    }

    impl BrowserControlHost for ConflictingTakeoverHost {
        fn sync_workspace(&mut self, workspace: &BrowserWorkspace) -> Result<(), BrowserError> {
            self.fake.sync_workspace(workspace)?;
            let key = hartevo_storage::DatabaseKey::new(self.key_bytes)
                .expect("conflict fixture database key");
            let mut store = ProjectStore::open(&self.database_path, &key)
                .expect("conflict fixture second connection");
            let mut rival = store
                .load_browser_workspace(&workspace.project_id, &workspace.id)
                .expect("load rival base");
            rival
                .user_takeover(
                    rival.revision,
                    rival.lease_generation,
                    BrowserControlLeaseId::from("lease-browser-application-rival"),
                    "d".repeat(64),
                    workspace.updated_at,
                )
                .expect("rival takeover");
            store
                .update_browser_workspace_atomic(&rival, 1)
                .expect("persist rival takeover");
            Ok(())
        }
    }

    #[test]
    fn takeover_persistence_conflict_keeps_host_hard_stopped_and_reports_reconciliation() {
        use hartevo_domain_kernel::BrowserSnapshotId;
        use hartevo_storage::DatabaseKey;

        let directory = tempfile::tempdir().expect("browser conflict directory");
        let database_path = directory.path().join("browser-conflict.sqlite3");
        let key_bytes = [31; 32];
        let key = DatabaseKey::new(key_bytes).expect("key");
        let store = ProjectStore::open(&database_path, &key).expect("store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let old_proof = fixture
            .workspace
            .agent_lease_proof(now())
            .expect("old proof");
        let fake = registered_browser_host(&fixture.profile, &fixture.workspace);
        let mut host = ConflictingTakeoverHost {
            fake,
            database_path,
            key_bytes,
        };

        assert!(matches!(
            fixture.service.take_over_browser_workspace(
                &mut host,
                TakeOverBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 1,
                    expected_generation: 1,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-application-2"),
                    evidence_digest: "b".repeat(64),
                },
                now() + Duration::seconds(1),
            ),
            Err(ApplicationError::BrowserPersistenceReconciliationRequired { .. })
        ));
        assert_eq!(
            host.fake
                .observe(
                    &fixture.workspace.id,
                    &old_proof,
                    BrowserSnapshotId::from("snapshot-after-conflict"),
                    &fixture.workspace.active_tab_id,
                    now() + Duration::seconds(1),
                )
                .expect_err("hard stop survives persistence conflict")
                .code(),
            "BROWSER_CONTROL_LEASE_LOST"
        );
        let durable = fixture
            .service
            .load_browser_workspace(&fixture.project_id, &fixture.workspace.id)
            .expect("rival durable takeover");
        assert_eq!(
            durable.control_state,
            hartevo_browser_adapter::BrowserControlState::UserControlled
        );
        assert_eq!(durable.lease_generation, 2);
    }

    struct RejectingControlHost;

    impl BrowserControlHost for RejectingControlHost {
        fn sync_workspace(&mut self, _workspace: &BrowserWorkspace) -> Result<(), BrowserError> {
            Err(BrowserError::WorkspaceNotRegistered)
        }
    }

    #[test]
    fn pause_rejects_before_persistence_while_resume_failure_keeps_durable_grant() {
        let directory = tempfile::tempdir().expect("browser ordering directory");
        let store = ProjectStore::in_memory().expect("store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let pause = PauseBrowserWorkspace {
            project_id: fixture.project_id.clone(),
            workspace_id: fixture.workspace.id.clone(),
            expected_revision: 1,
            expected_generation: 1,
            new_lease_id: BrowserControlLeaseId::from("lease-browser-ordering-2"),
            evidence_digest: "b".repeat(64),
        };
        assert!(matches!(
            fixture.service.pause_browser_workspace(
                &mut RejectingControlHost,
                pause.clone(),
                now() + Duration::seconds(1),
            ),
            Err(ApplicationError::Browser(
                BrowserError::WorkspaceNotRegistered
            ))
        ));
        assert_eq!(
            fixture
                .service
                .load_browser_workspace(&fixture.project_id, &fixture.workspace.id)
                .expect("pause rejection leaves durable state")
                .control_state,
            BrowserControlState::AgentControlled
        );

        let mut host = registered_browser_host(&fixture.profile, &fixture.workspace);
        fixture
            .service
            .pause_browser_workspace(&mut host, pause, now() + Duration::seconds(1))
            .expect("persist exact pause");
        assert!(matches!(
            fixture.service.resume_browser_workspace(
                &mut RejectingControlHost,
                ResumeBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 2,
                    expected_generation: 2,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-ordering-3"),
                    agent_lease_expires_at: Some(now() + Duration::hours(1)),
                    evidence_digest: "c".repeat(64),
                },
                now() + Duration::seconds(2),
            ),
            Err(ApplicationError::BrowserHostReconciliationRequired { .. })
        ));
        assert_eq!(
            fixture
                .service
                .load_browser_workspace(&fixture.project_id, &fixture.workspace.id)
                .expect("resume grant remains durable")
                .control_state,
            BrowserControlState::AgentControlled
        );
    }

    #[test]
    fn continue_host_failure_preserves_durable_explicit_grant_and_reports_reconciliation() {
        let directory = tempfile::tempdir().expect("browser continue directory");
        let store = ProjectStore::in_memory().expect("store");
        let mut fixture = browser_application_fixture(store, directory.path().to_path_buf());
        let mut host = registered_browser_host(&fixture.profile, &fixture.workspace);
        fixture
            .service
            .take_over_browser_workspace(
                &mut host,
                TakeOverBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 1,
                    expected_generation: 1,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-application-2"),
                    evidence_digest: "b".repeat(64),
                },
                now() + Duration::seconds(1),
            )
            .expect("takeover");

        assert!(matches!(
            fixture.service.continue_browser_workspace(
                &mut RejectingControlHost,
                ContinueBrowserWorkspace {
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace.id.clone(),
                    expected_revision: 2,
                    expected_generation: 2,
                    new_lease_id: BrowserControlLeaseId::from("lease-browser-application-3"),
                    lease_expires_at: now() + Duration::hours(1),
                    evidence_digest: "c".repeat(64),
                },
                now() + Duration::seconds(2),
            ),
            Err(ApplicationError::BrowserHostReconciliationRequired { .. })
        ));
        let durable = fixture
            .service
            .load_browser_workspace(&fixture.project_id, &fixture.workspace.id)
            .expect("durable explicit continue");
        assert_eq!(
            durable.control_state,
            hartevo_browser_adapter::BrowserControlState::AgentControlled
        );
        assert_eq!(durable.lease_generation, 3);
    }
